[[nodiscard]] bool sonic_native_diagnostic_enabled(
    const char* const name) noexcept {
    std::array<char, 32u> storage{};
#ifdef _MSC_VER
    std::size_t required = 0u;
    if (::getenv_s(&required, storage.data(), storage.size(), name) != 0 ||
        required != 2u)
        return false;
    return storage.front() == '1';
#else
    const char* const value = std::getenv(name);
    return value != nullptr && std::string_view(value) == "1";
#endif
}

[[nodiscard]] bool sonic_native_texlist_binding_diagnostic_enabled() noexcept {
    static const bool enabled = sonic_native_diagnostic_enabled(
        "KATANA_SONIC_DIAGNOSTIC_TEXLIST_BINDING");
    return enabled;
}

[[nodiscard]] bool sonic_native_timing_diagnostic_enabled() noexcept {
    static const bool enabled = sonic_native_diagnostic_enabled(
        "KATANA_SONIC_DIAGNOSTIC_TIMING");
    return enabled;
}

const bool sonic_native_save_diagnostic_enabled = sonic_native_diagnostic_enabled(
    "KATANA_SONIC_DIAGNOSTIC_SAVE");

[[nodiscard]] bool sonic_native_graphics_diagnostics_enabled() noexcept {
    static const bool enabled = [] {
        std::array<char, 32u> storage{};
        std::string_view value;
#ifdef _MSC_VER
        std::size_t required = 0u;
        if (::getenv_s(&required, storage.data(), storage.size(),
                       "KATANA_NATIVE_GRAPHICS_DIAGNOSTICS_MODE") != 0 ||
            required <= 1u || required > storage.size())
            return false;
        value = std::string_view(storage.data(), required - 1u);
#else
        const char* const raw =
            std::getenv("KATANA_NATIVE_GRAPHICS_DIAGNOSTICS_MODE");
        if (raw == nullptr) return false;
        value = raw;
#endif
        return value != "off";
    }();
    return enabled;
}

[[nodiscard]] std::optional<std::uint32_t> sonic_native_diagnostic_u32(
    const char* const name) noexcept {
    std::array<char, 32u> storage{};
    std::string_view text;
#ifdef _MSC_VER
    std::size_t required = 0u;
    if (::getenv_s(&required, storage.data(), storage.size(), name) != 0 ||
        required <= 1u || required > storage.size())
        return std::nullopt;
    text = std::string_view(storage.data(), required - 1u);
#else
    const char* const value = std::getenv(name);
    if (value == nullptr) return std::nullopt;
    text = value;
#endif
    std::uint64_t result = 0u;
    for (const char digit : text) {
        if (digit < '0' || digit > '9') return std::nullopt;
        result = result * 10u + static_cast<unsigned>(digit - '0');
        if (result > std::numeric_limits<std::uint32_t>::max())
            return std::nullopt;
    }
    return static_cast<std::uint32_t>(result);
}

struct SonicNativeCanonicalU32Environment final {
    bool present = false;
    std::optional<std::uint32_t> value;
};

[[nodiscard]] SonicNativeCanonicalU32Environment
sonic_native_canonical_diagnostic_u32(const char* const name) noexcept {
    std::array<char, 32u> storage{};
    std::string_view text;
#ifdef _MSC_VER
    std::size_t required = 0u;
    if (::getenv_s(&required, storage.data(), storage.size(), name) != 0)
        return {true, std::nullopt};
    if (required == 0u) return {};
    if (required <= 1u || required > storage.size())
        return {true, std::nullopt};
    text = std::string_view(storage.data(), required - 1u);
#else
    const char* const raw = std::getenv(name);
    if (raw == nullptr) return {};
    text = raw;
#endif
    if (text.empty() || (text.size() > 1u && text.front() == '0'))
        return {true, std::nullopt};
    std::uint32_t result = 0u;
    for (const char digit : text) {
        if (digit < '0' || digit > '9') return {true, std::nullopt};
        const auto value = static_cast<std::uint32_t>(digit - '0');
        if (result >
            (std::numeric_limits<std::uint32_t>::max() - value) / 10u)
            return {true, std::nullopt};
        result = result * 10u + value;
    }
    return {true, result};
}

[[nodiscard]] bool sonic_native_armed_graphics_identity_frame(
    const std::uint64_t frame_index) noexcept {
    static const bool armed = [] {
        std::array<char, 32u> storage{};
        std::string_view value;
#ifdef _MSC_VER
        std::size_t required = 0u;
        if (::getenv_s(&required, storage.data(), storage.size(),
                       "KATANA_NATIVE_GRAPHICS_DIAGNOSTICS_MODE") != 0 ||
            required <= 1u || required > storage.size())
            return false;
        value = std::string_view(storage.data(), required - 1u);
#else
        const char* const raw =
            std::getenv("KATANA_NATIVE_GRAPHICS_DIAGNOSTICS_MODE");
        if (raw == nullptr) return false;
        value = raw;
#endif
        return value == "armed-capture";
    }();
    if (!armed) return false;
    static const std::uint64_t start_frame =
        sonic_native_diagnostic_u32(
            "KATANA_NATIVE_GRAPHICS_CAPTURE_START_FRAME")
            .value_or(1u);
    static const std::uint64_t requested_end_frame =
        sonic_native_diagnostic_u32(
            "KATANA_NATIVE_GRAPHICS_CAPTURE_END_FRAME")
            .value_or(std::numeric_limits<std::uint32_t>::max());
    // Match the runtime's drawstream contract: identities which scan packet
    // vertices exist only for the same at-most-three armed frames. Digest and
    // breadcrumb modes retain their O(1) metadata without this extra work.
    const auto end_frame = std::min(requested_end_frame, start_frame + 2u);
    return frame_index >= start_frame && frame_index <= end_frame;
}

[[nodiscard]] bool sonic_native_graphics_authority_frame(
    const std::uint64_t frame_index) noexcept {
    // The visible-capture wrapper deliberately sanitizes arbitrary KATANA_*
    // variables.  Reuse its existing bounded model-state switch as the public
    // arm, while retaining the narrower switch for direct component runs.
    static const bool enabled =
        sonic_native_diagnostic_enabled(
            "KATANA_SONIC_DIAGNOSTIC_GRAPHICS_AUTHORITY") ||
        sonic_native_diagnostic_enabled(
            "KATANA_SONIC_DIAGNOSTIC_MODEL_STATE");
    return enabled && sonic_native_armed_graphics_identity_frame(frame_index);
}

constexpr std::uint32_t sonic_graphics_diagnostic_texture = 1u << 0u;
constexpr std::uint32_t sonic_graphics_diagnostic_blend = 1u << 1u;
constexpr std::uint32_t sonic_graphics_diagnostic_depth = 1u << 2u;
constexpr std::uint32_t sonic_graphics_diagnostic_cull = 1u << 3u;
constexpr std::uint32_t sonic_graphics_diagnostic_material = 1u << 4u;
constexpr std::uint32_t sonic_graphics_diagnostic_triangle_filter = 1u << 5u;
constexpr std::uint32_t sonic_graphics_diagnostic_all =
    sonic_graphics_diagnostic_texture | sonic_graphics_diagnostic_blend |
    sonic_graphics_diagnostic_depth | sonic_graphics_diagnostic_cull |
    sonic_graphics_diagnostic_material |
    sonic_graphics_diagnostic_triangle_filter;

constexpr std::uint32_t ninja_flag_use_alpha = 1u << 20u;
constexpr std::uint32_t ninja_flag_use_texture = 1u << 21u;
constexpr std::uint32_t ninja_flag_environment_map = 1u << 22u;
constexpr std::uint32_t ninja_flag_double_side = 1u << 23u;
constexpr std::uint32_t ninja_flag_ignore_light = 1u << 25u;
// Bit 19 belongs to two different words with different semantics.  In an
// NJS_MATERIAL it is IgnoreSpecular; in the live PVR TSP packet it is
// IgnoreTexA.  The PAL packet merge below deliberately preserves this bit
// from the active packet and does not import the material bit.
constexpr std::uint32_t ninja_flag_ignore_specular = 1u << 19u;
constexpr std::uint32_t pvr_tsp_flag_ignore_texture_alpha = 1u << 19u;
constexpr std::uint32_t ninja_flag_clamp_v = 1u << 15u;
constexpr std::uint32_t ninja_flag_clamp_u = 1u << 16u;
constexpr std::uint32_t ninja_flag_flip_v = 1u << 17u;
constexpr std::uint32_t ninja_flag_flip_u = 1u << 18u;

[[nodiscard]] constexpr std::uint32_t sonic_ninja_merge_packet_tsp(
    const std::uint32_t active_packet_tsp,
    const std::uint32_t material_control) noexcept {
    return (active_packet_tsp & 0x03F800FFu) |
           (material_control & 0xFC07FF00u);
}

constexpr std::uint32_t sonic_ninja_basic_opaque_arc1 = 0x000800CEu;
constexpr std::uint32_t sonic_ninja_basic_translucent_arc1 = 0x021000CEu;

[[nodiscard]] constexpr std::uint32_t sonic_ninja_basic_arc1(
    const std::uint32_t material_control) noexcept {
    // PAL 0x8C037700..0x8C0377BC, after ConstantAttr and TSP merge.
    const bool textured = (material_control & ninja_flag_use_texture) != 0u;
    const bool alpha = (material_control & ninja_flag_use_alpha) != 0u;
    if (!textured) return alpha ? 0x02100002u : 0x00080002u;
    if (alpha) return sonic_ninja_basic_translucent_arc1;
    return (material_control & ninja_flag_ignore_light) != 0u
               ? 0x0008000Eu : sonic_ninja_basic_opaque_arc1;
}

// Resident SDK 620B46..620BE8 selects a different ARC1 family from
// the title BasicAttach helper. 606948 retains all low PCW bits and TSP
// shading bits; copying the title's 03767C mask loses that ownership.
enum class SonicNativeSdkModelWriter : std::uint8_t {
    None,
    Sdk620,
    Sdk638
};

[[nodiscard]] constexpr std::uint32_t sonic_ninja_sdk_arc1(
    const std::uint32_t flags,
    const SonicNativeSdkModelWriter writer) noexcept {
    const bool textured = (flags & ninja_flag_use_texture) != 0u;
    const bool flat = (flags & (ninja_flag_ignore_light | 0x01000000u)) != 0u;
    // 6386BA..6387AE selects packed textured colour (08/0A/0C/0E),
    // unlike 620B46's intensity form (28/2A). Both owners retain the
    // material's TSP shading instruction through SDK 606948. The title
    // BasicAttach projection would instead turn an unlit, black monitor
    // into a Replace draw, discarding its off colour for the lit texture.
    if (writer == SonicNativeSdkModelWriter::Sdk638) {
        const auto format = !textured ? (flat ? 0x10u : 0x12u)
            : (flags & ninja_flag_ignore_light) != 0u ? 0x08u
            : (flags & 0x01000000u) != 0u
                ? ((flags & (1u << 19u)) != 0u ? 0x0Cu : 0x08u)
                : ((flags & (1u << 19u)) != 0u ? 0x0Au : 0x0Eu);
        return ((flags & ninja_flag_use_alpha) != 0u ? 0x02100000u : 0x00080000u) |
               format;
    }
    return ((flags & ninja_flag_use_alpha) != 0u ? 0x02100000u : 0x00080000u) |
           (textured ? 0x28u : 0x10u) | (flat ? 0u : 2u);
}

// Golden ARC1 choices from the two retail SDK switch trees. Cover alpha,
// texture, flat colour, IgnoreLight and IgnoreSpecular independently.
static_assert([] {
    constexpr std::array<std::array<std::uint32_t, 3u>, 8u> cases{{
        {0x00000000u, 0x12u, 0x12u}, {0x01000000u, 0x10u, 0x10u},
        {0x02000000u, 0x10u, 0x10u}, {0x00200000u, 0x2Au, 0x0Eu},
        {0x00280000u, 0x2Au, 0x0Au}, {0x01200000u, 0x28u, 0x08u},
        {0x01280000u, 0x28u, 0x0Cu}, {0x02280000u, 0x28u, 0x08u}}};
    for (const auto& row : cases)
        for (const auto alpha : {0u, ninja_flag_use_alpha}) {
            const auto prefix = alpha != 0u ? 0x02100000u : 0x00080000u;
            if (sonic_ninja_sdk_arc1(row[0] | alpha, SonicNativeSdkModelWriter::Sdk620) != (prefix | row[1]) ||
                sonic_ninja_sdk_arc1(row[0] | alpha, SonicNativeSdkModelWriter::Sdk638) != (prefix | row[2]))
                return false;
        }
    return true;
}());

static_assert(sonic_ninja_basic_arc1(0u) == 0x00080002u);
static_assert(sonic_ninja_basic_arc1(ninja_flag_ignore_light) == 0x00080002u);
static_assert(sonic_ninja_basic_arc1(ninja_flag_use_alpha) == 0x02100002u);
static_assert(sonic_ninja_basic_arc1(ninja_flag_use_alpha | ninja_flag_ignore_light) == 0x02100002u);
static_assert(sonic_ninja_basic_arc1(ninja_flag_use_texture) == 0x000800CEu);
static_assert(sonic_ninja_basic_arc1(ninja_flag_use_texture | ninja_flag_ignore_light) == 0x0008000Eu);
static_assert(sonic_ninja_basic_arc1(ninja_flag_use_texture | ninja_flag_use_alpha) == 0x021000CEu);
static_assert(sonic_ninja_basic_arc1(ninja_flag_use_texture | ninja_flag_use_alpha | ninja_flag_ignore_light) == 0x021000CEu);

struct SonicNinjaArc1PacketState final {
    std::uint32_t parameter_control = 0u;
    std::uint32_t texture_shading = 0u;
};

[[nodiscard]] constexpr SonicNinjaArc1PacketState
sonic_ninja_apply_arc1(const std::uint32_t parameter_control,
                       const std::uint32_t texture_shading,
                       const std::uint32_t arc1) noexcept {
    // Exact PAL 0x8C03767C projection. ARC1 owns PCW's list/colour-format
    // fields and TSP's alpha/IgnoreTexA fields as one draw-local
    // transaction. Projecting only UseAlpha (the former implementation)
    // leaves the renderer in the stale intensity packet format and drops the
    // original Offset-colour detail stream.
    return SonicNinjaArc1PacketState{
        (parameter_control & 0xFDFFFF00u) | (arc1 & 0x0200003Fu),
        (texture_shading & 0xFFE7FF3Fu) | (arc1 & 0x001800C0u)};
}

[[nodiscard]] constexpr SonicNinjaArc1PacketState sonic_ninja_sdk_apply_arc1(
    const std::uint32_t pcw, const std::uint32_t tsp,
    const std::uint32_t arc1, const std::uint32_t control) noexcept {
    auto next_pcw = (pcw & 0xFDFFFF00u) | (arc1 & 0x020000FFu);
    const bool shadow = (control & 0x400u) != 0u ||
        ((control & 0x1000u) != 0u && (arc1 & 0x02100000u) != 0u);
    next_pcw = shadow ? next_pcw | 0x80u : next_pcw & ~0x80u;
    return {next_pcw, (tsp & 0xFFE7FFFFu) | (arc1 & 0x00180000u)};
}

static_assert(
    (sonic_ninja_merge_packet_tsp(
         0u, pvr_tsp_flag_ignore_texture_alpha) &
     pvr_tsp_flag_ignore_texture_alpha) == 0u);
static_assert(
    (sonic_ninja_merge_packet_tsp(
         pvr_tsp_flag_ignore_texture_alpha, 0u) &
     pvr_tsp_flag_ignore_texture_alpha) != 0u);
static_assert(
    sonic_ninja_apply_arc1(
        0x808C0028u, 0x9489A4EDu,
        sonic_ninja_basic_translucent_arc1).parameter_control ==
    0x828C000Eu);
static_assert(
    (sonic_ninja_apply_arc1(
         0x808C0028u, 0x9489A4EDu,
         sonic_ninja_basic_translucent_arc1).texture_shading &
     pvr_tsp_flag_ignore_texture_alpha) == 0u);
static_assert(
    sonic_ninja_apply_arc1(
        0x828C000Eu, 0x9491A4EDu,
        sonic_ninja_basic_opaque_arc1).parameter_control == 0x808C000Eu);
static_assert(
    sonic_ninja_apply_arc1(
        0x828C000Eu, 0x9491A4EDu,
        sonic_ninja_basic_opaque_arc1).texture_shading == 0x9489A4EDu);

[[nodiscard]] constexpr bool sonic_ninja_material_uses_texture(
    const std::uint32_t material_control) noexcept {
    return (material_control & ninja_flag_use_texture) != 0u;
}

[[nodiscard]] constexpr bool sonic_ninja_material_uses_alpha(
    const std::uint32_t material_control) noexcept {
    return (material_control & ninja_flag_use_alpha) != 0u;
}

// 0x8C606B96 merges a material into the live PVR TSP packet, but its callers
// subsequently test the unmodified post-ConstantAttr material register for
// UseTexture/UseAlpha.  These exact PAL witnesses keep the two semantic
// domains independent at compile time.
static_assert(
    sonic_ninja_merge_packet_tsp(0x940824EDu, 0x94282400u) == 0x940824EDu);
static_assert(sonic_ninja_material_uses_texture(0x94282400u));
static_assert(sonic_ninja_material_uses_texture(0x9439A400u));
static_assert(sonic_ninja_material_uses_alpha(0x9439A400u));
static_assert(!sonic_ninja_material_uses_alpha(0x94282400u));

