enum class SonicNativeRegionOrdering : std::uint8_t {
    Unbound,
    Other,
    TypeTwoAutoSorted,
    TypeTwoPresorted,
};

[[nodiscard]] constexpr SonicNativeRegionOrdering
sonic_native_type2_region_ordering(
    const std::uint32_t header_word) noexcept {
    return (header_word & sonic_native_type2_presort_bit) == 0u
               ? SonicNativeRegionOrdering::TypeTwoAutoSorted
               : SonicNativeRegionOrdering::TypeTwoPresorted;
}

static_assert(sonic_native_type2_region_ordering(0u) ==
              SonicNativeRegionOrdering::TypeTwoAutoSorted);
static_assert(sonic_native_type2_region_ordering(
                  sonic_native_type2_presort_bit) ==
              SonicNativeRegionOrdering::TypeTwoPresorted);

[[nodiscard]] constexpr bool sonic_native_type2_blend_factor_supported(
    const katana::runtime::NativePortBlendFactor factor) noexcept {
    using Factor = katana::runtime::NativePortBlendFactor;
    return factor == Factor::Zero ||
           factor == Factor::One ||
           factor == Factor::SourceColor ||
           factor == Factor::InverseSourceColor ||
           factor == Factor::DestinationColor ||
           factor == Factor::InverseDestinationColor ||
           factor == Factor::SourceAlpha ||
           factor == Factor::InverseSourceAlpha ||
           factor == Factor::DestinationAlpha ||
           factor == Factor::InverseDestinationAlpha;
}

[[nodiscard]] constexpr bool sonic_native_type2_autosort_semantics(
    const SonicNativeRegionOrdering ordering,
    const std::uint32_t list_type,
    const katana::runtime::NativePortDrawClass draw_class,
    const katana::runtime::NativePortDrawBatchClass batch,
    const katana::runtime::NativePortDepthCoordinateMode depth_mode,
    const bool depth_test,
    const bool depth_write,
    const katana::runtime::NativePortCompareOperation depth_compare,
    const bool blend_enabled,
    const katana::runtime::NativePortBlendFactor source,
    const katana::runtime::NativePortBlendFactor destination) noexcept {
    const bool reciprocal_depth =
        depth_mode ==
            katana::runtime::NativePortDepthCoordinateMode::
                ReciprocalPositive ||
        depth_mode ==
            katana::runtime::NativePortDepthCoordinateMode::
                ReciprocalPositiveHomogeneousClip;
    const bool fixed_function_batch =
        batch == katana::runtime::NativePortDrawBatchClass::Scene3D ||
        batch == katana::runtime::NativePortDrawBatchClass::GameOverlay ||
        batch == katana::runtime::NativePortDrawBatchClass::UiOverlay ||
        batch == katana::runtime::NativePortDrawBatchClass::FontOverlay;
    (void)depth_write;
    return ordering == SonicNativeRegionOrdering::TypeTwoAutoSorted &&
           list_type == 2u &&
           draw_class ==
               katana::runtime::NativePortDrawClass::Translucent &&
           fixed_function_batch && reciprocal_depth && depth_test &&
           depth_compare ==
               katana::runtime::NativePortCompareOperation::GreaterEqual &&
           blend_enabled &&
           sonic_native_type2_blend_factor_supported(source) &&
           sonic_native_type2_blend_factor_supported(destination);
}

static_assert(sonic_native_type2_autosort_semantics(
    SonicNativeRegionOrdering::TypeTwoAutoSorted, 2u,
    katana::runtime::NativePortDrawClass::Translucent,
    katana::runtime::NativePortDrawBatchClass::Scene3D,
    katana::runtime::NativePortDepthCoordinateMode::
        ReciprocalPositiveHomogeneousClip,
    true, false, katana::runtime::NativePortCompareOperation::GreaterEqual,
    true, katana::runtime::NativePortBlendFactor::SourceAlpha,
    katana::runtime::NativePortBlendFactor::InverseSourceAlpha));
