[[nodiscard]] std::uint32_t sonic_native_backing_address(
    const std::uint32_t address) noexcept {
    const auto physical = katana::runtime::canonical_physical_address(address);
    if (physical < katana::runtime::native_port_main_memory_physical_base ||
        physical >= katana::runtime::native_port_main_memory_physical_base +
                        katana::runtime::native_port_main_memory_physical_span)
        return physical;
    return katana::runtime::native_port_main_memory_physical_base +
           ((physical - katana::runtime::native_port_main_memory_physical_base) &
            (katana::runtime::native_port_main_memory_backing_size - 1u));
}

[[nodiscard]] bool sonic_native_same_backing_address(
    const std::uint32_t left,
    const std::uint32_t right) noexcept {
    return left != 0u && right != 0u &&
           sonic_native_backing_address(left) ==
               sonic_native_backing_address(right);
}

[[nodiscard]] constexpr std::uint64_t sonic_native_opaque_identity(
    const std::uint64_t domain,
    const std::uint64_t first,
    const std::uint64_t second = 0u,
    const std::uint64_t third = 0u,
    const std::uint64_t fourth = 0u) noexcept {
    std::uint64_t identity = 1469598103934665603ull;
    const auto mix = [&identity](const std::uint64_t value) {
        identity ^= value;
        identity *= 1099511628211ull;
        identity ^= value >> 32u;
        identity *= 1099511628211ull;
    };
    mix(domain);
    mix(first);
    mix(second);
    mix(third);
    mix(fourth);
    return identity == 0u ? 1u : identity;
}

