// NativeBringup Candidate authority only.  A staged loaded-AOT generation is
// an exact transition witness; it is deliberately not a Product/Proven
// closure claim.  SDK descriptor recycling below requires this complete
// current tuple to remain active and the old descriptor generation either to
// have been released by the SDK or to belong to a retired executable tuple.
struct SonicNativeExecutableTransitionAuthority final {
    std::string module_identity;
    std::uint32_t module_source_start = 0u;
    std::uint32_t module_runtime_start = 0u;
    std::uint32_t module_byte_size = 0u;
    std::uint64_t module_lifecycle_generation = 0u;
    std::uint64_t transition_epoch = 0u;
    bool retired_resource_history = false;
};

struct SonicNativeGuestTextureDescriptor final {
    std::uint32_t descriptor_address = 0u;
    std::uint32_t guest_token = 0u;
    std::uint64_t generation = 0u;
    std::uint64_t transition_epoch = 0u;
    std::array<std::uint32_t, sonic_ninja_texture_descriptor_words>
        previous_words{};
    // Exact pre-commit image.  It differs from previous_words when a retired
    // generation left its publication live: rollback must restore the bytes
    // observed by this transaction, while a later release restores the
    // descriptor state that preceded the original publication.
    std::array<std::uint32_t, sonic_ninja_texture_descriptor_words>
        replaced_words{};
    std::array<std::uint32_t, sonic_ninja_texture_descriptor_words>
        published_words{};
};

// A PVM publication records catalog/ordinal provenance for one live physical
// SDK row. It is not one outstanding SDK reference: repeated acquisition of
// that row increments it without duplicating this alias, and mutable TEXLIST
// releases can decrement a shared row through any alias. The same catalog
// entry can simultaneously back another physical publication created through
// a legacy/set path, so retain one resident payload pin per physical
// publication until that row is freed/displaced. Uncopied archive tails remain
// allocated independently of the destination TEXLIST's M pointers.
struct SonicNativePvmAllocation final {
    std::uint32_t catalog_index = 0u;
    std::uint32_t archive_ordinal = 0u;
    SonicNativeGuestTextureDescriptor descriptor;
};

