class SonicNativeScopedWork final {
  public:
    SonicNativeScopedWork(SonicNativeWorkTelemetry& telemetry,
                          const SonicNativeWorkClass work_class) noexcept
        : telemetry_(telemetry),
          index_(static_cast<std::size_t>(work_class)),
          enabled_(sonic_native_timing_diagnostic_enabled()) {
        if (enabled_) started_ = std::chrono::steady_clock::now();
    }

    ~SonicNativeScopedWork() {
        if (!enabled_) return;
        const auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
                                 std::chrono::steady_clock::now() - started_)
                                 .count();
        if (elapsed <= 0) return;
        const auto nanoseconds = static_cast<std::uint64_t>(elapsed);
        telemetry_.nanoseconds[index_] += nanoseconds;
        telemetry_.maximum_nanoseconds[index_] = std::max(
            telemetry_.maximum_nanoseconds[index_], nanoseconds);
        ++telemetry_.calls[index_];
    }

  private:
    SonicNativeWorkTelemetry& telemetry_;
    std::size_t index_;
    std::chrono::steady_clock::time_point started_{};
    bool enabled_ = false;
};

