[[nodiscard]] bool pretransformed_ui_packet(
    const katana::runtime::NativePortDrawPacket& packet) noexcept {
    // A bound SDK model may publish screen-space vertices without becoming
    // UI. Keep scene packets out of every UI alpha/depth/collapse transaction.
    return packet.batch.semantic != katana::runtime::NativePortDrawBatchClass::Scene3D &&
           packet.viewport ==
               katana::runtime::NativePortViewportTarget::Ui &&
           packet.depth_mapping.mode ==
               katana::runtime::NativePortDepthCoordinateMode::
                   ReciprocalPositive;
}

