struct SonicNativePlatformInterruptState final {
    bool initialized = false;
    // Native status/mask words supplied by an identity-bound host producer.
    // They replace the four ASIC reads in 0x8C645ACE; no A05F* address is
    // ever dereferenced by the product.
    bool event_status_bound = false;
    std::uint32_t primary_status_word = 0u;
    std::uint32_t primary_mask_word = 0u;
    std::uint32_t secondary_status_word = 0u;
    std::uint32_t secondary_mask_word = 0u;
    std::uint64_t event_dispatch_sequence = 0u;
    // Exact title-side projection of IML4NRM. The bootstrap configuration
    // binds its initial zero value and the two isolated instruction hooks
    // below own every later read/write in the audited image. This is one
    // bounded platform value, not a System-ASIC register bank.
    bool iml4_nrm_bound = false;
    std::uint32_t iml4_nrm_value = 0u;
    std::uint64_t iml4_nrm_sequence = 0u;
    std::uint64_t sequence = 0u;
    std::array<SonicNativePlatformInterruptConfiguration,
               sonic_native_platform_interrupt_reset_count>
        intc_resets{};
    std::array<SonicNativePlatformInterruptConfiguration,
               sonic_native_platform_interrupt_entry_count>
        configuration{};
    std::size_t configuration_count = 0u;
    // Slot zero is the null-list sentinel; slots 1..255 are the exact
    // descriptor range scanned by both resident owners.
    std::array<SonicNativePlatformCallbackRegistration,
               sonic_native_platform_callback_slot_count>
        registrations{};
    std::array<std::uint16_t,
               sonic_native_platform_callback_bucket_count>
        bucket_heads{};
    std::uint64_t next_generation = 1u;
    bool special_0900_bound = false;
    bool special_0920_bound = false;
    // Host-side projections of the exact 0x8C653580 transaction. These are
    // bounded state records, never a guest MMIO/device model.
    bool owner_8c653580_bound = false;
    bool owner_8c653580_vector_bound = false;
    std::uint32_t owner_8c653580_vector_target = 0u;
    std::uint32_t owner_8c653580_iml6_nrm = 0u;
    std::uint32_t owner_8c653580_iml6_err = 0u;
    std::uint32_t owner_8c653580_ist_nrm = 0u;
    std::uint32_t owner_8c653580_ist_err = 0u;
    std::uint32_t owner_8c653580_dma_control = 0u;
    std::uint32_t owner_8c653580_dma_control_secondary = 0u;
    std::uint64_t owner_8c653580_sequence = 0u;
    std::array<SonicNativePlatformInterruptHardwarePublication,
               sonic_native_platform_interrupt_owner_publication_count>
        owner_8c653580_publications{};
    std::size_t owner_8c653580_publication_count = 0u;
};

// State-owner/checkpoint transitions rebuild the ordinary interrupt mirror.
// Keep independent bounded projections across those transitions; they are
// native observations, not part of the callback-table checkpoint.
void sonic_native_platform_interrupt_preserve_independent_projections(
    const SonicNativePlatformInterruptState& source,
    SonicNativePlatformInterruptState& destination) noexcept {
    destination.iml4_nrm_bound = source.iml4_nrm_bound;
    destination.iml4_nrm_value = source.iml4_nrm_value;
    destination.iml4_nrm_sequence = source.iml4_nrm_sequence;
    destination.owner_8c653580_bound = source.owner_8c653580_bound;
    destination.owner_8c653580_vector_bound =
        source.owner_8c653580_vector_bound;
    destination.owner_8c653580_vector_target =
        source.owner_8c653580_vector_target;
    destination.owner_8c653580_iml6_nrm = source.owner_8c653580_iml6_nrm;
    destination.owner_8c653580_iml6_err = source.owner_8c653580_iml6_err;
    destination.owner_8c653580_ist_nrm = source.owner_8c653580_ist_nrm;
    destination.owner_8c653580_ist_err = source.owner_8c653580_ist_err;
    destination.owner_8c653580_dma_control =
        source.owner_8c653580_dma_control;
    destination.owner_8c653580_dma_control_secondary =
        source.owner_8c653580_dma_control_secondary;
    destination.owner_8c653580_sequence = source.owner_8c653580_sequence;
    destination.owner_8c653580_publications =
        source.owner_8c653580_publications;
    destination.owner_8c653580_publication_count =
        source.owner_8c653580_publication_count;
}

