thread_local SonicNativeTitleState sonic_native_title_state;

[[nodiscard]] bool sonic_render_completion_experiment_enabled() noexcept {
    static const bool enabled = [] {
        const auto* flag = std::getenv("SARECOMP_RENDER_COMPLETION_EXPERIMENT");
        const auto* background = std::getenv("KATANA_PORT_BACKGROUND_TEST");
        return flag && std::string_view(flag) == "1" &&
               background && std::string_view(background) == "1";
    }();
    return enabled;
}

[[nodiscard]] bool sonic_sixty_frame_interactive_requested() noexcept {
    static const bool requested=[] {
        const auto* flag=std::getenv("SARECOMP_SIXTY_FRAME_INTERACTIVE");
        const auto* saves=std::getenv("KATANA_USER_DATA_ROOT");
        return flag && std::string_view(flag)=="1" && saves && *saves;
    }();
    return requested;
}

[[nodiscard]] bool sonic_sixty_frame_matrix_requested() noexcept {
    static const bool requested=[] {
        const auto* flag=std::getenv("SARECOMP_SIXTY_FRAME_MATRIX");
        const auto* hidden=std::getenv("KATANA_PORT_BACKGROUND_TEST");
        return flag && std::string_view(flag)=="1" && hidden && std::string_view(hidden)=="1";
    }();
    return requested;
}

[[nodiscard]] bool sonic_sixty_frame_fixture_enabled() noexcept {
    static const bool enabled = [] {
        const auto* flag = std::getenv("SARECOMP_SIXTY_FRAME_FIXTURE");
        const auto* background = std::getenv("KATANA_PORT_BACKGROUND_TEST");
        const auto* probe = std::getenv("KATANA_SONIC_GAMEPLAY_PROBE");
        const auto* scenario = std::getenv("KATANA_SONIC_PRIVATE_SCENARIO");
        return flag && std::string_view(flag)=="1" &&
            ((background && std::string_view(background)=="1") ||
                sonic_sixty_frame_interactive_requested()) &&
            probe && std::string_view(probe)=="1" &&
            scenario && (std::string_view(scenario)=="emerald-coast" ||
                sonic_sixty_frame_matrix_requested());
    }();
    return enabled;
}

// Direct experimental/game.exe uses the user-accepted gameplay path. The
// original cadence is a restart-only option, without touching r354. Keep the
// environment override for matched diagnostic runs.
[[nodiscard]] bool sonic_standard_sixty_enabled() noexcept {
    static const bool enabled=[] {
        const auto* original=std::getenv("SARECOMP_ORIGINAL_CADENCE");
        return sonic::presentation::settings().gameplay_timing==1u &&
            (!original || std::string_view(original)!="1");
    }();
    return enabled && !sonic_sixty_frame_fixture_enabled();
}

[[nodiscard]] bool sonic_native_gameplay_math_active() noexcept {
    static const bool retained = sonic_native_diagnostic_enabled("SARECOMP_GAMEPLAY_MATH_RETAINED");
    if (retained) return false;
    const auto& state=sonic_native_title_state;
    return state.original_gameplay_math_active ||
        (sonic_standard_sixty_enabled() && state.standard_sixty_active) ||
        (sonic_sixty_frame_fixture_enabled() && state.gameplay_probe.active &&
         state.gameplay_probe.sixty_frame_configured);
}

[[nodiscard]] bool sonic_native_gameplay_math_defaults_enabled() noexcept {
    // Original selects the title clock, not the slow translated math owners.
    // Preserve explicit leaf selection in the older private 60-Hz fixture.
    return !sonic_sixty_frame_fixture_enabled();
}

// These leaf families authenticate their own code, CPU/FPU mode and complete
// memory effects. Their semantics do not depend on scene or video cadence.
// Keep the wider callback-bearing collision owners on the gameplay gate.
[[nodiscard]] bool sonic_native_leaf_math_active() noexcept {
    static const bool retained = sonic_native_diagnostic_enabled("SARECOMP_GAMEPLAY_MATH_RETAINED");
    static const bool gameplay_only = sonic_native_diagnostic_enabled("SARECOMP_NATIVE_MATH_GAMEPLAY_ONLY");
    if (retained) return false;
    return (gameplay_only || sonic_sixty_frame_fixture_enabled())
        ? sonic_native_gameplay_math_active() : true;
}

[[nodiscard]] bool sonic_native_collision_owner_active() noexcept {
    // These complete owners retain their own code, memory and callback
    // admission. Compare their scene-independent semantics separately from
    // the historical gameplay-only policy; never change the title clock.
    static const bool all_scenes =
        sonic::native_cpu::enabled("SARECOMP_NATIVE_COLLISION_ALL_SCENES");
    return all_scenes ? sonic_native_leaf_math_active()
                      : sonic_native_gameplay_math_active();
}

// These tests publish synthetic gamepad snapshots inside the hidden process;
// they never send OS keys, move focus, or write into a personal save namespace.
[[nodiscard]] unsigned sonic_hidden_transition_mode() noexcept {
    static const unsigned mode=[] {
        const auto* value=std::getenv("SARECOMP_HIDDEN_TRANSITION_TEST");
        const auto* hidden=std::getenv("KATANA_PORT_BACKGROUND_TEST");
        const auto* isolated=std::getenv("SARECOMP_BENCHMARK_ISOLATED_INPUT");
        const auto* saves=std::getenv("KATANA_USER_DATA_ROOT");
        if (!hidden || std::string_view(hidden)!="1" || !value ||
            !isolated || std::string_view(isolated)!="1" || !saves || !*saves) return 0u;
        return std::string_view(value)=="pause-quit" ? 1u :
            std::string_view(value)=="level-switch" ? 2u : 0u;
    }();
    return mode;
}

// The experiment owns cadence only while its measured stage owns gameplay.
// A later cutscene/loader request is authoritative and must never be a crash.
void handoff_sonic_sixty_frame_fixture(katana::runtime::NativePortContext& context,
    const char* reason, bool restore_cadence) noexcept {
    auto& state=sonic_native_title_state;
    auto& probe=state.gameplay_probe;
    if (!sonic_sixty_frame_fixture_enabled() || !probe.sixty_frame_configured) return;
    state.sixty_restore_cadence_pending=restore_cadence;
    probe.sixty_frame_configured=false;
    probe.active=false;
    probe.queued=false;
    probe.complete=true;
    probe.interrupted=false;
    state.scenario_frame_boundary_deadline_nanoseconds=0u;
    std::cerr << "SONIC_SIXTY_FRAME_HANDOFF reason=" << reason
        << " frame=" << context.frame_index << " restore=" << restore_cadence << '\n';
}

[[nodiscard]] sonic::render_completion::Channel* sonic_guest_render_channel(
    const std::string_view owner) noexcept {
    if (!sonic_render_completion_experiment_enabled() ||
        !sonic_native_title_state.periodic_clock_initialized) return nullptr;
    return owner == "frame-begin" || owner == "frame-turnover" ||
           owner == "kamui-drain" || owner == "movie-handoff"
        ? &sonic_native_title_state.render_completions : nullptr;
}

void bind_sonic_native_video_refresh(const std::uint32_t rate_hz,
                                    const char* const owner,
                                    const std::uint64_t frame) noexcept {
    auto& state = sonic_native_title_state;
    state.active_video_refresh_hz = rate_hz;
    state.active_video_refresh_owner = owner;
    state.active_video_refresh_frame = frame;
    state.frame_producer_next_deadline_nanoseconds = 0u;
    state.frame_producer_deferred_deadline_nanoseconds = 0u;
    state.frame_producer_deadline_remainder = 0u;
}

void note_texlist_bind_diagnostic(
    const katana::runtime::NativePortContext& context,
    const std::uint32_t texlist_address) noexcept {
    // Keep only the last real bind as cheap numeric provenance. Formatting and
    // capture remain opt-in or failure-only; selector observations are separate.
    auto& state = sonic_native_title_state;
    ++state.diagnostic_texlist_bind_sequence;
    if (state.diagnostic_texlist_bind_sequence == 0u)
        state.diagnostic_texlist_bind_sequence = 1u;
    state.diagnostic_texlist_bind_pc =
        context.cpu != nullptr ? context.cpu->active_instruction_pc : 0u;
    state.diagnostic_texlist_bind_pr =
        context.cpu != nullptr ? context.cpu->pr : 0u;
    state.diagnostic_texlist_bind_address = texlist_address;
}

void configure_native_texture_registry_write_trace() noexcept {
    auto& state = sonic_native_title_state;
    state.texture_registry_write_trace_requested =
        sonic_native_diagnostic_enabled(
            "KATANA_SONIC_TEXTURE_REGISTRY_WRITE_TRACE");
    state.texture_registry_write_trace_start_frame = 0u;
    state.texture_registry_write_trace_end_frame =
        std::numeric_limits<std::uint32_t>::max();
    if (!state.texture_registry_write_trace_requested) return;

    const auto start = sonic_native_canonical_diagnostic_u32(
        "KATANA_SONIC_TEXTURE_REGISTRY_WRITE_TRACE_START_FRAME");
    const auto end = sonic_native_canonical_diagnostic_u32(
        "KATANA_SONIC_TEXTURE_REGISTRY_WRITE_TRACE_END_FRAME");
    if ((start.present && !start.value.has_value()) ||
        (end.present && !end.value.has_value())) {
        state.texture_registry_write_trace_requested = false;
        std::cerr << "SONIC_NATIVE_TEXTURE_REGISTRY_WRITE_TRACE armed=0"
                     " failure=invalid-frame-window\n";
        return;
    }
    state.texture_registry_write_trace_start_frame =
        start.value.value_or(0u);
    state.texture_registry_write_trace_end_frame = end.value.value_or(
        std::numeric_limits<std::uint32_t>::max());
    if (state.texture_registry_write_trace_end_frame <
        state.texture_registry_write_trace_start_frame) {
        state.texture_registry_write_trace_requested = false;
        std::cerr << "SONIC_NATIVE_TEXTURE_REGISTRY_WRITE_TRACE armed=0"
                     " failure=descending-frame-window\n";
    }
}

