// The frame prepare and wait-tail functions are statically recompiled title
// services. The former post-service was positively identified as the complete
// 24-slot SDK peripheral updater; native input replaces that whole semantic
// family below instead of retaining its Maple/device descendants as AOT.
constexpr std::uint32_t sonic_frame_prepare_service = 0x8C055B32u;

// The event and recap frontends publish dynamic text through 055C20's
// eight-context queue. Observe that existing RAM contract around 055B32;
// never advance a timer, enqueue text or replace the guest message service.
void trace_sonic_native_text_progress(
    katana::runtime::NativePortContext& context, const bool after_service) noexcept {
    static const bool enabled = sonic_native_diagnostic_enabled(
        "KATANA_SONIC_DIAGNOSTIC_TEXT_PROGRESS");
    if (!enabled || context.cpu == nullptr) return;
    static std::array<std::uint32_t, 8u> queued_contexts{};
    static std::uint32_t queued_count = 0u;
    static std::uint32_t reports = 0u;
    constexpr std::uint32_t maximum_reports = 256u;
    if (reports >= maximum_reports) return;
    try {
        SonicGuestReader reader(*context.cpu);
        std::uint32_t count = 0u, timer = 0u, delta = 0u;
        if (!reader.valid() || !reader.u32(0x8C788B74u, count) ||
            !reader.u32(0x8C752B28u, timer) ||
            !reader.u32(0x8C754E04u, delta)) return;
        if (!after_service) {
            queued_count = std::min(
                count, static_cast<std::uint32_t>(queued_contexts.size()));
            for (std::uint32_t index = 0u; index < queued_count; ++index)
                if (!reader.u32(0x8C788B54u + index * 4u, queued_contexts[index]))
                    queued_contexts[index] = 0u;
        }
        // Retain a sparse heartbeat when no further text is submitted. The
        // upload records alone cannot distinguish a stopped caller/timer
        // from a stale native texture view after a successful submission.
        if (queued_count == 0u &&
            (after_service || context.frame_index % 150u != 0u)) return;
        const auto record_count = std::max(queued_count, 1u);
        for (std::uint32_t index = 0u;
             index < record_count && reports < maximum_reports; ++index) {
            const auto queue_address = queued_count == 0u ? 0u : queued_contexts[index];
            // 055B58 loads queue[0] once; 055BAA advances that context by
            // 0x3C. Keep the independently enqueued pointer as evidence too.
            const auto service_address = queued_count == 0u ? 0ull :
                static_cast<std::uint64_t>(queued_contexts[0u]) + index * 60u;
            const auto address = service_address <= 0xFFFFFFFFull
                ? static_cast<std::uint32_t>(service_address) : 0u;
            std::array<std::uint32_t, 15u> words{};
            std::uint32_t valid = 0u;
            if (address != 0u && reader.range(address, words.size() * 4u)) {
                for (std::size_t word = 0u; word < words.size(); ++word)
                    if (reader.u32(address + static_cast<std::uint32_t>(word * 4u),
                                   words[word])) valid |= 1u << word;
            }
            // 055A66 publishes u16 POT dimensions at +10/+12 and clears
            // exactly 2*width*height bytes. Hash the full usual 64-KiB text
            // bitmap; larger observations have an explicit 1-MiB cap.
            const auto width = words[2u] >> 16u;
            const auto height = words[3u] & 0xFFFFu;
            const auto pixel_bytes = 2ull * width * height;
            constexpr std::size_t pixel_cap = 1024u * 1024u;
            const auto probe_bytes = static_cast<std::size_t>(
                std::min<std::uint64_t>(pixel_bytes, pixel_cap));
            bool pixels_valid = (valid & 0x10Cu) == 0x10Cu &&
                width >= 8u && height >= 8u &&
                (width & (width - 1u)) == 0u &&
                (height & (height - 1u)) == 0u && words[8u] != 0u &&
                reader.range(words[8u], static_cast<std::size_t>(pixel_bytes));
            std::array<std::uint8_t, 4096u> pixels{};
            std::uint64_t pixel_hash = 1469598103934665603ull;
            std::size_t hashed_bytes = 0u;
            while (pixels_valid && hashed_bytes < probe_bytes) {
                const auto amount = std::min(pixels.size(), probe_bytes - hashed_bytes);
                pixels_valid = reader.copy_bytes(
                    words[8u] + static_cast<std::uint32_t>(hashed_bytes),
                    std::span<std::uint8_t>(pixels.data(), amount));
                if (!pixels_valid) break;
                for (std::size_t byte = 0u; byte < amount; ++byte) {
                    pixel_hash ^= pixels[byte];
                    pixel_hash *= 1099511628211ull;
                }
                hashed_bytes += amount;
            }
            const auto descriptor = (valid & (1u << 14u)) != 0u ? words[14u] : 0u;
            std::array<std::uint32_t, 17u> descriptor_words{};
            std::uint32_t descriptor_valid = 0u;
            if (descriptor != 0u && reader.range(descriptor, descriptor_words.size() * 4u))
                for (std::size_t word = 0u; word < descriptor_words.size(); ++word)
                    if (reader.u32(descriptor + static_cast<std::uint32_t>(word * 4u),
                                   descriptor_words[word])) descriptor_valid |= 1u << word;
            std::cerr << "SONIC_NATIVE_TEXT_PROGRESS version=2 record=" << reports++
                      << " frame=" << context.frame_index
                      << " phase=" << (after_service ? "published" : "queued")
                      << " queue_count=" << count << " timer=" << timer
                      << " delta=" << delta << " queue_context=0x" << std::hex << queue_address
                      << " service_context=0x" << address
                      << " valid=0x" << valid << " words=";
            for (std::size_t word = 0u; word < words.size(); ++word) {
                if (word != 0u) std::cerr << ',';
                std::cerr << words[word];
            }
            std::cerr << std::dec << " width=" << width << " height=" << height
                      << " pixel_bytes=" << pixel_bytes << " hashed_bytes=" << hashed_bytes
                      << " pixels_valid=" << pixels_valid
                      << " hash_complete=" << (pixels_valid && hashed_bytes == pixel_bytes)
                      << " pixel_hash=" << (pixels_valid ? pixel_hash : 0u)
                      << " descriptor_valid=0x" << std::hex << descriptor_valid
                      << " descriptor_words=";
            for (std::size_t word = 0u; word < descriptor_words.size(); ++word) {
                if (word != 0u) std::cerr << ',';
                std::cerr << descriptor_words[word];
            }
            // Read existing cache identities only. Resolving a new host view
            // here would change the very publication path being observed.
            std::cerr << " surfaces=";
            for (const auto& surface : sonic_native_title_state.dynamic_surfaces)
                if (descriptor != 0u && sonic_native_same_backing_address(
                        surface.descriptor_address, descriptor))
                    std::cerr << surface.texture.value << ':' << surface.upload_sequence << ',';
            std::cerr << " views=";
            for (const auto& view : sonic_native_title_state.dynamic_texture_views)
                if (descriptor != 0u && sonic_native_same_backing_address(
                        view.descriptor_address, descriptor))
                    std::cerr << view.texture.value << ':' << view.tsp << ':' << view.tcw << ',';
            std::cerr << std::dec << " upload_sequence="
                      << sonic_native_title_state.texture_upload_sequence << '\n';
        }
    } catch (...) {
        // An unavailable observation never alters the original text path.
    }
}

constexpr std::uint32_t sonic_frame_completion_callback = 0x8C051810u;
constexpr std::uint32_t sonic_frame_wait_tail_service = 0x8C0947E0u;
