struct SonicNativeContentBinding final {
    std::string_view guest_path;
    std::string_view content_path;
    std::string_view byte_identity;
    std::uint64_t byte_size = 0u;
    std::uint64_t extent_lba = 0u;
    std::uint64_t extent_sector_count = 0u;
};

// Generated from the authorized disc's ISO directory.  This table contains
// identities and paths only.  It lets one verified SDK file-loader boundary
// serve every title asset without a GD-ROM device, guessed file identity or
// per-call address hook.
// Keep the element type explicit.  Class-template argument deduction for this
// full-disc inventory asks clang-cl to build one recursive same-type
// conjunction per entry and exceeds its default template-depth limit without
// adding any useful validation: every generated initializer already targets
// this exact aggregate type.
constexpr SonicNativeContentBinding sonic_native_content_bindings[]{
#include "sonic-native-content-index.inc"
};

struct SonicNativeEventAdxEntryBinding final {
    std::uint64_t source_offset = 0u;
    std::uint64_t byte_size = 0u;
    std::string_view byte_identity;
};

struct SonicNativeEventAdxArchiveCatalog final {
    std::string_view content_path;
    std::string_view archive_byte_identity;
    std::span<const SonicNativeEventAdxEntryBinding> entries;
};

#include "sonic-native-event-adx-catalog.inc"

[[nodiscard]] const SonicNativeEventAdxArchiveCatalog*
find_native_event_adx_catalog(
    const SonicNativeContentBinding& content) noexcept {
    const auto match = std::ranges::find_if(
        sonic_native_event_adx_archives,
        [&content](const auto& candidate) {
            return candidate.content_path == content.content_path &&
                   candidate.archive_byte_identity == content.byte_identity;
        });
    return match == sonic_native_event_adx_archives.end() ? nullptr : &*match;
}

