extern "C" katana::runtime::NativePortHookResult
sonic_native_ninja_cull_value(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return graphics_abort(sonic_native_graphics_error_context);

    // Complete SDK/NINJA cull-value owner.  The displaced implementation
    // cleared the sign bit of fr4, published the resulting finite float to
    // the legacy PVR cull register and returned zero.  Preserve that
    // renderer-level value without exposing a register bank or accepting a
    // raw MMIO write in the native product.
    const auto magnitude_bits = context.cpu->fr[4] & 0x7FFFFFFFu;
    const auto magnitude = std::bit_cast<float>(magnitude_bits);
    if (!std::isfinite(magnitude))
        return graphics_abort(sonic_native_graphics_error_fog_state);
    sonic_native_title_state.cull_value = magnitude;
    sonic_native_title_state.cull_value_bound = true;
    context.cpu->r[0] = 0u;
    return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
}

[[nodiscard]] katana::runtime::NativePortHookResult
sonic_native_transfer_ring_abort(const std::uint32_t error) noexcept {
    return {katana::runtime::NativePortHookAction::Abort, 0u, error};
}

[[nodiscard]] bool transfer_ring_descriptor_address(
    const std::uint32_t bank,
    const std::uint32_t slot,
    const std::uint32_t field_offset,
    std::uint32_t& address) noexcept {
    if (bank >= sonic_native_transfer_ring_banks ||
        slot >= sonic_native_transfer_ring_slots ||
        field_offset >= sonic_native_transfer_ring_descriptor_stride)
        return false;
    const auto result = static_cast<std::uint64_t>(
        sonic_native_transfer_ring_base) +
                        static_cast<std::uint64_t>(bank) *
                            sonic_native_transfer_ring_bank_stride +
                        static_cast<std::uint64_t>(slot) *
                            sonic_native_transfer_ring_descriptor_stride +
                        field_offset;
    if (result > std::numeric_limits<std::uint32_t>::max()) return false;
    address = static_cast<std::uint32_t>(result);
    return true;
}

[[nodiscard]] bool transfer_ring_layout_valid(
    const SonicGuestReader& reader) noexcept {
    return reader.valid() &&
           reader.range(sonic_native_transfer_ring_globals,
                        sonic_native_transfer_ring_global_bytes) &&
           reader.range(sonic_native_transfer_ring_base,
                        sonic_native_transfer_ring_bytes);
}

[[nodiscard]] bool transfer_ring_read_status(
    const SonicGuestReader& reader,
    const std::uint32_t bank,
    const std::uint32_t slot,
    std::uint32_t& status) noexcept {
    std::uint32_t address = 0u;
    return transfer_ring_descriptor_address(
               bank, slot, sonic_native_transfer_ring_status_offset,
               address) &&
           reader.u32(address, status);
}

[[nodiscard]] bool transfer_ring_all_slots_free(
    const SonicGuestReader& reader) noexcept {
    for (std::uint32_t bank = 0u;
         bank < sonic_native_transfer_ring_banks; ++bank) {
        for (std::uint32_t slot = 0u;
             slot < sonic_native_transfer_ring_slots; ++slot) {
            std::uint32_t status = 0u;
            if (!transfer_ring_read_status(reader, bank, slot, status) ||
                (status & 3u) != 0u)
                return false;
        }
    }
    return true;
}

[[nodiscard]] std::size_t transfer_ring_state_index(
    const std::uint32_t bank,
    const std::uint32_t slot) noexcept {
    return static_cast<std::size_t>(bank) *
               sonic_native_transfer_ring_slots +
           static_cast<std::size_t>(slot);
}

[[nodiscard]] std::uint32_t transfer_ring_target_value(
    const std::uint32_t raw_target) noexcept {
    // The original DAR2 path adds the fixed PVR/TA aperture bias and shifts
    // once. This is an address calculation only; the resulting value is
    // handed to native graphics/content state and never host-dereferenced.
    const auto transformed =
        (static_cast<std::uint64_t>(raw_target) + 0xF0000000ull) << 1u;
    return static_cast<std::uint32_t>(transformed);
}

void reset_native_transfer_ring_state() noexcept {
    auto& ring = sonic_native_title_state.transfer_ring;
    ring = {};
    ring.initialized = true;
    // The displaced owner reads CHCR2 at 0x8C6509E6, but overwrites that dead
    // result before any use. The subsequent writes below are retained in
    // exact order/value as private native state rather than exposing a guest
    // DMAC, System-Bus or QACR register bank.
    ring.sar2 = 0u;
    ring.dar2 = 0u;
    ring.tcr2 = 0u;
    ring.chcr2 = 0x12C0u;
    ring.dmaor = 0x8201u;
    ring.sb_lmmode0 = 0u;
    ring.qacr0 = 16u;
    ring.qacr1 = 16u;
    ring.chcr_policy = 0x1000u;
    sonic_native_title_state.native_transfer_submissions_in_flight = 0u;
}

[[nodiscard]] bool transfer_ring_write_u32(
    katana::runtime::NativePortContext& context,
    const SonicGuestReader& reader,
    const std::uint32_t address,
    const std::uint32_t value) {
    if (!reader.range(address, sizeof(value))) return false;
    katana::runtime::guest_write_u32(
        *context.cpu, address, value, katana::runtime::CodeWriteSource::Copy);
    return true;
}

[[nodiscard]] bool transfer_ring_stack_out_pointer(
    katana::runtime::NativePortContext& context,
    const SonicGuestReader& reader,
    std::uint32_t& pointer) noexcept {
    const auto stack_slot = static_cast<std::uint64_t>(context.cpu->r[15]) +
                            32u;
    if (stack_slot > std::numeric_limits<std::uint32_t>::max()) return false;
    const auto stack_address = static_cast<std::uint32_t>(stack_slot);
    return reader.u32(stack_address, pointer) && pointer != 0u &&
           reader.range(pointer, sizeof(pointer));
}

[[nodiscard]] bool transfer_ring_source_span_valid(
    const SonicGuestReader& reader,
    const std::uint32_t source,
    const std::uint32_t byte_size) noexcept {
    return byte_size != 0u && byte_size <= sonic_native_transfer_ring_max_bytes &&
           (byte_size & 31u) == 0u && reader.range(source, byte_size);
}

[[nodiscard]] bool transfer_ring_supported_flags(
    const std::uint32_t flags) noexcept {
    // Bit 3 selects the bank. No other submit flags have an identity-bound
    // meaning in this provider, so accepting them would silently alter the
    // descriptor/CHCR contract.
    return (flags & ~8u) == 0u;
}

[[nodiscard]] bool transfer_ring_native_handoff(
    SonicNativeTransferDescriptor& descriptor,
    const std::uint32_t bank,
    const std::uint32_t source,
    const std::uint32_t target,
    const std::uint32_t context_value,
    const std::uint32_t byte_size,
    const std::uint32_t flags,
    const std::uint32_t sequence) noexcept {
    if constexpr (!sonic_native_transfer_ring_consumer_bound)
        return false;
    if (bank >= sonic_native_transfer_ring_banks || byte_size == 0u ||
        (byte_size & 31u) != 0u)
        return false;

    auto& ring = sonic_native_title_state.transfer_ring;
    const auto control = bank == 0u ? 0x0241u : 0x02C1u;
    descriptor.source = source;
    descriptor.target = target;
    descriptor.context = context_value;
    descriptor.byte_size = byte_size;
    descriptor.flags = flags;
    descriptor.sequence = sequence;
    descriptor.dma_control = control;
    descriptor.pending = true;

    ring.sar2 = source;
    ring.dar2 = target;
    ring.tcr2 = byte_size >> 5u;
    ring.chcr2 = control;
    ring.chcr_policy = 0x1000u;
    ring.asic_source = source;
    ring.asic_size = byte_size;
    ring.asic_enable = 1u;
    std::atomic_thread_fence(std::memory_order_release);
    return true;
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_transfer_ring_initialize(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return sonic_native_transfer_ring_abort(
            sonic_native_transfer_error_context);
    try {
        SonicGuestReader reader(*context.cpu);
        if (!transfer_ring_layout_valid(reader))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);

        // The authenticated PAL owner publishes its displaced hardware state
        // before touching the ordinary-RAM queue. Keep that ordering in the
        // private native state; no guest register bank is exposed.
        reset_native_transfer_ring_state();

        // This is the complete ordinary-RAM publication order of the
        // resident initializer. Unlike submit/drain, initialization has no
        // consumer or in-flight precondition in the authenticated PAL owner.
        constexpr std::array<std::pair<std::uint32_t, std::uint32_t>, 7u>
            initial_globals{{
                {0x00u, 0u}, {0x04u, 0u}, {0x0Cu, 0u}, {0x10u, 0u},
                {0x08u, 0u}, {0x14u, 7u}, {0x18u, 1u}}};
        for (const auto [offset, value] : initial_globals) {
            if (!transfer_ring_write_u32(
                    context, reader,
                    sonic_native_transfer_ring_globals + offset, value))
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_state);
        }
        for (std::uint32_t slot = 0u;
             slot < sonic_native_transfer_ring_slots; ++slot) {
            std::uint32_t bank0_status = 0u;
            std::uint32_t bank1_status = 0u;
            if (!transfer_ring_descriptor_address(
                    0u, slot, sonic_native_transfer_ring_status_offset,
                    bank0_status) ||
                !transfer_ring_descriptor_address(
                    1u, slot, sonic_native_transfer_ring_status_offset,
                    bank1_status) ||
                !transfer_ring_write_u32(context, reader, bank0_status, 0u) ||
                !transfer_ring_write_u32(context, reader, bank1_status, 8u))
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_state);
        }
        // Preserve the exact architectural exit state of 0x8C6509E0. R13,
        // R15 and PR are restored/preserved by the guest owner and by the
        // FunctionEntry Return hook ABI; the remaining definitions are
        // materialized explicitly instead of relying on caller liveness.
        context.cpu->r[0] = sonic_native_transfer_ring_globals + 0x14u;
        context.cpu->r[1] =
            sonic_native_transfer_ring_base +
            sonic_native_transfer_ring_bank_stride;
        context.cpu->r[2] =
            sonic_native_transfer_ring_base +
            sonic_native_transfer_ring_bank_stride +
            (sonic_native_transfer_ring_slots - 1u) *
                sonic_native_transfer_ring_descriptor_stride;
        context.cpu->r[3] =
            sonic_native_transfer_ring_base +
            (sonic_native_transfer_ring_slots - 1u) *
                sonic_native_transfer_ring_descriptor_stride;
        context.cpu->r[4] = 0u;
        context.cpu->r[5] = sonic_native_transfer_ring_bank_stride;
        context.cpu->r[6] = sonic_native_transfer_ring_bank_stride;
        context.cpu->r[7] = sonic_native_transfer_ring_slots;
        context.cpu->t = true;
        std::atomic_thread_fence(std::memory_order_seq_cst);
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_TRANSFER_RING_INIT failure="
                  << error.what() << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_TRANSFER_RING_INIT "
                     "failure=non-standard-exception\n";
    }
    return sonic_native_transfer_ring_abort(sonic_native_transfer_error_state);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_transfer_ring_reset(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return sonic_native_transfer_ring_abort(
            sonic_native_transfer_error_context);
    try {
        SonicGuestReader reader(*context.cpu);
        if (!transfer_ring_layout_valid(reader) ||
            sonic_native_title_state.native_transfer_submissions_in_flight !=
                0u ||
            !transfer_ring_all_slots_free(reader))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);

        constexpr std::array<std::pair<std::uint32_t, std::uint32_t>, 6u>
            reset_globals{{
                {0x00u, 0u}, {0x04u, 0u}, {0x0Cu, 0u}, {0x10u, 0u},
                {0x14u, 7u}, {0x18u, 7u}}};
        for (const auto [offset, value] : reset_globals) {
            if (!transfer_ring_write_u32(
                    context, reader,
                    sonic_native_transfer_ring_globals + offset, value))
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_state);
        }
        for (std::uint32_t slot = 0u;
             slot < sonic_native_transfer_ring_slots; ++slot) {
            std::uint32_t bank0_status = 0u;
            std::uint32_t bank1_status = 0u;
            if (!transfer_ring_descriptor_address(
                    0u, slot, sonic_native_transfer_ring_status_offset,
                    bank0_status) ||
                !transfer_ring_descriptor_address(
                    1u, slot, sonic_native_transfer_ring_status_offset,
                    bank1_status) ||
                !transfer_ring_write_u32(context, reader, bank0_status, 0u) ||
                !transfer_ring_write_u32(context, reader, bank1_status, 8u))
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_state);
        }
        reset_native_transfer_ring_state();
        context.cpu->r[0] = 0u;
        std::atomic_thread_fence(std::memory_order_seq_cst);
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_TRANSFER_RING_RESET failure="
                  << error.what() << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_TRANSFER_RING_RESET "
                     "failure=non-standard-exception\n";
    }
    return sonic_native_transfer_ring_abort(sonic_native_transfer_error_state);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_transfer_ring_submit(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return sonic_native_transfer_ring_abort(
            sonic_native_transfer_error_context);
    try {
        SonicGuestReader reader(*context.cpu);
        if (!transfer_ring_layout_valid(reader) ||
            !sonic_native_title_state.transfer_ring.initialized ||
            sonic_native_title_state.native_transfers_suspended)
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);

        const auto source = context.cpu->r[5];
        const auto target = context.cpu->r[4];
        const auto byte_size = context.cpu->r[6];
        const auto flags = context.cpu->r[7];
        if (byte_size == 0u) {
            context.cpu->r[0] = 0x103u;
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
        }
        if (!transfer_ring_supported_flags(flags) ||
            !transfer_ring_source_span_valid(reader, source, byte_size))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_contract);

        const auto bank = (flags & 8u) >> 3u;
        std::uint32_t producer = 0u;
        std::uint32_t sequence = 0u;
        const auto producer_address =
            sonic_native_transfer_ring_globals +
            static_cast<std::uint32_t>(bank * sizeof(std::uint32_t));
        if (!reader.u32(producer_address, producer) || producer >=
                sonic_native_transfer_ring_slots ||
            !reader.u32(sonic_native_transfer_ring_globals + 8u, sequence))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);

        std::uint32_t descriptor_address = 0u;
        if (!transfer_ring_descriptor_address(bank, producer, 0u,
                                              descriptor_address))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);
        std::uint32_t status = 0u;
        if (!reader.u32(descriptor_address +
                            sonic_native_transfer_ring_status_offset,
                        status))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);
        if ((status & 3u) != 0u ||
            sonic_native_title_state.native_transfer_submissions_in_flight >=
                sonic_native_transfer_ring_banks *
                    sonic_native_transfer_ring_slots)
            {
                context.cpu->r[0] = 0x100u;
                return {katana::runtime::NativePortHookAction::Return, 0u,
                        0u};
            }

        std::uint32_t out_pointer = 0u;
        if (!transfer_ring_stack_out_pointer(context, reader, out_pointer))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_destination);

        // Do this before any descriptor, out-pointer, producer or sequence
        // publication.  Without a proven native TA/content consumer, a
        // successful enqueue would be indistinguishable from a dropped DMA
        // payload and would leave a partially committed guest queue on the
        // subsequent typed failure.
        if (!sonic_native_transfer_ring_consumer_bound)
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_handoff);

        auto& descriptor = sonic_native_title_state.transfer_ring
                              .descriptors[transfer_ring_state_index(
                                  bank, producer)];
        const auto transformed_target = transfer_ring_target_value(target);

        // Publish descriptor fields in the exact observed order.  r5 is the
        // SAR2/source value; r4 is only the raw DAR2/TA target aperture.
        if (!transfer_ring_write_u32(context, reader, descriptor_address,
                                     sequence) ||
            !transfer_ring_write_u32(context, reader, descriptor_address + 4u,
                                     source) ||
            !transfer_ring_write_u32(context, reader, descriptor_address +
                                         0x0Cu,
                                     target) ||
            !transfer_ring_write_u32(context, reader, descriptor_address +
                                         0x14u,
                                     byte_size) ||
            !transfer_ring_write_u32(context, reader, descriptor_address +
                                         0x18u,
                                     flags | 1u))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);
        std::atomic_thread_fence(std::memory_order_release);
        if (!transfer_ring_write_u32(context, reader, out_pointer,
                                     descriptor_address) ||
            !transfer_ring_write_u32(context, reader, producer_address,
                                     (producer + 1u) & 7u) ||
            !transfer_ring_write_u32(context, reader,
                                     sonic_native_transfer_ring_globals + 8u,
                                     sequence + 1u))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);

        if (!transfer_ring_native_handoff(
                descriptor, bank, source, transformed_target, target, byte_size,
                flags, sequence))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_handoff);
        ++sonic_native_title_state.native_transfer_submissions_in_flight;
        sonic_native_title_state.transfer_ring.producer_indices[bank] =
            (producer + 1u) & 7u;
        sonic_native_title_state.transfer_ring.sequence = sequence + 1u;
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_TRANSFER_RING_SUBMIT failure="
                  << error.what() << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_TRANSFER_RING_SUBMIT "
                     "failure=non-standard-exception\n";
    }
    return sonic_native_transfer_ring_abort(sonic_native_transfer_error_state);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_transfer_ring_drain(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return sonic_native_transfer_ring_abort(
            sonic_native_transfer_error_context);
    try {
        SonicGuestReader reader(*context.cpu);
        if (!transfer_ring_layout_valid(reader) ||
            !sonic_native_title_state.transfer_ring.initialized ||
            !sonic_native_transfer_ring_consumer_bound)
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_handoff);

        std::uint32_t current_slot = 0u;
        std::uint32_t current_bank = 0u;
        if (!reader.u32(sonic_native_transfer_ring_globals + 0x14u,
                        current_slot) ||
            !reader.u32(sonic_native_transfer_ring_globals + 0x18u,
                        current_bank) ||
            current_slot >= sonic_native_transfer_ring_slots ||
            current_bank >= sonic_native_transfer_ring_banks)
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);

        std::uint32_t first_descriptor = 0u;
        if (!transfer_ring_descriptor_address(
                current_bank, current_slot, sonic_native_transfer_ring_status_offset,
                first_descriptor))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);
        std::uint32_t first_status = 0u;
        if (!reader.u32(first_descriptor, first_status) ||
            !transfer_ring_write_u32(context, reader, first_descriptor,
                                     first_status & ~4u))
            return sonic_native_transfer_ring_abort(
                sonic_native_transfer_error_state);

        for (std::uint32_t bank = 0u;
             bank < sonic_native_transfer_ring_banks; ++bank) {
            std::uint32_t slot = 0u;
            if (!reader.u32(sonic_native_transfer_ring_globals +
                                0x0Cu + bank * sizeof(std::uint32_t),
                            slot) ||
                slot >= sonic_native_transfer_ring_slots)
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_state);
            std::uint32_t descriptor_address = 0u;
            if (!transfer_ring_descriptor_address(bank, slot, 0u,
                                                  descriptor_address))
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_state);
            std::uint32_t status = 0u;
            std::uint32_t source = 0u;
            std::uint32_t target = 0u;
            std::uint32_t byte_size = 0u;
            if (!reader.u32(descriptor_address +
                                sonic_native_transfer_ring_status_offset,
                            status) ||
                (status & 3u) != 1u)
                continue;
            if (!reader.u32(descriptor_address + 4u, source) ||
                !reader.u32(descriptor_address + 0x0Cu, target) ||
                !reader.u32(descriptor_address + 0x14u, byte_size) ||
                !transfer_ring_source_span_valid(reader, source, byte_size))
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_contract);

            const auto claimed_status = (status & ~3u) | 2u;
            if (!transfer_ring_write_u32(
                    context, reader,
                    descriptor_address + sonic_native_transfer_ring_status_offset,
                    claimed_status))
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_state);
            auto& descriptor = sonic_native_title_state.transfer_ring
                                  .descriptors[transfer_ring_state_index(bank,
                                                                           slot)];
            if (!transfer_ring_native_handoff(
                    descriptor, bank, source, transfer_ring_target_value(target),
                    target, byte_size, status & ~3u,
                    descriptor.sequence)) {
                static_cast<void>(transfer_ring_write_u32(
                    context, reader,
                    descriptor_address + sonic_native_transfer_ring_status_offset,
                    status));
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_handoff);
            }

            // E4E/E50 publish the current r7/r4 pair: the consumed slot and
            // bank. The next consumer index is committed only after the
            // native handoff succeeds.
            if (!transfer_ring_write_u32(
                    context, reader,
                    sonic_native_transfer_ring_globals + 0x14u, slot) ||
                !transfer_ring_write_u32(
                    context, reader,
                    sonic_native_transfer_ring_globals + 0x18u, bank) ||
                !transfer_ring_write_u32(
                    context, reader,
                    sonic_native_transfer_ring_globals + 0x0Cu +
                        bank * sizeof(std::uint32_t),
                    (slot + 1u) & 7u))
                return sonic_native_transfer_ring_abort(
                    sonic_native_transfer_error_state);

            descriptor.pending = false;
            if (sonic_native_title_state.native_transfer_submissions_in_flight !=
                0u)
                --sonic_native_title_state.native_transfer_submissions_in_flight;
            sonic_native_title_state.transfer_ring.consumer_indices[bank] =
                (slot + 1u) & 7u;
        }
        std::atomic_thread_fence(std::memory_order_seq_cst);
        context.cpu->r[0] = 1u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_TRANSFER_RING_DRAIN failure="
                  << error.what() << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_TRANSFER_RING_DRAIN "
                     "failure=non-standard-exception\n";
    }
    return sonic_native_transfer_ring_abort(sonic_native_transfer_error_state);
}

[[nodiscard]] katana::runtime::NativePortHookResult
set_native_transfer_submission_state(
    katana::runtime::NativePortContext& context,
    const bool suspended) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_transfer_error_context};

    try {
        constexpr std::uint32_t title_transfer_suspended_state = 0x8C7AC800u;
        SonicGuestReader reader(*context.cpu);
        if (!reader.valid() ||
            !reader.range(title_transfer_suspended_state,
                          sizeof(std::uint32_t)))
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_transfer_error_state};

        // The displaced pair iterated four G2 DMA channel registers solely to
        // suspend/resume submission, then published this title-visible word.
        // The native product has no G2 device or channel registers: it keeps
        // the same SDK-level barrier and ordinary-RAM state for all native
        // asset/audio transfers as one atomic provider operation.
        sonic_native_title_state.native_transfers_suspended = suspended;
        katana::runtime::guest_write_u32(
            *context.cpu, title_transfer_suspended_state,
            suspended ? 1u : 0u, katana::runtime::CodeWriteSource::Copy);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_TRANSFER_BARRIER failure=" << error.what()
                  << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_TRANSFER_BARRIER "
                     "failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_transfer_error_state};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_transfer_resume_all(
    katana::runtime::NativePortContext& context) noexcept {
    return set_native_transfer_submission_state(context, false);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_transfer_suspend_all(
    katana::runtime::NativePortContext& context) noexcept {
    return set_native_transfer_submission_state(context, true);
}

[[nodiscard]] katana::runtime::NativePortHookResult
publish_native_transfer_fifo_ready(
    katana::runtime::NativePortContext& context,
    const std::uint32_t displaced_status_mask,
    const bool preserve_status_return) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_transfer_error_context};

    try {
        const auto destination = context.cpu->r[4];
        SonicGuestReader reader(*context.cpu);
        if (!reader.valid() || !reader.range(destination, sizeof(std::uint32_t)))
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_transfer_error_destination};

        // The three displaced SDK leaves exposed SB_FFST bits 0/5 as a
        // boolean "the relevant transfer submission has drained" result.
        // Native content/audio operations are synchronous today, while this
        // counter is the bounded contract for later asynchronous host work.
        // This is a semantic transfer provider, not a System-Bus register.
        const auto ready =
            sonic_native_title_state.native_transfer_submissions_in_flight == 0u;
        katana::runtime::guest_write_u32(
            *context.cpu, destination, ready ? 1u : 0u,
            katana::runtime::CodeWriteSource::Copy);
        // Two wrappers explicitly return zero in their RTS delay slot. The
        // resident helper at 0x8C6044E8 returns the sampled status word, so
        // preserve that ABI as either drained (zero) or the queried busy bit.
        context.cpu->r[0] =
            preserve_status_return && !ready ? displaced_status_mask : 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_TRANSFER_SYNC failure=" << error.what()
                  << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_TRANSFER_SYNC "
                     "failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_transfer_error_state};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_transfer_fifo_ready_raw(
    katana::runtime::NativePortContext& context) noexcept {
    return publish_native_transfer_fifo_ready(context, 0x20u, true);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_transfer_audio_fifo_ready(
    katana::runtime::NativePortContext& context) noexcept {
    return publish_native_transfer_fifo_ready(context, 0x01u, false);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_transfer_fifo_ready(
    katana::runtime::NativePortContext& context) noexcept {
    return publish_native_transfer_fifo_ready(context, 0x20u, false);
}

constexpr std::uint8_t sonic_native_adxt_state_stopped = 0u;
constexpr std::uint8_t sonic_native_adxt_state_decoder_info = 1u;
constexpr std::uint8_t sonic_native_adxt_state_preparing = 2u;
constexpr std::uint8_t sonic_native_adxt_state_playing = 3u;
constexpr std::uint8_t sonic_native_adxt_state_decode_end = 4u;
constexpr std::uint8_t sonic_native_adxt_state_play_end = 5u;
constexpr std::uint32_t sonic_native_audio_output_sample_rate = 44'100u;

katana::runtime::NativePortAudioCommandStamp
sonic_native_audio_command_stamp(void* const user) noexcept {
    const auto* const context =
        static_cast<const katana::runtime::NativePortContext*>(user);
    return {context != nullptr ? context->frame_index : 0u, 0u};
}
constexpr std::uint32_t sonic_native_adxt_wrapper_bytes = 0x6Eu;
constexpr std::uint32_t sonic_native_adxt_volume_offset = 0x40u;

[[nodiscard]] SonicNativeAdxStream* native_adx_stream(
    const std::uint32_t guest_handle) noexcept {
    const auto match = std::ranges::find_if(
        sonic_native_title_state.adx_streams,
        [guest_handle](const SonicNativeAdxStream& stream) {
            return stream.bound && stream.guest_handle == guest_handle;
        });
    return match == sonic_native_title_state.adx_streams.end()
               ? nullptr
               : &*match;
}

void release_native_adx_voice(SonicNativeAdxStream& stream) {
    if (!stream.voice.has_value()) return;
    if (sonic_native_title_state.audio_status)
        sonic_native_title_state.audio_status->unwatch(*stream.voice);
    if (sonic_native_title_state.audio_engine) {
        sonic_native_title_state.audio_engine->stop(*stream.voice);
        sonic_native_title_state.audio_engine->release(*stream.voice);
    }
    stream.voice.reset();
}

void clear_native_adx_streams() {
    for (auto& stream : sonic_native_title_state.adx_streams) {
        release_native_adx_voice(stream);
        stream = {};
    }
}

[[nodiscard]] SonicNativeAdxStream& available_native_adx_stream_slot(
    const std::uint32_t guest_handle) {
    if (auto* const existing = native_adx_stream(guest_handle))
        return *existing;
    const auto free = std::ranges::find_if(
        sonic_native_title_state.adx_streams,
        [](const SonicNativeAdxStream& stream) { return !stream.bound; });
    if (free == sonic_native_title_state.adx_streams.end())
        throw std::runtime_error("native-adx-stream-limit");
    return *free;
}

[[nodiscard]] float native_adx_output_gain(const std::int16_t volume) {
    // CRI's ADXT output volume is a signed tenth-decibel attenuation.  Sonic
    // initializes its standalone stereo player to -10 (one decibel). Positive
    // gain and attenuation below -96 dB are outside the proven title contract.
    if (volume > 0 || volume < -960)
        throw std::runtime_error("native-adx-volume-range");
    return std::pow(10.0f, static_cast<float>(volume) / 200.0f);
}

[[nodiscard]] katana::runtime::NativePortAudioVoiceConfig
native_adx_voice_config(
    katana::runtime::NativePortContext& context,
    const katana::runtime::NativePortContentFileBinding& binding,
    const float gain,
    const float pan) {
    const auto metadata = katana::runtime::inspect_native_port_adx_content(
        *context.platform, binding);
    return katana::runtime::native_port_adx_voice_config(
        metadata, sonic_native_audio_output_sample_rate, gain*sonic::audio::factor(sonic::audio::adx_bus(binding.logical_id)), pan);
}

void publish_native_adx_state(katana::runtime::NativePortContext& context,
                              SonicNativeAdxStream& stream,
                              const std::uint8_t state) {
    katana::runtime::guest_write_u8(
        *context.cpu, stream.guest_handle + 1u, state,
        katana::runtime::CodeWriteSource::Copy);
    stream.published_state = state;
}

[[nodiscard]] sonic::audio::StatusPublisher::Status native_adx_snapshot(
    const katana::runtime::NativePortAudioVoiceHandle voice) {
    if (sonic_native_title_state.audio_status)
        return sonic_native_title_state.audio_status->read(voice);
    const auto snapshot = sonic_native_title_state.audio_engine->voice_snapshot(voice);
    return {snapshot.state, snapshot.mixed_output_frames, snapshot.played_output_frames};
}

void synchronize_native_adx_streams(
    katana::runtime::NativePortContext& context) {
    if (!sonic_native_title_state.audio_engine) return;
    for (auto& stream : sonic_native_title_state.adx_streams) {
        if (!stream.bound || !stream.voice.has_value()) continue;
        const auto snapshot = native_adx_snapshot(*stream.voice);
        std::uint8_t state = sonic_native_adxt_state_decoder_info;
        switch (snapshot.state) {
        case katana::runtime::NativePortAudioVoiceState::Ready:
            state = sonic_native_adxt_state_decoder_info;
            break;
        case katana::runtime::NativePortAudioVoiceState::Playing:
            state = sonic_native_adxt_state_playing;
            break;
        case katana::runtime::NativePortAudioVoiceState::Paused:
            // ADXT pause is a player substate; the public decoder state stays
            // PLAYING while its time counter is stationary.
            state = sonic_native_adxt_state_playing;
            break;
        case katana::runtime::NativePortAudioVoiceState::Completed:
            state = snapshot.played_output_frames <
                            snapshot.mixed_output_frames
                        ? sonic_native_adxt_state_decode_end
                        : sonic_native_adxt_state_play_end;
            break;
        case katana::runtime::NativePortAudioVoiceState::Stopped:
            state = sonic_native_adxt_state_stopped;
            break;
        case katana::runtime::NativePortAudioVoiceState::Failed:
            throw std::runtime_error("native-adx-decoder-failed");
        }
        if (state != stream.published_state) {
            publish_native_adx_state(context, stream, state);
            std::cerr << "SONIC_NATIVE_ADX state="
                      << static_cast<unsigned>(state)
                      << " content=" << stream.guest_path;
            if (stream.archive_entry !=
                std::numeric_limits<std::uint32_t>::max())
                std::cerr << " afs_entry=" << stream.archive_entry
                          << " source_offset=" << stream.source_offset
                          << " bytes=" << stream.byte_size;
            std::cerr << '\n';
        }
    }
}

void ensure_native_title_audio(
    katana::runtime::NativePortContext& context) {
    if (context.platform == nullptr)
        throw std::runtime_error("native-audio-platform-missing");
    if (!sonic_native_title_state.audio_engine &&
        sonic_native_title_state.sound_bank_engine)
        throw std::runtime_error("native-audio-backend-invariant");

    // Build both dependent providers off to the side.  The sound-bank engine
    // stores a reference to this exact audio backend, so neither object may be
    // published until both constructors and endpoint initialization succeed.
    std::unique_ptr<katana::runtime::NativePortAudioEngine> audio_candidate;
    std::unique_ptr<sonic::audio::StatusPublisher> status_candidate;
    if (!sonic_native_title_state.audio_engine) {
        katana::runtime::NativePortAudioEngineConfig audio_config;
        audio_config.output_format = {
            sonic_native_audio_output_sample_rate, 2u};
        audio_config.maximum_voices = 256u;
        audio_config.telemetry = context.telemetry;
        audio_config.command_stamp_source =
            &sonic_native_audio_command_stamp;
        audio_config.command_stamp_user = &context;
        audio_candidate =
            std::make_unique<katana::runtime::NativePortAudioEngine>(
                *context.platform,
                katana::runtime::native_port_ffmpeg_codec_provider(),
                audio_config);
        // NativePortAudioEngine is shared by sound-bank PCM and independent
        // ADXT codec voices.  The host endpoint therefore stays live for the
        // lifetime of the engine; the guest processor gate is applied only in
        // pump_native_title_audio().
        audio_candidate->set_output_paused(false);
    }

    auto* const audio = sonic_native_title_state.audio_engine
                            ? sonic_native_title_state.audio_engine.get()
                            : audio_candidate.get();
    if (audio == nullptr)
        throw std::runtime_error("native-audio-backend-missing");
    if (!sonic_native_title_state.audio_status && sonic::audio::async_status_enabled())
        status_candidate = std::make_unique<sonic::audio::StatusPublisher>(
            *audio, katana::runtime::NativePortAudioEngineConfig{});

    std::unique_ptr<katana::runtime::NativePortSoundBankEngine>
        sound_bank_candidate;
    if (!sonic_native_title_state.sound_bank_engine) {
        katana::runtime::NativePortSoundBankConfig sound_config;
        sound_config.maximum_collections = 256u;
        sound_config.maximum_total_collection_bytes =
            256ull * 1024ull * 1024ull;
        sound_config.maximum_midi_ports = 64u;
        sound_config.effect_kernel_provider =
            sonic::native_qsound_reverb_medium::provider();
        sound_bank_candidate =
            std::make_unique<katana::runtime::NativePortSoundBankEngine>(
                *context.platform, *audio, sound_config);
    }

    if (audio_candidate)
        sonic_native_title_state.audio_engine = std::move(audio_candidate);
    if (status_candidate)
        sonic_native_title_state.audio_status = std::move(status_candidate);
    if (sound_bank_candidate)
        sonic_native_title_state.sound_bank_engine =
            std::move(sound_bank_candidate);
}

void clear_native_title_audio_port_bindings() noexcept {
    for (auto& port : sonic_native_title_state.sound_midi_ports) port.reset();
    for (auto& collection :
         sonic_native_title_state.sound_midi_port_collections)
        collection.reset();
    sonic_native_title_state.sound_midi_port_programs.fill(std::nullopt);
    sonic_native_title_state.sound_active_notes.fill(0u);
    sonic_native_title_state.sound_midi_port_state.fill({});
    for (auto& port : sonic_native_title_state.sound_sequence_ports)
        port.reset();
    for (auto& collection :
         sonic_native_title_state.sound_sequence_port_collections)
        collection.reset();
    sonic_native_title_state.sound_sequence_port_program_banks.fill(
        std::nullopt);
    sonic_native_title_state.sound_sequence_port_sequence_banks.fill(
        std::nullopt);
    sonic_native_title_state.sound_sequence_port_state.fill({});
    sonic_native_title_state.sound_sequence_start_reported.fill(false);
}

void clear_native_title_audio_collection_bindings() noexcept {
    clear_native_title_audio_port_bindings();
    sonic_native_title_state.loaded_sound_collections.clear();
    sonic_native_title_state.current_sound_collection.reset();
    sonic_native_title_state.sound_unit_registrations.fill({});
    sonic_native_title_state.sound_pcm_stream_ring_registrations.fill({});
    sonic_native_title_state.sound_unit_registration_sequence = 0u;
}

void close_native_title_midi_ports() {
    if (sonic_native_title_state.sound_bank_engine) {
        auto& engine = *sonic_native_title_state.sound_bank_engine;
        for (auto& port : sonic_native_title_state.sound_midi_ports)
            if (port.has_value()) engine.close_midi_port(*port);
        for (auto& port : sonic_native_title_state.sound_sequence_ports)
            if (port.has_value()) engine.close_midi_port(*port);
    }
    for (auto& port : sonic_native_title_state.sound_midi_ports) port.reset();
    for (auto& collection :
         sonic_native_title_state.sound_midi_port_collections)
        collection.reset();
    sonic_native_title_state.sound_midi_port_programs.fill(std::nullopt);
    sonic_native_title_state.sound_active_notes.fill(0u);
    sonic_native_title_state.sound_midi_port_state.fill({});
    for (auto& port : sonic_native_title_state.sound_sequence_ports)
        port.reset();
    for (auto& collection :
         sonic_native_title_state.sound_sequence_port_collections)
        collection.reset();
    sonic_native_title_state.sound_sequence_port_program_banks.fill(
        std::nullopt);
    sonic_native_title_state.sound_sequence_port_sequence_banks.fill(
        std::nullopt);
    sonic_native_title_state.sound_sequence_port_state.fill({});
    sonic_native_title_state.sound_sequence_start_reported.fill(false);
}

void reset_native_title_audio_provider() {
    clear_native_adx_streams();
    if (sonic_native_title_state.sound_bank_engine)
        sonic_native_title_state.sound_bank_engine->reset();
    clear_native_title_audio_collection_bindings();
    sonic_native_title_state.native_audio_default_port = 0u;
    sonic_native_title_state.native_audio_default_value = 0u;
    sonic_native_title_state.native_audio_service_sequence = 0u;
    sonic_native_title_state.native_audio_last_pump_frame =
        std::numeric_limits<std::uint64_t>::max();
}

void destroy_native_title_audio_provider() {
    // NativePortSoundBankEngine owns feeds in NativePortAudioEngine.  Tear the
    // dependent engine down first so state replacement can never invoke its
    // destructor through an already destroyed audio backend.
    clear_native_adx_streams();
    if (sonic_native_title_state.sound_bank_engine) {
        sonic_native_title_state.sound_bank_engine->reset();
        clear_native_title_audio_collection_bindings();
        sonic_native_title_state.sound_bank_engine.reset();
    } else {
        clear_native_title_audio_collection_bindings();
    }
    sonic_native_title_state.audio_status.reset();
    sonic_native_title_state.audio_engine.reset();
}

void reset_native_title_audio_provider_fail_closed() noexcept {
    bool provider_reset = true;
    for (auto& stream : sonic_native_title_state.adx_streams) {
        try {
            release_native_adx_voice(stream);
        } catch (...) {
            provider_reset = false;
        }
        stream = {};
    }

    if (sonic_native_title_state.sound_bank_engine) {
        try {
            sonic_native_title_state.sound_bank_engine->reset();
        } catch (...) {
            provider_reset = false;
        }
    }

    if (!provider_reset) {
        // A failed provider reset cannot leave a live handle reachable through
        // the private mirror.  Destroy the dependent backend first; the audio
        // backend destructor then closes any voices the failed reset missed.
        sonic_native_title_state.sound_bank_engine.reset();
        sonic_native_title_state.audio_status.reset();
        sonic_native_title_state.audio_engine.reset();
        sonic_native_title_state.native_audio_foundation_refcount = 0u;
        sonic_native_title_state.native_audio_processor_running = false;
        sonic_native_title_state.native_sound_driver_initialized = false;
        sonic_native_title_state.native_sound_catalog_validated = false;
        sonic_native_title_state.native_audio_control_word = 0u;
    }

    clear_native_title_audio_collection_bindings();
    sonic_native_title_state.native_audio_default_port = 0u;
    sonic_native_title_state.native_audio_default_value = 0u;
    sonic_native_title_state.native_audio_service_sequence = 0u;
    sonic_native_title_state.native_audio_last_pump_frame =
        std::numeric_limits<std::uint64_t>::max();
}

[[nodiscard]] bool native_sound_catalog_validation_requested() noexcept {
#ifdef _MSC_VER
    std::array<char, 8u> value{};
    std::size_t required = 0u;
    return ::getenv_s(&required,
                      value.data(),
                      value.size(),
                      "KATANA_SONIC_VALIDATE_SOUND_CATALOG") == 0 &&
           required == 2u && value.front() == '1';
#else
    const char* const value =
        std::getenv("KATANA_SONIC_VALIDATE_SOUND_CATALOG");
    return value != nullptr && std::string_view(value) == "1";
#endif
}

void validate_native_sound_catalog(
    katana::runtime::NativePortContext& context) {
    if (!sonic_native_title_state.sound_bank_engine ||
        context.platform == nullptr)
        throw std::runtime_error("native-sound-catalog-validator-state");
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    std::uint64_t total_bytes = 0u;
    std::size_t validated = 0u;
    for (const auto& binding : sonic_native::sound_collection_catalog()) {
        katana::runtime::NativePortContentFileBinding content;
        content.logical_id = binding.logical_id;
        content.content_relative_path =
            std::filesystem::path(binding.content_relative_path);
        content.byte_identity = binding.byte_identity;
        content.byte_size = binding.byte_size;
        std::optional<katana::runtime::NativePortSoundCollectionHandle>
            in_flight;
        try {
            in_flight = engine.load_collection(content);
            engine.predecode_collection_samples(*in_flight);
            engine.unload_collection(*in_flight);
            in_flight.reset();
        } catch (...) {
            // Validation is deliberately independent of the ordinary title
            // collection table.  Never leave a failed in-flight collection
            // resident when the hook aborts and the caller may retry.
            if (in_flight.has_value()) {
                try {
                    engine.unload_collection(*in_flight);
                } catch (...) {
                }
            }
            throw;
        }
        total_bytes += binding.byte_size;
        ++validated;
    }
    const auto snapshot = engine.snapshot();
    std::cerr << "SONIC_NATIVE_SOUND_CATALOG validated=" << validated
              << " bytes=" << total_bytes
              << " programs=" << snapshot.parsed_programs
              << " splits=" << snapshot.parsed_splits
              << " sequences=" << snapshot.parsed_sequences
              << " events=" << snapshot.parsed_events
              << " samples=" << snapshot.decoded_samples
              << " pcm16=" << snapshot.decoded_pcm16_samples
              << " pcm8=" << snapshot.decoded_pcm8_samples
              << " adpcm=" << snapshot.decoded_adpcm_samples
              << " sample_frames=" << snapshot.decoded_sample_frames
              << '\n';
}

[[nodiscard]] katana::runtime::NativePortHookResult audio_abort(
    const std::uint32_t error_code,
    const char* const owner,
    const char* const detail = nullptr) noexcept {
    std::cerr << "SONIC_NATIVE_AUDIO_ABORT owner=" << owner << " code=0x"
              << std::hex << error_code << std::dec;
    if (detail != nullptr) std::cerr << " detail=" << detail;
    std::cerr << '\n';
    return {katana::runtime::NativePortHookAction::Abort, 0u, error_code};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_audio_foundation_initialize(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "foundation-initialize";
    if (!valid_sonic_native_context(context) || context.platform == nullptr)
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        // The displaced Manatee owner is a one-time SDK/library boundary.
        // Its positive refcount branch is idempotent; it never creates an
        // additional guest device instance. Preserve that valid lifecycle
        // while rejecting an underflowing shutdown below.
        if (sonic_native_title_state.native_audio_foundation_refcount != 0u) {
            context.cpu->r[0] = 0u;
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
        }

        ensure_native_title_audio(context);
        reset_native_title_audio_provider();
        if (native_sound_catalog_validation_requested() &&
            !sonic_native_title_state.native_sound_catalog_validated) {
            validate_native_sound_catalog(context);
            sonic_native_title_state.native_sound_catalog_validated = true;
            // Validation parses and decodes through the exact product engine,
            // then leaves the ordinary title lifecycle in a pristine state.
            reset_native_title_audio_provider();
        }
        // Do not publish the new lifecycle mirror until the host endpoint has
        // accepted the corresponding resume operation.
        sonic_native_title_state.audio_engine->set_output_paused(false);
        sonic_native_title_state.native_audio_control_word = 0u;
        sonic_native_title_state.native_sound_driver_initialized = false;
        sonic_native_title_state.native_audio_stereo_output = true;
        sonic_native_title_state.native_audio_processor_running = true;
        sonic_native_title_state.native_audio_foundation_refcount = 1u;
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner, "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_audio_foundation_shutdown(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "foundation-shutdown";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        if (sonic_native_title_state.native_audio_foundation_refcount == 0u)
            return audio_abort(
                sonic_native_audio_error_state, owner, "refcount-underflow");

        reset_native_title_audio_provider();
        sonic_native_title_state.sound_bank_engine.reset();
        sonic_native_title_state.audio_status.reset();
        sonic_native_title_state.audio_engine.reset();
        sonic_native_title_state.native_audio_control_word = 0u;
        sonic_native_title_state.native_audio_processor_running = false;
        sonic_native_title_state.native_sound_driver_initialized = false;
        sonic_native_title_state.native_audio_foundation_refcount = 0u;
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner, "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_sound_driver_initialize(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "sound-driver-initialize";
    if (!valid_sonic_native_context(context) || context.platform == nullptr)
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        if (sonic_native_title_state.native_audio_foundation_refcount == 0u)
            return audio_abort(
                sonic_native_audio_error_state, owner, "foundation-missing");
        ensure_native_title_audio(context);
        // Commit the private lifecycle flags only after the host endpoint has
        // accepted the resume operation.
        sonic_native_title_state.audio_engine->set_output_paused(false);
        sonic_native_title_state.native_audio_processor_running = true;
        sonic_native_title_state.native_sound_driver_initialized = true;
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner, "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_sound_output_mode_initialize(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "sound-output-mode";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        if (!sonic_native_title_state.native_sound_driver_initialized)
            return audio_abort(
                sonic_native_audio_error_state, owner, "driver-missing");

        // Katana owns the host output layout. Preserve the final ordinary-RAM
        // command mirror (0x8A, stereo=0) consumed by title diagnostics while
        // never constructing or submitting a Manatee/AICA packet.
        katana::runtime::guest_write_u32(
            *context.cpu, 0x8C890540u, 0x8Au,
            katana::runtime::CodeWriteSource::Copy);
        katana::runtime::guest_write_u8(
            *context.cpu, 0x8C890544u, 0u,
            katana::runtime::CodeWriteSource::Copy);
        sonic_native_title_state.native_audio_stereo_output = true;
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner, "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_sound_port_table_initialize(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "sound-port-table";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        if (!sonic_native_title_state.sound_bank_engine ||
            !sonic_native_title_state.native_sound_driver_initialized)
            return audio_abort(
                sonic_native_audio_error_state, owner, "driver-missing");
        close_native_title_midi_ports();
        katana::runtime::guest_write_u32(
            *context.cpu, 0x8C1C18ECu, 0u,
            katana::runtime::CodeWriteSource::Copy);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_port, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_port, owner, "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_audio_defaults(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "audio-defaults";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        if (!sonic_native_title_state.native_sound_driver_initialized)
            return audio_abort(
                sonic_native_audio_error_state, owner, "driver-missing");
        const auto port = static_cast<std::int8_t>(context.cpu->r[4] & 0xFFu);
        const auto value = static_cast<std::int8_t>(context.cpu->r[5] & 0xFFu);
        if (port < 0 || value < 0)
            return audio_abort(
                sonic_native_audio_error_control, owner, "negative-argument");

        sonic_native_title_state.native_audio_default_port =
            static_cast<std::uint8_t>(port);
        sonic_native_title_state.native_audio_default_value =
            static_cast<std::uint8_t>(value);
        // Preserve the final command mirror after the original owner's two
        // synchronous submissions. No guest command queue remains live.
        katana::runtime::guest_write_u32(
            *context.cpu, 0x8C89052Cu, 0x82u,
            katana::runtime::CodeWriteSource::Copy);
        katana::runtime::guest_write_u8(
            *context.cpu, 0x8C890530u,
            static_cast<std::uint8_t>(value),
            katana::runtime::CodeWriteSource::Copy);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner, "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_audio_service(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "audio-service";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        // The historical server returned immediately before driver startup.
        // Once active, synchronous native pumping replaces its scheduler and
        // command-service chain. Publish equal monotone service epochs into
        // the two ordinary-RAM mirrors, proving that no deferred guest task
        // remains outstanding.
        if (sonic_native_title_state.native_sound_driver_initialized)
            pump_native_title_audio(context);
        if (sonic_native_title_state.native_sound_driver_initialized &&
            sonic_native_title_state.native_audio_processor_running) {
            if (sonic_native_title_state.native_audio_service_sequence !=
                std::numeric_limits<std::uint64_t>::max())
                ++sonic_native_title_state.native_audio_service_sequence;
            const auto published = static_cast<std::uint32_t>(
                sonic_native_title_state.native_audio_service_sequence);
            katana::runtime::guest_write_u32(
                *context.cpu, 0x8C8905B8u, published,
                katana::runtime::CodeWriteSource::Copy);
            katana::runtime::guest_write_u32(
                *context.cpu, 0x8C8905BCu, published,
                katana::runtime::CodeWriteSource::Copy);
        }
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner, "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_sound_frame_service(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "sound-frame-service";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        // This whole-function provider replaces the SDK's per-tick Manatee
        // server. High-level collection, sequence, MIDI and ADX hooks have
        // already published all semantic work to the native engines; pumping
        // them here replaces the old command, scheduler and AICA wave-RAM
        // subtree. The six surviving words are duration/profiling mirrors,
        // not device state. Native service completion is immediate and
        // deterministic in guest time, so publish zero elapsed ticks.
        if (sonic_native_title_state.native_sound_driver_initialized)
            pump_native_title_audio(context);
        for (const auto address :
             sonic_native_sound_frame_duration_mirrors) {
            katana::runtime::guest_write_u32(
                *context.cpu, address, 0u,
                katana::runtime::CodeWriteSource::Copy);
        }
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner,
            "non-standard-exception");
    }
}

[[nodiscard]] katana::runtime::NativePortSoundCollectionHandle
activate_native_sound_collection_units(
    katana::runtime::NativePortSoundCollectionHandle collection);

class SonicNativeSoundProviderReset final : public std::runtime_error {
  public:
    SonicNativeSoundProviderReset()
        : std::runtime_error("native-sound-provider-reset") {}
};

class SonicNativeSoundPlayCommandRejected final : public std::runtime_error {
  public:
    SonicNativeSoundPlayCommandRejected()
        : std::runtime_error("native-sound-program-not-in-active-bank") {}
};

[[nodiscard]] katana::runtime::NativePortSoundCollectionHandle
load_native_sound_collection(
    katana::runtime::NativePortContext& context,
    const std::string_view title_path) {
    const auto binding =
        sonic_native::find_sound_collection_by_title_path(title_path);
    if (!binding.has_value()) {
        // 0938F0 ignores a failed SDK file open/read, then reparses the
        // unchanged MLT staging buffer. Preserve its last successful semantic
        // owner, not a filename alias (EV0072 requests an absent e_0072.mlt).
        // A present file with missing catalog coverage, failed identity load,
        // or absent/stale previous collection remains an actual error.
        const auto path = normalize_guest_content_path(title_path);
        const auto current = sonic_native_title_state.current_sound_collection;
        if (!path || !path->ends_with(".MLT") || find_native_content_binding(*path) != nullptr ||
            !current || !sonic_native_title_state.sound_bank_engine)
            throw std::runtime_error("native-sound-content-path");
        const SonicNativeLoadedSoundCollection* owner = nullptr;
        for (const auto& loaded : sonic_native_title_state.loaded_sound_collections) {
            if (loaded.handle.slot != current->slot || loaded.handle.generation != current->generation) continue;
            if (owner != nullptr) throw std::runtime_error("native-sound-buffer-owner-ambiguous");
            owner = &loaded;
        }
        const auto catalog = sonic_native::sound_collection_catalog();
        if (owner == nullptr || owner->catalog_index >= catalog.size() ||
            catalog[owner->catalog_index].catalog_index != owner->catalog_index)
            throw std::runtime_error("native-sound-buffer-owner-unbound");
        // This operation validates the collection generation before any unit
        // publication and re-applies the original sparse bank overlay.
        const auto result = activate_native_sound_collection_units(*current);
        std::cerr << "SONIC_NATIVE_SOUND_MISSING_REUSE requested=" << *path
                  << " retained=" << catalog[owner->catalog_index].content_relative_path << '\n';
        return result;
    }
    ensure_native_title_audio(context);
    if (native_sound_catalog_validation_requested() &&
        !sonic_native_title_state.native_sound_catalog_validated) {
        validate_native_sound_catalog(context);
        sonic_native_title_state.native_sound_catalog_validated = true;
        reset_native_title_audio_provider();
    }
    const auto existing = std::ranges::find_if(
        sonic_native_title_state.loaded_sound_collections,
        [&](const SonicNativeLoadedSoundCollection& loaded) {
            return loaded.catalog_index == binding->catalog_index;
        });
    if (existing !=
        sonic_native_title_state.loaded_sound_collections.end()) {
        if (sonic_native_title_state.current_sound_collection.has_value() &&
            sonic_native_title_state.current_sound_collection->slot ==
                existing->handle.slot &&
            sonic_native_title_state.current_sound_collection->generation ==
                existing->handle.generation)
            return existing->handle;
        const auto previous_current =
            sonic_native_title_state.current_sound_collection;
        const auto previous_registrations =
            sonic_native_title_state.sound_unit_registrations;
        sonic_native_title_state.current_sound_collection = existing->handle;
        try {
            return activate_native_sound_collection_units(existing->handle);
        } catch (const SonicNativeSoundProviderReset&) {
            throw;
        } catch (...) {
            sonic_native_title_state.current_sound_collection =
                previous_current;
            sonic_native_title_state.sound_unit_registrations =
                previous_registrations;
            throw;
        }
    }

    katana::runtime::NativePortContentFileBinding content;
    content.logical_id = binding->logical_id;
    content.content_relative_path =
        std::filesystem::path(binding->content_relative_path);
    content.byte_identity = binding->byte_identity;
    content.byte_size = binding->byte_size;
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    const auto previous_current =
        sonic_native_title_state.current_sound_collection;
    const auto previous_registrations =
        sonic_native_title_state.sound_unit_registrations;
    const auto handle = engine.load_collection(content);
    try {
        sonic_native_title_state.loaded_sound_collections.push_back(
            {binding->catalog_index, handle});
        sonic_native_title_state.current_sound_collection = handle;
        static_cast<void>(activate_native_sound_collection_units(handle));
    } catch (const SonicNativeSoundProviderReset&) {
        throw;
    } catch (...) {
        const auto inserted = std::ranges::find_if(
            sonic_native_title_state.loaded_sound_collections,
            [&](const SonicNativeLoadedSoundCollection& loaded) {
                return loaded.handle.slot == handle.slot &&
                       loaded.handle.generation == handle.generation;
            });
        if (inserted !=
            sonic_native_title_state.loaded_sound_collections.end())
            sonic_native_title_state.loaded_sound_collections.erase(inserted);
        sonic_native_title_state.current_sound_collection = previous_current;
        sonic_native_title_state.sound_unit_registrations =
            previous_registrations;
        try {
            engine.unload_collection(handle);
        } catch (...) {}
        throw;
    }
    std::cerr << "SONIC_NATIVE_SOUND_COLLECTION loaded="
              << binding->content_relative_path << " bytes="
              << binding->byte_size << " active="
              << sonic_native_title_state.loaded_sound_collections.size()
              << '\n';
    return handle;
}

[[nodiscard]] katana::runtime::NativePortSoundCollectionHandle
sound_collection_for_program(const std::uint8_t bank,
                             const std::uint8_t program) {
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    if (bank >= 16u) throw std::runtime_error("native-sound-program-bank-range");
    const auto& registration =
        sonic_native_title_state.sound_unit_registrations[bank];
    if (registration.bound || registration.pending) {
        if (registration.kind !=
                katana::runtime::NativePortSoundCollectionUnitKind::ProgramBank ||
            registration.bank != bank)
            throw std::runtime_error("native-sound-program-not-in-active-bank");
        // The original title wrapper submits program selection to Manatee and
        // does not turn a driver-side program miss into a process stop. Keep
        // this exact, pre-mutation active-owner rejection distinguishable so
        // sound_play can preserve that command-level failure boundary without
        // selecting an older collection which happens to contain the number.
        if (!engine.has_program(registration.collection, bank, program))
            throw SonicNativeSoundPlayCommandRejected();
        return registration.collection;
    }

    std::optional<katana::runtime::NativePortSoundCollectionHandle> match;
    for (const auto& loaded :
         sonic_native_title_state.loaded_sound_collections) {
        if (!engine.has_program(loaded.handle, bank, program)) continue;
        if (match.has_value())
            throw std::runtime_error("native-sound-program-bank-ambiguous");
        match = loaded.handle;
    }
    if (match.has_value()) return *match;
    throw std::runtime_error("native-sound-program-not-resident");
}

[[nodiscard]] katana::runtime::NativePortSoundCollectionHandle
sound_collection_for_sequence(const std::uint8_t bank,
                              const std::uint16_t sequence) {
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    if (bank >= 16u)
        throw std::runtime_error("native-sound-sequence-bank-range");
    const auto& registration =
        sonic_native_title_state.sound_unit_registrations[16u + bank];
    if (registration.bound || registration.pending) {
        if (registration.kind !=
                katana::runtime::NativePortSoundCollectionUnitKind::SequenceBank ||
            registration.bank != bank ||
            !engine.has_sequence(registration.collection, bank, sequence))
            throw std::runtime_error("native-sound-sequence-not-in-active-bank");
        return registration.collection;
    }

    std::optional<katana::runtime::NativePortSoundCollectionHandle> match;
    for (const auto& loaded :
         sonic_native_title_state.loaded_sound_collections) {
        if (!engine.has_sequence(loaded.handle, bank, sequence)) continue;
        if (match.has_value())
            throw std::runtime_error("native-sound-sequence-bank-ambiguous");
        match = loaded.handle;
    }
    if (match.has_value()) return *match;
    throw std::runtime_error("native-sound-sequence-not-resident");
}

[[nodiscard]] std::uint8_t sequence_program_bank_for_collection(
    const katana::runtime::NativePortSoundCollectionHandle collection,
    const std::uint8_t sequence_bank) {
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    if (engine.has_program(collection, 0u, 0u)) return 0u;
    if (engine.has_program(collection, sequence_bank, 0u))
        return sequence_bank;
    throw std::runtime_error("native-sound-sequence-program-not-resident");
}

[[nodiscard]] std::string_view sound_collection_path(
    const katana::runtime::NativePortSoundCollectionHandle handle) noexcept {
    const auto loaded = std::ranges::find_if(
        sonic_native_title_state.loaded_sound_collections,
        [&](const SonicNativeLoadedSoundCollection& candidate) {
            return candidate.handle.slot == handle.slot &&
                   candidate.handle.generation == handle.generation;
        });
    if (loaded == sonic_native_title_state.loaded_sound_collections.end())
        return "<unknown>";
    const auto catalog = sonic_native::sound_collection_catalog();
    if (loaded->catalog_index >= catalog.size()) return "<invalid-catalog>";
    return catalog[loaded->catalog_index].content_relative_path;
}

void refresh_sonic_audio_settings(bool force){
    static thread_local std::uint64_t revision=0;static thread_local bool focused=true;
    const auto next=sonic::presentation::revision();const bool focus=sonic::audio::focused.load();
    if(!force&&revision==next&&focus==focused)return;revision=next;focused=focus;
    auto& s=sonic_native_title_state;
    if(s.audio_engine)for(const auto& v:s.adx_streams)if(v.bound&&v.voice)s.audio_engine->set_gain_pan(*v.voice,v.gain*sonic::audio::factor(sonic::audio::adx_bus(v.guest_path)),v.pan);
    // SoundBank applies current bus gains per note in its audio worker. A
    // container can hold both voices and effects; port-wide scaling would
    // misroute them and multiply master volume twice.
}
void apply_native_sound_port_state(
    const katana::runtime::NativePortSoundMidiPortHandle port,
    const SonicNativeLogicalSoundPortState& state) {
    if (!sonic_native_title_state.sound_bank_engine)
        throw std::runtime_error("native-sound-engine-unbound");
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    engine.set_midi_gain_pan(port, state.gain, state.pan);
    engine.set_midi_pitch_bend(port, state.pitch_bend);
    engine.set_midi_playback_rate(port, state.playback_rate);
    engine.set_midi_send_levels(
        port, state.direct_level, state.effect_level);
}

void commit_native_sound_port_state(
    const std::optional<katana::runtime::NativePortSoundMidiPortHandle>& port,
    SonicNativeLogicalSoundPortState& state,
    const SonicNativeLogicalSoundPortState& candidate) {
    // Keep the private logical mirror unchanged until every native setter has
    // accepted the candidate.  The engine API is fail-closed and may throw on
    // a stale handle or invalid configuration; publishing first would make a
    // later rebind replay a state the native port never received.
    if (port.has_value()) {
        try {
            apply_native_sound_port_state(*port, candidate);
        } catch (...) {
            // The shared engine updates a port through several setters.  If a
            // later setter rejects the candidate, best-effort restore the
            // complete prior logical configuration before propagating the
            // fail-closed error.  If that restore also fails, reset/destroy
            // the provider so no partially configured handle survives.
            bool restored = false;
            try {
                apply_native_sound_port_state(*port, state);
                restored = true;
            } catch (...) {
            }
            if (!restored) reset_native_title_audio_provider_fail_closed();
            throw;
        }
    }
    state = candidate;
}

[[nodiscard]] katana::runtime::NativePortSoundMidiPortConfig
native_sound_port_config(
    const SonicNativeLogicalSoundPortState& state,
    const katana::runtime::NativePortSoundCollectionHandle,
    const std::uint8_t bank = 0u,
    const std::uint8_t program = 0u) noexcept {
    katana::runtime::NativePortSoundMidiPortConfig config;
    config.program_bank = bank;
    config.program = program;
    config.gain = state.gain;
    config.pan = state.pan;
    config.playback_rate = state.playback_rate;
    config.pitch_bend = state.pitch_bend;
    config.direct_level = state.direct_level;
    config.effect_level = state.effect_level;
    return config;
}

[[nodiscard]] std::optional<katana::runtime::NativePortSoundMidiPortHandle>
find_native_midi_port(const std::uint32_t port_index) {
    if (port_index >= sonic_native_title_state.sound_midi_ports.size())
        throw std::runtime_error("native-sound-midi-port-range");
    return sonic_native_title_state.sound_midi_ports[port_index];
}

[[nodiscard]] std::optional<katana::runtime::NativePortSoundMidiPortHandle>
find_native_sequence_port(const std::uint32_t logical_port) {
    constexpr std::uint32_t first_sequence_port = 32u;
    if (logical_port < first_sequence_port ||
        logical_port - first_sequence_port >=
            sonic_native_title_state.sound_sequence_ports.size())
        throw std::runtime_error("native-sound-sequence-port-range");
    return sonic_native_title_state
        .sound_sequence_ports[logical_port - first_sequence_port];
}

[[nodiscard]] katana::runtime::NativePortSoundMidiPortHandle
bind_native_midi_port(const std::uint32_t port_index,
                      const std::uint8_t bank,
                      const std::uint8_t program) {
    if (port_index >= sonic_native_title_state.sound_midi_ports.size() ||
        !sonic_native_title_state.sound_bank_engine)
        throw std::runtime_error("native-sound-midi-port");
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    const auto collection = sound_collection_for_program(bank, program);
    auto& port = sonic_native_title_state.sound_midi_ports[port_index];
    auto& port_collection =
        sonic_native_title_state.sound_midi_port_collections[port_index];
    auto& port_program =
        sonic_native_title_state.sound_midi_port_programs[port_index];
    const auto& state =
        sonic_native_title_state.sound_midi_port_state[port_index];
    const auto authored_program = static_cast<std::uint16_t>(
        (static_cast<std::uint16_t>(bank) << 8u) | program);
    if (port.has_value() && port_collection.has_value() &&
        port_collection->slot == collection.slot &&
        port_collection->generation == collection.generation) {
        if (!port_program.has_value()) {
            reset_native_title_audio_provider_fail_closed();
            throw std::runtime_error("native-sound-midi-program-state");
        }
        if (*port_program == authored_program) return *port;
        const auto previous_bank =
            static_cast<std::uint8_t>(*port_program >> 8u);
        const auto previous_program =
            static_cast<std::uint8_t>(*port_program & 0xFFu);
        try {
            engine.set_midi_program(*port, bank, program);
            apply_native_sound_port_state(*port, state);
        } catch (...) {
            bool restored = false;
            try {
                engine.set_midi_program(
                    *port, previous_bank, previous_program);
                apply_native_sound_port_state(*port, state);
                restored = true;
            } catch (...) {
            }
            if (!restored) reset_native_title_audio_provider_fail_closed();
            throw;
        }
        port_program = authored_program;
        return *port;
    }
    const auto config = native_sound_port_config(state, collection, bank, program);
    const auto candidate = engine.open_midi_port(collection, config);
    if (port.has_value()) {
        try {
            engine.close_midi_port(*port);
        } catch (...) {
            try {
                engine.close_midi_port(candidate);
            } catch (...) {}
            port.reset();
            port_collection.reset();
            port_program.reset();
            sonic_native_title_state.sound_active_notes[port_index] = 0u;
            throw;
        }
    }
    port = candidate;
    port_collection = collection;
    port_program = authored_program;
    sonic_native_title_state.sound_active_notes[port_index] = 0u;
    return *port;
}

[[nodiscard]] katana::runtime::NativePortSoundMidiPortHandle
require_native_midi_port(const std::uint32_t port_index) {
    if (port_index >= sonic_native_title_state.sound_midi_ports.size() ||
        !sonic_native_title_state.sound_midi_ports[port_index].has_value() ||
        !sonic_native_title_state.sound_bank_engine)
        throw std::runtime_error("native-sound-midi-port-unbound");
    return *sonic_native_title_state.sound_midi_ports[port_index];
}

struct SonicNativeBoundSequencePort final {
    katana::runtime::NativePortSoundMidiPortHandle port;
    bool opened = false;
    bool program_changed = false;
    std::uint8_t previous_program_bank = 0u;
};

[[nodiscard]] SonicNativeBoundSequencePort
bind_native_sequence_port(const std::uint32_t logical_port,
                          const std::uint8_t bank,
                          const std::uint16_t sequence) {
    constexpr std::uint32_t first_sequence_port = 32u;
    if (logical_port < first_sequence_port ||
        logical_port - first_sequence_port >=
            sonic_native_title_state.sound_sequence_ports.size() ||
        !sonic_native_title_state.sound_bank_engine)
        throw std::runtime_error("native-sound-sequence-port");
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    const auto collection = sound_collection_for_sequence(bank, sequence);
    const auto program_bank =
        sequence_program_bank_for_collection(collection, bank);
    const auto index = logical_port - first_sequence_port;
    auto& port = sonic_native_title_state.sound_sequence_ports[index];
    auto& port_collection =
        sonic_native_title_state.sound_sequence_port_collections[index];
    auto& bound_program_bank =
        sonic_native_title_state.sound_sequence_port_program_banks[index];
    auto& bound_sequence_bank =
        sonic_native_title_state.sound_sequence_port_sequence_banks[index];
    const auto& state =
        sonic_native_title_state.sound_sequence_port_state[index];
    if (!port.has_value() || !port_collection.has_value() ||
        port_collection->slot != collection.slot ||
        port_collection->generation != collection.generation) {
        const auto candidate = engine.open_midi_port(
            collection, native_sound_port_config(state, collection, program_bank, 0u));
        if (port.has_value()) {
            try {
                engine.close_midi_port(*port);
            } catch (...) {
                try {
                    engine.close_midi_port(candidate);
                } catch (...) {}
                port.reset();
                port_collection.reset();
                bound_program_bank.reset();
                bound_sequence_bank.reset();
                sonic_native_title_state.sound_sequence_port_state[index] = {};
                sonic_native_title_state.sound_sequence_start_reported[index] =
                    false;
                throw;
            }
        }
        port = candidate;
        port_collection = collection;
        bound_program_bank = program_bank;
        bound_sequence_bank.reset();
        return {*port, true, false, 0u};
    } else {
        if (!bound_program_bank.has_value()) {
            reset_native_title_audio_provider_fail_closed();
            throw std::runtime_error("native-sound-sequence-program-state");
        }
        const auto previous_program_bank = *bound_program_bank;
        if (previous_program_bank == program_bank)
            return {*port, false, false, previous_program_bank};
        try {
            engine.set_midi_program(*port, program_bank, 0u);
            apply_native_sound_port_state(*port, state);
        } catch (...) {
            bool restored = false;
            try {
                engine.set_midi_program(*port, previous_program_bank, 0u);
                apply_native_sound_port_state(*port, state);
                restored = true;
            } catch (...) {
            }
            if (!restored) reset_native_title_audio_provider_fail_closed();
            throw;
        }
        bound_program_bank = program_bank;
        return {*port, false, true, previous_program_bank};
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_sound_collection_load(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context) || context.platform == nullptr)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_context};
    try {
        SonicGuestReader reader(*context.cpu);
        const auto path = read_guest_string(reader, context.cpu->r[4], 255u);
        if (!path.has_value())
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_audio_error_content};
        static_cast<void>(load_native_sound_collection(context, *path));
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_SOUND_LOAD failure=" << error.what()
                  << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_SOUND_LOAD failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_audio_error_content};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_adxt_start_file(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "adxt-start-file";
    if (!valid_sonic_native_context(context) || context.platform == nullptr)
        return audio_abort(sonic_native_audio_error_context, owner);
    std::uint64_t lookahead_sequence = 0u;
    try {
        SonicGuestReader reader(*context.cpu);
        const auto guest_handle = context.cpu->r[4];
        if (!reader.valid() || (guest_handle & 3u) != 0u ||
            !reader.range(guest_handle, sonic_native_adxt_wrapper_bytes))
            throw std::runtime_error("native-adx-wrapper-range");
        const auto raw_path = read_guest_string(reader, context.cpu->r[5], 255u);
        const auto normalized = raw_path
                                    ? normalize_guest_content_path(*raw_path)
                                    : std::nullopt;
        const auto* const content = normalized
                                        ? find_native_content_binding(*normalized)
                                        : nullptr;
        if (content == nullptr || !content->guest_path.ends_with(".ADX"))
            throw std::runtime_error("native-adx-content-path");
        const auto lookahead_byte_size =
            content->byte_size <=
                    std::numeric_limits<std::uint32_t>::max()
                ? static_cast<std::uint32_t>(content->byte_size)
                : 0u;

        lookahead_sequence = context.crash_capsule != nullptr
            ? context.crash_capsule->note_v3_lookahead(
                  katana::runtime::CrashCapsuleLookaheadKind::AdxStreamStart,
                  context.cpu->active_instruction_pc, guest_handle,
                  context.cpu->pr, context.cpu->r[5], 0u, 0u,
                  lookahead_byte_size, context.frame_index,
                  content->byte_identity,
                  {context.cpu->r[4], context.cpu->r[5], context.cpu->r[6],
                   context.cpu->r[7]})
            : 0u;

        std::int16_t volume = 0;
        if (!reader.i16(guest_handle + sonic_native_adxt_volume_offset,
                        volume))
            throw std::runtime_error("native-adx-volume-unreadable");
        const auto gain = native_adx_output_gain(volume);
        ensure_native_title_audio(context);
        auto& stream = available_native_adx_stream_slot(guest_handle);
        const auto pan = stream.pan;
        const katana::runtime::NativePortContentFileBinding binding{
            content->guest_path,
            std::filesystem::path(content->content_path),
            content->byte_identity,
            0u,
            content->byte_size};
        const auto config = native_adx_voice_config(
            context, binding, gain, pan);
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Validated);
        std::optional<katana::runtime::NativePortAudioVoiceHandle> replacement =
            sonic_native_title_state.audio_engine->create_voice(binding, config);
        try {
            sonic_native_title_state.audio_engine->play(*replacement);
        } catch (...) {
            sonic_native_title_state.audio_engine->release(*replacement);
            throw;
        }

        // Binding is transactional. A malformed stream or codec failure must
        // never consume one of the eight bounded title slots, and a guest-RAM
        // publication failure must not leave an unreachable native voice.
        try {
            release_native_adx_voice(stream);
            stream = {};
            stream.guest_handle = guest_handle;
            stream.voice = *replacement;
            replacement.reset();
            stream.guest_path = content->guest_path;
            stream.source_offset = 0u;
            stream.byte_size = content->byte_size;
            stream.output_volume = volume;
            stream.gain = gain;
            stream.pan = pan;
            stream.bound = true;
            if (sonic_native_title_state.audio_status)
                sonic_native_title_state.audio_status->watch(*stream.voice);
            publish_native_adx_state(
                context, stream, sonic_native_adxt_state_playing);
            if (context.crash_capsule != nullptr)
                context.crash_capsule->update_v3_lookahead(
                    lookahead_sequence,
                    katana::runtime::CrashCapsuleLookaheadState::Completed);
        } catch (...) {
            if (replacement.has_value()) {
                sonic_native_title_state.audio_engine->stop(*replacement);
                sonic_native_title_state.audio_engine->release(*replacement);
            }
            release_native_adx_voice(stream);
            stream = {};
            throw;
        }
        context.cpu->r[0] = 0u;
        const auto audio_snapshot =
            sonic_native_title_state.audio_engine->snapshot();
        std::array<std::uint32_t, 6u> wrapper_words{};
        bool wrapper_words_valid = true;
        for (std::size_t index = 0u; index < wrapper_words.size(); ++index) {
            if (!reader.u32(
                    guest_handle + static_cast<std::uint32_t>(index * 4u),
                    wrapper_words[index])) {
                wrapper_words_valid = false;
                break;
            }
        }
        std::cerr << "SONIC_NATIVE_ADX start=" << content->content_path
                  << " identity=" << content->byte_identity
                  << " guest_handle=0x" << std::hex << guest_handle
                  << " callsite=0x" << context.cpu->active_instruction_pc
                  << " pr=0x" << context.cpu->pr
                  << " bgm_signature=0x"
                  << sonic_native_title_state.title_audio_trace_signature
                  << std::dec << " bgm_trace="
                  << sonic_native_title_state.title_audio_trace_sequence
                  << " bgm_frame="
                  << sonic_native_title_state.title_audio_trace_frame
                  << " bgm_selection="
                  << sonic_native_title_state.title_audio_trace_selection
                  << " bgm_request=" << static_cast<std::int32_t>(
                         sonic_native_title_state.title_audio_trace_request)
                  << " bgm_mirror=" << static_cast<std::int32_t>(
                         sonic_native_title_state.title_audio_trace_mirror)
                  << " bgm_handles=0x" << std::hex
                  << sonic_native_title_state.title_audio_trace_primary_handle
                  << ",0x"
                  << sonic_native_title_state.title_audio_trace_secondary_handle
                  << std::dec << " voice=" << stream.voice->slot << ':'
                  << stream.voice->generation
                  << " active=" << audio_snapshot.active_voices
                  << " playing=" << audio_snapshot.playing_voices
                  << " queued=" << audio_snapshot.output.queued_frames
                  << " loop=" << (config.loop ? 1 : 0)
                  << " loop_start=" << config.loop_start_frame
                  << " loop_end=" << config.loop_end_frame
                  << " gain=" << config.gain
                  << " wrapper_valid=" << (wrapper_words_valid ? 1 : 0)
                  << " wrapper=";
        for (std::size_t index = 0u; index < wrapper_words.size(); ++index) {
            if (index != 0u) std::cerr << ',';
            std::cerr << "0x" << std::hex << wrapper_words[index];
        }
        std::cerr << std::dec << '\n';
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Cancelled);
        return audio_abort(
            sonic_native_audio_error_content, owner, error.what());
    } catch (...) {
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Cancelled);
        return audio_abort(
            sonic_native_audio_error_content, owner,
            "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_adxt_start_afs(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "adxt-start-afs";
    constexpr std::uint32_t sonic_event_afs_id = 0u;
    if (!valid_sonic_native_context(context) || context.platform == nullptr)
        return audio_abort(sonic_native_audio_error_context, owner);
    std::uint64_t lookahead_sequence = 0u;
    try {
        SonicGuestReader reader(*context.cpu);
        const auto guest_handle = context.cpu->r[4];
        const auto afs_id = context.cpu->r[5];
        const auto entry_index = context.cpu->r[6];
        if (!reader.valid() || (guest_handle & 3u) != 0u ||
            !reader.range(guest_handle, sonic_native_adxt_wrapper_bytes))
            throw std::runtime_error("native-adx-wrapper-range");
        if (afs_id != sonic_event_afs_id)
            throw std::runtime_error("native-adx-afs-id");

        const auto* const content =
            sonic_native_title_state.event_adx_archive;
        if (content == nullptr)
            throw std::runtime_error("native-adx-afs-unbound");
        const auto* const catalog = find_native_event_adx_catalog(*content);
        if (catalog == nullptr || entry_index >= catalog->entries.size())
            throw std::runtime_error("native-adx-afs-entry");
        const auto& entry = catalog->entries[entry_index];
        if (entry.source_offset >
                std::numeric_limits<std::uint32_t>::max() ||
            entry.byte_size > std::numeric_limits<std::uint32_t>::max())
            throw std::runtime_error("native-adx-afs-entry-range");

        lookahead_sequence = context.crash_capsule != nullptr
            ? context.crash_capsule->note_v3_lookahead(
                  katana::runtime::CrashCapsuleLookaheadKind::AdxStreamStart,
                  context.cpu->active_instruction_pc, guest_handle,
                  context.cpu->pr, afs_id, entry_index,
                  static_cast<std::uint32_t>(entry.source_offset),
                  static_cast<std::uint32_t>(entry.byte_size),
                  context.frame_index, entry.byte_identity,
                  {context.cpu->r[4], context.cpu->r[5], context.cpu->r[6],
                   context.cpu->r[7]})
            : 0u;

        std::int16_t volume = 0;
        if (!reader.i16(guest_handle + sonic_native_adxt_volume_offset,
                        volume))
            throw std::runtime_error("native-adx-volume-unreadable");
        const auto gain = native_adx_output_gain(volume);
        ensure_native_title_audio(context);
        auto& stream = available_native_adx_stream_slot(guest_handle);
        const auto pan = stream.pan;
        const katana::runtime::NativePortContentFileBinding binding{
            content->guest_path,
            std::filesystem::path(content->content_path),
            entry.byte_identity,
            entry.source_offset,
            entry.byte_size};
        const auto config = native_adx_voice_config(
            context, binding, gain, pan);
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Validated);
        std::optional<katana::runtime::NativePortAudioVoiceHandle> replacement =
            sonic_native_title_state.audio_engine->create_voice(binding, config);
        try {
            sonic_native_title_state.audio_engine->play(*replacement);
        } catch (...) {
            sonic_native_title_state.audio_engine->release(*replacement);
            throw;
        }

        try {
            release_native_adx_voice(stream);
            stream = {};
            stream.guest_handle = guest_handle;
            stream.voice = *replacement;
            replacement.reset();
            stream.guest_path = content->guest_path;
            stream.source_offset = entry.source_offset;
            stream.byte_size = entry.byte_size;
            stream.archive_entry = entry_index;
            stream.output_volume = volume;
            stream.gain = gain;
            stream.pan = pan;
            stream.bound = true;
            if (sonic_native_title_state.audio_status)
                sonic_native_title_state.audio_status->watch(*stream.voice);
            publish_native_adx_state(
                context, stream, sonic_native_adxt_state_playing);
            if (context.crash_capsule != nullptr)
                context.crash_capsule->update_v3_lookahead(
                    lookahead_sequence,
                    katana::runtime::CrashCapsuleLookaheadState::Completed);
        } catch (...) {
            if (replacement.has_value()) {
                sonic_native_title_state.audio_engine->stop(*replacement);
                sonic_native_title_state.audio_engine->release(*replacement);
            }
            release_native_adx_voice(stream);
            stream = {};
            throw;
        }

        context.cpu->r[0] = 0u;
        const auto audio_snapshot =
            sonic_native_title_state.audio_engine->snapshot();
        std::cerr << "SONIC_NATIVE_ADX_AFS start=" << content->content_path
                  << " archive_identity=" << content->byte_identity
                  << " afs_id=" << afs_id
                  << " entry=" << entry_index
                  << " source_offset=" << entry.source_offset
                  << " bytes=" << entry.byte_size
                  << " member_identity=" << entry.byte_identity
                  << " guest_handle=0x" << std::hex << guest_handle
                  << " callsite=0x" << context.cpu->active_instruction_pc
                  << " pr=0x" << context.cpu->pr << std::dec
                  << " voice=" << stream.voice->slot << ':'
                  << stream.voice->generation
                  << " active=" << audio_snapshot.active_voices
                  << " playing=" << audio_snapshot.playing_voices
                  << " queued=" << audio_snapshot.output.queued_frames
                  << " loop=" << (config.loop ? 1 : 0)
                  << " gain=" << config.gain << '\n';
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Cancelled);
        return audio_abort(
            sonic_native_audio_error_content, owner, error.what());
    } catch (...) {
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Cancelled);
        return audio_abort(
            sonic_native_audio_error_content, owner,
            "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_adxt_status(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "adxt-status";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        SonicGuestReader reader(*context.cpu);
        const auto guest_handle = context.cpu->r[4];
        if (!reader.valid() || !reader.range(guest_handle, 2u))
            throw std::runtime_error("native-adx-wrapper-range");
        if (auto* const stream = native_adx_stream(guest_handle)) {
            synchronize_native_adx_streams(context);
            context.cpu->r[0] = stream->published_state;
        } else {
            std::uint8_t state = 0u;
            if (!reader.u8(guest_handle + 1u, state))
                throw std::runtime_error("native-adx-state-unreadable");
            context.cpu->r[0] = static_cast<std::uint32_t>(
                static_cast<std::int32_t>(static_cast<std::int8_t>(state)));
        }
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner,
            "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_adxt_time(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "adxt-time";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        SonicGuestReader reader(*context.cpu);
        const auto guest_handle = context.cpu->r[4];
        const auto counter_address = context.cpu->r[5];
        const auto frequency_address = context.cpu->r[6];
        if (!reader.valid() || (guest_handle & 3u) != 0u ||
            (counter_address & 3u) != 0u ||
            (frequency_address & 3u) != 0u ||
            !reader.range(guest_handle, 2u) ||
            !reader.range(counter_address, sizeof(std::uint32_t)) ||
            !reader.range(frequency_address, sizeof(std::uint32_t)))
            throw std::runtime_error("native-adx-time-range");

        std::uint8_t guest_state = 0u;
        if (!reader.u8(guest_handle + 1u, guest_state))
            throw std::runtime_error("native-adx-state-unreadable");
        std::uint32_t counter = 0u;
        std::uint32_t frequency = 1u;
        if (auto* const stream = native_adx_stream(guest_handle);
            stream != nullptr && stream->voice.has_value()) {
            if (!sonic_native_title_state.audio_engine)
                throw std::runtime_error("native-adx-engine-missing");
            synchronize_native_adx_streams(context);
            const auto snapshot = native_adx_snapshot(*stream->voice);
            if (snapshot.state ==
                katana::runtime::NativePortAudioVoiceState::Failed)
                throw std::runtime_error("native-adx-decoder-failed");
            if (snapshot.state ==
                    katana::runtime::NativePortAudioVoiceState::Playing ||
                snapshot.state ==
                    katana::runtime::NativePortAudioVoiceState::Paused ||
                snapshot.state ==
                    katana::runtime::NativePortAudioVoiceState::Completed) {
                if (snapshot.played_output_frames >
                    std::numeric_limits<std::uint32_t>::max())
                    throw std::runtime_error("native-adx-time-overflow");
                counter = static_cast<std::uint32_t>(
                    snapshot.played_output_frames);
                frequency = sonic_native_audio_output_sample_rate;
            }
        } else if (guest_state == sonic_native_adxt_state_playing ||
                   guest_state == sonic_native_adxt_state_decode_end ||
                   guest_state == sonic_native_adxt_state_play_end) {
            // The original active-state paths dereference displaced decoder
            // objects at handle+4/+12. An unbound native active handle is a
            // closure violation, never permission to re-enter that subtree.
            throw std::runtime_error("native-adx-active-handle-unbound");
        }

        katana::runtime::guest_write_u32(
            *context.cpu, counter_address, counter,
            katana::runtime::CodeWriteSource::Copy);
        katana::runtime::guest_write_u32(
            *context.cpu, frequency_address, frequency,
            katana::runtime::CodeWriteSource::Copy);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner,
            "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_adxt_stop(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "adxt-stop";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        SonicGuestReader reader(*context.cpu);
        const auto guest_handle = context.cpu->r[4];
        if (!reader.valid() || (guest_handle & 3u) != 0u ||
            !reader.range(guest_handle, sonic_native_adxt_wrapper_bytes))
            throw std::runtime_error("native-adx-wrapper-range");
        if (auto* const stream = native_adx_stream(guest_handle)) {
            if (!sonic_native_title_state.audio_engine)
                throw std::runtime_error("native-adx-engine-missing");
            const auto guest_path = stream->guest_path;
            release_native_adx_voice(*stream);
            publish_native_adx_state(
                context, *stream, sonic_native_adxt_state_stopped);
            const auto audio_snapshot =
                sonic_native_title_state.audio_engine->snapshot();
            std::cerr << "SONIC_NATIVE_ADX stop=" << guest_path
                      << " guest_handle=0x" << std::hex << guest_handle
                      << std::dec << " active="
                      << audio_snapshot.active_voices << " playing="
                      << audio_snapshot.playing_voices << " queued="
                      << audio_snapshot.output.queued_frames << '\n';
        } else {
            katana::runtime::guest_write_u8(
                *context.cpu, guest_handle + 1u,
                sonic_native_adxt_state_stopped,
                katana::runtime::CodeWriteSource::Copy);
        }
        // Native StartFname never constructs the displaced Manatee decoder or
        // player objects. Preserve the wrapper-visible stop effects without
        // re-entering those legacy callback chains.
        katana::runtime::guest_write_u32(
            *context.cpu, guest_handle + 8u, 0u,
            katana::runtime::CodeWriteSource::Copy);
        katana::runtime::guest_write_u32(
            *context.cpu, guest_handle + 20u, 0u,
            katana::runtime::CodeWriteSource::Copy);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner,
            "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_adxt_destroy(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "adxt-destroy";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        SonicGuestReader reader(*context.cpu);
        const auto guest_handle = context.cpu->r[4];
        if (!reader.valid() || (guest_handle & 3u) != 0u ||
            !reader.range(guest_handle, sonic_native_adxt_wrapper_bytes))
            throw std::runtime_error("native-adx-wrapper-range");
        std::array<std::uint32_t, 6u> wrapper_words{};
        bool wrapper_words_valid = true;
        for (std::size_t index = 0u; index < wrapper_words.size(); ++index) {
            if (!reader.u32(
                    guest_handle + static_cast<std::uint32_t>(index * 4u),
                    wrapper_words[index])) {
                wrapper_words_valid = false;
                break;
            }
        }
        if (auto* const stream = native_adx_stream(guest_handle)) {
            if (!sonic_native_title_state.audio_engine)
                throw std::runtime_error("native-adx-engine-missing");
            const auto guest_path = stream->guest_path;
            release_native_adx_voice(*stream);
            *stream = {};
            const auto audio_snapshot =
                sonic_native_title_state.audio_engine->snapshot();
            std::cerr << "SONIC_NATIVE_ADX destroy=" << guest_path
                      << " guest_handle=0x" << std::hex << guest_handle
                      << std::dec << " active="
                      << audio_snapshot.active_voices << " playing="
                      << audio_snapshot.playing_voices << " queued="
                      << audio_snapshot.output.queued_frames
                      << " wrapper_valid=" << (wrapper_words_valid ? 1 : 0)
                      << " wrapper=";
            for (std::size_t index = 0u; index < wrapper_words.size();
                 ++index) {
                if (index != 0u) std::cerr << ',';
                std::cerr << "0x" << std::hex << wrapper_words[index];
            }
            std::cerr << std::dec << '\n';
        } else {
            std::cerr << "SONIC_NATIVE_ADX destroy=<unbound>"
                      << " guest_handle=0x" << std::hex << guest_handle
                      << std::dec
                      << " wrapper_valid=" << (wrapper_words_valid ? 1 : 0)
                      << " wrapper=";
            for (std::size_t index = 0u; index < wrapper_words.size();
                 ++index) {
                if (index != 0u) std::cerr << ',';
                std::cerr << "0x" << std::hex << wrapper_words[index];
            }
            std::cerr << std::dec << '\n';
        }
        // Native StartFname owns only the host stream/voice. The PAL destroy
        // owner additionally releases the identity-bound guest wrapper and
        // its allocator-owned members. Skipping that tail leaves the two BGM
        // wrapper slots unavailable after a later cleanup/re-registration
        // cycle. Continue through the original owner after the host resource
        // is gone; its first stop call is safe and idempotent because the
        // native stream record above has already been cleared.
        return {katana::runtime::NativePortHookAction::ContinueOriginal, 0u,
                0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner,
            "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_adxt_output_volume(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "adxt-output-volume";
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        SonicGuestReader reader(*context.cpu);
        const auto guest_handle = context.cpu->r[4];
        if (!reader.valid() || (guest_handle & 3u) != 0u ||
            !reader.range(guest_handle, sonic_native_adxt_wrapper_bytes))
            throw std::runtime_error("native-adx-wrapper-range");
        std::int16_t previous_volume = 0;
        if (!reader.i16(guest_handle + sonic_native_adxt_volume_offset,
                        previous_volume))
            throw std::runtime_error("native-adx-volume-unreadable");
        const auto volume = static_cast<std::int16_t>(
            context.cpu->r[5] & 0xFFFFu);
        const auto gain = native_adx_output_gain(volume);
        const auto write_volume = [&](const std::int16_t value) {
            katana::runtime::guest_write_u16(
                *context.cpu,
                guest_handle + sonic_native_adxt_volume_offset,
                static_cast<std::uint16_t>(value),
                katana::runtime::CodeWriteSource::Copy);
        };
        if (auto* const stream = native_adx_stream(guest_handle)) {
            const auto previous_gain = stream->gain;
            const auto previous_pan = stream->pan;
            if (stream->voice.has_value()) {
                if (!sonic_native_title_state.audio_engine)
                    throw std::runtime_error("native-adx-engine-missing");
                auto& audio = *sonic_native_title_state.audio_engine;
                try {
                    audio.set_gain_pan(*stream->voice, gain*sonic::audio::factor(sonic::audio::adx_bus(stream->guest_path)), stream->pan);
                    write_volume(volume);
                } catch (...) {
                    try {
                        audio.set_gain_pan(
                            *stream->voice, previous_gain*sonic::audio::factor(sonic::audio::adx_bus(stream->guest_path)), previous_pan);
                    } catch (...) {
                    }
                    try {
                        write_volume(previous_volume);
                    } catch (...) {
                    }
                    throw;
                }
            } else {
                write_volume(volume);
            }
            stream->output_volume = volume;
            stream->gain = gain;
        } else {
            write_volume(volume);
        }
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_control, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_control, owner,
            "non-standard-exception");
    }
}

struct SonicNativeSoundUnitLayout final {
    katana::runtime::NativePortSoundCollectionUnitKind kind;
    std::uint32_t bank_limit = 0u;
    std::uint32_t resource_offset = 0u;
    std::uint32_t mirror_offset = 0u;
    std::size_t registration_base = 0u;
};

[[nodiscard]] std::optional<SonicNativeSoundUnitLayout>
sonic_native_sound_unit_layout(const std::uint32_t magic) noexcept {
    using Kind = katana::runtime::NativePortSoundCollectionUnitKind;
    switch (magic) {
    case 0x42504D53u: // SMPB
        return SonicNativeSoundUnitLayout{
            Kind::ProgramBank, 16u, 0x80u, 0x264u, 0u};
    case 0x42534D53u: // SMSB
        return SonicNativeSoundUnitLayout{
            Kind::SequenceBank, 16u, 0x00u, 0x1E4u, 16u};
    case 0x42504653u: // SFPB
        return SonicNativeSoundUnitLayout{
            Kind::EffectProgramBank, 1u, 0x200u, 0x3E4u, 32u};
    case 0x424F4653u: // SFOB
        return SonicNativeSoundUnitLayout{
            Kind::EffectOutputBank, 1u, 0x280u, 0x464u, 33u};
    case 0x57504653u: // SFPW
        return SonicNativeSoundUnitLayout{
            Kind::EffectProgramWork, 1u, 0x288u, 0x46Cu, 34u};
    default:
        return std::nullopt;
    }
}

struct SonicNativeSoundPortRetirement final {
    std::size_t one_shot = 0u;
    std::size_t sequence = 0u;
    std::size_t stale_handles = 0u;
};

[[nodiscard]] bool same_native_sound_collection(
    const katana::runtime::NativePortSoundCollectionHandle lhs,
    const katana::runtime::NativePortSoundCollectionHandle rhs) noexcept {
    return lhs.slot == rhs.slot && lhs.generation == rhs.generation;
}

[[nodiscard]] SonicNativeSoundPortRetirement
retire_native_sound_ports_for_replaced_unit(
    const SonicNativeSoundUnitRegistration& displaced) {
    using Kind = katana::runtime::NativePortSoundCollectionUnitKind;
    SonicNativeSoundPortRetirement retired;
    if ((!displaced.bound && !displaced.pending) ||
        !sonic_native_title_state.sound_bank_engine)
        return retired;

    auto& engine = *sonic_native_title_state.sound_bank_engine;
    const auto matches_displaced_collection =
        [&](const auto& collection) noexcept {
            return collection.has_value() &&
                   same_native_sound_collection(
                       *collection, displaced.collection);
        };
    const auto close_port = [&](auto& port) {
        if (!port.has_value()) return;
        try {
            engine.close_midi_port(*port);
        } catch (const katana::runtime::NativePortSoundBankError& error) {
            if (error.failure() !=
                katana::runtime::NativePortSoundBankFailure::InvalidHandle) {
                std::cerr << "SONIC_NATIVE_SOUND_BANK_RETIRE failure="
                          << error.what() << '\n';
                reset_native_title_audio_provider_fail_closed();
                throw SonicNativeSoundProviderReset{};
            }
            // A stale generation is already retired from the engine.  Clear
            // the private mirror regardless; activation must never restore a
            // displaced or unprovable handle through the outer load rollback.
            ++retired.stale_handles;
        } catch (...) {
            std::cerr << "SONIC_NATIVE_SOUND_BANK_RETIRE "
                         "failure=non-standard-exception\n";
            reset_native_title_audio_provider_fail_closed();
            throw SonicNativeSoundProviderReset{};
        }
        port.reset();
    };

    if (displaced.kind == Kind::ProgramBank) {
        for (std::size_t index = 0u;
             index < sonic_native_title_state.sound_midi_ports.size();
             ++index) {
            auto& collection =
                sonic_native_title_state.sound_midi_port_collections[index];
            if (!matches_displaced_collection(collection)) continue;
            auto& program =
                sonic_native_title_state.sound_midi_port_programs[index];
            if (program.has_value() &&
                static_cast<std::uint8_t>(*program >> 8u) != displaced.bank)
                continue;
            close_port(sonic_native_title_state.sound_midi_ports[index]);
            collection.reset();
            program.reset();
            sonic_native_title_state.sound_active_notes[index] = 0u;
            ++retired.one_shot;
        }
    }

    if (displaced.kind != Kind::ProgramBank &&
        displaced.kind != Kind::SequenceBank)
        return retired;

    for (std::size_t index = 0u;
         index < sonic_native_title_state.sound_sequence_ports.size();
         ++index) {
        auto& collection =
            sonic_native_title_state.sound_sequence_port_collections[index];
        if (!matches_displaced_collection(collection)) continue;
        const auto& selected_bank =
            displaced.kind == Kind::ProgramBank
                ? sonic_native_title_state
                      .sound_sequence_port_program_banks[index]
                : sonic_native_title_state
                      .sound_sequence_port_sequence_banks[index];
        if (selected_bank.has_value() &&
            *selected_bank != displaced.bank)
            continue;
        close_port(sonic_native_title_state.sound_sequence_ports[index]);
        collection.reset();
        sonic_native_title_state.sound_sequence_port_program_banks[index]
            .reset();
        sonic_native_title_state.sound_sequence_port_sequence_banks[index]
            .reset();
        sonic_native_title_state.sound_sequence_start_reported[index] = false;
        ++retired.sequence;
    }
    return retired;
}

[[nodiscard]] katana::runtime::NativePortSoundCollectionHandle
activate_native_sound_collection_units(
    const katana::runtime::NativePortSoundCollectionHandle collection) {
    if (!sonic_native_title_state.sound_bank_engine)
        throw std::runtime_error("native-sound-engine-unbound");
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    constexpr std::array unit_magics{
        0x42504D53u, // SMPB
        0x42534D53u, // SMSB
        0x42504653u, // SFPB
        0x424F4653u, // SFOB
        0x57504653u, // SFPW
    };
    // Loading an MLT is a sparse overlay, not a replacement of the complete
    // Manatee bank namespace.  Only units which actually exist in the new,
    // generation-bound collection supersede the active owner for that slot.
    // Retaining every other exact registration is required by authored
    // routes such as the Egg Carrier demo: E_001B publishes bank 6 while its
    // one-shot effects continue to use resident bank 5 from EGGCARRIER.
    // Zero-sized placeholder units are deliberately ignored by
    // has_collection_unit(), so they can never erase a live semantic owner.
    std::array<std::optional<SonicNativeSoundUnitRegistration>, 35u>
        candidates{};
    std::size_t available = 0u;
    for (const auto magic : unit_magics) {
        const auto layout = sonic_native_sound_unit_layout(magic);
        if (!layout.has_value())
            throw std::runtime_error("native-sound-unit-layout");
        for (std::uint32_t bank = 0u; bank < layout->bank_limit; ++bank) {
            if (!engine.has_collection_unit(
                    collection, layout->kind,
                    static_cast<std::uint8_t>(bank)))
                continue;
            const auto slot = layout->registration_base + bank;
            if (slot >=
                sonic_native_title_state.sound_unit_registrations.size())
                throw std::runtime_error("native-sound-unit-slot-overflow");
            SonicNativeSoundUnitRegistration candidate;
            candidate.kind = layout->kind;
            candidate.collection = collection;
            candidate.bank = bank;
            candidate.pending = true;
            candidates[slot] = candidate;
            ++available;
        }
    }

    std::size_t replaced = 0u;
    SonicNativeSoundPortRetirement retired;
    for (std::size_t slot = 0u; slot < candidates.size(); ++slot) {
        if (!candidates[slot].has_value()) continue;
        auto& registration =
            sonic_native_title_state.sound_unit_registrations[slot];
        if (registration.bound || registration.pending) {
            ++replaced;
            if (!same_native_sound_collection(
                    registration.collection, collection)) {
                const auto current =
                    retire_native_sound_ports_for_replaced_unit(registration);
                retired.one_shot += current.one_shot;
                retired.sequence += current.sequence;
                retired.stale_handles += current.stale_handles;
            }
        }
        registration = *candidates[slot];
    }
    const auto retained = static_cast<std::size_t>(std::ranges::count_if(
        sonic_native_title_state.sound_unit_registrations,
        [&](const SonicNativeSoundUnitRegistration& registration) {
            return (registration.bound || registration.pending) &&
                   (registration.collection.slot != collection.slot ||
                    registration.collection.generation !=
                        collection.generation);
        }));
    std::cerr << "SONIC_NATIVE_SOUND_BANK_MAP collection="
              << collection.slot << ':' << collection.generation
              << " available=" << available << " retained=" << retained
              << " replaced=" << replaced
              << " retired_one_shot=" << retired.one_shot
              << " retired_sequence=" << retired.sequence
              << " stale_handles=" << retired.stale_handles << '\n';
    return collection;
}

[[nodiscard]] std::optional<katana::runtime::NativePortSoundCollectionHandle>
sound_collection_for_unit(
    const katana::runtime::NativePortSoundCollectionUnitKind kind,
    const std::uint8_t bank) {
    if (!sonic_native_title_state.sound_bank_engine) return std::nullopt;
    auto& engine = *sonic_native_title_state.sound_bank_engine;
    const auto contains = [&](const auto handle) {
        return engine.has_collection_unit(handle, kind, bank);
    };

    // The title loads one MLT and immediately publishes its Manatee unit
    // records.  Bind that registration to the exact just-loaded collection;
    // merely discovering another collection with the same bank must never
    // overwrite the active semantic owner before the guest registration call
    // supplies its resource/mirror/slot tuple below.
    if (sonic_native_title_state.current_sound_collection.has_value() &&
        contains(*sonic_native_title_state.current_sound_collection))
        return sonic_native_title_state.current_sound_collection;

    std::optional<std::size_t> slot;
    switch (kind) {
    case katana::runtime::NativePortSoundCollectionUnitKind::ProgramBank:
        if (bank < 16u) slot = bank;
        break;
    case katana::runtime::NativePortSoundCollectionUnitKind::SequenceBank:
        if (bank < 16u) slot = 16u + bank;
        break;
    case katana::runtime::NativePortSoundCollectionUnitKind::EffectProgramBank:
        if (bank == 0u) slot = 32u;
        break;
    case katana::runtime::NativePortSoundCollectionUnitKind::EffectOutputBank:
        if (bank == 0u) slot = 33u;
        break;
    case katana::runtime::NativePortSoundCollectionUnitKind::EffectProgramWork:
        if (bank == 0u) slot = 34u;
        break;
    case katana::runtime::NativePortSoundCollectionUnitKind::OneShotBank:
    case katana::runtime::NativePortSoundCollectionUnitKind::PcmStreamRing:
        break;
    }
    if (slot.has_value()) {
        const auto& registration =
            sonic_native_title_state.sound_unit_registrations[*slot];
        if (registration.bound || registration.pending)
            return registration.kind == kind && registration.bank == bank &&
                           contains(registration.collection)
                       ? std::optional{registration.collection}
                       : std::nullopt;
    }

    std::optional<katana::runtime::NativePortSoundCollectionHandle> match;
    for (const auto& loaded :
         sonic_native_title_state.loaded_sound_collections) {
        if (!contains(loaded.handle)) continue;
        if (match.has_value()) return std::nullopt;
        match = loaded.handle;
    }
    return match;
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_sound_bank_chunk_register(
    katana::runtime::NativePortContext& context) noexcept {
    constexpr auto owner = "sound-bank-chunk-registration";
    constexpr std::uint32_t manatee_state_pointer = 0x8C67C110u;
    constexpr std::uint32_t manatee_resource_base_field = 0x1C0u;
    constexpr std::uint32_t sound_resource_bytes = 2u * 1024u * 1024u;
    constexpr std::uint32_t status_not_initialized = 0x0D000001u;
    constexpr std::uint32_t status_invalid_bank = 0x08000003u;
    constexpr std::uint32_t status_unsupported_unit = 0x09000001u;
    if (!valid_sonic_native_context(context))
        return audio_abort(sonic_native_audio_error_context, owner);
    try {
        SonicGuestReader reader(*context.cpu);
        std::uint32_t state = 0u;
        if (!reader.valid() || !reader.u32(manatee_state_pointer, state))
            throw std::runtime_error("state-pointer-unreadable");
        if (state == 0u) {
            context.cpu->r[0] = status_not_initialized;
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
        }

        const auto magic = context.cpu->r[4];
        const auto signed_bank = static_cast<std::int8_t>(
            context.cpu->r[5] & 0xFFu);
        constexpr std::uint32_t pcm_stream_ring_magic = 0x52535053u; // SPSR
        const bool pcm_stream_ring = magic == pcm_stream_ring_magic;
        const auto layout = sonic_native_sound_unit_layout(magic);
        if (!layout.has_value() && !pcm_stream_ring) {
            // The native collection parser deliberately supports the full
            // Sonic-authored corpus plus the payloadless SPSR layout. SOSB
            // remains distinct from SMPB and is never guessed as one.
            if (magic == 0x42534F53u) { // SOSB
                std::cerr << "SONIC_NATIVE_SOUND_UNIT unsupported magic=0x"
                          << std::hex << magic << std::dec
                          << " bank=" << static_cast<int>(signed_bank)
                          << " slot0=0x" << std::hex << context.cpu->r[6]
                          << " slot1=0x" << context.cpu->r[7] << std::dec
                          << '\n';
                return audio_abort(
                    sonic_native_audio_error_content, owner,
                    "unsupported-manatee-unit-family");
            }
            context.cpu->r[0] = status_unsupported_unit;
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
        }
        const auto bank_limit = pcm_stream_ring ? 16u : layout->bank_limit;
        if (signed_bank < 0 ||
            static_cast<std::uint32_t>(signed_bank) >= bank_limit) {
            context.cpu->r[0] = status_invalid_bank;
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
        }
        if (!sonic_native_title_state.native_sound_driver_initialized ||
            !sonic_native_title_state.sound_bank_engine)
            return audio_abort(
                sonic_native_audio_error_state, owner, "driver-missing");

        const auto bank = static_cast<std::uint8_t>(signed_bank);
        std::optional<katana::runtime::NativePortSoundCollectionHandle>
            collection;
        if (!pcm_stream_ring) {
            collection = sound_collection_for_unit(layout->kind, bank);
            if (!collection.has_value())
                return audio_abort(
                    sonic_native_audio_error_content, owner,
                    "collection-unit-unbound");
        }

        std::uint32_t resource_base = 0u;
        if (!reader.u32(state + manatee_resource_base_field, resource_base))
            throw std::runtime_error("resource-base-unreadable");
        const auto bank_stride = static_cast<std::uint64_t>(bank) * 8u;
        const auto resource_offset =
            pcm_stream_ring ? 0x180u : layout->resource_offset;
        const auto mirror_offset =
            pcm_stream_ring ? 0x364u : layout->mirror_offset;
        const auto resource_address =
            static_cast<std::uint64_t>(resource_base) +
            resource_offset + bank_stride;
        const auto mirror_address = static_cast<std::uint64_t>(state) +
                                    mirror_offset + bank_stride;
        if (resource_address + 8u > sound_resource_bytes ||
            mirror_address > std::numeric_limits<std::uint32_t>::max() ||
            !reader.range(static_cast<std::uint32_t>(mirror_address), 8u))
            return audio_abort(
                sonic_native_audio_error_state, owner,
                "derived-registration-range");

        const std::array registration_values{
            context.cpu->r[6], context.cpu->r[7]};
        if (!pcm_stream_ring &&
            std::ranges::any_of(registration_values, [](const auto value) {
                return value >= sound_resource_bytes || (value & 3u) != 0u;
            }))
            return audio_abort(sonic_native_audio_error_control,
                               owner,
                               "sound-slot-range");

        std::optional<katana::runtime::NativePortSoundPcmStreamRingHandle>
            pcm_stream_handle;
        if (pcm_stream_ring) {
            pcm_stream_handle =
                sonic_native_title_state.sound_bank_engine
                    ->bind_pcm_stream_ring({
                        bank, registration_values[0], registration_values[1]});
        }

        // These are the only guest-visible side effects after the historical
        // pair of AICA-wave writes. Surviving query APIs read these ordinary
        // mirrors, while native audio consumes the semantic collection/unit
        // binding below.
        katana::runtime::guest_write_u32(
            *context.cpu, static_cast<std::uint32_t>(mirror_address),
            registration_values[0], katana::runtime::CodeWriteSource::Copy);
        katana::runtime::guest_write_u32(
            *context.cpu, static_cast<std::uint32_t>(mirror_address + 4u),
            registration_values[1], katana::runtime::CodeWriteSource::Copy);

        if (pcm_stream_ring) {
            auto& registration = sonic_native_title_state
                                     .sound_pcm_stream_ring_registrations[bank];
            registration = {
                *pcm_stream_handle,
                magic,
                bank,
                static_cast<std::uint32_t>(resource_address),
                static_cast<std::uint32_t>(mirror_address),
                registration_values[0],
                registration_values[1],
                ++sonic_native_title_state.sound_unit_registration_sequence,
                true};
            context.cpu->r[0] = 0u;
            std::cerr << "SONIC_NATIVE_PCM_STREAM_RING registered bank="
                      << static_cast<unsigned>(bank)
                      << " offset=0x" << std::hex << registration_values[0]
                      << " bytes=0x" << registration_values[1]
                      << " resource=0x" << resource_address
                      << " mirror=0x" << mirror_address << std::dec << '\n';
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
        }

        const auto slot = layout->registration_base + bank;
        if (slot >= sonic_native_title_state.sound_unit_registrations.size())
            throw std::runtime_error("registration-slot-overflow");
        auto& registration =
            sonic_native_title_state.sound_unit_registrations[slot];
        registration = {
            layout->kind,
            *collection,
            magic,
            bank,
            static_cast<std::uint32_t>(resource_address),
            static_cast<std::uint32_t>(mirror_address),
            registration_values,
            ++sonic_native_title_state.sound_unit_registration_sequence,
            true,
            false};
        context.cpu->r[0] = 0u;
        std::cerr << "SONIC_NATIVE_SOUND_UNIT registered magic=0x"
                  << std::hex << magic << std::dec
                  << " bank=" << static_cast<unsigned>(bank)
                  << " collection=" << collection->slot
                  << " resource=0x" << std::hex << resource_address
                  << " mirror=0x" << mirror_address << std::dec << '\n';
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        return audio_abort(
            sonic_native_audio_error_state, owner, error.what());
    } catch (...) {
        return audio_abort(
            sonic_native_audio_error_state, owner,
            "non-standard-exception");
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_midi_initialize(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_context};
    try {
        const auto port = context.cpu->r[4];
        const auto bank = context.cpu->r[5];
        const auto program = context.cpu->r[6];
        if (port >= 32u || bank > 15u || program > 127u)
            throw std::runtime_error("native-sound-midi-init-range");
        static_cast<void>(bind_native_midi_port(
            port,
            static_cast<std::uint8_t>(bank),
            static_cast<std::uint8_t>(program)));
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_MIDI_INIT failure=" << error.what() << '\n';
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_audio_error_port};
}

extern "C" katana::runtime::NativePortHookResult sonic_native_midi_volume(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context) || context.cpu->r[4] >= 32u ||
            context.cpu->r[5] > 127u)
            throw std::runtime_error("native-sound-midi-volume-range");
        const auto port_index = context.cpu->r[4];
        auto& state =
            sonic_native_title_state.sound_midi_port_state[port_index];
        auto candidate = state;
        candidate.gain = static_cast<float>(context.cpu->r[5]) / 127.0f;
        commit_native_sound_port_state(
            find_native_midi_port(port_index), state, candidate);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_port};
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_midi_pan(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context))
            throw std::runtime_error("native-sound-midi-pan-context");
        const auto offset = static_cast<std::int32_t>(context.cpu->r[5]);
        if (offset < -64 || offset > 63)
            throw std::runtime_error("native-sound-midi-pan-range");
        const auto port_index = context.cpu->r[4];
        if (port_index >= 32u)
            throw std::runtime_error("native-sound-midi-pan-port");
        const auto pan = offset >= 0
                             ? static_cast<float>(offset) / 63.0f
                             : static_cast<float>(offset) / 64.0f;
        auto& state =
            sonic_native_title_state.sound_midi_port_state[port_index];
        auto candidate = state;
        candidate.pan = pan;
        commit_native_sound_port_state(
            find_native_midi_port(port_index), state, candidate);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_port};
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_midi_pitch(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context))
            throw std::runtime_error("native-sound-midi-pitch-context");
        const auto bend = static_cast<std::int32_t>(context.cpu->r[5]);
        if (bend < -8192 || bend > 8191)
            throw std::runtime_error("native-sound-midi-pitch-range");
        const auto port_index = context.cpu->r[4];
        if (port_index >= 32u)
            throw std::runtime_error("native-sound-midi-pitch-port");
        auto& state =
            sonic_native_title_state.sound_midi_port_state[port_index];
        auto candidate = state;
        candidate.pitch_bend = static_cast<std::int16_t>(bend);
        commit_native_sound_port_state(
            find_native_midi_port(port_index), state, candidate);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_port};
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_midi_note_on(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context) || context.cpu->r[4] >= 32u ||
            context.cpu->r[5] > 127u || context.cpu->r[6] > 127u)
            throw std::runtime_error("native-sound-midi-note-on-range");
        const auto index = context.cpu->r[4];
        const auto port = require_native_midi_port(index);
        sonic::audio::start_note_without_handle(*sonic_native_title_state.sound_bank_engine,
            port,
            static_cast<std::uint8_t>(context.cpu->r[5]),
            static_cast<std::uint8_t>(context.cpu->r[6]));
        sonic_native_title_state.sound_active_notes[index] =
            static_cast<std::uint8_t>(context.cpu->r[5]);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_port};
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_midi_note_off(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context) || context.cpu->r[4] >= 32u)
            throw std::runtime_error("native-sound-midi-note-off-range");
        const auto index = context.cpu->r[4];
        if (const auto port = find_native_midi_port(index); port.has_value()) {
            if (!sonic_native_title_state.sound_bank_engine)
                throw std::runtime_error("native-sound-engine-unbound");
            sonic_native_title_state.sound_bank_engine->midi_note_off(
                *port, sonic_native_title_state.sound_active_notes[index]);
        }
        sonic_native_title_state.sound_active_notes[index] = 0u;
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_port};
    }
}

// Complete title-facing Manatee sound family.  The title multiplexes 32
// one-shot MIDI ports and six sequence ports through these wrappers.  Binding
// the wrappers preserves the game-level bank/program/note/sequence contract
// and makes every lower command-packer/AICA path unreachable by construction.
void note_native_sound_play_failure(
    katana::runtime::NativePortContext& context,
    const std::string_view description) noexcept {
    if (context.crash_capsule == nullptr) return;

    const auto pair = [](const std::uint32_t low,
                         const std::uint32_t high) noexcept {
        return static_cast<std::uint64_t>(low) |
               (static_cast<std::uint64_t>(high) << 32u);
    };
    const auto* const cpu = context.cpu;
    const auto logical_port = cpu != nullptr ? cpu->r[7] : 0u;
    const auto bank = cpu != nullptr ? cpu->r[4] : 0u;
    const auto program = cpu != nullptr ? cpu->r[5] : 0u;

    const SonicNativeSoundUnitRegistration* registration = nullptr;
    if (bank < 16u) {
        const auto slot = logical_port < 32u ? bank : 16u + bank;
        registration =
            &sonic_native_title_state.sound_unit_registrations[slot];
    }

    std::optional<katana::runtime::NativePortSoundCollectionHandle>
        port_collection;
    bool port_bound = false;
    if (logical_port < 32u) {
        port_collection = sonic_native_title_state
                              .sound_midi_port_collections[logical_port];
        port_bound = sonic_native_title_state.sound_midi_ports[logical_port]
                         .has_value();
    } else if (logical_port < 38u) {
        const auto index = logical_port - 32u;
        port_collection = sonic_native_title_state
                              .sound_sequence_port_collections[index];
        port_bound = sonic_native_title_state.sound_sequence_ports[index]
                         .has_value();
    }

    katana::runtime::CrashCapsuleProviderTranscript record;
    record.provider = 0x53415350u; // SASP: Sonic Adventure sound play.
    record.operation = logical_port < 32u ? 1u : 2u;
    record.sequence = context.frame_index;
    record.address = pair(bank, program);
    record.value = logical_port;
    record.source = cpu != nullptr ? cpu->pc : 0u;
    record.callsite = cpu != nullptr ? cpu->pr : 0u;
    record.instruction_runtime_pc =
        cpu != nullptr ? cpu->active_instruction_pc : 0u;
    record.instruction_valid = cpu != nullptr ? 1u : 0u;
    record.provider_identity.assign("sonic-native-sound-play-failure-v1");
    record.source_identity.assign_diagnostic(description);
    if ((record.source_identity.flag_bits() &
         katana::runtime::CrashCapsuleTokenFlagInvalid) != 0u)
        record.source_identity.assign("exception-text-not-token-safe");

    if (registration != nullptr) {
        record.region = static_cast<std::uint32_t>(registration->kind);
        record.result = pair(registration->collection.slot,
                             registration->collection.generation);
        record.flags |= 1u;
        if (registration->bound) record.flags |= 2u;
        if (registration->pending) record.flags |= 4u;
        auto path = sound_collection_path(registration->collection);
        constexpr std::string_view title_prefix = "SONICAD/";
        if (path.starts_with(title_prefix)) path.remove_prefix(title_prefix.size());
        record.target_identity.assign_diagnostic(path);
        if ((record.target_identity.flag_bits() &
             katana::runtime::CrashCapsuleTokenFlagInvalid) != 0u)
            record.target_identity.assign("collection-path-not-token-safe");
    } else {
        record.target_identity.assign("no-registration-slot");
    }
    if (port_collection.has_value()) {
        record.slot = port_collection->slot;
        record.alias = port_collection->generation;
        record.flags |= 8u;
    }
    if (port_bound) record.flags |= 16u;
    if (sonic_native_title_state.current_sound_collection.has_value()) {
        const auto current = *sonic_native_title_state.current_sound_collection;
        record.state = pair(current.slot, current.generation);
        record.flags |= 32u;
    }
    context.crash_capsule->note_v5_provider_transcript(record);
}

extern "C" katana::runtime::NativePortHookResult sonic_native_sound_play(
    katana::runtime::NativePortContext& context) noexcept {
    std::uint64_t lookahead_sequence = 0u;
    try {
        if (!valid_sonic_native_context(context))
            throw std::runtime_error("native-sound-play-context");
        static const bool diagnostic =
            sonic_native_diagnostic_enabled("KATANA_PORT_DIAGNOSTICS") ||
            sonic_native_diagnostic_enabled(
                "KATANA_SONIC_DIAGNOSTIC_SOUND_CALLS");
        const auto logical_port = context.cpu->r[7];
        lookahead_sequence = context.crash_capsule != nullptr
            ? context.crash_capsule->note_v3_lookahead(
                  katana::runtime::CrashCapsuleLookaheadKind::
                      SoundBankCommand,
                  context.cpu->active_instruction_pc, logical_port,
                  context.cpu->pr, 0u, 0u, 0u, 0u, context.frame_index,
                  "sonic-sound-bank-command-v1",
                  {context.cpu->r[4], context.cpu->r[5], context.cpu->r[6],
                   context.cpu->r[7]})
            : 0u;
        if (diagnostic)
            std::cerr << "SONIC_NATIVE_SOUND_PLAY_CALL pc=0x" << std::hex
                      << context.cpu->pc << " pr=0x" << context.cpu->pr
                      << " r4=0x" << context.cpu->r[4] << " r5=0x"
                      << context.cpu->r[5] << " r6=0x" << context.cpu->r[6]
                      << " r7=0x" << context.cpu->r[7] << std::dec << '\n';
        if (logical_port < 32u) {
            // The resident wrapper preserves the original r4/r5/r6 tuple,
            // then calls its lower one-shot initializer as
            // (logical_port, original_r4, original_r5).  Original r6 is not
            // part of this branch's bank/program contract.
            const auto bank = context.cpu->r[4];
            const auto program = context.cpu->r[5];
            if (bank > 15u || program > 127u)
                throw std::runtime_error("native-sound-play-program");
            SonicGuestReader reader(*context.cpu);
            std::uint32_t authored_note = 0u;
            if (!reader.valid() ||
                !reader.u32(0x8C1C18E4u, authored_note) ||
                authored_note > 127u)
                throw std::runtime_error("native-sound-play-note");
            if (context.crash_capsule != nullptr)
                context.crash_capsule->update_v3_lookahead(
                    lookahead_sequence,
                    katana::runtime::CrashCapsuleLookaheadState::Validated);
            const auto port = bind_native_midi_port(
                logical_port,
                static_cast<std::uint8_t>(bank),
                static_cast<std::uint8_t>(program));
            sonic::audio::start_note_without_handle(*sonic_native_title_state.sound_bank_engine,
                    port,
                    static_cast<std::uint8_t>(authored_note),
                    127u);
            sonic_native_title_state.sound_active_notes[logical_port] =
                static_cast<std::uint8_t>(authored_note);
            if (diagnostic) {
                const auto collection = sonic_native_title_state
                                            .sound_midi_port_collections
                                                [logical_port];
                std::cerr << "SONIC_NATIVE_SOUND_PLAY_BOUND kind=note port="
                          << logical_port << " bank=" << bank
                          << " program=" << program
                          << " note=" << authored_note << " collection="
                          << (collection.has_value()
                                  ? sound_collection_path(*collection)
                                  : std::string_view{"<unbound>"})
                          << '\n';
            }
        } else {
            const auto bank = context.cpu->r[4];
            const auto sequence = context.cpu->r[5];
            const auto play_mode = context.cpu->r[6];
            if (logical_port > 37u || bank > 255u || sequence > 255u ||
                play_mode > 15u)
                throw std::runtime_error("native-sound-play-sequence");
            if (context.crash_capsule != nullptr)
                context.crash_capsule->update_v3_lookahead(
                    lookahead_sequence,
                    katana::runtime::CrashCapsuleLookaheadState::Validated);
            const auto sequence_port_index = logical_port - 32u;
            const auto binding = bind_native_sequence_port(
                logical_port,
                static_cast<std::uint8_t>(bank),
                static_cast<std::uint16_t>(sequence));
            const auto port = binding.port;
            const auto rollback_sequence_port = [&]() noexcept {
                if (binding.opened) {
                    try {
                        sonic_native_title_state.sound_bank_engine
                            ->close_midi_port(port);
                    } catch (...) {}
                    sonic_native_title_state
                        .sound_sequence_ports[sequence_port_index]
                        .reset();
                    sonic_native_title_state
                        .sound_sequence_port_collections[sequence_port_index]
                        .reset();
                    sonic_native_title_state
                        .sound_sequence_port_program_banks[sequence_port_index]
                        .reset();
                    sonic_native_title_state
                        .sound_sequence_port_sequence_banks[sequence_port_index]
                        .reset();
                    sonic_native_title_state
                        .sound_sequence_port_state[sequence_port_index] = {};
                    sonic_native_title_state
                        .sound_sequence_start_reported[sequence_port_index] =
                        false;
                    return;
                }
                if (!binding.program_changed) return;
                try {
                    sonic_native_title_state.sound_bank_engine
                        ->set_midi_program(
                            port, binding.previous_program_bank, 0u);
                    sonic_native_title_state
                        .sound_sequence_port_program_banks[sequence_port_index] =
                        binding.previous_program_bank;
                } catch (...) {
                    reset_native_title_audio_provider_fail_closed();
                }
            };
            // The fourth Manatee argument is a bounded playback mode.  It
            // selects command scheduling, not sequence data; native playback
            // always honours the authored loop events embedded in SMSB.
            katana::runtime::NativePortSoundSequenceHandle sequence_handle;
            try {
                sequence_handle =
                    sonic_native_title_state.sound_bank_engine
                        ->midi_play_sequence(
                            port,
                            static_cast<std::uint8_t>(bank),
                            static_cast<std::uint16_t>(sequence),
                            true);
            } catch (...) {
                rollback_sequence_port();
                throw;
            }
            if (!static_cast<bool>(sequence_handle)) {
                rollback_sequence_port();
                throw std::runtime_error("native-sound-sequence-handle");
            }
            sonic_native_title_state
                .sound_sequence_port_sequence_banks[sequence_port_index] =
                static_cast<std::uint8_t>(bank);
            if (diagnostic) {
                const auto collection = sonic_native_title_state
                                            .sound_sequence_port_collections
                                                [sequence_port_index];
                std::cerr
                    << "SONIC_NATIVE_SOUND_PLAY_BOUND kind=sequence port="
                    << logical_port << " bank=" << bank
                    << " sequence=" << sequence << " mode=" << play_mode
                    << " collection="
                    << (collection.has_value()
                            ? sound_collection_path(*collection)
                            : std::string_view{"<unbound>"})
                    << " handle=" << sequence_handle.slot << ':'
                    << sequence_handle.generation << '\n';
            }
            if (!sonic_native_title_state
                     .sound_sequence_start_reported[sequence_port_index]) {
                sonic_native_title_state
                    .sound_sequence_start_reported[sequence_port_index] = true;
                std::cerr << "SONIC_NATIVE_SOUND_SEQUENCE_START port="
                          << logical_port << " bank=" << bank
                          << " sequence=" << sequence
                          << " mode=" << play_mode
                          << " handle=" << sequence_handle.slot << ':'
                          << sequence_handle.generation << '\n';
            }
        }
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Completed);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const SonicNativeSoundPlayCommandRejected& error) {
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Cancelled);
        note_native_sound_play_failure(context, error.what());
        std::cerr << "SONIC_NATIVE_SOUND_PLAY rejected=" << error.what()
                  << '\n';
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Cancelled);
        note_native_sound_play_failure(context, error.what());
        std::cerr << "SONIC_NATIVE_SOUND_PLAY failure=" << error.what()
                  << '\n';
    } catch (...) {
        if (context.crash_capsule != nullptr)
            context.crash_capsule->update_v3_lookahead(
                lookahead_sequence,
                katana::runtime::CrashCapsuleLookaheadState::Cancelled);
        note_native_sound_play_failure(context, "non-standard-exception");
        std::cerr << "SONIC_NATIVE_SOUND_PLAY failure="
                     "non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_audio_error_port};
}

extern "C" katana::runtime::NativePortHookResult sonic_native_sound_stop(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context))
            throw std::runtime_error("native-sound-stop-context");
        const auto logical_port = context.cpu->r[4];
        if (logical_port < 32u) {
            if (const auto port = find_native_midi_port(logical_port);
                port.has_value()) {
                if (!sonic_native_title_state.sound_bank_engine)
                    throw std::runtime_error("native-sound-engine-unbound");
                sonic_native_title_state.sound_bank_engine->midi_note_off(
                    *port,
                    sonic_native_title_state.sound_active_notes[logical_port]);
            }
            sonic_native_title_state.sound_active_notes[logical_port] = 0u;
        } else {
            if (const auto port = find_native_sequence_port(logical_port);
                port.has_value()) {
                if (!sonic_native_title_state.sound_bank_engine)
                    throw std::runtime_error("native-sound-engine-unbound");
                sonic_native_title_state.sound_bank_engine->midi_stop(*port);
            }
        }
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_SOUND_STOP failure=" << error.what()
                  << '\n';
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_audio_error_port};
}

extern "C" katana::runtime::NativePortHookResult sonic_native_sound_volume(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context))
            throw std::runtime_error("native-sound-volume-context");
        const auto logical_port = context.cpu->r[5];
        float gain = 0.0f;
        if (logical_port < 32u) {
            auto title_level = static_cast<std::int32_t>(context.cpu->r[4]);
            if (title_level > 0) title_level /= 6;
            const auto midi_level = std::clamp(title_level + 106, 0, 127);
            gain = static_cast<float>(midi_level) / 127.0f;
            auto& state =
                sonic_native_title_state.sound_midi_port_state[logical_port];
            auto candidate = state;
            candidate.gain = gain;
            commit_native_sound_port_state(
                find_native_midi_port(logical_port), state, candidate);
        } else {
            const auto signed_level = static_cast<std::int8_t>(
                static_cast<std::uint8_t>(context.cpu->r[4]));
            gain = static_cast<float>(
                       static_cast<std::int32_t>(signed_level) + 128) /
                   255.0f;
            auto& state = sonic_native_title_state.sound_sequence_port_state
                [logical_port - 32u];
            auto candidate = state;
            candidate.gain = gain;
            commit_native_sound_port_state(
                find_native_sequence_port(logical_port), state, candidate);
        }
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_port};
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_sound_pan(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context))
            throw std::runtime_error("native-sound-pan-context");
        const auto logical_port = context.cpu->r[5];
        // The original high-level wrapper deliberately exposes no pan update
        // for the sequence-port family.
        if (logical_port < 32u) {
            const auto title_pan =
                static_cast<std::int32_t>(context.cpu->r[4]);
            if (title_pan < -128 || title_pan > 127)
                throw std::runtime_error("native-sound-pan-range");
            const auto midi_pan = title_pan / 2;
            const auto pan = midi_pan >= 0
                                 ? static_cast<float>(midi_pan) / 63.0f
                                 : static_cast<float>(midi_pan) / 64.0f;
            auto& state =
                sonic_native_title_state.sound_midi_port_state[logical_port];
            auto candidate = state;
            candidate.pan = pan;
            commit_native_sound_port_state(
                find_native_midi_port(logical_port), state, candidate);
        } else {
            static_cast<void>(find_native_sequence_port(logical_port));
        }
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_port};
    }
}

extern "C" katana::runtime::NativePortHookResult sonic_native_sound_pitch(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context))
            throw std::runtime_error("native-sound-pitch-context");
        const auto logical_port = context.cpu->r[5];
        // As in the original title wrapper, pitch changes apply only to the
        // 32 one-shot MIDI ports. Sequence tempo remains independently
        // controlled by authored SMSB events and the native port API.
        if (logical_port < 32u) {
            const auto bend = static_cast<std::int32_t>(context.cpu->r[4]);
            if (bend < -8192 || bend > 8191)
                throw std::runtime_error("native-sound-pitch-range");
            auto& state =
                sonic_native_title_state.sound_midi_port_state[logical_port];
            auto candidate = state;
            candidate.pitch_bend = static_cast<std::int16_t>(bend);
            commit_native_sound_port_state(
                find_native_midi_port(logical_port), state, candidate);
        } else {
            static_cast<void>(find_native_sequence_port(logical_port));
        }
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_port};
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_sound_close_sequence_ports(
    katana::runtime::NativePortContext& context) noexcept {
    try {
        if (!valid_sonic_native_context(context) ||
            !sonic_native_title_state.sound_bank_engine)
            throw std::runtime_error("native-sound-close-context");
        auto& engine = *sonic_native_title_state.sound_bank_engine;
        for (std::size_t index = 0u;
             index < sonic_native_title_state.sound_sequence_ports.size();
             ++index) {
            auto& port = sonic_native_title_state.sound_sequence_ports[index];
            if (port.has_value()) engine.close_midi_port(*port);
            port.reset();
            sonic_native_title_state.sound_sequence_port_collections[index]
                .reset();
            sonic_native_title_state
                .sound_sequence_port_program_banks[index]
                .reset();
            sonic_native_title_state
                .sound_sequence_port_sequence_banks[index]
                .reset();
            sonic_native_title_state.sound_sequence_port_state[index] = {};
            sonic_native_title_state.sound_sequence_start_reported[index] =
                false;
        }
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_port};
    }
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_audio_control_transaction(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_context};

    try {
        // This is the complete SDK owner above the displaced AICA control
        // register. It brackets four ordinary title-RAM transfer records,
        // waits for the native transfer provider, commits bits 8/9 of the
        // audio-control word and publishes completion. No AICA register,
        // ARM7 state or device-timing protocol survives this boundary.
        constexpr std::uint32_t supported_control_mask = 0x00000300u;
        constexpr std::uint32_t record_table_pointer = 0x8C673408u;
        constexpr std::uint32_t record_count = 4u;
        constexpr std::uint32_t record_stride = 32u;
        constexpr std::uint32_t active_offset = 24u;
        constexpr std::uint32_t completion_offset = 28u;

        const auto requested = context.cpu->r[4];
        if ((requested & ~supported_control_mask) != 0u)
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_audio_error_control};

        SonicGuestReader reader(*context.cpu);
        std::uint32_t records = 0u;
        if (!reader.valid() ||
            !reader.u32(record_table_pointer, records) ||
            !reader.range(records, record_count * record_stride))
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_audio_error_state};

        std::array<bool, record_count> active{};
        for (std::uint32_t index = 0u; index < record_count; ++index) {
            std::uint32_t flags = 0u;
            if (!reader.u32(records + index * record_stride + active_offset,
                            flags))
                return {katana::runtime::NativePortHookAction::Abort, 0u,
                        sonic_native_audio_error_state};
            active[index] = (flags & 1u) != 0u;
        }

        for (std::uint32_t index = 0u; index < record_count; ++index) {
            if (!active[index]) continue;
            katana::runtime::guest_write_u32(
                *context.cpu,
                records + index * record_stride + completion_offset,
                0u,
                katana::runtime::CodeWriteSource::Copy);
        }
        std::atomic_thread_fence(std::memory_order_seq_cst);

        // Native content/audio submissions are synchronous today. A future
        // asynchronous backend must drain through this same bounded counter;
        // silently publishing completion while work remains is forbidden.
        if (sonic_native_title_state.native_transfer_submissions_in_flight !=
            0u)
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_audio_error_state};

        sonic_native_title_state.native_audio_control_word =
            (sonic_native_title_state.native_audio_control_word &
             ~supported_control_mask) |
            requested;
        std::atomic_thread_fence(std::memory_order_seq_cst);

        for (std::uint32_t index = 0u; index < record_count; ++index) {
            if (!active[index]) continue;
            katana::runtime::guest_write_u32(
                *context.cpu,
                records + index * record_stride + completion_offset,
                1u,
                katana::runtime::CodeWriteSource::Copy);
        }

        // The original masks interrupts only around the transaction, then
        // restores the caller's IMASK and returns the resulting full SR.
        // Native hooks are atomic on the owner thread, so SR itself remains
        // untouched and the exact observable return is the current full SR.
        context.cpu->r[0] = context.cpu->read_sr();
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_AUDIO_CONTROL failure=" << error.what()
                  << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_AUDIO_CONTROL "
                     "failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_audio_error_state};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_audio_output_control(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_context};

    // The displaced SDK owner changes only bits 8 and 9 of the combined
    // audio-control word.  Preserve that complete title-level contract while
    // rejecting unknown device-control bits instead of recreating an AICA
    // register or silently accepting a wider protocol.
    constexpr std::uint32_t supported_control_mask = 0x00000300u;
    const auto requested = context.cpu->r[4];
    if ((requested & ~supported_control_mask) != 0u)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_control};
    sonic_native_title_state.native_audio_control_word =
        (sonic_native_title_state.native_audio_control_word &
         ~supported_control_mask) |
        requested;
    context.cpu->r[0] = 0u;
    return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
}

[[nodiscard]] katana::runtime::NativePortHookResult
set_native_audio_processor_running(
    katana::runtime::NativePortContext& context,
    const bool running) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_audio_error_context};

    try {
        // These two SDK owners mirror the ARM-reset bit into separate
        // ordinary title-RAM caches.  Keep those observable side effects but
        // model the operation as a native stream lifecycle, never as an ARM7
        // core or an AICA device-register write.
        const auto cache_address =
            running ? 0x8C67C100u : 0x8C8A3348u;
        SonicGuestReader reader(*context.cpu);
        std::uint32_t cached_control = 0u;
        if (!reader.valid() || !reader.u32(cache_address, cached_control))
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_audio_error_state};
        const auto previous_cached_control = cached_control;
        cached_control = running ? (cached_control & ~1u)
                                 : (cached_control | 1u);
        try {
            katana::runtime::guest_write_u32(
                *context.cpu, cache_address, cached_control,
                katana::runtime::CodeWriteSource::Copy);
            sonic_native_title_state.native_audio_processor_running = running;
        } catch (...) {
            try {
                katana::runtime::guest_write_u32(
                    *context.cpu, cache_address, previous_cached_control,
                    katana::runtime::CodeWriteSource::Copy);
            } catch (...) {
            }
            throw;
        }
        if (sonic_native_title_state.audio_engine) {
            // Observability must never turn a successfully committed guest
            // lifecycle transition into a hook failure.
            try {
                const auto audio =
                    sonic_native_title_state.audio_engine->snapshot();
                std::cerr << "SONIC_NATIVE_AUDIO_LIFECYCLE processor="
                          << (running ? "running" : "stopped")
                          << " endpoint_paused="
                          << (audio.output_paused ? 1 : 0)
                          << " active=" << audio.active_voices
                          << " playing=" << audio.playing_voices
                          << " submitted=" << audio.submitted_output_frames
                          << '\n';
            } catch (...) {
            }
        }
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_AUDIO_LIFECYCLE failure=" << error.what()
                  << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_AUDIO_LIFECYCLE "
                     "failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_audio_error_state};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_audio_processor_stop(
    katana::runtime::NativePortContext& context) noexcept {
    return set_native_audio_processor_running(context, false);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_audio_processor_start(
    katana::runtime::NativePortContext& context) noexcept {
    return set_native_audio_processor_running(context, true);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_video_mode_apply(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_video_mode_error_context};

    try {
        // This identity-bound SDK owner consumes a contiguous stack argument
        // record, publishes thirteen ordinary title-RAM mirrors/derived
        // values, then programs PVR timing registers and waits for a complete
        // scanline transition.  Preserve the entire title-visible half here;
        // the device half becomes one native simulation boundary.  No PVR
        // register file, scanline counter or MMIO value exists in the product.
        constexpr std::size_t stack_word_count = 63u;
        std::array<std::uint32_t, stack_word_count> words{};
        SonicGuestReader reader(*context.cpu);
        const auto stack = context.cpu->r[15];
        if (!reader.valid() ||
            !reader.range(stack, words.size() * sizeof(words.front())))
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_video_mode_error_stack};
        for (std::size_t index = 0u; index < words.size(); ++index) {
            const auto address =
                stack + static_cast<std::uint32_t>(index * sizeof(words.front()));
            if (!reader.u32(address, words[index]))
                return {katana::runtime::NativePortHookAction::Abort, 0u,
                        sonic_native_video_mode_error_stack};
        }
        const auto word = [&](const std::uint32_t offset) noexcept {
            return words[offset / sizeof(words.front())];
        };

        constexpr std::uint32_t field_mask = 0x7FFu;
        const auto packed_control =
            word(0x50u) |
            (word(0x54u) << 1u) |
            (word(0x5Cu) << 2u) |
            (word(0x68u) << 3u) |
            (word(0x30u) << 4u) |
            (word(0x60u) << 5u) |
            (word(0x28u) << 6u) |
            (word(0x2Cu) << 7u) |
            (word(0x48u) << 8u) |
            (word(0x4Cu) << 9u);
        const auto packed_horizontal =
            ((word(0x00u) & field_mask) << 16u) |
            (word(0x04u) & field_mask);
        const auto packed_horizontal_start =
            (word(0x04u) & field_mask) << 16u;
        const auto packed_vertical =
            ((word(0x14u) & field_mask) << 16u) |
            (word(0x08u) & field_mask);
        const auto packed_vertical_border =
            ((word(0x0Cu) & field_mask) << 16u) |
            (word(0x10u) & field_mask);
        const auto packed_interrupt =
            ((word(0x78u) & field_mask) << 16u) |
            (word(0x74u) & field_mask);
        const auto packed_sync =
            (word(0x18u) & 0x7Fu) |
            ((word(0x1Cu) & 0x0Fu) << 8u) |
            ((word(0x20u) & 0x3FFu) << 12u) |
            ((word(0x24u) & 0x7Fu) << 22u);
        const auto packed_scaler =
            (word(0x34u) & 1u) |
            ((word(0x38u) & 1u) << 1u) |
            ((word(0x3Cu) & 1u) << 2u) |
            ((word(0x40u) & 1u) << 3u) |
            ((word(0x44u) & 0x0Fu) << 4u) |
            ((word(0x6Cu) & 1u) << 8u) |
            ((word(0x70u) & 0x3Fu) << 16u);

        std::uint32_t horizontal_base = 0u;
        std::uint32_t vertical_base = 0u;
        std::uint32_t mode_flags = 0u;
        if (!reader.u32(0x8C8A2CE4u, horizontal_base) ||
            !reader.u32(0x8C8A2CE8u, vertical_base) ||
            !reader.u32(0x8C8A2C9Cu, mode_flags))
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_video_mode_error_state};

        const auto derived_horizontal = horizontal_base + word(0xF8u);
        const auto derived_vertical =
            (vertical_base + word(0xF0u)) |
            ((vertical_base + word(0xF4u)) << 16u);
        constexpr std::array<std::uint32_t, 13u> destinations{
            0x8C8A2CECu, 0x8C8A2CF0u, 0x8C8A2CF4u,
            0x8C8A2F6Cu, 0x8C8A2F78u, 0x8C8A2F70u,
            0x8C8A2F7Cu, 0x8C8A2F80u, 0x8C8A2F74u,
            0x8C8A2F84u, 0x8C8A2F90u, 0x8C8A2F94u,
            0x8C8A2F98u};
        const std::array values{
            word(0xF8u), word(0xF0u), word(0xF4u),
            packed_control, packed_horizontal, packed_horizontal_start,
            packed_vertical, packed_vertical_border, packed_interrupt,
            packed_sync, packed_scaler, derived_horizontal,
            derived_vertical};
        for (std::size_t index = 0u; index < destinations.size(); ++index)
            katana::runtime::guest_write_u32(
                *context.cpu, destinations[index], values[index],
                katana::runtime::CodeWriteSource::Copy);

        // The original skips its complete hardware phase when bit 1 is
        // clear, returning the mode word it tested.  When active it waits for
        // a scanline transition, performs the register batch and returns the
        // SDK write-success value 1.
        if ((mode_flags & 2u) == 0u) {
            context.cpu->r[0] = mode_flags;
        } else {
            context.host->synchronize_simulation_boundary();
            // Bind only an actually applied constructor tuple. The selected
            // KAMUI setting is intent and may differ from this active mode.
            std::uint32_t rate_hz = 0u;
            if (packed_horizontal == 0x007E0345u &&
                (packed_vertical == 0x020C0359u || packed_vertical == 0x01060359u))
                rate_hz = 60u;
            else if (packed_horizontal == 0x008D034Bu &&
                     (packed_vertical == 0x0270035Fu || packed_vertical == 0x0138035Fu))
                rate_hz = 50u;
            bind_sonic_native_video_refresh(rate_hz, "applied-658220", context.frame_index);
            if (sonic_native_timing_diagnostic_enabled())
                std::cerr << "SONIC_NATIVE_CADENCE_MODE owner=658220 hz=" << rate_hz
                          << " frame=" << context.frame_index << '\n';
            context.cpu->r[0] = 1u;
        }
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_VIDEO_MODE failure=" << error.what()
                  << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_VIDEO_MODE failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_video_mode_error_state};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_video_mode_60hz(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_video_mode_error_context};

    try {
        // This complete identity-bound SDK constructor has no title input. It
        // chooses the verified PAL 625-line profile, publishes the three
        // SDK-visible geometry values and submits the mode. The native host
        // owns pacing separately from this display profile and keeps a 4:3
        // UI viewport. The temporary PVR register record disappears here;
        // the display profile does not establish the title simulation rate.
        constexpr std::array<std::pair<std::uint32_t, std::uint32_t>, 3u>
            title_geometry{{
                {0x8C8A2FACu, 240u},
                {0x8C8A2FA4u, 262u},
                {0x8C8A2FA8u, 44u},
            }};
        SonicGuestReader reader(*context.cpu);
        if (!reader.valid())
            return {katana::runtime::NativePortHookAction::Abort, 0u,
                    sonic_native_video_mode_error_state};
        for (const auto& [address, value] : title_geometry) {
            if (!reader.range(address, sizeof(value)))
                return {katana::runtime::NativePortHookAction::Abort, 0u,
                        sonic_native_video_mode_error_state};
            katana::runtime::guest_write_u32(
                *context.cpu, address, value,
                katana::runtime::CodeWriteSource::Copy);
        }
        context.host->synchronize_simulation_boundary();
        bind_sonic_native_video_refresh(50u, "pal625-658500", context.frame_index);
        if (sonic_native_timing_diagnostic_enabled())
            std::cerr << "SONIC_NATIVE_CADENCE_MODE owner=658500 profile=PAL625"
                      << " hz=50 frame=" << context.frame_index << '\n';
        context.cpu->r[0] = 1u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_VIDEO_MODE_60HZ failure=" << error.what()
                  << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_VIDEO_MODE_60HZ "
                     "failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_video_mode_error_state};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_video_output_commit(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_video_mode_error_context};

    // The displaced exact SDK owner only committed already-derived border,
    // clip, scaler and framebuffer-control words to PVR registers.  Native
    // output layout is fixed by NativePortGraphicsConfig and the 4:3 title UI
    // viewport, so the whole operation collapses to a successful host-layout
    // commit.  No register shadow or device state is retained.
    context.cpu->r[0] = 1u;
    return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
}

namespace {

[[nodiscard]] katana::runtime::NativePortHookResult
sonic_native_video_scanout_address_commit(
    katana::runtime::NativePortContext& context,
    const std::uint32_t register_offset,
    const std::uint32_t resume_address) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_video_mode_error_context};

    // These identity-bound sites only publish already-derived FB_R/FB_W SOF
    // addresses through the shared PVR register-write leaf. Native graphics
    // owns the actual host scanout buffers, so no register/device shadow is
    // retained. Preserve every architectural effect of the displaced
    // `jsr @r14` plus delay slot and its tiny leaf before resuming the AOT
    // owner: r4 becomes the legacy effective address, r3 retains the leaf's
    // base literal, r0 reports success and PR contains the return address.
    constexpr std::uint32_t legacy_pvr_base = 0xA05F8000u;
    context.cpu->r[3] = legacy_pvr_base;
    context.cpu->r[4] = legacy_pvr_base + register_offset;
    context.cpu->r[0] = 1u;
    context.cpu->pr = resume_address;
    return {katana::runtime::NativePortHookAction::Jump, resume_address, 0u};
}

[[nodiscard]] katana::runtime::NativePortHookResult
sonic_native_video_timing_reset(
    katana::runtime::NativePortContext& context,
    const std::uint32_t resume_address) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_video_mode_error_context};

    // The four identity-bound sites are the complete branch family inside
    // the video-memory arena initializer. They only reset the legacy SPG
    // vertical timing word to zero through the generic register-write leaf.
    // Native frame pacing owns that clock, while all allocator/list effects
    // surrounding these calls remain statically recompiled and observable.
    // The displaced architectural instruction includes its `mov #0,r5`
    // delay slot, whose visible register effect is preserved here.
    context.cpu->r[5] = 0u;
    return {katana::runtime::NativePortHookAction::Jump, resume_address, 0u};
}

} // namespace

#define SONIC_NATIVE_VIDEO_SCANOUT_ADDRESS_HOOK(                             \
    symbol, register_offset, resume_address)                                \
    extern "C" katana::runtime::NativePortHookResult symbol(               \
        katana::runtime::NativePortContext& context) noexcept {             \
        return sonic_native_video_scanout_address_commit(                   \
            context, register_offset, resume_address);                      \
    }

