void write_sonic_native_development_cpu(
    SonicNativeDevelopmentStateWriter& writer,
    const SonicNativeDevelopmentCpuState& cpu) {
    const auto words = [&writer](const auto& values) {
        for (const auto value : values) writer.u32(value);
    };
    words(cpu.r);
    words(cpu.r_bank);
    words(cpu.fr);
    words(cpu.xf);
    writer.u32(cpu.pc);
    writer.u32(cpu.pr);
    writer.u32(cpu.gbr);
    writer.u32(cpu.vbr);
    writer.u32(cpu.ssr);
    writer.u32(cpu.spc);
    writer.u32(cpu.sgr);
    writer.u32(cpu.dbr);
    writer.u32(cpu.tra);
    writer.u32(cpu.tea);
    writer.u32(cpu.expevt);
    writer.u32(cpu.intevt);
    writer.u32(cpu.pteh);
    writer.u32(cpu.ptel);
    writer.u32(cpu.ptea);
    writer.u32(cpu.ttb);
    writer.u32(cpu.mmucr);
    for (const auto& entry : cpu.utlb) {
        writer.u32(entry.pteh);
        writer.u32(entry.ptel);
        writer.u32(entry.ptea);
    }
    writer.u64(cpu.tlb_load_count);
    writer.u32(cpu.mach);
    writer.u32(cpu.macl);
    writer.u32(cpu.fpul);
    writer.u32(cpu.fpscr);
    writer.u32(cpu.sr);
    writer.boolean(cpu.t);
    writer.boolean(cpu.s);
    writer.boolean(cpu.q);
    writer.boolean(cpu.m);
    writer.boolean(cpu.trap_pending);
    writer.u64(cpu.exception_generation);
    writer.u32(static_cast<std::uint32_t>(cpu.last_exception_cause));
    writer.boolean(cpu.exception_in_delay_slot);
    writer.u32(cpu.last_exception_instruction_pc);
    writer.u32(cpu.last_exception_instruction_physical_pc);
    writer.u32(cpu.last_exception_owner_pc);
    const auto& fault = cpu.last_memory_fault_provenance;
    writer.boolean(fault.valid);
    writer.boolean(fault.instruction_valid);
    writer.boolean(fault.opcode_valid);
    writer.boolean(fault.access_valid);
    writer.u32(fault.source_pc);
    writer.u32(fault.runtime_pc);
    writer.u32(fault.address);
    writer.u32(fault.opcode);
    writer.u32(static_cast<std::uint32_t>(fault.operation));
    writer.u32(static_cast<std::uint32_t>(fault.width));
    writer.u64(cpu.last_exception_generation);
    writer.boolean(cpu.sleeping);
    writer.u32(cpu.last_prefetch_address);
    writer.u64(cpu.prefetch_count);
    writer.u64(cpu.attempted_guest_instructions);
    writer.u64(cpu.retired_guest_instructions);
    writer.u64(cpu.total_guest_cycles);
    writer.u64(cpu.pending_guest_cycles);
    writer.u32(cpu.active_instruction_pc);
    writer.u32(cpu.active_instruction_physical_pc);
    writer.u32(cpu.active_block_virtual_start);
    writer.u32(cpu.active_block_physical_start);
    writer.u32(cpu.active_block_size);
    writer.boolean(cpu.last_prefetch_was_store_queue);
}

[[nodiscard]] SonicNativeDevelopmentCpuState
read_sonic_native_development_cpu(SonicNativeDevelopmentStateReader& reader) {
    SonicNativeDevelopmentCpuState cpu;
    const auto words = [&reader](auto& values) {
        for (auto& value : values) value = reader.u32();
    };
    words(cpu.r);
    words(cpu.r_bank);
    words(cpu.fr);
    words(cpu.xf);
    cpu.pc = reader.u32();
    cpu.pr = reader.u32();
    cpu.gbr = reader.u32();
    cpu.vbr = reader.u32();
    cpu.ssr = reader.u32();
    cpu.spc = reader.u32();
    cpu.sgr = reader.u32();
    cpu.dbr = reader.u32();
    cpu.tra = reader.u32();
    cpu.tea = reader.u32();
    cpu.expevt = reader.u32();
    cpu.intevt = reader.u32();
    cpu.pteh = reader.u32();
    cpu.ptel = reader.u32();
    cpu.ptea = reader.u32();
    cpu.ttb = reader.u32();
    cpu.mmucr = reader.u32();
    for (auto& entry : cpu.utlb) {
        entry.pteh = reader.u32();
        entry.ptel = reader.u32();
        entry.ptea = reader.u32();
    }
    cpu.tlb_load_count = reader.u64();
    cpu.mach = reader.u32();
    cpu.macl = reader.u32();
    cpu.fpul = reader.u32();
    cpu.fpscr = reader.u32();
    cpu.sr = reader.u32();
    cpu.t = reader.boolean();
    cpu.s = reader.boolean();
    cpu.q = reader.boolean();
    cpu.m = reader.boolean();
    cpu.trap_pending = reader.boolean();
    cpu.exception_generation = reader.u64();
    cpu.last_exception_cause =
        static_cast<katana::runtime::ExceptionCause>(reader.u32());
    cpu.exception_in_delay_slot = reader.boolean();
    cpu.last_exception_instruction_pc = reader.u32();
    cpu.last_exception_instruction_physical_pc = reader.u32();
    cpu.last_exception_owner_pc = reader.u32();
    auto& fault = cpu.last_memory_fault_provenance;
    fault.valid = reader.boolean();
    fault.instruction_valid = reader.boolean();
    fault.opcode_valid = reader.boolean();
    fault.access_valid = reader.boolean();
    fault.source_pc = reader.u32();
    fault.runtime_pc = reader.u32();
    fault.address = reader.u32();
    fault.opcode = reader.u32();
    fault.operation =
        static_cast<katana::runtime::MemoryAccessOperation>(reader.u32());
    fault.width =
        static_cast<katana::runtime::MemoryAccessWidth>(reader.u32());
    cpu.last_exception_generation = reader.u64();
    cpu.sleeping = reader.boolean();
    cpu.last_prefetch_address = reader.u32();
    cpu.prefetch_count = reader.u64();
    cpu.attempted_guest_instructions = reader.u64();
    cpu.retired_guest_instructions = reader.u64();
    cpu.total_guest_cycles = reader.u64();
    cpu.pending_guest_cycles = reader.u64();
    cpu.active_instruction_pc = reader.u32();
    cpu.active_instruction_physical_pc = reader.u32();
    cpu.active_block_virtual_start = reader.u32();
    cpu.active_block_physical_start = reader.u32();
    cpu.active_block_size = reader.u32();
    cpu.last_prefetch_was_store_queue = reader.boolean();
    return cpu;
}

// Bind a state to the exact executable and loaded codec DLLs. Provider names
// and ABI major numbers alone do not identify a decoder/resampler build.
// This runs once on an explicit state request, never on the frame hot path.
[[nodiscard]] const std::string& sonic_native_development_binary_identity() {
    static const std::string identity = []() -> std::string {
#if defined(_WIN32)
        const auto hash_file = [](const std::filesystem::path& path) {
            struct Hash final {
                BCRYPT_ALG_HANDLE algorithm = nullptr;
                BCRYPT_HASH_HANDLE hash = nullptr;
                ~Hash() {
                    if (hash != nullptr) BCryptDestroyHash(hash);
                    if (algorithm != nullptr) BCryptCloseAlgorithmProvider(algorithm, 0u);
                }
            } state;
            if (BCryptOpenAlgorithmProvider(&state.algorithm, BCRYPT_SHA256_ALGORITHM, nullptr, 0u) < 0)
                throw std::runtime_error("development-state-binary-hash-provider");
            DWORD object_bytes = 0u, returned = 0u;
            if (BCryptGetProperty(state.algorithm, BCRYPT_OBJECT_LENGTH,
                    reinterpret_cast<PUCHAR>(&object_bytes), sizeof(object_bytes), &returned, 0u) < 0 ||
                returned != sizeof(object_bytes) || object_bytes > 1024u * 1024u)
                throw std::runtime_error("development-state-binary-hash-size");
            std::vector<std::uint8_t> object(object_bytes);
            if (BCryptCreateHash(state.algorithm, &state.hash, object.data(), object_bytes, nullptr, 0u, 0u) < 0)
                throw std::runtime_error("development-state-binary-hash-create");
            std::ifstream file(path, std::ios::binary);
            if (!file) throw std::runtime_error("development-state-binary-open");
            std::array<char, 64u * 1024u> buffer{};
            while (file) {
                file.read(buffer.data(), buffer.size());
                const auto count = file.gcount();
                if (count > 0 && BCryptHashData(state.hash, reinterpret_cast<PUCHAR>(buffer.data()),
                                                static_cast<ULONG>(count), 0u) < 0)
                    throw std::runtime_error("development-state-binary-hash");
            }
            if (!file.eof()) throw std::runtime_error("development-state-binary-read");
            std::array<std::uint8_t, 32u> digest{};
            if (BCryptFinishHash(state.hash, digest.data(), static_cast<ULONG>(digest.size()), 0u) < 0)
                throw std::runtime_error("development-state-binary-hash-finish");
            constexpr char hex[] = "0123456789abcdef";
            std::string result;
            for (const auto byte : digest) { result += hex[byte >> 4u]; result += hex[byte & 15u]; }
            return result;
        };
        const auto module_path = [](const HMODULE module) {
            std::array<wchar_t, 32768u> path{};
            const auto size = GetModuleFileNameW(module, path.data(), static_cast<DWORD>(path.size()));
            if (size == 0u || size >= path.size()) throw std::runtime_error("development-state-module-path");
            return std::filesystem::path(std::wstring_view(path.data(), size));
        };
        std::string result = hash_file(module_path(nullptr));
        std::array<HMODULE, 1024u> modules{};
        DWORD bytes = 0u;
        if (!K32EnumProcessModules(GetCurrentProcess(), modules.data(), sizeof(modules), &bytes) ||
            bytes > sizeof(modules) || bytes % sizeof(HMODULE) != 0u)
            throw std::runtime_error("development-state-codec-modules");
        std::map<std::wstring, std::filesystem::path> codecs;
        for (std::size_t index = 0u; index < bytes / sizeof(HMODULE); ++index) {
            const auto path = module_path(modules[index]);
            auto name = path.filename().wstring();
            std::transform(name.begin(), name.end(), name.begin(), [](wchar_t value) {
                return value >= L'A' && value <= L'Z' ? static_cast<wchar_t>(value + L'a' - L'A') : value;
            });
            for (const auto family : {L"avcodec-", L"avformat-", L"avutil-", L"swresample-"}) {
                if (name.starts_with(family) && name.ends_with(L".dll") &&
                    !codecs.emplace(family, path).second)
                    throw std::runtime_error("development-state-codec-module-ambiguous");
            }
        }
        // A fully static codec is covered by the EXE identity. A partially
        // dynamic FFmpeg installation must provide all four audio components.
        if (!codecs.empty() && codecs.size() != 4u)
            throw std::runtime_error("development-state-codec-module-incomplete");
        for (const auto& [family, path] : codecs) result += ":" + hash_file(path);
        return result;
#else
        throw std::runtime_error("development-state-binary-identity-unavailable");
#endif
    }();
    return identity;
}

[[nodiscard]] SonicNativeDevelopmentState
capture_sonic_native_development_state(
    katana::runtime::NativePortContext& context) {
    if (!valid_sonic_native_context(context) ||
        context.runtime_images == nullptr || context.loaded_aot == nullptr ||
        context.graphics == nullptr)
        throw std::runtime_error("development-state-context");
    if (sonic_native_title_state.frame_open || sonic_native_title_state.standard_sixty_configuring ||
        sonic_native_title_state.pending_draw_vertices != 0u ||
        sonic_native_title_state.native_transfer_submissions_in_flight != 0u ||
        sonic_native_title_state.texture_upload_pending ||
        std::ranges::any_of(
            sonic_native_title_state.pending_prs_modules,
            [](const SonicNativePendingPrsModule& pending) {
                return pending.content != nullptr;
            }))
        throw std::runtime_error("development-state-frame-busy");

    context.graphics->finish();
    collect_native_pvm_allocations(context);
    // A quiescent snapshot must include the RAM effects of all completed
    // guest renders. Tickets themselves are host lifetime data, not saves.
    if (sonic_render_completion_experiment_enabled() &&
        !service_sonic_render_completions(context))
        throw std::runtime_error("development-state-render-completion");
    SonicNativeDevelopmentState result;
    const auto now = context.host->monotonic_time_nanoseconds();
    result.saved_frame_index = context.frame_index;
    result.services.postpal_main_textures_pending = sonic_native_title_state.postpal_main_textures_pending;
    result.services.private_stage_tuple_override = sonic_native_title_state.private_stage_tuple_override;
    result.services.texture_binding = sonic_native_title_state.texture_binding;
    result.services.current_texture_index = sonic_native_title_state.current_texture_index;
    result.services.current_texture_index_bound = sonic_native_title_state.current_texture_index_bound;
    result.services.most_recent_texture_archive = sonic_native_title_state.most_recent_texture_archive;
    result.services.texture_list_epoch = sonic_native_title_state.texture_list_epoch;
    result.services.texture_writer_sequence = sonic_native_title_state.texture_writer_sequence;
    result.services.texture_writer_identity = sonic_native_title_state.texture_writer_identity;
    result.services.texture_writer_texlist_address = sonic_native_title_state.texture_writer_texlist_address;
    result.services.texture_writer = sonic_native_title_state.texture_writer;
    result.services.texture_upload_sequence = sonic_native_title_state.texture_upload_sequence;
    result.services.texture_upload_completion_token = sonic_native_title_state.texture_upload_completion_token;
    result.services.texture_upload_completion_bound = sonic_native_title_state.texture_upload_completion_bound;
    result.services.native_render_width = sonic_native_title_state.native_render_width;
    result.services.native_render_height = sonic_native_title_state.native_render_height;
    result.services.native_render_arena_index = sonic_native_title_state.native_render_arena_index;
    result.services.native_render_arena_generation = sonic_native_title_state.native_render_arena_generation;
    result.services.native_scene_sequence = sonic_native_title_state.native_scene_sequence;
    result.services.font_source_address = sonic_native_title_state.font_source_address;
    result.services.font_dimension = sonic_native_title_state.font_dimension;
    result.services.font_format = sonic_native_title_state.font_format;
    result.services.frame_clear_producer_pc = sonic_native_title_state.frame_clear_producer_pc;
    result.services.frame_clear_producer_pr = sonic_native_title_state.frame_clear_producer_pr;
    result.services.frame_clear_sequence = sonic_native_title_state.frame_clear_sequence;
    result.services.loaded_sound_collections = sonic_native_title_state.loaded_sound_collections;
    result.services.current_sound_collection = sonic_native_title_state.current_sound_collection;
    result.services.sound_unit_registrations = sonic_native_title_state.sound_unit_registrations;
    result.services.sound_pcm_stream_ring_registrations = sonic_native_title_state.sound_pcm_stream_ring_registrations;
    result.services.sound_unit_registration_sequence = sonic_native_title_state.sound_unit_registration_sequence;
    result.services.sound_midi_ports = sonic_native_title_state.sound_midi_ports;
    result.services.sound_midi_port_collections = sonic_native_title_state.sound_midi_port_collections;
    result.services.sound_midi_port_programs = sonic_native_title_state.sound_midi_port_programs;
    result.services.sound_active_notes = sonic_native_title_state.sound_active_notes;
    result.services.sound_midi_port_state = sonic_native_title_state.sound_midi_port_state;
    result.services.sound_sequence_ports = sonic_native_title_state.sound_sequence_ports;
    result.services.sound_sequence_port_collections = sonic_native_title_state.sound_sequence_port_collections;
    result.services.sound_sequence_port_program_banks = sonic_native_title_state.sound_sequence_port_program_banks;
    result.services.sound_sequence_port_sequence_banks = sonic_native_title_state.sound_sequence_port_sequence_banks;
    result.services.sound_sequence_port_state = sonic_native_title_state.sound_sequence_port_state;
    result.services.sound_sequence_start_reported = sonic_native_title_state.sound_sequence_start_reported;
    result.services.native_audio_default_port = sonic_native_title_state.native_audio_default_port;
    result.services.native_audio_default_value = sonic_native_title_state.native_audio_default_value;
    result.services.native_audio_service_sequence = sonic_native_title_state.native_audio_service_sequence;
    result.services.native_input_buttons = sonic_native_title_state.native_input_buttons;
    result.services.native_input_record_addresses = sonic_native_title_state.native_input_record_addresses;
    result.services.native_input_initialized = sonic_native_title_state.native_input_initialized;
    result.services.native_input_connected = sonic_native_title_state.native_input_connected;
    result.services.transfer_ring = sonic_native_title_state.transfer_ring;
    result.services.platform_interrupt_state = sonic_native_title_state.platform_interrupt_state;
    result.services.native_transfers_suspended = sonic_native_title_state.native_transfers_suspended;
    for (std::size_t index = 0u; index < result.services.adx.size(); ++index) {
        auto& target = result.services.adx[index];
        target.stream = sonic_native_title_state.adx_streams[index];
        target.path = target.stream.guest_path;
        target.stream.guest_path = {};
    }
    if (sonic_native_title_state.event_adx_archive != nullptr)
        result.services.event_adx_path = sonic_native_title_state.event_adx_archive->guest_path;
    if (!sonic_native_title_state.audio_engine || !sonic_native_title_state.sound_bank_engine)
        throw std::runtime_error("development-state-audio-provider");
    result.services.audio = sonic_native_title_state.audio_engine->capture_development_state();
    result.services.sound_bank = sonic_native_title_state.sound_bank_engine->capture_development_state();

    result.timer_elapsed_nanoseconds =
        now >= sonic_native_title_state.timer_epoch_nanoseconds
            ? now - sonic_native_title_state.timer_epoch_nanoseconds
            : 0u;
    result.periodic_elapsed_nanoseconds =
        now >= sonic_native_title_state.periodic_epoch_nanoseconds
            ? now - sonic_native_title_state.periodic_epoch_nanoseconds
            : 0u;
    result.periodic_callbacks_dispatched =
        sonic_native_title_state.periodic_callbacks_dispatched;
    result.periodic_reload_ticks =
        sonic_native_title_state.periodic_reload_ticks;
    result.periodic_clock_initialized =
        sonic_native_title_state.periodic_clock_initialized;
    result.begun_frames = sonic_native_title_state.begun_frames;
    result.active_video_refresh_hz = sonic_native_title_state.active_video_refresh_hz;
    result.standard_sixty_active = sonic_native_title_state.standard_sixty_active;
    result.sixty_original_release = sonic_native_title_state.sixty_original_release;
    result.sixty_original_delta = sonic_native_title_state.sixty_original_delta;
    result.cpu = capture_sonic_native_development_cpu(*context.cpu);
    result.cpu.active_instruction_pc = 0u;
    result.cpu.active_instruction_physical_pc = 0u;
    result.cpu.active_block_virtual_start = 0u;
    result.cpu.active_block_physical_start = 0u;
    result.cpu.active_block_size = 0u;
    result.main_memory =
        katana::runtime::capture_native_port_main_memory(*context.cpu);
    result.module_universe_identity =
        context.loaded_aot->module_universe_identity();
    result.aot_pack_identity = context.loaded_aot->aot_pack_identity();
    result.provider_identity = sonic_native_title_adapter_source_identity;
    result.runtime_binary_identity = sonic_native_development_binary_identity();
    for (const auto& archive : sonic_native_title_state.materialized_texture_archives) {
        const auto catalog = sonic_native::texture_archive_binding(archive.catalog_index);
        if (!catalog || archive.catalog_index > std::numeric_limits<std::uint32_t>::max() ||
            !sonic_native_sha256_identity_matches(catalog->byte_identity, archive.archive.content_sha256))
            throw std::runtime_error("development-state-archive-identity");
        result.archives.push_back({static_cast<std::uint32_t>(archive.catalog_index),
            archive.texture_set_references, std::string(catalog->byte_identity)});
    }
    for (const auto& image :
         context.runtime_images->active_images_for_development_state())
        result.runtime_images.push_back({std::string(image.image_id)});
    for (const auto& module :
         context.loaded_aot->modules_for_development_state())
        result.modules.push_back(
            {std::string(module.sha256), module.source_start,
             module.runtime_start, module.byte_size, module.activation_entry,
             module.lifecycle_generation, module.active});
    result.executable_transition_authority =
        sonic_native_title_state.executable_transition_authority;

    SonicGuestReader reader(*context.cpu);
    if (!reader.valid())
        throw std::runtime_error("development-state-reader");
    result.texlists.reserve(
        sonic_native_title_state.texlist_catalog_bindings.size());
    for (const auto& binding :
         sonic_native_title_state.texlist_catalog_bindings) {
        // The draw resolver also caches non-owning catalog lookups. Those
        // entries have no published descriptors or leases and are rebuilt
        // from the restored TEXLIST through the ordinary exact resolver.
        // They must not be serialized as resource owners (or given a lease).
        const bool lookup_only = !binding.texture_set_owner &&
            !binding.named_archive_owner && !binding.named_archive_binding &&
            !binding.loaded_aot_module_binding &&
            binding.texture_set_references == 0u &&
            binding.guest_descriptors.empty() &&
            binding.per_texture_catalog_indices.empty() &&
            binding.module_identity.empty() && binding.module_source_start == 0u &&
            binding.module_runtime_start == 0u && binding.module_byte_size == 0u &&
            binding.module_lifecycle_generation == 0u &&
            !sonic_native_transition_authority_bound(binding.descriptor_transition_authority);
        if (lookup_only) continue;
        if ((binding.named_archive_owner &&
             !binding.named_archive_binding) ||
            (!binding.texture_set_owner &&
             !binding.named_archive_owner) ||
            (!binding.named_archive_binding &&
             !binding.guest_descriptors.empty()) ||
            (binding.named_archive_binding &&
             binding.guest_descriptors.size() != binding.texture_count) ||
            (!binding.named_archive_binding &&
             binding.texture_set_owner &&
             binding.named_archive_owner))
            throw std::runtime_error("development-state-texture-owner");
        if (binding.catalog_index >
            std::numeric_limits<std::uint32_t>::max())
            throw std::runtime_error("development-state-texture-catalog");
        SonicNativeDevelopmentTexlist saved;
        saved.texlist_address = binding.texlist_address;
        saved.texname_address = binding.texname_address;
        saved.texture_count = binding.texture_count;
        saved.catalog_index =
            static_cast<std::uint32_t>(binding.catalog_index);
        saved.per_texture_catalog_indices = binding.per_texture_catalog_indices;
        saved.texture_set_references = binding.texture_set_references;
        saved.descriptor_transition_authority = binding.descriptor_transition_authority;
        saved.texture_set_owner = binding.texture_set_owner;
        saved.named_archive_binding = binding.named_archive_binding;
        saved.named_archive_owner = binding.named_archive_owner;
        saved.loaded_aot_module_binding =
            binding.loaded_aot_module_binding;
        saved.module_identity = binding.module_identity;
        saved.module_source_start = binding.module_source_start;
        saved.module_runtime_start = binding.module_runtime_start;
        saved.module_byte_size = binding.module_byte_size;
        saved.module_lifecycle_generation =
            binding.module_lifecycle_generation;
        saved.descriptors.reserve(binding.guest_descriptors.size());
        for (std::size_t ordinal = 0u;
             ordinal < binding.guest_descriptors.size(); ++ordinal) {
            const auto& descriptor = binding.guest_descriptors[ordinal];
            std::array<std::uint32_t, sonic_ninja_texture_descriptor_words>
                current{};
            const bool readable = read_native_guest_texture_descriptor(
                reader, descriptor.descriptor_address, current);
            const bool sdk_row_reused = readable &&
                !sonic_native_same_texture_publication(current, descriptor.published_words) &&
                sonic_native_descriptor_claim_is_bound(reader, binding, ordinal) &&
                sonic_native_descriptor_is_registry_row(reader, descriptor.descriptor_address) &&
                sonic_native_descriptor_has_sdk_row_reuse(reader, descriptor, current);
            if (!readable || (!sonic_native_same_texture_publication(current, descriptor.published_words) && !sdk_row_reused)) {
                std::uint32_t texname_reference = 0u;
                const auto texname_reference_address =
                    static_cast<std::uint64_t>(binding.texname_address) +
                    ordinal * 12u + 8u;
                const bool reference_read =
                    texname_reference_address <=
                        std::numeric_limits<std::uint32_t>::max() &&
                    reader.u32(
                        static_cast<std::uint32_t>(texname_reference_address),
                        texname_reference);
                bool sdk_released = false;
                bool sdk_retired_or_displaced = false;
                bool claim_bound = false;
                try {
                    sdk_released = readable &&
                        sonic_native_guest_texture_descriptor_released(current);
                    sdk_retired_or_displaced = readable &&
                        sonic_native_descriptor_is_sdk_retired_or_displaced(
                            context, descriptor, current);
                    claim_bound = sonic_native_descriptor_claim_is_bound(
                        reader, binding, ordinal);
                } catch (...) {
                    // Diagnostics must not replace the original fail-closed
                    // development-state rejection.
                }
                const auto diff_mask = [](const auto& left,
                                          const auto& right) noexcept {
                    std::uint32_t result = 0u;
                    for (std::size_t word = 0u; word < left.size(); ++word)
                        if (left[word] != right[word])
                            result |= std::uint32_t{1u} << word;
                    return result;
                };
                const auto print_words = [](const char* label,
                                            const auto& words) {
                    std::cerr << ' ' << label << '=' << std::hex;
                    for (std::size_t word = 0u; word < words.size(); ++word) {
                        if (word != 0u) std::cerr << ',';
                        std::cerr << "0x" << words[word];
                    }
                    std::cerr << std::dec;
                };
                const bool entry_catalog_valid =
                    binding.per_texture_catalog_indices.empty() ||
                    ordinal < binding.per_texture_catalog_indices.size();
                const auto entry_catalog =
                    binding.per_texture_catalog_indices.empty()
                        ? binding.catalog_index
                        : entry_catalog_valid
                              ? binding.per_texture_catalog_indices[ordinal]
                              : std::numeric_limits<std::size_t>::max();
                const auto& authority = binding.descriptor_transition_authority;
                std::cerr
                    << "SONIC_NATIVE_DEVELOPMENT_TEXTURE_DESCRIPTOR_DRIFT"
                    << " frame=" << context.frame_index
                    << " texlist=0x" << std::hex << binding.texlist_address
                    << " texname=0x" << binding.texname_address
                    << " texname_reference_address=0x"
                    << texname_reference_address
                    << " texname_reference=0x" << texname_reference
                    << " descriptor=0x" << descriptor.descriptor_address
                    << std::dec << " catalog_index=" << binding.catalog_index
                    << " entry_catalog_index=" << entry_catalog
                    << " entry_catalog_valid=" << entry_catalog_valid
                    << " ordinal=" << ordinal
                    << " texture_count=" << binding.texture_count
                    << " texture_set_references="
                    << binding.texture_set_references
                    << " descriptor_generation=" << descriptor.generation
                    << " descriptor_epoch=" << descriptor.transition_epoch
                    << " authority_generation="
                    << authority.module_lifecycle_generation
                    << " authority_epoch=" << authority.transition_epoch
                    << " readable=" << readable
                    << " reference_read=" << reference_read
                    << " reference_match="
                    << (reference_read && sonic_native_same_backing_address(
                           texname_reference, descriptor.descriptor_address))
                    << " claim_bound=" << claim_bound
                    << " sdk_released=" << sdk_released
                    << " sdk_retired_or_displaced="
                    << sdk_retired_or_displaced
                    << " competing_publication="
                    << sonic_native_descriptor_has_competing_publication(
                           context, descriptor)
                    << " named_archive_binding="
                    << binding.named_archive_binding
                    << " named_archive_owner=" << binding.named_archive_owner
                    << " texture_set_owner=" << binding.texture_set_owner
                    << " loaded_aot_module_binding="
                    << binding.loaded_aot_module_binding
                    << " authority_bound="
                    << sonic_native_transition_authority_bound(authority)
                    << " authority_retired_history="
                    << authority.retired_resource_history
                    << " current_published_diff=0x" << std::hex
                    << diff_mask(current, descriptor.published_words)
                    << " current_previous_diff=0x"
                    << diff_mask(current, descriptor.previous_words)
                    << " current_replaced_diff=0x"
                    << diff_mask(current, descriptor.replaced_words)
                    << std::dec;
                print_words("current_words", current);
                print_words("published_words", descriptor.published_words);
                print_words("previous_words", descriptor.previous_words);
                print_words("replaced_words", descriptor.replaced_words);
                std::cerr << '\n';
                note_native_texture_contract_failure(
                    context, "development-state-texture-descriptor-drift",
                    binding.texlist_address, &descriptor,
                    reference_read ? texname_reference : 0u);
                throw std::runtime_error(
                    "development-state-texture-descriptor-drift");
            }
            SonicNativeDevelopmentDescriptor item;
            item.descriptor_address = descriptor.descriptor_address;
            item.guest_token = descriptor.guest_token;
            item.generation = descriptor.generation;
            item.transition_epoch = descriptor.transition_epoch;
            item.previous_words = descriptor.previous_words;
            item.replaced_words = descriptor.replaced_words;
            item.published_words = descriptor.published_words;
            saved.descriptors.push_back(item);
        }
        result.texlists.push_back(std::move(saved));
    }
    if (sonic_native_title_state.pvm_allocations.size() >
            max_native_pvm_allocations ||
        sonic_native_title_state.pvm_views.size() > max_native_pvm_views)
        throw std::runtime_error("development-state-pvm-count");
    result.pvm_allocations = sonic_native_title_state.pvm_allocations;
    result.pvm_views = sonic_native_title_state.pvm_views;
    result.texture_sets.reserve(
        sonic_native_title_state.active_texture_sets.size());
    for (const auto& set : sonic_native_title_state.active_texture_sets) {
        if (set.acquisition_count == 0u ||
            set.acquisition_count >
                static_cast<std::size_t>(
                    std::numeric_limits<std::uint32_t>::max()))
            throw std::runtime_error("development-state-texture-set-count");
        SonicNativeDevelopmentTextureSet item;
        item.domain = set.domain;
        item.set_index = set.set_index;
        item.acquisition_count = static_cast<std::uint32_t>(set.acquisition_count);
        item.row_address = set.row_address;
        item.return_value = set.return_value;
        item.catalog_indices = set.catalog_indices;
        item.texlist_addresses = set.texlist_addresses;
        result.texture_sets.push_back(std::move(item));
    }

    result.dynamic_surfaces.reserve(
        sonic_native_title_state.dynamic_surfaces.size());
    for (const auto& surface : sonic_native_title_state.dynamic_surfaces) {
        if (!sonic_native_title_state.texture_backing_store ||
            surface.byte_size >
                sonic_native_development_state_maximum_bytes)
            throw std::runtime_error("development-state-dynamic-surface");
        SonicNativeDevelopmentDynamicSurface saved;
        saved.descriptor_address = surface.descriptor_address;
        saved.destination_address = surface.destination_address;
        saved.source_address = surface.source_address;
        saved.extent = surface.extent;
        saved.surface_type = surface.surface_type;
        saved.surface_flags = surface.surface_flags;
        saved.pixel_format = surface.pixel_format;
        saved.data_format = surface.data_format;
        saved.upload_sequence = surface.upload_sequence;
        saved.encoded.resize(surface.byte_size);
        if (sonic_native_title_state.texture_backing_store->overlay(
                surface.destination_address, saved.encoded) !=
            katana::runtime::NativePortTextureOverlayCoverage::Complete)
            throw std::runtime_error(
                "development-state-dynamic-surface-coverage");
        result.dynamic_surfaces.push_back(std::move(saved));
    }

    for (const auto& loaded :
         sonic_native_title_state.loaded_sound_collections) {
        if (loaded.catalog_index >
            std::numeric_limits<std::uint32_t>::max())
            throw std::runtime_error("development-state-sound-catalog");
        result.sound_collection_catalog_indices.push_back(
            static_cast<std::uint32_t>(loaded.catalog_index));
    }
    result.native_audio_control_word =
        sonic_native_title_state.native_audio_control_word;
    result.native_audio_foundation_refcount =
        sonic_native_title_state.native_audio_foundation_refcount;
    result.native_sound_driver_initialized =
        sonic_native_title_state.native_sound_driver_initialized;
    result.native_audio_stereo_output =
        sonic_native_title_state.native_audio_stereo_output;
    result.native_audio_processor_running =
        sonic_native_title_state.native_audio_processor_running;
    result.frame_clear_color = sonic_native_title_state.frame_clear_color;
    result.fog_table_color = sonic_native_title_state.fog_table_color;
    result.fog_vertex_color = sonic_native_title_state.fog_vertex_color;
    result.fog_table = sonic_native_title_state.fog_table;
    result.fog_density_word = sonic_native_title_state.fog_density_word;
    result.cull_value = sonic_native_title_state.cull_value;
    result.fog_table_color_bound =
        sonic_native_title_state.fog_table_color_bound;
    result.fog_vertex_color_bound =
        sonic_native_title_state.fog_vertex_color_bound;
    result.fog_density_bound = sonic_native_title_state.fog_density_bound;
    result.fog_table_bound = sonic_native_title_state.fog_table_bound;
    result.cull_value_bound = sonic_native_title_state.cull_value_bound;
    return result;
}

void write_sonic_native_development_authority(
    SonicNativeDevelopmentStateWriter& writer,
    const SonicNativeExecutableTransitionAuthority& authority) {
    writer.string(authority.module_identity);
    writer.u32(authority.module_source_start);
    writer.u32(authority.module_runtime_start);
    writer.u32(authority.module_byte_size);
    writer.u64(authority.module_lifecycle_generation);
    writer.u64(authority.transition_epoch);
    writer.boolean(authority.retired_resource_history);
}

[[nodiscard]] SonicNativeExecutableTransitionAuthority
read_sonic_native_development_authority(
    SonicNativeDevelopmentStateReader& reader) {
    SonicNativeExecutableTransitionAuthority result;
    result.module_identity = reader.string();
    result.module_source_start = reader.u32();
    result.module_runtime_start = reader.u32();
    result.module_byte_size = reader.u32();
    result.module_lifecycle_generation = reader.u64();
    result.transition_epoch = reader.u64();
    result.retired_resource_history = reader.boolean();
    return result;
}

void write_sonic_native_guest_texture_descriptor(
    SonicNativeDevelopmentStateWriter& writer,
    const SonicNativeGuestTextureDescriptor& descriptor) {
    writer.u32(descriptor.descriptor_address);
    writer.u32(descriptor.guest_token);
    writer.u64(descriptor.generation);
    writer.u64(descriptor.transition_epoch);
    for (const auto word : descriptor.replaced_words) writer.u32(word);
    for (const auto word : descriptor.previous_words) writer.u32(word);
    for (const auto word : descriptor.published_words) writer.u32(word);
}

[[nodiscard]] SonicNativeGuestTextureDescriptor
read_sonic_native_guest_texture_descriptor(
    SonicNativeDevelopmentStateReader& reader) {
    SonicNativeGuestTextureDescriptor result;
    result.descriptor_address = reader.u32();
    result.guest_token = reader.u32();
    result.generation = reader.u64();
    result.transition_epoch = reader.u64();
    for (auto& word : result.replaced_words) word = reader.u32();
    for (auto& word : result.previous_words) word = reader.u32();
    for (auto& word : result.published_words) word = reader.u32();
    return result;
}

void write_sonic_native_pvm_allocation(
    SonicNativeDevelopmentStateWriter& writer,
    const SonicNativePvmAllocation& allocation) {
    writer.u32(allocation.catalog_index);
    writer.u32(allocation.archive_ordinal);
    write_sonic_native_guest_texture_descriptor(writer, allocation.descriptor);
}

[[nodiscard]] SonicNativePvmAllocation
read_sonic_native_pvm_allocation(SonicNativeDevelopmentStateReader& reader) {
    SonicNativePvmAllocation result;
    result.catalog_index = reader.u32();
    result.archive_ordinal = reader.u32();
    result.descriptor = read_sonic_native_guest_texture_descriptor(reader);
    return result;
}

[[nodiscard]] std::vector<std::uint8_t>
encode_sonic_native_development_state(
    const SonicNativeDevelopmentState& state) {
    SonicNativeDevelopmentStateWriter writer;
    writer.raw(sonic_native_development_state_magic);
    writer.u32(sonic_native_development_state_schema);
    writer.u32(katana::runtime::native_port_definition_contract_version);
    writer.string("sonic-adventure-pal-v1003-development-state");
    writer.u64(state.saved_frame_index);
    writer.u64(state.timer_elapsed_nanoseconds);
    writer.u64(state.periodic_elapsed_nanoseconds);
    writer.u64(state.periodic_callbacks_dispatched);
    writer.u32(state.periodic_reload_ticks);
    writer.boolean(state.periodic_clock_initialized);
    writer.u64(state.begun_frames);
    writer.u32(state.active_video_refresh_hz);
    writer.boolean(state.standard_sixty_active);
    writer.u32(state.sixty_original_release);
    writer.u32(state.sixty_original_delta);
    writer.string(state.module_universe_identity);
    writer.string(state.aot_pack_identity);
    writer.string(state.provider_identity);
    writer.string(state.runtime_binary_identity);
    writer.u32(static_cast<std::uint32_t>(state.archives.size()));
    for (const auto& archive : state.archives) {
        writer.u32(archive.catalog_index);
        writer.u64(archive.references);
        writer.string(archive.byte_identity);
    }
    SonicDevelopmentWriteFields service_writer{writer};
    sonic_native_development_fields(service_writer, state.services);
    write_sonic_native_development_cpu(writer, state.cpu);
    if (state.main_memory.size() !=
        katana::runtime::native_port_main_memory_backing_size)
        throw std::runtime_error("development-state-main-memory-size");
    writer.u32(static_cast<std::uint32_t>(state.main_memory.size()));
    writer.raw(state.main_memory);

    const auto write_count = [&writer](const std::size_t count) {
        if (count > std::numeric_limits<std::uint32_t>::max())
            throw std::runtime_error("development-state-count");
        writer.u32(static_cast<std::uint32_t>(count));
    };
    if (state.pvm_allocations.size() > max_native_pvm_allocations ||
        state.pvm_views.size() > max_native_pvm_views)
        throw std::runtime_error("development-state-pvm-count");
    write_count(state.runtime_images.size());
    for (const auto& image : state.runtime_images) writer.string(image.image_id);
    write_count(state.modules.size());
    for (const auto& module : state.modules) {
        writer.string(module.sha256);
        writer.u32(module.source_start);
        writer.u32(module.runtime_start);
        writer.u32(module.byte_size);
        writer.u32(module.activation_entry);
        writer.u64(module.lifecycle_generation);
        writer.boolean(module.active);
    }
    write_sonic_native_development_authority(
        writer, state.executable_transition_authority);
    write_count(state.texlists.size());
    for (const auto& texlist : state.texlists) {
        writer.u32(texlist.texlist_address);
        writer.u32(texlist.texname_address);
        writer.u32(texlist.texture_count);
        writer.u32(texlist.catalog_index);
        writer.u64(texlist.texture_set_references);
        write_sonic_native_development_authority(writer, texlist.descriptor_transition_authority);
        write_count(texlist.per_texture_catalog_indices.size());
        for (const auto catalog : texlist.per_texture_catalog_indices)
            writer.u32(static_cast<std::uint32_t>(catalog));
        writer.boolean(texlist.texture_set_owner);
        writer.boolean(texlist.named_archive_binding);
        writer.boolean(texlist.named_archive_owner);
        writer.boolean(texlist.loaded_aot_module_binding);
        writer.string(texlist.module_identity);
        writer.u32(texlist.module_source_start);
        writer.u32(texlist.module_runtime_start);
        writer.u32(texlist.module_byte_size);
        writer.u64(texlist.module_lifecycle_generation);
        write_count(texlist.descriptors.size());
        for (const auto& descriptor : texlist.descriptors) {
            writer.u32(descriptor.descriptor_address);
            writer.u32(descriptor.guest_token);
            writer.u64(descriptor.generation);
            writer.u64(descriptor.transition_epoch);
            for (const auto word : descriptor.replaced_words) writer.u32(word);
            for (const auto word : descriptor.previous_words) writer.u32(word);
            for (const auto word : descriptor.published_words) writer.u32(word);
        }
    }
    write_count(state.pvm_allocations.size());
    for (const auto& allocation : state.pvm_allocations)
        write_sonic_native_pvm_allocation(writer, allocation);
    write_count(state.pvm_views.size());
    for (const auto& view : state.pvm_views) {
        writer.u32(view.texlist_address);
        writer.u32(view.texname_address);
        writer.u32(view.texture_count);
        writer.u32(view.catalog_index);
    }
    write_count(state.texture_sets.size());
    for (const auto& set : state.texture_sets) {
        writer.u32(static_cast<std::uint32_t>(set.domain));
        writer.u32(set.set_index);
        writer.u32(set.acquisition_count);
        writer.u32(set.row_address);
        writer.u32(set.return_value);
        write_count(set.catalog_indices.size());
        for (const auto catalog : set.catalog_indices) writer.u32(static_cast<std::uint32_t>(catalog));
        write_count(set.texlist_addresses.size());
        for (const auto address : set.texlist_addresses) writer.u32(address);
    }
    write_count(state.dynamic_surfaces.size());
    for (const auto& surface : state.dynamic_surfaces) {
        writer.u32(surface.descriptor_address);
        writer.u32(surface.destination_address);
        writer.u32(surface.source_address);
        writer.u32(surface.extent.width);
        writer.u32(surface.extent.height);
        writer.u32(surface.surface_type);
        writer.u32(surface.surface_flags);
        writer.u32(static_cast<std::uint32_t>(surface.pixel_format));
        writer.u32(static_cast<std::uint32_t>(surface.data_format));
        writer.u64(surface.upload_sequence);
        write_count(surface.encoded.size());
        writer.raw(surface.encoded);
    }
    write_count(state.sound_collection_catalog_indices.size());
    for (const auto index : state.sound_collection_catalog_indices)
        writer.u32(index);
    writer.u32(state.native_audio_control_word);
    writer.u32(state.native_audio_foundation_refcount);
    writer.boolean(state.native_sound_driver_initialized);
    writer.boolean(state.native_audio_stereo_output);
    writer.boolean(state.native_audio_processor_running);
    for (const auto value : state.frame_clear_color) writer.f32(value);
    for (const auto value : state.fog_table_color) writer.f32(value);
    for (const auto value : state.fog_vertex_color) writer.f32(value);
    for (const auto value : state.fog_table) writer.f32(value);
    writer.u32(state.fog_density_word);
    writer.f32(state.cull_value);
    writer.boolean(state.fog_table_color_bound);
    writer.boolean(state.fog_vertex_color_bound);
    writer.boolean(state.fog_density_bound);
    writer.boolean(state.fog_table_bound);
    writer.boolean(state.cull_value_bound);
    return writer.finish();
}

[[nodiscard]] SonicNativeDevelopmentState
decode_sonic_native_development_state(
    const std::span<const std::uint8_t> file_bytes) {
    if (file_bytes.size() < sonic_native_development_state_magic.size() +
                                sizeof(std::uint64_t) ||
        file_bytes.size() > sonic_native_development_state_maximum_bytes)
        throw std::runtime_error("development-state-file-size");
    const auto payload = file_bytes.first(
        file_bytes.size() - sizeof(std::uint64_t));
    std::uint64_t stored_hash = 0u;
    for (std::uint32_t shift = 0u; shift != 64u; shift += 8u)
        stored_hash |= static_cast<std::uint64_t>(
                           file_bytes[payload.size() + shift / 8u])
                       << shift;
    if (sonic_native_development_state_hash(payload) != stored_hash)
        throw std::runtime_error("development-state-checksum");
    SonicNativeDevelopmentStateReader reader(payload);
    std::array<std::uint8_t, sonic_native_development_state_magic.size()>
        magic{};
    reader.raw(magic);
    const auto stored_schema = reader.u32();
    if (magic != sonic_native_development_state_magic ||
        (stored_schema < 3u || stored_schema > sonic_native_development_state_schema) ||
        reader.u32() !=
            katana::runtime::native_port_definition_contract_version ||
        reader.string() !=
            "sonic-adventure-pal-v1003-development-state")
        throw std::runtime_error("development-state-identity");

    SonicNativeDevelopmentState state;
    state.saved_frame_index = reader.u64();
    state.timer_elapsed_nanoseconds = reader.u64();
    state.periodic_elapsed_nanoseconds = reader.u64();
    state.periodic_callbacks_dispatched = reader.u64();
    state.periodic_reload_ticks = reader.u32();
    state.periodic_clock_initialized = reader.boolean();
    state.begun_frames = reader.u64();
    if (stored_schema >= 5u) {
        state.active_video_refresh_hz = reader.u32();
        if (state.active_video_refresh_hz != 0u && state.active_video_refresh_hz != 50u &&
            state.active_video_refresh_hz != 60u)
            throw std::runtime_error("development-state-video-rate");
    }
    if (stored_schema >= 6u) {
        state.standard_sixty_active = reader.boolean();
        state.sixty_original_release = reader.u32();
        state.sixty_original_delta = reader.u32();
    }
    state.module_universe_identity = reader.string();
    state.aot_pack_identity = reader.string();
    state.provider_identity = reader.string();
    state.runtime_binary_identity = reader.string();
    const auto archive_count = reader.u32();
    if (archive_count > max_native_resident_texture_archives)
        throw std::runtime_error("development-state-archive-count");
    for (std::uint32_t index = 0u; index < archive_count; ++index)
        state.archives.push_back({reader.u32(), reader.u64(), reader.string()});
    SonicDevelopmentReadFields service_reader{reader};
    sonic_native_development_fields(service_reader, state.services);
    state.cpu = read_sonic_native_development_cpu(reader);
    const auto memory_size = reader.u32();
    if (memory_size != katana::runtime::native_port_main_memory_backing_size)
        throw std::runtime_error("development-state-main-memory-size");
    state.main_memory.resize(memory_size);
    reader.raw(state.main_memory);
    if (stored_schema < 6u) {
        // Only the explicitly compatible old implementations may migrate.
        // They never owned a standard60 translation; read their saved pair,
        // not the pair from whichever scene happens to be live during load.
        const auto saved_word = [&](std::uint32_t address) {
            const auto offset = (address & 0x1FFFFFFFu) -
                katana::runtime::native_port_main_memory_physical_base;
            if (offset > state.main_memory.size()-4u)
                throw std::runtime_error("development-state-cadence-range");
            std::uint32_t value=0;
            for (unsigned byte=0;byte<4;++byte)
                value |= std::uint32_t(state.main_memory[offset+byte]) << (byte*8u);
            return value;
        };
        state.sixty_original_release = saved_word(sonic_frame_producer_release);
        state.sixty_original_delta = saved_word(0x8C754E04u);
    }

    const auto read_count = [&reader](const std::size_t maximum) {
        const auto count = reader.u32();
        if (count > maximum)
            throw std::runtime_error("development-state-count");
        return count;
    };
    const auto image_count = read_count(
        sonic_native_development_state_maximum_modules);
    state.runtime_images.reserve(image_count);
    for (std::uint32_t index = 0u; index < image_count; ++index)
        state.runtime_images.push_back({reader.string()});
    const auto module_count = read_count(
        sonic_native_development_state_maximum_modules);
    state.modules.reserve(module_count);
    for (std::uint32_t index = 0u; index < module_count; ++index) {
        SonicNativeDevelopmentModule module;
        module.sha256 = reader.string();
        module.source_start = reader.u32();
        module.runtime_start = reader.u32();
        module.byte_size = reader.u32();
        module.activation_entry = reader.u32();
        module.lifecycle_generation = reader.u64();
        module.active = reader.boolean();
        state.modules.push_back(std::move(module));
    }
    state.executable_transition_authority =
        read_sonic_native_development_authority(reader);
    const auto texlist_count = read_count(max_native_texture_names);
    state.texlists.reserve(texlist_count);
    for (std::uint32_t index = 0u; index < texlist_count; ++index) {
        SonicNativeDevelopmentTexlist texlist;
        texlist.texlist_address = reader.u32();
        texlist.texname_address = reader.u32();
        texlist.texture_count = reader.u32();
        texlist.catalog_index = reader.u32();
        texlist.texture_set_references = reader.u64();
        texlist.descriptor_transition_authority = read_sonic_native_development_authority(reader);
        const auto per_entry_count = read_count(max_native_texture_names);
        for (std::uint32_t ordinal = 0u; ordinal < per_entry_count; ++ordinal)
            texlist.per_texture_catalog_indices.push_back(reader.u32());
        texlist.texture_set_owner = reader.boolean();
        texlist.named_archive_binding = reader.boolean();
        texlist.named_archive_owner = reader.boolean();
        texlist.loaded_aot_module_binding = reader.boolean();
        texlist.module_identity = reader.string();
        texlist.module_source_start = reader.u32();
        texlist.module_runtime_start = reader.u32();
        texlist.module_byte_size = reader.u32();
        texlist.module_lifecycle_generation = reader.u64();
        const auto descriptor_count = read_count(max_native_texture_names);
        if (descriptor_count != (texlist.named_archive_binding ? texlist.texture_count : 0u))
            throw std::runtime_error(
                "development-state-texture-descriptor-count");
        texlist.descriptors.reserve(descriptor_count);
        for (std::uint32_t ordinal = 0u; ordinal < descriptor_count;
             ++ordinal) {
            SonicNativeDevelopmentDescriptor descriptor;
            descriptor.descriptor_address = reader.u32();
            descriptor.guest_token = reader.u32();
            descriptor.generation = reader.u64();
            descriptor.transition_epoch = reader.u64();
            for (auto& word : descriptor.replaced_words) word = reader.u32();
            for (auto& word : descriptor.previous_words) word = reader.u32();
            for (auto& word : descriptor.published_words) word = reader.u32();
            texlist.descriptors.push_back(std::move(descriptor));
        }
        state.texlists.push_back(std::move(texlist));
    }
    // Schema 3 predates the split PVM ownership/view records.  Its reader is
    // intentionally kept compatible because the old payload has no bytes in
    // this position; schema 4 always carries both counts, even when empty.
    if (stored_schema >= 4u) {
        const auto allocation_count = read_count(max_native_pvm_allocations);
        state.pvm_allocations.reserve(allocation_count);
        for (std::uint32_t index = 0u; index < allocation_count; ++index)
            state.pvm_allocations.push_back(
                read_sonic_native_pvm_allocation(reader));
        const auto view_count = read_count(max_native_pvm_views);
        state.pvm_views.reserve(view_count);
        for (std::uint32_t index = 0u; index < view_count; ++index) {
            SonicNativePvmView view;
            view.texlist_address = reader.u32();
            view.texname_address = reader.u32();
            view.texture_count = reader.u32();
            view.catalog_index = reader.u32();
            state.pvm_views.push_back(view);
        }
    }
    const auto texture_set_count = read_count(
        sonic_native_main_texture_set_count +
        sonic_native_character_texture_set_count);
    state.texture_sets.reserve(texture_set_count);
    for (std::uint32_t index = 0u; index < texture_set_count; ++index) {
        const auto domain = reader.u32();
        if (domain >
            static_cast<std::uint32_t>(SonicNativeTextureSetDomain::Character))
            throw std::runtime_error("development-state-texture-set-domain");
        SonicNativeDevelopmentTextureSet set;
        set.domain = static_cast<SonicNativeTextureSetDomain>(domain);
        set.set_index = reader.u32();
        set.acquisition_count = reader.u32();
        set.row_address = reader.u32();
        set.return_value = reader.u32();
        const auto catalog_count = read_count(max_native_resident_texture_archives);
        for (std::uint32_t ordinal = 0u; ordinal < catalog_count; ++ordinal)
            set.catalog_indices.push_back(reader.u32());
        const auto row_count = read_count(max_native_texture_set_rows);
        for (std::uint32_t ordinal = 0u; ordinal < row_count; ++ordinal)
            set.texlist_addresses.push_back(reader.u32());
        if (set.acquisition_count == 0u)
            throw std::runtime_error("development-state-texture-set-count");
        state.texture_sets.push_back(set);
    }
    const auto surface_count = read_count(max_native_dynamic_surfaces);
    state.dynamic_surfaces.reserve(surface_count);
    for (std::uint32_t index = 0u; index < surface_count; ++index) {
        SonicNativeDevelopmentDynamicSurface surface;
        surface.descriptor_address = reader.u32();
        surface.destination_address = reader.u32();
        surface.source_address = reader.u32();
        surface.extent.width = reader.u32();
        surface.extent.height = reader.u32();
        surface.surface_type = reader.u32();
        surface.surface_flags = reader.u32();
        surface.pixel_format = static_cast<
            katana::runtime::NativePortTextureAssetPixelFormat>(reader.u32());
        surface.data_format = static_cast<
            katana::runtime::NativePortTextureAssetDataFormat>(reader.u32());
        surface.upload_sequence = reader.u64();
        const auto byte_count = read_count(
            8u * 1024u * 1024u);
        surface.encoded.resize(byte_count);
        reader.raw(surface.encoded);
        state.dynamic_surfaces.push_back(std::move(surface));
    }
    const auto sound_count = read_count(256u);
    state.sound_collection_catalog_indices.reserve(sound_count);
    for (std::uint32_t index = 0u; index < sound_count; ++index)
        state.sound_collection_catalog_indices.push_back(reader.u32());
    state.native_audio_control_word = reader.u32();
    state.native_audio_foundation_refcount = reader.u32();
    state.native_sound_driver_initialized = reader.boolean();
    state.native_audio_stereo_output = reader.boolean();
    state.native_audio_processor_running = reader.boolean();
    for (auto& value : state.frame_clear_color) value = reader.f32();
    for (auto& value : state.fog_table_color) value = reader.f32();
    for (auto& value : state.fog_vertex_color) value = reader.f32();
    for (auto& value : state.fog_table) value = reader.f32();
    state.fog_density_word = reader.u32();
    state.cull_value = reader.f32();
    state.fog_table_color_bound = reader.boolean();
    state.fog_vertex_color_bound = reader.boolean();
    state.fog_density_bound = reader.boolean();
    state.fog_table_bound = reader.boolean();
    state.cull_value_bound = reader.boolean();
    if (!reader.complete())
        throw std::runtime_error("development-state-trailing-data");
    return state;
}

void write_sonic_native_development_state_file(
    const std::filesystem::path& path,
    const std::span<const std::uint8_t> bytes) {
    if (path.empty() || bytes.empty() ||
        bytes.size() > sonic_native_development_state_maximum_bytes)
        throw std::runtime_error("development-state-output");
    if (!path.parent_path().empty())
        std::filesystem::create_directories(path.parent_path());
    auto temporary = path;
    temporary += ".tmp";
    std::error_code error;
    std::filesystem::remove(temporary, error);
    {
        std::ofstream output(temporary, std::ios::binary | std::ios::trunc);
        if (!output)
            throw std::runtime_error("development-state-output-open");
        output.write(reinterpret_cast<const char*>(bytes.data()),
                     static_cast<std::streamsize>(bytes.size()));
        output.flush();
        if (!output)
            throw std::runtime_error("development-state-output-write");
    }
#ifdef _WIN32
    if (!MoveFileExW(
            temporary.c_str(), path.c_str(),
            MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH)) {
        const auto platform_error = GetLastError();
        std::filesystem::remove(temporary, error);
        throw std::runtime_error(
            "development-state-output-commit:" +
            std::to_string(platform_error));
    }
#else
    std::filesystem::rename(temporary, path, error);
    if (error) {
        std::filesystem::remove(temporary, error);
        throw std::runtime_error("development-state-output-commit");
    }
#endif
}

[[nodiscard]] std::vector<std::uint8_t>
read_sonic_native_development_state_file(
    const std::filesystem::path& path) {
    std::error_code error;
    const auto size = std::filesystem::file_size(path, error);
    if (error || size == 0u ||
        size > sonic_native_development_state_maximum_bytes ||
        size > static_cast<std::uintmax_t>(
                   std::numeric_limits<std::streamsize>::max()))
        throw std::runtime_error("development-state-input-size");
    std::ifstream input(path, std::ios::binary);
    if (!input)
        throw std::runtime_error("development-state-input-open");
    std::vector<std::uint8_t> bytes(static_cast<std::size_t>(size));
    input.read(reinterpret_cast<char*>(bytes.data()),
               static_cast<std::streamsize>(bytes.size()));
    if (!input || input.gcount() !=
                      static_cast<std::streamsize>(bytes.size()))
        throw std::runtime_error("development-state-input-read");
    return bytes;
}

// Schema-3/4 snapshots from these reviewed builds use the same pointer-free
// CPU, title, audio and sound-bank formats. Every saved origin also binds its
// exact AOT pack. The sole cross-pack migration below adds the reviewed event
// loader guard: guest bytes, block/owner inventory and ABI remain unchanged,
// while dispatch/chaining becomes guarded at that existing function.
// The module universe, codec DLLs and all saved payloads still match exactly.
// Remove compatibility entries when changing snapshot semantics or formats.
// Schema 5 adds the applied video rate; the legacy reader keeps rate=0 and
// its old host cadence until a real mode apply supplies new evidence. All
// existing exact provider/binary/pack migration checks below remain required.
// Schema6 additionally preserves standard60 ownership and the original
// requested pair. No unreviewed schema5 producer with translated1/1 is admitted.
[[nodiscard]] bool sonic_native_development_implementation_compatible(
    const SonicNativeDevelopmentState& state,
    const std::string_view current_pack) {
    static_assert(sonic_native_development_state_schema == 6u,
                  "Review saved-build migrations before changing the snapshot schema");
    const auto& current_binary = sonic_native_development_binary_identity();
    if (state.provider_identity == sonic_native_title_adapter_source_identity &&
        state.runtime_binary_identity == current_binary)
        return state.aot_pack_identity == current_pack;
    constexpr std::size_t executable_hash_bytes = 64u;
    constexpr std::size_t binary_identity_bytes = 5u * 64u + 4u;
    const std::string_view saved_binary = state.runtime_binary_identity;
    if (saved_binary.size() != binary_identity_bytes ||
        current_binary.size() != binary_identity_bytes ||
        saved_binary.substr(executable_hash_bytes) !=
            std::string_view(current_binary).substr(executable_hash_bytes))
        return false;
    struct CompatibleBuild {
        std::string_view provider;
        std::string_view executable;
        std::string_view pack;
    };
    constexpr std::string_view before_event_guard =
        "sha256:1635ee5cf87575a71fc940328774516a1eab145dbb3b6e409798abb7574d4cd1";
    constexpr std::string_view with_event_guard =
        "sha256:d9a155152bea5d3f24a1c21e39436c6bc331575c001624d98a876b4809b03c5d";
    if (state.aot_pack_identity != current_pack &&
        !(state.aot_pack_identity == before_event_guard &&
          current_pack == with_event_guard))
        return false;
    constexpr std::array<CompatibleBuild, 4u> compatible{{
        // r277: observed immutable-safe RAM restore; full save/load validation.
        {"sha256:cf9548916080fb7fc788fb6b7e4c8ec828a8d4c0429f2a35ba8675571ea73eb3",
         "515fd3e53d809f822c0f009875593ecab47fcf82c5f72e60100ff793731f7626",
         before_event_guard},
        // r279: same schema, reviewed save/repeated-load and migration tests.
        {"sha256:f7406701b23450f94431e356160c5e363da53073a1f936e390342e42536bb9b0",
         "2ef74135c944d6170704ff5ababdbda1c9234c722f471168ab3a844c67e606e4",
         before_event_guard},
        // r278: only the SDK texture-reference-count width differs from r277.
        {"sha256:b22eb546bc9ef0d3bb2f6ef3724ffbc5458cc78a7373fa881e413429072eaeec",
         "117fde36c63d9235ac935bbde858ef3cd16f50d1c4fc2a5891682d4943d471d9",
         before_event_guard},
        // r280: same snapshot format with the event arena guard installed.
        {"sha256:4286e8e41e911ba0ec0d7d8136d94cbf2aedee1fc2ef09fe2e1b7f97420b0cad",
         "50ec266a119f782bde6d826f27d4b48e2fac35e02687bdb092a937cd60ef3110",
         with_event_guard},
    }};
    return std::ranges::any_of(compatible, [&](const CompatibleBuild& build) {
        return state.provider_identity == build.provider &&
               saved_binary.substr(0u, executable_hash_bytes) == build.executable &&
               state.aot_pack_identity == build.pack;
    });
}

// Reads only the immutable snapshot during preflight. It must never consult
// the current level's CPU memory, registry or texture ownership.
class SonicNativeSavedGuestReader final {
  public:
    explicit SonicNativeSavedGuestReader(
        const std::span<const std::uint8_t> bytes) noexcept : bytes_(bytes) {}

    [[nodiscard]] bool range(const std::uint32_t address,
                             const std::size_t size) const noexcept {
        const auto physical = sonic_native_backing_address(address);
        constexpr auto base = katana::runtime::native_port_main_memory_physical_base;
        return physical >= base &&
            static_cast<std::uint64_t>(physical - base) <= bytes_.size() &&
            size <= bytes_.size() - static_cast<std::size_t>(physical - base);
    }

    [[nodiscard]] bool u32(const std::uint32_t address,
                           std::uint32_t& value) const noexcept {
        if (!range(address, sizeof(value))) return false;
        const auto offset = sonic_native_backing_address(address) -
            katana::runtime::native_port_main_memory_physical_base;
        value = 0u;
        for (std::uint32_t byte = 0u; byte < 4u; ++byte)
            value |= static_cast<std::uint32_t>(bytes_[offset + byte]) << (byte * 8u);
        return true;
    }

  private:
    std::span<const std::uint8_t> bytes_;
};

struct SonicNativeDevelopmentDescriptorClaim final {
    const SonicNativeDevelopmentTexlist* texlist = nullptr;
    const SonicNativeDevelopmentDescriptor* descriptor = nullptr;
    std::size_t ordinal = 0u;
    std::array<std::uint32_t, sonic_ninja_texture_descriptor_words>
        current_words{};
};

enum class SonicNativeDevelopmentDescriptorClaimFailure : std::uint32_t {
    None,
    RowImageConflict,
    PublishedWordsConflict,
    MultipleExactPublications,
    HistoricalRowNotReusable,
};

struct SonicNativeDevelopmentDescriptorClaimCheck final {
    SonicNativeDevelopmentDescriptorClaimFailure failure =
        SonicNativeDevelopmentDescriptorClaimFailure::None;
    std::size_t claim = 0u;
    std::size_t conflicting_claim = std::numeric_limits<std::size_t>::max();
};

// A registry row is an SDK allocation slot, not a permanent owner identity.
// Preserve every authenticated historical claim, but require one coherent
// saved row image, at most one unsuperseded current publication, and the bounded
// SDK reuse proof for every displaced claim. This grants no restore write.
template <typename GuestReader>
[[nodiscard]] SonicNativeDevelopmentDescriptorClaimCheck
check_sonic_native_development_descriptor_claim_group(
    const GuestReader& reader,
    const std::span<const SonicNativeDevelopmentDescriptorClaim> claims) {
    if (claims.empty()) return {};
    std::size_t exact_publication = std::numeric_limits<std::size_t>::max();
    for (std::size_t claim = 0u; claim < claims.size(); ++claim)
        if (claims[claim].descriptor == nullptr || claims[claim].texlist == nullptr ||
            claims[claim].current_words != claims.front().current_words)
            return {SonicNativeDevelopmentDescriptorClaimFailure::RowImageConflict,
                    claim, 0u};
    for (std::size_t claim = 0u; claim < claims.size(); ++claim) {
        const auto& candidate = claims[claim];
        const bool exact_words =
            sonic_native_same_texture_publication(candidate.current_words, candidate.descriptor->published_words);
        std::size_t newer_publications = 0u;
        for (std::size_t other = 0u; other < claims.size(); ++other) {
            if (other == claim || claims[other].descriptor->published_words !=
                                      candidate.descriptor->published_words) continue;
            const auto& peer = claims[other];
            const bool peer_supersedes = sonic_native_descriptor_publication_supersedes(
                *candidate.descriptor, candidate.texlist->descriptor_transition_authority,
                *peer.descriptor, peer.texlist->descriptor_transition_authority);
            if (peer_supersedes) ++newer_publications;
            else if (!sonic_native_descriptor_publication_supersedes(
                         *peer.descriptor, peer.texlist->descriptor_transition_authority,
                         *candidate.descriptor, candidate.texlist->descriptor_transition_authority))
                return {SonicNativeDevelopmentDescriptorClaimFailure::PublishedWordsConflict,
                        claim, other};
        }
        const bool current_publication = exact_words && newer_publications == 0u;
        if (current_publication &&
            exact_publication != std::numeric_limits<std::size_t>::max())
            return {
                SonicNativeDevelopmentDescriptorClaimFailure::MultipleExactPublications,
                claim, exact_publication};
        if (current_publication) {
            exact_publication = claim;
            continue;
        }
        if (exact_words && newer_publications != 0u &&
            sonic_native_descriptor_is_registry_row(reader, candidate.descriptor->descriptor_address))
            continue; // Authenticated ABA history; no restore write to this row.
        if (!sonic_native_descriptor_is_registry_row(
                reader, candidate.descriptor->descriptor_address) ||
            !sonic_native_descriptor_has_sdk_row_reuse(
                reader, *candidate.descriptor, candidate.current_words))
            return {
                SonicNativeDevelopmentDescriptorClaimFailure::HistoricalRowNotReusable,
                claim, exact_publication};
    }
    return {};
}

void validate_sonic_native_development_state(
    katana::runtime::NativePortContext& context,
    const SonicNativeDevelopmentState& state) {
    if (!valid_sonic_native_context(context) ||
        context.runtime_images == nullptr || context.loaded_aot == nullptr ||
        context.development_state_restore_main_memory == nullptr ||
        context.development_state_validate_main_memory == nullptr ||
        context.development_state_static_entry == nullptr ||
        state.main_memory.size() !=
            katana::runtime::native_port_main_memory_backing_size ||
        !sonic_native_development_implementation_compatible(
            state, context.loaded_aot->aot_pack_identity()) ||
        state.module_universe_identity !=
            context.loaded_aot->module_universe_identity())
        throw std::runtime_error("development-state-runtime-identity");
    if (state.cpu.active_instruction_pc != 0u ||
        state.cpu.active_instruction_physical_pc != 0u ||
        state.cpu.active_block_virtual_start != 0u ||
        state.cpu.active_block_physical_start != 0u ||
        state.cpu.active_block_size != 0u)
        throw std::runtime_error("development-state-active-execution");

    if ((state.cpu.pc & 1u) != 0u || (state.cpu.pc >> 29u) >= 6u)
        throw std::runtime_error("development-state-resume-entry");
    if (!context.development_state_validate_main_memory(context, state.main_memory))
        throw std::runtime_error("development-state-fixed-memory-preflight");

    if (!sonic_native_title_state.audio_engine || !sonic_native_title_state.sound_bank_engine)
        throw std::runtime_error("development-state-audio-provider");
    const auto audio_inventory =
        sonic_native_title_state.audio_engine->validate_development_state(state.services.audio);
    const auto bank_inventory =
        sonic_native_title_state.sound_bank_engine->validate_development_state(state.services.sound_bank);
    const auto has_handle = [](const auto& inventory, const auto& handle) {
        return std::ranges::any_of(inventory, [&](const auto& candidate) {
            return candidate.slot == handle.slot && candidate.generation == handle.generation;
        });
    };
    const auto require_collection = [&](const auto& handle) {
        if (!has_handle(bank_inventory.collections, handle))
            throw std::runtime_error("development-state-sound-collection-handle");
    };
    std::set<std::size_t> collection_catalogs;
    std::set<std::pair<std::uint32_t, std::uint32_t>> collection_handles;
    for (const auto& item : state.services.loaded_sound_collections) {
        if (std::ranges::none_of(sonic_native::sound_collection_catalog(),
                [&](const auto& candidate) { return candidate.catalog_index == item.catalog_index; }) ||
            !collection_catalogs.insert(item.catalog_index).second ||
            !collection_handles.insert({item.handle.slot, item.handle.generation}).second)
            throw std::runtime_error("development-state-sound-collection-catalog");
        require_collection(item.handle);
    }
    if (state.services.current_sound_collection)
        require_collection(*state.services.current_sound_collection);
    for (const auto& unit : state.services.sound_unit_registrations)
        if (unit.bound || unit.pending) require_collection(unit.collection);
    for (const auto& ring : state.services.sound_pcm_stream_ring_registrations)
        if (ring.bound && !has_handle(bank_inventory.pcm_stream_rings, ring.handle))
            throw std::runtime_error("development-state-sound-ring-handle");
    const auto validate_ports = [&](const auto& ports, const auto& collections) {
        for (std::size_t index = 0u; index < ports.size(); ++index) {
            if (ports[index] && !has_handle(bank_inventory.midi_ports, *ports[index]))
                throw std::runtime_error("development-state-sound-port-handle");
            if (collections[index]) require_collection(*collections[index]);
            if (ports[index].has_value() != collections[index].has_value())
                throw std::runtime_error("development-state-sound-port-owner");
        }
    };
    validate_ports(state.services.sound_midi_ports, state.services.sound_midi_port_collections);
    validate_ports(state.services.sound_sequence_ports, state.services.sound_sequence_port_collections);
    for (const auto& stream : state.services.adx)
        if (stream.stream.voice && !has_handle(audio_inventory.voices, *stream.stream.voice))
            throw std::runtime_error("development-state-adx-voice-handle");
    const auto known_content = [](const std::string& path) {
        return path.empty() || std::ranges::any_of(sonic_native_content_bindings,
            [&](const auto& content) { return content.guest_path == path; });
    };
    if (!known_content(state.services.event_adx_path))
        throw std::runtime_error("development-state-audio-content");
    for (const auto& stream : state.services.adx)
        if (!known_content(stream.path) || (stream.stream.voice.has_value() && stream.path.empty()) ||
            (stream.stream.voice.has_value() && !stream.stream.bound))
            throw std::runtime_error("development-state-audio-stream");
    struct SavedRange final {
        std::uint32_t begin = 0u;
        std::uint64_t end = 0u;
    };
    std::vector<SavedRange> module_ranges;
    module_ranges.reserve(state.modules.size() + state.runtime_images.size());
    const auto saved_pc_backing = sonic_native_backing_address(state.cpu.pc);
    bool saved_pc_dynamic_owner = false;
    const auto owns_saved_pc = [&](const std::uint32_t address, const std::uint32_t size) {
        const auto begin = sonic_native_backing_address(address);
        return saved_pc_backing >= begin &&
            static_cast<std::uint64_t>(saved_pc_backing) <
                static_cast<std::uint64_t>(begin) + size;
    };
    const auto add_range = [&](const std::uint32_t address, const std::uint32_t size) {
        const auto begin = sonic_native_backing_address(address);
        const auto end = static_cast<std::uint64_t>(begin) + size;
        if (size == 0u || end > 0x0D000000ull)
            throw std::runtime_error("development-state-executable-range");
        for (const auto& range : module_ranges)
            if (begin < range.end && range.begin < end)
                throw std::runtime_error("development-state-executable-overlap");
        module_ranges.push_back({begin, end});
    };
    std::set<std::string> image_ids;
    for (const auto& image : state.runtime_images) {
        if (!image_ids.insert(image.image_id).second)
            throw std::runtime_error("development-state-runtime-image");
        const auto range = context.runtime_images->validate_development_state_image(
            image.image_id, state.main_memory);
        add_range(range.runtime_start, static_cast<std::uint32_t>(range.byte_size));
        if (owns_saved_pc(range.runtime_start, static_cast<std::uint32_t>(range.byte_size))) {
            static_cast<void>(context.runtime_images->validate_development_state_image(
                image.image_id, state.cpu.pc, state.main_memory));
            saved_pc_dynamic_owner = true;
        }
    }
    std::set<std::tuple<std::string, std::uint32_t, std::uint32_t>> modules;
    for (const auto& module : state.modules) {
        const katana::runtime::NativePortLoadedAotModuleActivation activation{
            module.sha256, module.source_start, module.runtime_start,
            module.byte_size};
        context.loaded_aot->validate_development_state_module(
            activation, module.activation_entry, state.main_memory);
        if (!modules
                 .insert({module.sha256, module.source_start,
                          module.runtime_start})
                 .second)
            throw std::runtime_error("development-state-module-duplicate");
        add_range(module.runtime_start, module.byte_size);
        if (owns_saved_pc(module.runtime_start, module.byte_size)) {
            if (!module.active)
                throw std::runtime_error("development-state-resume-owner-inactive");
            context.loaded_aot->validate_development_state_module(
                activation, state.cpu.pc, state.main_memory);
            saved_pc_dynamic_owner = true;
        }
    }
    // Classify against the saved inventories, never the unrelated live level.
    // A dynamic range claims its whole carrier, including non-entry data;
    // its exact-entry validator must succeed before any fallback is possible.
    if (!saved_pc_dynamic_owner && !context.development_state_static_entry(state.cpu.pc))
        throw std::runtime_error("development-state-resume-entry");
    const auto& authority = state.executable_transition_authority;
    if (sonic_native_transition_authority_bound(authority)) {
        const auto match = std::ranges::find_if(
            state.modules,
            [&](const SonicNativeDevelopmentModule& module) {
                return module.active &&
                       module.sha256 == authority.module_identity &&
                       module.source_start == authority.module_source_start &&
                       module.runtime_start == authority.module_runtime_start &&
                       module.byte_size == authority.module_byte_size &&
                       module.lifecycle_generation ==
                           authority.module_lifecycle_generation;
            });
        if (match == state.modules.end() || authority.transition_epoch == 0u)
            throw std::runtime_error(
                "development-state-transition-authority");
    }

    // Validate against the saved RAM image, never the unrelated level that
    // happens to be running when Quick Load is requested.
    const SonicNativeSavedGuestReader saved_reader(state.main_memory);
    const auto saved_word = [&](const std::uint64_t address) {
        if (address > std::numeric_limits<std::uint32_t>::max())
            throw std::runtime_error("development-state-guest-address");
        std::uint32_t word = 0u;
        if (!saved_reader.u32(static_cast<std::uint32_t>(address), word))
            throw std::runtime_error("development-state-guest-range");
        return word;
    };
    if (state.standard_sixty_active &&
        (!sonic_standard_sixty_enabled() || state.active_video_refresh_hz!=60u ||
         state.sixty_original_release!=2u || state.sixty_original_delta!=2u ||
         saved_word(0x8C754B44u)!=0u || saved_word(sonic_frame_producer_release)!=1u ||
         saved_word(0x8C754E04u)!=1u))
        throw std::runtime_error("development-state-standard60-cadence-incompatible");
    const auto& services = state.services;
    if (services.font_source_address != 0u) {
        const auto dimension = services.font_dimension;
        const auto physical = sonic_native_backing_address(services.font_source_address);
        constexpr auto base = katana::runtime::native_port_main_memory_physical_base;
        const auto bytes = static_cast<std::uint64_t>(dimension) * dimension * 2u;
        if (dimension < 8u || dimension > 1024u || !std::has_single_bit(dimension) ||
            services.font_format != sonic_ninja_font_argb1555_twiddled || physical < base ||
            static_cast<std::uint64_t>(physical - base) + bytes > state.main_memory.size())
            throw std::runtime_error("development-state-font");
    } else if (services.font_dimension != 0u || services.font_format != 0u) {
        throw std::runtime_error("development-state-font-unbound");
    }
    if (services.texture_binding.valid &&
        (saved_word(services.texture_binding.texlist_address) != services.texture_binding.texname_address ||
         saved_word(static_cast<std::uint64_t>(services.texture_binding.texlist_address) + 4u) !=
             services.texture_binding.texture_count))
        throw std::runtime_error("development-state-selected-texlist");
    if (services.most_recent_texture_archive &&
        std::ranges::none_of(state.archives, [&](const auto& archive) {
            return archive.catalog_index == *services.most_recent_texture_archive;
        }))
        throw std::runtime_error("development-state-selected-archive");
    std::map<std::size_t, std::uint64_t> expected_archive_references;
    const auto maximum_archive_references =
        static_cast<std::uint64_t>(max_native_pvm_allocations) +
        static_cast<std::uint64_t>(max_native_texture_names) +
        sonic_native_main_texture_set_count +
        sonic_native_character_texture_set_count;
    for (const auto& archive : state.archives) {
        const auto catalog = sonic_native::texture_archive_binding(archive.catalog_index);
        if (!catalog || catalog->byte_identity != archive.byte_identity ||
            archive.references > maximum_archive_references ||
            !expected_archive_references.emplace(archive.catalog_index, 0u).second)
            throw std::runtime_error("development-state-archive-identity");
    }
    struct SavedPvmAllocationClaim final {
        const SonicNativePvmAllocation* allocation = nullptr;
        std::array<std::uint32_t, sonic_ninja_texture_descriptor_words>
            current_words{};
        bool current_free = false;
    };
    std::map<std::uint32_t, SavedPvmAllocationClaim> pvm_allocation_claims;
    std::set<std::tuple<std::uint32_t, std::uint32_t, std::uint32_t>>
        pvm_allocation_publications;
    std::map<std::uint32_t, std::uint64_t> pvm_catalog_generations;
    if (state.pvm_allocations.size() > max_native_pvm_allocations)
        throw std::runtime_error("development-state-pvm-allocation-count");
    for (const auto& allocation : state.pvm_allocations) {
        const auto catalog =
            sonic_native::texture_archive_binding(allocation.catalog_index);
        const auto& descriptor = allocation.descriptor;
        if (!catalog || (catalog->standalone_pvr &&
                         (catalog->entry_count != 1u || allocation.archive_ordinal != 0u)) ||
            !expected_archive_references.contains(allocation.catalog_index) ||
            allocation.archive_ordinal >= catalog->entry_count)
            throw std::runtime_error("development-state-pvm-allocation-identity");
        if (descriptor.descriptor_address == 0u ||
            !sonic_native_descriptor_is_registry_row(
                saved_reader, descriptor.descriptor_address))
            throw std::runtime_error("development-state-pvm-allocation-row");
        const auto physical =
            sonic_native_backing_address(descriptor.descriptor_address);
        if (!pvm_allocation_publications.insert(
                 {allocation.catalog_index, allocation.archive_ordinal,
                  physical})
                 .second)
            throw std::runtime_error(
                "development-state-pvm-allocation-identity");
        if (descriptor.guest_token == 0u ||
            descriptor.guest_token == 0xFFFFFFFFu ||
            descriptor.generation == 0u ||
            (descriptor.published_words[0] == 0u && !catalog->standalone_pvr) ||
            descriptor.published_words[0] == 0xFFFFFFFFu ||
            descriptor.published_words[1] != 0xFFFFFFFFu ||
            descriptor.published_words[4] !=
                sonic_ninja_texture_descriptor_loaded ||
            descriptor.published_words[6] != 0u)
            throw std::runtime_error("development-state-pvm-allocation-descriptor");
        std::array<std::uint32_t, sonic_ninja_texture_descriptor_words>
            current{};
        for (std::size_t word = 0u; word < current.size(); ++word)
            current[word] = saved_word(
                static_cast<std::uint64_t>(descriptor.descriptor_address) + word * 4u);
        const bool current_published =
            sonic_native_pvm_row_matches(descriptor, current);
        const bool current_free =
            sonic_native_guest_texture_descriptor_released(current);
        if (!current_published && !current_free)
            throw std::runtime_error("development-state-pvm-allocation-current");
        if (const auto [it, inserted] = pvm_catalog_generations.emplace(
                allocation.catalog_index, descriptor.generation);
            !inserted && it->second != descriptor.generation)
            throw std::runtime_error("development-state-pvm-allocation-generation");
        if (const auto [previous, inserted] = pvm_allocation_claims.emplace(
                physical,
                SavedPvmAllocationClaim{&allocation, current, current_free}); !inserted) {
            const auto& other = *previous->second.allocation;
            const auto other_catalog = sonic_native::texture_archive_binding(other.catalog_index);
            const auto payload = sonic_native::texture_archive_entry_pvrt_identity(*catalog, allocation.archive_ordinal);
            const auto other_payload = other_catalog
                ? sonic_native::texture_archive_entry_pvrt_identity(*other_catalog, other.archive_ordinal)
                : std::nullopt;
            if (!payload || !other_payload || *payload != *other_payload ||
                previous->second.current_words != current ||
                !sonic_native_same_texture_publication(descriptor.published_words, other.descriptor.published_words))
                throw std::runtime_error("development-state-pvm-allocation-duplicate");
        }
        auto& references = expected_archive_references.at(allocation.catalog_index);
        if (references == std::numeric_limits<std::uint64_t>::max())
            throw std::runtime_error("development-state-archive-reference-count");
        // Each retained catalog/ordinal alias owns one resident pin. A
        // view below is only a copied M-pointer projection and adds no pin.
        ++references;
    }
    if (state.pvm_views.size() > max_native_pvm_views)
        throw std::runtime_error("development-state-pvm-view-count");
    std::set<std::uint32_t> texlist_addresses;
    std::map<std::uint32_t,
             std::vector<SonicNativeDevelopmentDescriptorClaim>>
        descriptor_claims;
    const auto fail_descriptor_owner = [&](
        const std::string_view clause,
        const SonicNativeDevelopmentTexlist& texlist,
        const std::size_t ordinal,
        const std::uint32_t descriptor_address,
        const SonicNativeDevelopmentDescriptorClaim* conflict) -> void {
        std::cerr << "SONIC_NATIVE_DEVELOPMENT_STATE"
                  << " failure=development-state-texture-descriptor-owner"
                  << " clause=" << clause
                  << " texlist=0x" << std::hex << texlist.texlist_address
                  << " ordinal=" << std::dec << ordinal
                  << " descriptor=0x" << std::hex << descriptor_address
                  << " row=0x"
                  << sonic_native_backing_address(descriptor_address);
        if (conflict != nullptr)
            std::cerr << " conflicting_texlist=0x"
                      << conflict->texlist->texlist_address
                      << " conflicting_ordinal=" << std::dec
                      << conflict->ordinal
                      << " conflicting_descriptor=0x" << std::hex
                      << conflict->descriptor->descriptor_address;
        else
            std::cerr << " conflicting_claim=none";
        std::cerr << std::dec << '\n';
        throw std::runtime_error(
            "development-state-texture-descriptor-owner");
    };
    for (const auto& texlist : state.texlists) {
        const auto catalog = sonic_native::texture_archive_binding(texlist.catalog_index);
        const bool per_entry = !texlist.per_texture_catalog_indices.empty();
        if (!catalog || !expected_archive_references.contains(texlist.catalog_index) ||
            texlist.texture_count == 0u || texlist.texture_count > max_native_texture_names ||
            (per_entry ? texlist.per_texture_catalog_indices.size() != texlist.texture_count
                       : !sonic_native_named_texture_archive_view_is_exact(*catalog, texlist.texture_count)) ||
            texlist.descriptors.size() != (texlist.named_archive_binding ? texlist.texture_count : 0u) ||
            (!texlist.texture_set_owner && !texlist.named_archive_owner) ||
            (texlist.named_archive_owner && (!texlist.named_archive_binding || per_entry)) ||
            texlist.texture_set_references != 1u ||
            !texlist_addresses.insert(sonic_native_backing_address(texlist.texlist_address)).second ||
            saved_word(texlist.texlist_address) != texlist.texname_address ||
            saved_word(static_cast<std::uint64_t>(texlist.texlist_address) + 4u) != texlist.texture_count)
            throw std::runtime_error("development-state-texture-catalog");
        if (texlist.named_archive_owner) ++expected_archive_references.at(texlist.catalog_index);
        std::map<std::uint32_t, SonicNativeDevelopmentDescriptorClaim>
            binding_descriptor_claims;
        for (std::size_t ordinal = 0u; ordinal < texlist.descriptors.size(); ++ordinal) {
            const auto& descriptor = texlist.descriptors[ordinal];
            const auto index = per_entry ? texlist.per_texture_catalog_indices[ordinal] : texlist.catalog_index;
            const auto entry_catalog = sonic_native::texture_archive_binding(index);
            if (!entry_catalog)
                fail_descriptor_owner("catalog", texlist, ordinal,
                                      descriptor.descriptor_address, nullptr);
            if (!expected_archive_references.contains(index))
                fail_descriptor_owner("archive-reference", texlist, ordinal,
                                      descriptor.descriptor_address, nullptr);
            if (per_entry &&
                (!entry_catalog->standalone_pvr || entry_catalog->entry_count != 1u))
                fail_descriptor_owner("per-entry-catalog", texlist, ordinal,
                                      descriptor.descriptor_address, nullptr);
            if (descriptor.guest_token == 0u)
                fail_descriptor_owner("token-zero", texlist, ordinal,
                                      descriptor.descriptor_address, nullptr);
            if (descriptor.guest_token == 0xFFFFFFFFu)
                fail_descriptor_owner("token-sentinel", texlist, ordinal,
                                      descriptor.descriptor_address, nullptr);
            if (descriptor.generation == 0u)
                fail_descriptor_owner("generation-zero", texlist, ordinal,
                                      descriptor.descriptor_address, nullptr);
            const auto physical_descriptor =
                sonic_native_backing_address(descriptor.descriptor_address);
            if (const auto previous = binding_descriptor_claims.find(
                    physical_descriptor);
                previous != binding_descriptor_claims.end())
                fail_descriptor_owner("binding-row-conflict", texlist,
                                      ordinal, descriptor.descriptor_address,
                                      &previous->second);
            const auto reference_address =
                static_cast<std::uint64_t>(texlist.texname_address) +
                ordinal * 12u + 8u;
            std::uint32_t reference = 0u;
            if (reference_address > std::numeric_limits<std::uint32_t>::max() ||
                !saved_reader.u32(static_cast<std::uint32_t>(reference_address),
                                  reference))
                fail_descriptor_owner("texname-reference-read", texlist,
                                      ordinal, descriptor.descriptor_address, nullptr);
            if (!sonic_native_same_backing_address(
                    reference, descriptor.descriptor_address))
                fail_descriptor_owner("texname-reference", texlist, ordinal,
                                      descriptor.descriptor_address, nullptr);
            std::array<std::uint32_t, sonic_ninja_texture_descriptor_words> current{};
            for (std::size_t word = 0u; word < current.size(); ++word)
                current[word] = saved_word(
                    static_cast<std::uint64_t>(descriptor.descriptor_address) + word * 4u);
            // An allocation row may also be named by a copied TEXNAME view.
            // Permit that exact live alias, while allowing an older binding
            // history after the row was freed/reused. Two live publications
            // at the same SDK row must carry one coherent identity.
            if (const auto allocation = pvm_allocation_claims.find(
                    physical_descriptor);
                allocation != pvm_allocation_claims.end()) {
                const auto& allocated = allocation->second.allocation->descriptor;
                SonicNativeGuestTextureDescriptor normal_binding_shape;
                normal_binding_shape.published_words = descriptor.published_words;
                const auto allocated_catalog = sonic_native::texture_archive_binding(
                    allocation->second.allocation->catalog_index);
                const auto a = sonic_native::texture_archive_entry_pvrt_identity(*entry_catalog, per_entry ? 0u : ordinal);
                const auto b = allocated_catalog
                    ? sonic_native::texture_archive_entry_pvrt_identity(*allocated_catalog,
                        allocation->second.allocation->archive_ordinal) : std::nullopt;
                if (sonic_native_pvm_row_matches(allocated, current) &&
                    sonic_native_pvm_row_matches(normal_binding_shape, current) &&
                    (!a || !b || *a != *b))
                    fail_descriptor_owner("pvm-allocation-publication", texlist,
                                          ordinal, descriptor.descriptor_address,
                                          nullptr);
            }
            const SonicNativeDevelopmentDescriptorClaim claim{
                &texlist, &descriptor, ordinal, current};
            binding_descriptor_claims.emplace(physical_descriptor, claim);
            descriptor_claims[physical_descriptor].push_back(claim);
        }
        if (texlist.loaded_aot_module_binding) {
            const auto match = std::ranges::find_if(state.modules, [&](const auto& module) {
                return module.active && module.sha256 == texlist.module_identity &&
                    module.source_start == texlist.module_source_start &&
                    module.runtime_start == texlist.module_runtime_start &&
                    module.byte_size == texlist.module_byte_size &&
                    module.lifecycle_generation == texlist.module_lifecycle_generation;
            });
            if (match == state.modules.end())
                throw std::runtime_error("development-state-texture-module");
        }
    }
    const auto descriptor_group_clause = [](
        const SonicNativeDevelopmentDescriptorClaimFailure failure) {
        switch (failure) {
        case SonicNativeDevelopmentDescriptorClaimFailure::RowImageConflict:
            return std::string_view{"row-image-conflict"};
        case SonicNativeDevelopmentDescriptorClaimFailure::PublishedWordsConflict:
            return std::string_view{"published-words-conflict"};
        case SonicNativeDevelopmentDescriptorClaimFailure::MultipleExactPublications:
            return std::string_view{"multiple-exact-publications"};
        case SonicNativeDevelopmentDescriptorClaimFailure::HistoricalRowNotReusable:
            return std::string_view{"historical-row-not-reusable"};
        case SonicNativeDevelopmentDescriptorClaimFailure::None:
            break;
        }
        return std::string_view{"unknown"};
    };
    for (const auto& [row, claims] : descriptor_claims) {
        const auto check = check_sonic_native_development_descriptor_claim_group(
            saved_reader, std::span<const SonicNativeDevelopmentDescriptorClaim>{
                              claims});
        if (check.failure ==
            SonicNativeDevelopmentDescriptorClaimFailure::None)
            continue;
        const auto& claim = claims.at(check.claim);
        const auto* conflict =
            check.conflicting_claim < claims.size()
                ? &claims[check.conflicting_claim]
                : nullptr;
        fail_descriptor_owner(descriptor_group_clause(check.failure),
                              *claim.texlist, claim.ordinal,
                              claim.descriptor->descriptor_address, conflict);
    }
    // Catalog aliases are provenance, not SDK leases. Their cardinality may
    // exceed or fall below the row's low16 reference count. Exact payload,
    // current publication and generation checks above authenticate sharing;
    // no invented alias-count invariant may reject a valid saved SDK state.
    std::set<std::uint32_t> pvm_view_texlists;
    for (const auto& view : state.pvm_views) {
        const auto catalog =
            sonic_native::texture_archive_binding(view.catalog_index);
        if (!catalog ||
            view.texlist_address == 0u || view.texname_address == 0u ||
            view.texture_count == 0u ||
            view.texture_count > max_native_texture_names ||
            !pvm_view_texlists.insert(
                 sonic_native_backing_address(view.texlist_address))
                 .second)
            throw std::runtime_error("development-state-pvm-view-identity");
        const auto name_bytes =
            static_cast<std::uint64_t>(view.texture_count) * 12u;
        if (static_cast<std::uint64_t>(view.texname_address) + name_bytes >
                static_cast<std::uint64_t>(
                    std::numeric_limits<std::uint32_t>::max()) +
                    1u ||
            !saved_reader.range(view.texname_address,
                                static_cast<std::size_t>(name_bytes)) ||
            saved_word(view.texlist_address) != view.texname_address ||
            saved_word(static_cast<std::uint64_t>(view.texlist_address) + 4u) !=
                view.texture_count)
            throw std::runtime_error("development-state-pvm-view-header");
        for (std::uint32_t ordinal = 0u; ordinal < view.texture_count;
             ++ordinal) {
            const auto reference_address =
                static_cast<std::uint64_t>(view.texname_address) +
                static_cast<std::uint64_t>(ordinal) * 12u + 8u;
            std::uint32_t descriptor_address = 0u;
            if (reference_address >
                    std::numeric_limits<std::uint32_t>::max() ||
                !saved_reader.u32(static_cast<std::uint32_t>(reference_address),
                                  descriptor_address) ||
                descriptor_address == 0u || descriptor_address == 0xFFFFFFFFu ||
                !sonic_native_descriptor_is_registry_row(
                    saved_reader, descriptor_address))
                throw std::runtime_error("development-state-pvm-view-reference");
        }
    }
    std::set<std::pair<std::uint32_t, std::uint32_t>> texture_sets;
    std::set<std::uint32_t> owned_texlists;
    for (const auto& set : state.texture_sets) {
        const bool main = set.domain == SonicNativeTextureSetDomain::Main;
        const auto limit = main ? sonic_native_main_texture_set_count : sonic_native_character_texture_set_count;
        const auto table = main ? sonic_main_texture_set_table : sonic_character_texture_set_table;
        if (set.set_index >= limit || set.acquisition_count == 0u ||
            (main && set.acquisition_count != 1u) ||
            set.acquisition_count > 255u || set.texlist_addresses.empty() ||
            !texture_sets.insert({static_cast<std::uint32_t>(set.domain), set.set_index}).second ||
            saved_word(table + set.set_index * 4u) != set.row_address)
            throw std::runtime_error("development-state-texture-set");
        std::set<std::size_t> row_catalogs;
        std::set<std::uint32_t> rows;
        bool terminated = false;
        for (std::size_t row = 0u; row < max_native_texture_set_rows; ++row) {
            const auto name = saved_word(static_cast<std::uint64_t>(set.row_address) + row * 8u);
            const auto address = saved_word(static_cast<std::uint64_t>(set.row_address) + row * 8u + 4u);
            if (name == 0u && address == 0u) { terminated = true; break; }
            rows.insert(sonic_native_backing_address(address));
        }
        if (!terminated) throw std::runtime_error("development-state-texture-set-terminator");
        std::set<std::uint32_t> set_lists;
        for (const auto address : set.texlist_addresses) {
            const auto physical = sonic_native_backing_address(address);
            const auto binding = std::ranges::find_if(state.texlists, [&](const auto& candidate) {
                return sonic_native_same_backing_address(candidate.texlist_address, address);
            });
            if (!rows.contains(physical) || !set_lists.insert(physical).second ||
                binding == state.texlists.end() || !binding->texture_set_owner)
                throw std::runtime_error("development-state-texture-set-row");
            owned_texlists.insert(physical);
            if (binding->per_texture_catalog_indices.empty()) row_catalogs.insert(binding->catalog_index);
            else row_catalogs.insert(binding->per_texture_catalog_indices.begin(),
                                     binding->per_texture_catalog_indices.end());
        }
        const std::set<std::size_t> catalogs(set.catalog_indices.begin(), set.catalog_indices.end());
        if (catalogs.size() != set.catalog_indices.size() || catalogs != row_catalogs)
            throw std::runtime_error("development-state-texture-set-catalogs");
        for (const auto catalog : catalogs) ++expected_archive_references.at(catalog);
    }
    for (const auto& binding : state.texlists)
        if (binding.texture_set_owner != owned_texlists.contains(sonic_native_backing_address(binding.texlist_address)))
            throw std::runtime_error("development-state-texture-set-lease");
    for (const auto& archive : state.archives)
        if (archive.references != expected_archive_references.at(archive.catalog_index))
            throw std::runtime_error("development-state-archive-reference-count");
    std::set<std::uint32_t> dynamic_surface_descriptors;
    std::set<std::uint64_t> dynamic_surface_sequences;
    for (const auto& surface : state.dynamic_surfaces) {
        const auto bytes = surface.encoded.size();
        if (surface.descriptor_address == 0u || bytes == 0u ||
            surface.extent.width == 0u || surface.extent.height == 0u ||
            surface.destination_address >= native_texture_backing_bytes ||
            bytes > native_texture_backing_bytes -
                        surface.destination_address ||
            surface.upload_sequence == 0u ||
            !dynamic_surface_descriptors.insert(surface.descriptor_address)
                 .second ||
            !dynamic_surface_sequences.insert(surface.upload_sequence).second)
            throw std::runtime_error("development-state-dynamic-surface");
        // Decode before the destructive restore commit. This validates the
        // enum values, format-specific byte count, mip layout and dimensions
        // using the same bounded implementation that will recreate the host
        // texture, so a corrupt state file cannot fail halfway through load.
        static_cast<void>(katana::runtime::decode_native_port_texture_surface(
            surface.encoded, surface.extent, surface.pixel_format,
            surface.data_format));
    }
    const auto sound_catalog = sonic_native::sound_collection_catalog();
    std::set<std::uint32_t> sounds;
    for (const auto index : state.sound_collection_catalog_indices) {
        if (std::ranges::none_of(
                sound_catalog,
                [index](const sonic_native::SoundCollectionBinding& binding) {
                    return binding.catalog_index == index;
                }) ||
            !sounds.insert(index).second)
            throw std::runtime_error("development-state-sound-catalog");
    }
}

void discard_sonic_native_development_resources(
    katana::runtime::NativePortContext& context) {
    auto& state = sonic_native_title_state;
    if (state.lighting_palette_pointer_watchpoint.has_value())
        static_cast<void>(context.cpu->memory.remove_watchpoint(
            *state.lighting_palette_pointer_watchpoint));
    if (state.lighting_palette_data_watchpoint.has_value())
        static_cast<void>(context.cpu->memory.remove_watchpoint(
            *state.lighting_palette_data_watchpoint));
    remove_native_texture_registry_write_trace(context, true);
    remove_native_texture_descriptor_write_trace(context);
    release_all_native_persistent_meshes(context);
    // Use the owner-aware release path for all texture archives.  In
    // particular, a live Character Set-7 BIG_KAERU alias must first retire
    // its descriptor publication before the resident archive vectors are
    // discarded; clearing those vectors directly would leave guest texaddr
    // slots pointing at dead native ownership.
    release_all_native_texture_archives(context);
    // Audio is quiesced and restored independently after the RAM transaction.
    clear_native_pending_prs_modules();
}

void initialize_sonic_native_development_resources(
    katana::runtime::NativePortContext& context,
    const SonicNativeDevelopmentState& saved) {
    auto& state = sonic_native_title_state;
    state.native_audio_control_word = saved.native_audio_control_word;
    state.native_audio_foundation_refcount =
        saved.native_audio_foundation_refcount;
    state.native_sound_driver_initialized =
        saved.native_sound_driver_initialized;
    state.native_audio_stereo_output = saved.native_audio_stereo_output;
    state.native_audio_processor_running =
        saved.native_audio_processor_running;
    state.lighting_palette_trace_requested = sonic_native_diagnostic_enabled(
        "KATANA_SONIC_LIGHTING_PALETTE_TRACE") ||
        sonic_native_diagnostic_enabled(
            "KATANA_SONIC_DIAGNOSTIC_MODEL_STATE");
    state.texture_descriptor_write_trace_requested =
        sonic_native_diagnostic_enabled(
            "KATANA_SONIC_TEXTURE_DESCRIPTOR_WRITE_TRACE");
    configure_native_texture_registry_write_trace();
    state.transient_vertices.reserve(max_native_draw_vertices);
    state.persistent_meshes.reserve(max_native_persistent_meshes);
    state.persistent_mesh_index.reserve(max_native_persistent_meshes);
    state.free_persistent_mesh_slots.reserve(max_native_persistent_meshes);
    state.transformed_point_clipped.reserve(max_native_draw_vertices);
    state.model_point_scratch.reserve(max_native_draw_vertices);
    state.model_normal_scratch.reserve(max_native_draw_vertices);
    state.model_polygon_index_scratch.reserve(64u);
    state.transformed_primary_colors.reserve(max_native_draw_vertices);
    state.transformed_secondary_colors.reserve(max_native_draw_vertices);
    state.materialized_texture_archives.reserve(
        max_native_resident_texture_archives);
    state.dynamic_surfaces.reserve(max_native_dynamic_surfaces);
    state.dynamic_texture_views.reserve(max_native_dynamic_texture_views);
    state.retired_dynamic_textures.reserve(max_native_retired_dynamic_textures);
    state.texlist_catalog_bindings.reserve(max_native_texture_names);
    state.pvm_allocations.reserve(max_native_pvm_allocations);
    state.pvm_views.reserve(max_native_pvm_views);
    state.active_texture_sets.reserve(
        sonic_native_main_texture_set_count +
        sonic_native_character_texture_set_count);
    const std::array save_units{
        katana::runtime::NativePortSaveUnitConfig{
            sonic_native_save_endpoint, sonic_native_save_medium_identity,
            true, true, sonic_native_save_block_bytes,
            sonic_native_save_block_count, sonic_native_save_maximum_files}};
    const katana::runtime::NativePortSaveProviderConfig save_config{
        katana::runtime::native_port_save_provider_contract_version,
        sonic_native_save_provider_id, sonic_native_save_profile_identity,
        save_units};
    state.save_provider =
        std::make_unique<katana::runtime::NativePortSaveProvider>(
            *context.platform, save_config);
    context.title_state = &state;
    ensure_native_title_audio(context);
    if (saved.services.font_source_address != 0u)
        materialize_native_font_texture(
            context, saved.services.font_source_address,
            saved.services.font_dimension, saved.services.font_format);
    materialize_sega_logo_textures(context);
}

struct SonicNativeDevelopmentModuleGeneration final {
    std::string identity;
    std::uint32_t source_start = 0u;
    std::uint32_t runtime_start = 0u;
    std::uint32_t byte_size = 0u;
    std::uint64_t saved_generation = 0u;
    std::uint64_t restored_generation = 0u;
};

[[nodiscard]] std::uint64_t
restored_sonic_native_development_module_generation(
    const std::span<const SonicNativeDevelopmentModuleGeneration> mappings,
    const std::string_view identity,
    const std::uint32_t source_start,
    const std::uint32_t runtime_start,
    const std::uint32_t byte_size,
    const std::uint64_t saved_generation) {
    const auto match = std::ranges::find_if(
        mappings,
        [&](const SonicNativeDevelopmentModuleGeneration& mapping) {
            return mapping.identity == identity &&
                   mapping.source_start == source_start &&
                   mapping.runtime_start == runtime_start &&
                   mapping.byte_size == byte_size &&
                   mapping.saved_generation == saved_generation;
        });
    if (match == mappings.end() || match->restored_generation == 0u)
        throw std::runtime_error("development-state-module-generation");
    return match->restored_generation;
}

void restore_sonic_native_development_state(
    katana::runtime::NativePortContext& context,
    const SonicNativeDevelopmentState& saved) {
    if (context.graphics == nullptr || context.runtime_images == nullptr ||
        context.loaded_aot == nullptr || context.cpu == nullptr ||
        context.development_state_restore_main_memory == nullptr)
        throw std::runtime_error("development-state-restore-context");
    context.graphics->finish();

    // Snapshot the live executable owners before changing RAM.  The handler
    // runs only at the outermost generated dispatch boundary, so clearing the
    // architectural continuation fields makes every exact retirement safe
    // without skipping or fabricating a guest return.
    const auto current_modules =
        context.loaded_aot->modules_for_development_state();
    const auto current_images =
        context.runtime_images->active_images_for_development_state();
    discard_sonic_native_development_resources(context);
    auto& cpu = *context.cpu;
    cpu.pc = 0u;
    cpu.pr = 0u;
    cpu.active_instruction_pc = 0u;
    cpu.active_instruction_physical_pc = 0u;
    cpu.active_block_virtual_start = 0u;
    cpu.active_block_physical_start = 0u;
    cpu.active_block_size = 0u;
    for (const auto& module : current_modules)
        static_cast<void>(katana::runtime::
            deactivate_native_port_executable_range(
                context, module.runtime_start, module.byte_size));
    for (const auto& image : current_images)
        static_cast<void>(katana::runtime::
            deactivate_native_port_executable_range(
                context, image.runtime_start, image.byte_size));

    if (!context.development_state_restore_main_memory(
            context, saved.main_memory))
        throw std::runtime_error("development-state-main-memory-restore");

    for (const auto& image : saved.runtime_images)
        context.runtime_images->activate(image.image_id);

    std::vector<SonicNativeDevelopmentModuleGeneration> generations;
    generations.reserve(saved.modules.size());
    for (const auto& module : saved.modules) {
        const katana::runtime::NativePortLoadedAotModuleActivation activation{
            module.sha256, module.source_start, module.runtime_start,
            module.byte_size};
        const auto generation =
            context.loaded_aot->stage_runtime_module(activation);
        if (generation == 0u ||
            (module.active &&
             !context.loaded_aot->bind_entry(module.activation_entry)))
            throw std::runtime_error("development-state-module-activate");
        generations.push_back(
            {module.sha256, module.source_start, module.runtime_start,
             module.byte_size, module.lifecycle_generation, generation});
    }

    auto restored_authority = saved.executable_transition_authority;
    if (sonic_native_transition_authority_bound(restored_authority))
        restored_authority.module_lifecycle_generation =
            restored_sonic_native_development_module_generation(
                generations, restored_authority.module_identity,
                restored_authority.module_source_start,
                restored_authority.module_runtime_start,
                restored_authority.module_byte_size,
                restored_authority.module_lifecycle_generation);

    auto gameplay_probe = sonic_native_title_state.gameplay_probe;
    const auto probe_deadline =
        sonic_native_title_state.scenario_frame_boundary_deadline_nanoseconds;
    const auto movie_skip_consumed =
        sonic_native_title_state.diagnostic_movie_skip_consumed;
    if (gameplay_probe.active) {
        std::cerr << "SONIC_NATIVE_SCENARIO_GAMEPLAY_INTERRUPTED id="
                  << gameplay_probe.descriptor->id
                  << " reason=development-state-load\n";
        gameplay_probe.active = false;
        gameplay_probe.interrupted = true;
    }
    sonic_native_title_state.audio_status.reset();
    auto audio = std::move(sonic_native_title_state.audio_engine);
    auto sound_bank = std::move(sonic_native_title_state.sound_bank_engine);
    sonic_native_title_state = {};
    sonic_native_title_state.gameplay_probe = gameplay_probe;
    sonic_native_title_state.scenario_frame_boundary_deadline_nanoseconds = probe_deadline;
    sonic_native_title_state.diagnostic_movie_skip_consumed = movie_skip_consumed;
    sonic_native_title_state.audio_engine = std::move(audio);
    sonic_native_title_state.sound_bank_engine = std::move(sound_bank);
    initialize_sonic_native_development_resources(context, saved);
    sonic_native_title_state.executable_transition_authority =
        restored_authority;

    // A descriptor's guest image is SDK data, not a GPU handle. Preserve its
    // exact address, attributes and resource key; only the native registry
    // token/generation in the adapter binding is rebound to recreated pixels.
    for (const auto& archive : saved.archives) {
        const auto catalog = sonic_native::texture_archive_binding(archive.catalog_index);
        if (!catalog) throw std::runtime_error("development-state-archive-identity");
        static_cast<void>(materialize_native_texture_archive(context, *catalog));
        resident_texture_archive_or_throw(archive.catalog_index).texture_set_references = archive.references;
    }
    for (const auto& source : saved.pvm_allocations) {
        const auto catalog =
            sonic_native::texture_archive_binding(source.catalog_index);
        auto& resident =
            resident_texture_archive_or_throw(source.catalog_index);
        if (!catalog || (catalog->standalone_pvr &&
                         (catalog->entry_count != 1u || source.archive_ordinal != 0u)) ||
            resident.archive.generation == 0u ||
            resident.archive.entries.size() != catalog->entry_count ||
            source.archive_ordinal >= resident.archive.entries.size() ||
            resident.archive.entries[source.archive_ordinal].archive_ordinal !=
                source.archive_ordinal)
            throw std::runtime_error("development-state-pvm-restore-ordinal");
        const auto& entry = resident.archive.entries[source.archive_ordinal];
        if (entry.guest_token == 0u || entry.guest_token == 0xFFFFFFFFu)
            throw std::runtime_error("development-state-pvm-restore-token");
        SonicNativePvmAllocation restored = source;
        // Guest descriptor words remain the saved ordinary-RAM image. Only
        // host registry identity is retokenized against the newly materialized
        // archive; a saved released row stays released and is never rewritten.
        restored.descriptor.guest_token = entry.guest_token;
        restored.descriptor.generation = resident.archive.generation;
        sonic_native_title_state.descriptor_candidate_index.invalidate();
        sonic_native_title_state.pvm_allocations.push_back(std::move(restored));
    }
    sonic_native_title_state.pvm_views = saved.pvm_views;
    for (const auto& source : saved.texlists) {
        SonicNativeTexlistCatalogBinding target;
        target.texlist_address = source.texlist_address;
        target.texname_address = source.texname_address;
        target.texture_count = source.texture_count;
        target.catalog_index = source.catalog_index;
        target.per_texture_catalog_indices = source.per_texture_catalog_indices;
        target.texture_set_references = source.texture_set_references;
        target.texture_set_owner = source.texture_set_owner;
        target.named_archive_binding = source.named_archive_binding;
        target.named_archive_owner = source.named_archive_owner;
        target.loaded_aot_module_binding = source.loaded_aot_module_binding;
        target.module_identity = source.module_identity;
        target.module_source_start = source.module_source_start;
        target.module_runtime_start = source.module_runtime_start;
        target.module_byte_size = source.module_byte_size;
        target.module_lifecycle_generation = source.module_lifecycle_generation;
        if (target.loaded_aot_module_binding)
            target.module_lifecycle_generation = restored_sonic_native_development_module_generation(
                generations, source.module_identity, source.module_source_start, source.module_runtime_start,
                source.module_byte_size, source.module_lifecycle_generation);
        target.descriptor_transition_authority = source.descriptor_transition_authority;
        auto& authority = target.descriptor_transition_authority;
        if (sonic_native_transition_authority_bound(authority)) {
            const auto match = std::ranges::find_if(generations, [&](const auto& candidate) {
                return !authority.retired_resource_history &&
                    candidate.identity == authority.module_identity &&
                    candidate.source_start == authority.module_source_start &&
                    candidate.runtime_start == authority.module_runtime_start &&
                    candidate.byte_size == authority.module_byte_size &&
                    candidate.saved_generation == authority.module_lifecycle_generation;
            });
            if (match != generations.end()) authority.module_lifecycle_generation = match->restored_generation;
            else authority.retired_resource_history = true;
        }
        for (std::size_t ordinal = 0u; ordinal < source.descriptors.size(); ++ordinal) {
            const auto& item = source.descriptors[ordinal];
            const auto index = source.per_texture_catalog_indices.empty()
                ? source.catalog_index : source.per_texture_catalog_indices[ordinal];
            const auto& archive = resident_texture_archive_or_throw(index).archive;
            const auto entry = source.per_texture_catalog_indices.empty() ? ordinal : 0u;
            if (entry >= archive.entries.size()) throw std::runtime_error("development-state-texture-ordinal");
            SonicNativeGuestTextureDescriptor descriptor;
            descriptor.descriptor_address = item.descriptor_address;
            descriptor.guest_token = archive.entries[entry].guest_token;
            descriptor.generation = archive.generation;
            descriptor.transition_epoch = item.transition_epoch;
            descriptor.previous_words = item.previous_words;
            descriptor.replaced_words = item.replaced_words;
            descriptor.published_words = item.published_words;
            target.guest_descriptors.push_back(descriptor);
        }
        sonic_native_title_state.descriptor_candidate_index.invalidate();
        sonic_native_title_state.texlist_catalog_bindings.push_back(std::move(target));
    }
    for (const auto& set : saved.texture_sets)
        sonic_native_title_state.active_texture_sets.push_back(
            {set.domain, set.set_index, set.row_address, set.return_value, set.acquisition_count,
             set.catalog_indices, set.texlist_addresses});

    auto& backing_store = native_texture_backing_store();
    for (const auto& saved_surface : saved.dynamic_surfaces) {
        auto texture = create_native_texture_surface(
            context, saved_surface.encoded, saved_surface.extent,
            saved_surface.pixel_format, saved_surface.data_format);
        try {
            backing_store.write(saved_surface.destination_address,
                                saved_surface.encoded);
            sonic_native_title_state.dynamic_surfaces.push_back(
                {saved_surface.descriptor_address,
                 saved_surface.destination_address,
                 saved_surface.source_address,
                 saved_surface.extent,
                 saved_surface.encoded.size(),
                 saved_surface.surface_type,
                 saved_surface.surface_flags,
                 saved_surface.pixel_format,
                 saved_surface.data_format,
                 saved_surface.upload_sequence,
                 texture});
            sonic_native_title_state.dynamic_surface_upload_sequence =
                std::max(
                    sonic_native_title_state.dynamic_surface_upload_sequence,
                    saved_surface.upload_sequence);
        } catch (...) {
            context.graphics->destroy_texture(texture);
            throw;
        }
    }

    sonic_native_title_state.sound_bank_engine->restore_development_state(saved.services.sound_bank);
    sonic_native_title_state.audio_status.reset();
    sonic_native_title_state.audio_engine->restore_development_state(saved.services.audio);
    sonic_native_title_state.postpal_main_textures_pending = saved.services.postpal_main_textures_pending;
    sonic_native_title_state.private_stage_tuple_override = saved.services.private_stage_tuple_override;
    sonic_native_title_state.texture_binding = saved.services.texture_binding;
    sonic_native_title_state.current_texture_index = saved.services.current_texture_index;
    sonic_native_title_state.current_texture_index_bound = saved.services.current_texture_index_bound;
    sonic_native_title_state.most_recent_texture_archive = saved.services.most_recent_texture_archive;
    sonic_native_title_state.texture_list_epoch = saved.services.texture_list_epoch;
    sonic_native_title_state.texture_writer_sequence = saved.services.texture_writer_sequence;
    sonic_native_title_state.diagnostic_texlist_bind_sequence = 0u;
    sonic_native_title_state.diagnostic_texlist_bind_pc = 0u;
    sonic_native_title_state.diagnostic_texlist_bind_pr = 0u;
    sonic_native_title_state.diagnostic_texlist_bind_address = 0u;
    sonic_native_title_state.texture_writer_identity = saved.services.texture_writer_identity;
    sonic_native_title_state.texture_writer_texlist_address = saved.services.texture_writer_texlist_address;
    sonic_native_title_state.texture_writer = saved.services.texture_writer;
    sonic_native_title_state.texture_upload_sequence = saved.services.texture_upload_sequence;
    sonic_native_title_state.texture_upload_completion_token = saved.services.texture_upload_completion_token;
    sonic_native_title_state.texture_upload_completion_bound = saved.services.texture_upload_completion_bound;
    sonic_native_title_state.native_render_width = saved.services.native_render_width;
    sonic_native_title_state.native_render_height = saved.services.native_render_height;
    sonic_native_title_state.native_render_arena_index = saved.services.native_render_arena_index;
    sonic_native_title_state.native_render_arena_generation = saved.services.native_render_arena_generation;
    sonic_native_title_state.native_scene_sequence = saved.services.native_scene_sequence;
    sonic_native_title_state.font_source_address = saved.services.font_source_address;
    sonic_native_title_state.font_dimension = saved.services.font_dimension;
    sonic_native_title_state.font_format = saved.services.font_format;
    sonic_native_title_state.frame_clear_producer_pc = saved.services.frame_clear_producer_pc;
    sonic_native_title_state.frame_clear_producer_pr = saved.services.frame_clear_producer_pr;
    sonic_native_title_state.frame_clear_sequence = saved.services.frame_clear_sequence;
    sonic_native_title_state.loaded_sound_collections = saved.services.loaded_sound_collections;
    sonic_native_title_state.current_sound_collection = saved.services.current_sound_collection;
    sonic_native_title_state.sound_unit_registrations = saved.services.sound_unit_registrations;
    sonic_native_title_state.sound_pcm_stream_ring_registrations = saved.services.sound_pcm_stream_ring_registrations;
    sonic_native_title_state.sound_unit_registration_sequence = saved.services.sound_unit_registration_sequence;
    sonic_native_title_state.sound_midi_ports = saved.services.sound_midi_ports;
    sonic_native_title_state.sound_midi_port_collections = saved.services.sound_midi_port_collections;
    sonic_native_title_state.sound_midi_port_programs = saved.services.sound_midi_port_programs;
    sonic_native_title_state.sound_active_notes = saved.services.sound_active_notes;
    sonic_native_title_state.sound_midi_port_state = saved.services.sound_midi_port_state;
    sonic_native_title_state.sound_sequence_ports = saved.services.sound_sequence_ports;
    sonic_native_title_state.sound_sequence_port_collections = saved.services.sound_sequence_port_collections;
    sonic_native_title_state.sound_sequence_port_program_banks = saved.services.sound_sequence_port_program_banks;
    sonic_native_title_state.sound_sequence_port_sequence_banks = saved.services.sound_sequence_port_sequence_banks;
    sonic_native_title_state.sound_sequence_port_state = saved.services.sound_sequence_port_state;
    sonic_native_title_state.sound_sequence_start_reported = saved.services.sound_sequence_start_reported;
    sonic_native_title_state.native_audio_default_port = saved.services.native_audio_default_port;
    sonic_native_title_state.native_audio_default_value = saved.services.native_audio_default_value;
    sonic_native_title_state.native_audio_service_sequence = saved.services.native_audio_service_sequence;
    sonic_native_title_state.native_input_buttons = saved.services.native_input_buttons;
    sonic_native_title_state.native_input_record_addresses = saved.services.native_input_record_addresses;
    sonic_native_title_state.native_input_initialized = saved.services.native_input_initialized;
    sonic_native_title_state.native_input_connected = saved.services.native_input_connected;
    sonic_native_title_state.transfer_ring = saved.services.transfer_ring;
    sonic_native_title_state.platform_interrupt_state = saved.services.platform_interrupt_state;
    sonic_native_title_state.native_transfers_suspended = saved.services.native_transfers_suspended;

    const auto restore_content = [](const std::string& path) -> const SonicNativeContentBinding* {
        if (path.empty()) return nullptr;
        const auto item = std::ranges::find(sonic_native_content_bindings, path, &SonicNativeContentBinding::guest_path);
        if (item == std::end(sonic_native_content_bindings))
            throw std::runtime_error("development-state-audio-content");
        return &*item;
    };
    sonic_native_title_state.event_adx_archive = restore_content(saved.services.event_adx_path);
    for (std::size_t index = 0u; index < saved.services.adx.size(); ++index) {
        const auto& source = saved.services.adx[index];
        auto& target = sonic_native_title_state.adx_streams[index];
        target = source.stream;
        const auto content = restore_content(source.path);
        target.guest_path = content == nullptr ? std::string_view{} : content->guest_path;
    }
    ensure_native_title_audio(context);
    if (sonic_native_title_state.audio_status)
        for (const auto& stream : sonic_native_title_state.adx_streams)
            if (stream.bound && stream.voice)
                sonic_native_title_state.audio_status->watch(*stream.voice);
    const auto now = context.host->monotonic_time_nanoseconds();
    auto& state = sonic_native_title_state;
    state.timer_epoch_nanoseconds =
        now >= saved.timer_elapsed_nanoseconds
            ? now - saved.timer_elapsed_nanoseconds
            : 0u;
    state.periodic_epoch_nanoseconds =
        now >= saved.periodic_elapsed_nanoseconds
            ? now - saved.periodic_elapsed_nanoseconds
            : 0u;
    state.periodic_callbacks_dispatched =
        saved.periodic_callbacks_dispatched;
    state.periodic_reload_ticks = saved.periodic_reload_ticks;
    state.periodic_clock_initialized = saved.periodic_clock_initialized;
    state.begun_frames = saved.begun_frames;
    state.active_video_refresh_hz = saved.active_video_refresh_hz;
    state.standard_sixty_active = saved.standard_sixty_active;
    state.standard_sixty_configuring = false;
    state.original_gameplay_math_active = false;
    state.sixty_original_release = saved.sixty_original_release;
    state.sixty_original_delta = saved.sixty_original_delta;
    state.active_video_refresh_owner = "development-state-restore";
    state.active_video_refresh_frame = saved.saved_frame_index;
    state.frame_producer_next_deadline_nanoseconds = 0u;
    state.frame_producer_deferred_deadline_nanoseconds = 0u;
    state.frame_producer_deadline_remainder = 0u;
    state.frame_clear_color = saved.frame_clear_color;
    state.fog_table_color = saved.fog_table_color;
    state.fog_vertex_color = saved.fog_vertex_color;
    state.fog_table = saved.fog_table;
    state.fog_density_word = saved.fog_density_word;
    state.cull_value = saved.cull_value;
    state.fog_table_color_bound = saved.fog_table_color_bound;
    state.fog_vertex_color_bound = saved.fog_vertex_color_bound;
    state.fog_density_bound = saved.fog_density_bound;
    state.fog_table_bound = saved.fog_table_bound;
    state.cull_value_bound = saved.cull_value_bound;
    state.native_input_frame_index =
        std::numeric_limits<std::uint64_t>::max();
    // Edge history is restored above; the next physical poll is still fresh.
    // Clearing this history would invent presses for held buttons after load.

    // Architectural state is the commit marker.  The generated dispatcher
    // observes Loaded, discards its old target and restarts from this PC only
    // after this function has returned and the adapter frame is gone.
    context.frame_index = saved.saved_frame_index;
    apply_sonic_native_development_cpu(cpu, saved.cpu);
}

extern "C" katana::runtime::NativePortDevelopmentStateResult
sonic_native_development_state_request(
    katana::runtime::NativePortContext& context,
    const katana::runtime::NativePortDevelopmentStateRequest& request)
    noexcept {
    if (!valid_sonic_native_context(context) || context.graphics == nullptr ||
        request.path.empty())
        return katana::runtime::NativePortDevelopmentStateResult::Rejected;
    if (sonic_native_title_state.frame_open || sonic_native_title_state.standard_sixty_configuring ||
        sonic_native_title_state.pending_draw_vertices != 0u ||
        sonic_native_title_state.native_transfer_submissions_in_flight != 0u ||
        sonic_native_title_state.texture_upload_pending ||
        std::ranges::any_of(
            sonic_native_title_state.pending_prs_modules,
            [](const SonicNativePendingPrsModule& pending) {
                return pending.content != nullptr;
            }))
        return katana::runtime::NativePortDevelopmentStateResult::Deferred;

    bool restore_commit_started = false;
    auto* const audio = sonic_native_title_state.audio_engine.get();
    if (audio == nullptr || sonic_native_title_state.sound_bank_engine == nullptr)
        return katana::runtime::NativePortDevelopmentStateResult::Rejected;
    bool previous_output_paused = false;
    bool audio_quiesced = false;
    bool live_transaction_finished = false;
    const auto transaction_started = context.host->monotonic_time_nanoseconds();
    const auto finish_live_transaction = [&] {
        // Filesystem I/O and validation are a development pause, not elapsed
        // title timer time. Loading installs its own saved timer epochs.
        const auto now = context.host->monotonic_time_nanoseconds();
        const auto elapsed = now >= transaction_started ? now - transaction_started : 0u;
        auto& state = sonic_native_title_state;
        if (!live_transaction_finished) {
            live_transaction_finished = true;
            state.timer_epoch_nanoseconds += elapsed;
            state.periodic_epoch_nanoseconds += elapsed;
        }
        reset_sonic_host_sleep_clock(context);
        if (audio_quiesced) audio->set_output_paused(previous_output_paused);
    };
    try {
        previous_output_paused = audio->snapshot().output_paused;
        sonic::rumble::engine().policy(true,0);
        audio->rebase_development_state_epoch();
        audio_quiesced = true;
        const auto path = std::filesystem::u8path(request.path);
        switch (request.operation) {
        case katana::runtime::NativePortDevelopmentStateOperation::Save: {
            const auto capture_started = context.host->monotonic_time_nanoseconds();
            auto state = capture_sonic_native_development_state(context);
            state.services.output_paused = previous_output_paused;
            // Capture's host timer snapshot is taken after worker quiescence.
            // Anchor it to the same request boundary as the frozen guest CPU.
            const auto elapsed = capture_started >= transaction_started ? capture_started - transaction_started : 0u;
            state.timer_elapsed_nanoseconds = state.timer_elapsed_nanoseconds > elapsed
                ? state.timer_elapsed_nanoseconds - elapsed : 0u;
            state.periodic_elapsed_nanoseconds = state.periodic_elapsed_nanoseconds > elapsed
                ? state.periodic_elapsed_nanoseconds - elapsed : 0u;
            validate_sonic_native_development_state(context, state);
            const auto bytes = encode_sonic_native_development_state(state);
            write_sonic_native_development_state_file(path, bytes);
            std::cerr << "SONIC_NATIVE_DEVELOPMENT_STATE operation=save"
                      << " sequence=" << request.sequence
                      << " bytes=" << bytes.size()
                      << " frame=" << state.saved_frame_index
                      << " ram_digest=" << sonic_native_development_state_hash(state.main_memory)
                      << " standard60=" << state.standard_sixty_active
                      << " original_release=" << state.sixty_original_release
                      << " original_delta=" << state.sixty_original_delta
                      << " path=" << request.path << '\n';
            finish_live_transaction();
            return katana::runtime::
                NativePortDevelopmentStateResult::Completed;
        }
        case katana::runtime::NativePortDevelopmentStateOperation::Load: {
            const auto bytes = read_sonic_native_development_state_file(path);
            if (context.platform != nullptr && context.platform->input_initial_state_pending())
                context.platform->validate_input_initial_state(std::as_bytes(std::span(bytes)));
            const auto state =
                decode_sonic_native_development_state(bytes);
            validate_sonic_native_development_state(context, state);
            restore_commit_started = true;
            restore_sonic_native_development_state(context, state);
            reset_sonic_host_sleep_clock(context);
            const auto restored_memory = katana::runtime::capture_native_port_main_memory(*context.cpu);
            if (restored_memory != state.main_memory)
                throw std::runtime_error("development-state-restored-ram-mismatch");
            sonic::camera::reset_timeline();
            sonic::motion::timeline.fetch_add(1);
            // Gain commands observe the title frame. Bind the restored audio
            // cursor only after the saved frame was committed, otherwise the
            // following unpause sees the live-to-saved frame as a regression.
            refresh_sonic_audio_settings(true);
            audio->set_output_paused(state.services.output_paused);
            std::cerr << "SONIC_NATIVE_DEVELOPMENT_STATE operation=load"
                      << " sequence=" << request.sequence
                      << " bytes=" << bytes.size()
                      << " target=0x" << std::hex << context.cpu->pc
                      << std::dec << " frame=" << state.saved_frame_index
                      << " ram_digest=" << sonic_native_development_state_hash(restored_memory)
                      << " standard60=" << sonic_native_title_state.standard_sixty_active
                      << " original_release=" << sonic_native_title_state.sixty_original_release
                      << " original_delta=" << sonic_native_title_state.sixty_original_delta
                      << " path=" << request.path << '\n';
            return katana::runtime::
                NativePortDevelopmentStateResult::Loaded;
        }
        }
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_DEVELOPMENT_STATE operation="
                  << (request.operation ==
                              katana::runtime::
                                  NativePortDevelopmentStateOperation::Save
                          ? "save"
                          : "load")
                  << " sequence=" << request.sequence
                  << " failure=" << error.what() << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_DEVELOPMENT_STATE operation="
                  << (request.operation ==
                              katana::runtime::
                                  NativePortDevelopmentStateOperation::Save
                          ? "save"
                          : "load")
                  << " sequence=" << request.sequence
                  << " failure=non-standard-exception\n";
    }
    if (!restore_commit_started) {
        try { finish_live_transaction(); }
        catch (...) {
            static_cast<void>(graphics_abort(context, sonic_native_frame_error_exception));
        }
    }
    if (restore_commit_started)
        context.stop_reason =
            katana::runtime::NativePortStopReason::AotContractViolation;
    return katana::runtime::NativePortDevelopmentStateResult::Rejected;
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_collision_work_allocation_failure(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_collision_error_context};

    // 0x8C02F4DE is reached only after the first, 28-byte collision-work
    // allocation in the exact 0x8C02F4B0 owner returned zero.  The displaced
    // path never recovers: while 0x8C752B1C is negative it spins locally;
    // otherwise it draws "CANT GET COLLI_WORK!!!!" and branches back.  Keep
    // the successful allocator/object construction entirely in static AOT,
    // but translate this proven fatal branch into a typed native OOM instead
    // of inventing an external-progress or hardware provider.
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_collision_error_allocation};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_render_command_arena_configure(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_video_mode_error_context};

    // This exact SDK owner consumes only width, height and a bounded arena
    // index, then writes the derived object/parameter-buffer layout to seven
    // TA/PVR registers. NativePortGraphics owns command buffers directly, so
    // retain the semantic layout in title state without constructing guest
    // register or VRAM-device state.
    const auto width = context.cpu->r[4];
    const auto height = context.cpu->r[5];
    const auto arena_index = context.cpu->r[6];
    if (width == 0u || height == 0u || width > 8192u || height > 8192u ||
        arena_index >= 4u)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_video_mode_error_state};

    sonic_native_title_state.native_render_width = width;
    sonic_native_title_state.native_render_height = height;
    sonic_native_title_state.native_render_arena_index = arena_index;
    if (sonic_native_title_state.native_render_arena_generation ==
        std::numeric_limits<std::uint64_t>::max()) {
        sonic_native_title_state.native_render_arena_generation = 0u;
    } else {
        ++sonic_native_title_state.native_render_arena_generation;
    }
    // Region headers are derived from this exact arena layout.  A configure
    // call starts a new immutable producer generation even if its scalar
    // dimensions happen to match the previous one.
    sonic_native_title_state.native_region_headers = {};
    sonic_native_title_state.native_region_header_next = 0u;
    sonic_native_title_state.native_region_header_count = 0u;
    invalidate_sonic_native_type2_scene_authority();
    return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
}

void release_sonic_native_title_host_providers(
    katana::runtime::NativePortContext& context) noexcept {
    sonic::rumble::engine().policy(true,0);
    sonic::quit_prompt::release(context);
    auto& state = sonic_native_title_state;
    // The stopped guest cannot resume. Preserve the original failure's bounded
    // transcript; teardown of retired publications must not overwrite it.
    state.texture_diagnostics_suppressed = true;

    // Movie sessions are hook-local and are already closed before a hook can
    // return to the generated dispatcher. ADX voices are persistent consumers
    // and are retired by the existing audio teardown. SoundBank must die before
    // AudioEngine because it owns feeds and a command-stamp borrow into Context.
    try {
        destroy_native_title_audio_provider();
    } catch (...) {
        // Preserve dependency order even when an explicit stop/reset failed;
        // the provider destructors are the guaranteed fail-closed fallback.
        state.sound_bank_engine.reset();
        state.audio_status.reset();
        state.audio_engine.reset();
        clear_native_title_audio_collection_bindings();
        for (auto& stream : state.adx_streams) stream = {};
    }

    // These providers retain host/platform/graphics ownership. Retire their
    // published handles while the complete NativePortContext is still valid.
    state.save_provider.reset();
    state.content_range.reset();
    state.content_range_path.clear();
    state.event_adx_archive = nullptr;
    try {
        release_all_native_persistent_meshes(context);
    } catch (...) {
    }
    try {
        release_all_native_texture_archives(context);
    } catch (...) {
    }
    state.texture_backing_store.reset();

    if (context.cpu != nullptr) {
        if (state.lighting_palette_pointer_watchpoint.has_value()) {
            try {
                static_cast<void>(context.cpu->memory.remove_watchpoint(
                    *state.lighting_palette_pointer_watchpoint));
            } catch (...) {
            }
        }
        if (state.lighting_palette_data_watchpoint.has_value()) {
            try {
                static_cast<void>(context.cpu->memory.remove_watchpoint(
                    *state.lighting_palette_data_watchpoint));
            } catch (...) {
            }
        }
    }
    state.lighting_palette_pointer_watchpoint.reset();
    state.lighting_palette_data_watchpoint.reset();
    remove_native_texture_registry_write_trace(context, true);
    remove_native_texture_descriptor_write_trace(context);
    clear_native_pending_prs_modules();

    context.development_state_handler = nullptr;
    context.host_stop_ready = nullptr;
    context.title_state = nullptr;
}

extern "C" katana::runtime::NativePortBootstrapResult
sonic_native_bootstrap(
    katana::runtime::NativePortContext& context) noexcept {
    if (context.cpu == nullptr || context.host == nullptr ||
        context.platform == nullptr)
        return {false, 1u};

    // Register before opening the first host-backed provider. The generated
    // product guard consumes this on every normal or exceptional exit while
    // Context, platform, host, graphics and telemetry are still alive.
    context.title_state_cleanup = &release_sonic_native_title_host_providers;
    context.host_stop_ready = &sonic_native_host_stop_ready;

    try {
        auto checkpoint =
            context.platform->open_content_file(postpal_title_ram_binding);
        std::vector<std::byte> title_ram(postpal_title_ram_binding.byte_size);
        checkpoint->read_at(0u, title_ram);
        const auto main_ram =
            context.cpu->memory.direct_linear_memory_guard(true);
        std::uint32_t main_ram_offset = 0u;
        if (main_ram.write_bytes == nullptr ||
            !katana::runtime::direct_linear_guard_offset(
                main_ram, 0x8C000000u, title_ram.size(), main_ram_offset))
            throw std::runtime_error("native-main-ram-bootstrap-window");
        std::memcpy(main_ram.write_bytes + main_ram_offset,
                    title_ram.data(), title_ram.size());
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_BOOTSTRAP stage=checkpoint-load failure="
                  << error.what() << '\n';
        return {false, 2u};
    } catch (...) {
        std::cerr << "SONIC_NATIVE_BOOTSTRAP stage=checkpoint-load "
                     "failure=non-standard-exception\n";
        return {false, 2u};
    }

    // Development bootstrap at the unique title-owned continuation after the
    // PAL selector and its final native-transition call.  The bound 16-MiB
    // image contains title RAM only; BIOS,
    // scheduler, PVR, AICA, ASIC and other Dreamcast device state are absent.
    // Native pacing adopts the verified applied PAL mode below; host output
    // frequency does not replace that title clock.
    try {
        auto& cpu = *context.cpu;
        if (sonic_native_title_state.lighting_palette_pointer_watchpoint
                .has_value()) {
            static_cast<void>(cpu.memory.remove_watchpoint(
                *sonic_native_title_state.lighting_palette_pointer_watchpoint));
        }
        if (sonic_native_title_state.lighting_palette_data_watchpoint
                .has_value()) {
            static_cast<void>(cpu.memory.remove_watchpoint(
                *sonic_native_title_state.lighting_palette_data_watchpoint));
        }
        remove_native_texture_registry_write_trace(context, true);
        remove_native_texture_descriptor_write_trace(context);
        release_all_native_persistent_meshes(context);
        release_all_native_texture_archives(context);
        destroy_native_title_audio_provider();
        clear_native_pending_prs_modules();
        sonic_native_title_state = {};
        // The bound checkpoint was captured with the title's native audio
        // service enabled (the running cache has ARM-reset clear and control
        // bits 8/9 set). Preserve that semantic lifecycle state; no AICA or
        // ARM7 state is imported.
        sonic_native_title_state.native_audio_control_word = 0x00000300u;
        sonic_native_title_state.lighting_palette_trace_requested =
            sonic_native_diagnostic_enabled(
                "KATANA_SONIC_LIGHTING_PALETTE_TRACE") ||
            sonic_native_diagnostic_enabled(
                "KATANA_SONIC_DIAGNOSTIC_MODEL_STATE");
        sonic_native_title_state.texture_descriptor_write_trace_requested =
            sonic_native_diagnostic_enabled(
                "KATANA_SONIC_TEXTURE_DESCRIPTOR_WRITE_TRACE");
        if (sonic_native_title_state
                .texture_descriptor_write_trace_requested) {
            const auto catalog_filter =
                sonic_native_canonical_diagnostic_u32(
                    "KATANA_SONIC_TEXTURE_DESCRIPTOR_WRITE_TRACE_CATALOG_INDEX");
            if (catalog_filter.present && !catalog_filter.value.has_value()) {
                sonic_native_title_state
                    .texture_descriptor_write_trace_requested = false;
                std::cerr
                    << "SONIC_NATIVE_TEXTURE_DESCRIPTOR_WRITE_TRACE armed=0"
                       " failure=invalid-catalog-index-filter\n";
            } else {
                sonic_native_title_state
                    .texture_descriptor_write_trace_catalog_index =
                    catalog_filter.value;
            }
        }
        configure_native_texture_registry_write_trace();
        sonic_native_title_state.native_audio_processor_running = true;
        sonic_native_title_state.native_audio_foundation_refcount = 1u;
        sonic_native_title_state.native_sound_driver_initialized = true;
        sonic_native_title_state.native_audio_stereo_output = true;
        sonic_native_title_state.transient_vertices.reserve(max_native_draw_vertices);
        sonic_native_title_state.persistent_meshes.reserve(
            max_native_persistent_meshes);
        sonic_native_title_state.persistent_mesh_index.reserve(
            max_native_persistent_meshes);
        sonic_native_title_state.free_persistent_mesh_slots.reserve(
            max_native_persistent_meshes);
        sonic_native_title_state.transformed_point_clipped.reserve(
            max_native_draw_vertices);
        sonic_native_title_state.model_point_scratch.reserve(
            max_native_draw_vertices);
        sonic_native_title_state.model_normal_scratch.reserve(
            max_native_draw_vertices);
        sonic_native_title_state.model_polygon_index_scratch.reserve(64u);
        sonic_native_title_state.transformed_primary_colors.reserve(
            max_native_draw_vertices);
        sonic_native_title_state.transformed_secondary_colors.reserve(
            max_native_draw_vertices);
        sonic_native_title_state.materialized_texture_archives.reserve(
            max_native_resident_texture_archives);
        sonic_native_title_state.dynamic_surfaces.reserve(
            max_native_dynamic_surfaces);
        sonic_native_title_state.dynamic_texture_views.reserve(
            max_native_dynamic_texture_views);
        sonic_native_title_state.retired_dynamic_textures.reserve(
            max_native_retired_dynamic_textures);
        sonic_native_title_state.texlist_catalog_bindings.reserve(
            max_native_texture_names);
        sonic_native_title_state.active_texture_sets.reserve(
            sonic_native_main_texture_set_count +
            sonic_native_character_texture_set_count);
        const std::array save_units{
            katana::runtime::NativePortSaveUnitConfig{
                sonic_native_save_endpoint,
                sonic_native_save_medium_identity,
                true,
                true,
                sonic_native_save_block_bytes,
                sonic_native_save_block_count,
                sonic_native_save_maximum_files}};
        const katana::runtime::NativePortSaveProviderConfig save_config{
            katana::runtime::native_port_save_provider_contract_version,
            sonic_native_save_provider_id,
            sonic_native_save_profile_identity,
            save_units};
        sonic_native_title_state.save_provider =
            std::make_unique<katana::runtime::NativePortSaveProvider>(
                *context.platform, save_config);
        sonic_native_title_state.timer_epoch_nanoseconds =
            context.host->monotonic_time_nanoseconds();
        context.title_state = &sonic_native_title_state;
        context.development_state_handler =
            &sonic_native_development_state_request;
        // The checkpoint starts after the title completed both high-level
        // Manatee initialization boundaries. Recreate their native host
        // services atomically with the adopted title state so later default,
        // collection and MIDI calls observe a live driver. This is lifecycle
        // adoption, not import of an AICA/ARM7 device snapshot.
        ensure_native_title_audio(context);
        if (!adopt_periodic_host_time_from_checkpoint(context))
            throw std::runtime_error("native-periodic-checkpoint-contract");
        // Fresh bootstrap only: the identity-bound post-PAL snapshot captured
        // an applied 625-line mode. Do not reuse these RAM mirrors to infer
        // active mode after a later constructor or development-state load.
        SonicGuestReader cadence_reader(cpu);
        std::uint32_t horizontal = 0u, vertical = 0u, border = 0u;
        if (!cadence_reader.valid() ||
            !cadence_reader.u32(0x8C8A2F78u, horizontal) ||
            !cadence_reader.u32(0x8C8A2F7Cu, vertical) ||
            !cadence_reader.u32(0x8C8A2F80u, border) ||
            horizontal != 0x008D034Bu || vertical != 0x0270035Fu || border != 0x002C026Cu)
            throw std::runtime_error("native-video-checkpoint-contract");
        bind_sonic_native_video_refresh(50u, "postpal-checkpoint", context.frame_index);
        // The development checkpoint is taken after NINJA initialized its
        // embedded font through the legacy VRAM uploader. Recreate the same
        // immutable atlas directly on the host GPU so the post-PAL bootstrap
        // and the future IP.BIN path share one native font contract.
        materialize_native_font_texture(
            context, sonic_ninja_builtin_font_pixels,
            sonic_ninja_builtin_font_dimension,
            sonic_ninja_font_argb1555_twiddled);
        materialize_sega_logo_textures(context);
        // Bootstrap RAM must retain its exact declared post-write identity.
        // The checkpoint's incomplete main texture group is published at
        // the first native frame boundary, after bootstrap validation.
        sonic_native_title_state.postpal_main_textures_pending = true;
        sonic_native::apply_postpal_cpu_state(cpu);
        constexpr std::array<std::uint8_t, 4u> save_ready_state{};
        cpu.memory.write_bytes(
            katana::runtime::canonical_physical_address(
                sonic_native_save_busy_state_address),
            save_ready_state, katana::runtime::CodeWriteSource::Copy);
        return {true, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_BOOTSTRAP stage=graphics-state failure="
                  << error.what() << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_BOOTSTRAP stage=graphics-state "
                     "failure=non-standard-exception\n";
    }
    return {false, 3u};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_standalone_texture_list_load(
    katana::runtime::NativePortContext& context) noexcept {
    using Action = katana::runtime::NativePortHookAction;
    if (!valid_sonic_native_context(context) || context.platform == nullptr ||
        context.textures == nullptr)
        return {Action::Abort, 0u, sonic_native_content_error_context};
    try {
        SonicGuestReader reader(*context.cpu);
        std::uint32_t count = 0u;
        const auto address = context.cpu->r[4];
        if (address > std::numeric_limits<std::uint32_t>::max() - 8u ||
            !reader.u32(address + 4u, count))
            fail_native_texture_contract(context, "native-standalone-list-header");
        // Preserve the original empty-list error/reset ABI, including r1.
        if (count == 0u) return {Action::ContinueOriginal, 0u, 0u};
        SonicNativeTextureBinding texlist;
        if (!read_texlist(reader, address, texlist) || !texlist.valid ||
            count > max_native_texture_names)
            fail_native_texture_contract(context, "native-standalone-list-abi");
        if (!acquire_native_standalone_texture_list(context, texlist))
            return {Action::ContinueOriginal, 0u, 0u};
        // Nonempty successful 608BC2/64C2B4 file-import result. Callee-saved
        // registers, stack, PR, names and attributes survive the transaction.
        context.cpu->r[0] = 1u;
        context.cpu->r[1] = 0x148u;
        context.cpu->r[2] = count;
        context.cpu->r[3] = 0u;
        context.cpu->t = true;
        return {Action::Return, 0u, 0u};
    } catch (const std::exception& error) {
        note_native_texture_contract_failure(context, error.what(), context.cpu->r[4]);
        std::cerr << "SONIC_NATIVE_STANDALONE_TEXTURE failure=" << error.what() << '\n';
    } catch (...) {
        note_native_texture_contract_failure(context,
            "non-standard-standalone-texture-exception", context.cpu->r[4]);
    }
    return {Action::Abort, 0u, sonic_native_content_error_texture_set};
}

// ADVERTISE contains six rows in each Trial table. After Super Sonic the
// selected character can still be 6; retail then reads adjacent data as a row.
// This private bounds correction leaves normal Trial builders compiled and
// reports an empty list for the character with no authored Trial stages.
// It deliberately does not reset the selected character or emulate VRAM.
extern "C" katana::runtime::NativePortHookResult
sonic_native_trial_character_list_guard(
    katana::runtime::NativePortContext& context) noexcept {
    using Action = katana::runtime::NativePortHookAction;
    if (!valid_sonic_native_context(context))
        return {Action::Abort, 0u, sonic_native_content_error_context};
    try {
        SonicGuestReader reader(*context.cpu);
        std::uint8_t character = 0u;
        if (!reader.u8(0x8C78B39Du, character))
            throw std::runtime_error("trial-character-range");
        if (character < 6u) return {Action::ContinueOriginal, 0u, 0u};
        const auto output = context.cpu->r[4];
        if (character != 6u ||
            output > std::numeric_limits<std::uint32_t>::max() - 5u ||
            !reader.range(output, 5u))
            throw std::runtime_error("trial-character-list-range");
        constexpr std::array<std::uint8_t, 1u> empty_count{0u};
        context.cpu->memory.write_bytes(
            katana::runtime::canonical_physical_address(output + 4u),
            empty_count, katana::runtime::CodeWriteSource::Copy);
        context.cpu->r[0] = 0u;
        return {Action::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_TRIAL_LIST failure=" << error.what() << '\n';
    } catch (...) {}
    return {Action::Abort, 0u, sonic_native_scene_error_exception};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_trial_minigame_list_guard(
    katana::runtime::NativePortContext& context) noexcept {
    return sonic_native_trial_character_list_guard(context);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_main_texture_set_load(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context) || context.platform == nullptr ||
        context.textures == nullptr)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_content_error_context};
    try {
        auto& set = acquire_native_texture_set(
            context, SonicNativeTextureSetDomain::Main, context.cpu->r[4]);
        context.cpu->r[0] = set.return_value;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        note_native_texture_contract_failure(context, error.what(), 0u);
        std::cerr << "SONIC_NATIVE_TEXTURE_SET failure=main-load detail="
                  << error.what() << '\n';
    } catch (...) {
        note_native_texture_contract_failure(context, "non-standard-texture-exception", 0u);
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_content_error_texture_set};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_named_texture_archive_load(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context) || context.platform == nullptr ||
        context.textures == nullptr)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_content_error_context};
    try {
        // Exact SDK ABI: r4 is a bounded logical archive name without the
        // .PRS suffix, r5 is an NJS_TEXLIST. The native provider resolves the
        // immutable content catalog and publishes opaque guest tokens into
        // texaddr while rendering remains entirely host-native.
        context.cpu->r[0] = acquire_native_named_texture_archive(
            context, context.cpu->r[4], context.cpu->r[5]);
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        note_native_texture_contract_failure(context, error.what(), context.cpu->r[5]);
        std::cerr << "SONIC_NATIVE_NAMED_TEXTURE failure=load detail="
                  << error.what() << '\n';
    } catch (...) {
        note_native_texture_contract_failure(context, "non-standard-texture-exception", context.cpu->r[5]);
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_content_error_texture_set};
}

// 6087FC is the SDK's non-owning outer TEXLIST release loop. Native named,
// Main and PVM owners above retain their stronger host-lifetime transactions;
// every other current nonnull TEXNAME reaches the original compiled 64DD00
// leaf in source order. Null TEXNAMEs reproduce the exact bound-BIOS no-op
// result without the ignored boot-ROM write. This includes guest-created
// surfaces, copied/aliased lists, repeated pointers, unloaded rows and Type1
// rows. Host metadata never guesses
// which SDK branch succeeded: dynamic GPU views are retired only after the
// original leaf changes a previously live Type0 row to the exact free image.
[[nodiscard]] std::uint32_t release_native_sdk_texture_list(
    katana::runtime::NativePortContext& context, const std::uint32_t address) {
    auto& cpu = *context.cpu;
    SonicGuestReader reader(cpu);
    const auto fail = [&](const char* reason) -> void {
        note_native_texture_contract_failure(context, reason, address);
        throw std::runtime_error(reason);
    };

    std::uint32_t texnames = 0u;
    std::uint32_t texture_count = 0u;
    if (address > std::numeric_limits<std::uint32_t>::max() - 8u ||
        !reader.range(address, 8u) || !reader.u32(address, texnames) ||
        !reader.u32(address + 4u, texture_count) ||
        texture_count > max_native_texture_names)
        fail("native-sdk-release-texlist");
    // Retail checks the count before touching TEXNAME. A zero-entry list is a
    // successful no-op even when its pointer is null or otherwise unreadable.
    if (texture_count == 0u) {
        cpu.r[0] = 1u;
        cpu.r[2] = 0u;
        cpu.t = true;
        return 1u;
    }
    std::size_t texname_bytes = 0u;
    if (!checked_span_size(texture_count, 12u, texname_bytes) ||
        !reader.range(texnames, texname_bytes))
        fail("native-sdk-release-texnames");

    bool has_nonnull_descriptor = false;
    std::uint32_t null_descriptor_count = 0u;
    std::uint32_t first_null_index = 0u;
    for (std::uint32_t index = 0u; index < texture_count; ++index) {
        std::uint32_t descriptor = 0u;
        if (!reader.u32(texnames + index * 12u + 8u, descriptor))
            fail("native-sdk-release-texnames");
        has_nonnull_descriptor |= descriptor != 0u;
        if (descriptor == 0u) {
            if (null_descriptor_count == 0u) first_null_index = index;
            ++null_descriptor_count;
        }
    }

    std::uint32_t registry = 0u;
    std::uint32_t registry_count = 0u;
    std::size_t registry_bytes = 0u;
    std::uint32_t registry_backing = 0u;
    std::uint32_t registry_highwater = 0u;
    if (has_nonnull_descriptor) {
        if (!reader.u32(sonic_ninja_texture_registry_state, registry) ||
            !reader.u32(sonic_ninja_texture_registry_count, registry_count) ||
            registry == 0u || registry_count == 0u ||
            registry_count > max_native_texture_names ||
            !checked_span_size(registry_count,
                               sonic_ninja_texture_registry_stride,
                               registry_bytes) ||
            !reader.range(registry, registry_bytes))
            fail("native-sdk-release-registry");
        registry_backing = sonic_native_backing_address(registry);
        if (!reader.u32(sonic_native_sdk_release::highwater_slot,
                        registry_highwater) ||
            registry_highwater > registry_count)
            fail("native-sdk-release-highwater");
        for (const auto global : {
                 sonic_native_sdk_release::registry_slot,
                 sonic_native_sdk_release::registry_count_slot,
                 sonic_native_sdk_release::active_key_slot,
                 sonic_native_sdk_release::highwater_slot,
                 sonic_native_sdk_release::mask_slot,
                 sonic_native_sdk_release::last_error_index_slot,
                 sonic_native_sdk_release::release_error_slot}) {
            if (!reader.range(global, sizeof(std::uint32_t)) ||
                sonic_native_ranges_overlap(
                    registry_backing, registry_bytes,
                    sonic_native_backing_address(global), sizeof(std::uint32_t)))
                fail("native-sdk-release-registry");
        }
    }
    // The retail leaf writes only its registry row and SDK globals. Prove the
    // outer control records disjoint before snapshotting all future rows; this
    // makes preflight authoritative while the loop still performs retail's
    // observable count/TEXNAME reloads on every iteration.
    if (has_nonnull_descriptor &&
        (sonic_native_ranges_overlap(
             sonic_native_backing_address(address), 8u,
             registry_backing, registry_bytes) ||
         sonic_native_ranges_overlap(
             sonic_native_backing_address(texnames), texname_bytes,
             registry_backing, registry_bytes)))
        fail("native-sdk-release-control-alias");
    const auto is_registry_row = [&](const std::uint32_t descriptor) {
        const auto descriptor_backing = sonic_native_backing_address(descriptor);
        if (!reader.range(descriptor, sonic_ninja_texture_registry_stride) ||
            descriptor_backing < registry_backing)
            return false;
        const auto offset = static_cast<std::uint64_t>(descriptor_backing) -
                            registry_backing;
        return offset < registry_bytes &&
               offset % sonic_ninja_texture_registry_stride == 0u;
    };

    struct RowSnapshot final {
        std::uint32_t descriptor = 0u;
        std::array<std::uint32_t,
                   sonic_ninja_texture_descriptor_words> words{};
        std::optional<SonicNativeLiveTextureLayout> layout;
        std::uint32_t ordered_calls = 0u;
    };
    std::vector<RowSnapshot> rows;
    rows.reserve(texture_count);
    const auto record_rejection = [&](
        const sonic_native_sdk_texture_list_release::Error& error) noexcept {
        if (context.crash_capsule == nullptr) return;
        katana::runtime::CrashCapsuleProviderTranscript record;
        record.provider = 0x53524C4Au; // SRLJ: bounded list-row rejection.
        record.sequence = context.frame_index;
        record.operation = static_cast<std::uint32_t>(error.reason);
        record.address = address;
        record.value = error.index;
        record.result = error.descriptor;
        record.source = cpu.pc;
        record.callsite = cpu.pr;
        record.provider_identity.assign("sonic-sdk-release-list-rejection-v1");
        record.source_identity.assign("retail-6087fc-preflight");
        record.target_identity.assign("reason-index-descriptor");
        context.crash_capsule->note_v5_provider_transcript(record);
    };
    sonic_native_sdk_texture_list_release::Control initial;
    try {
        initial = sonic_native_sdk_texture_list_release::preflight(
        max_native_texture_names,
        [&](std::uint32_t& count) {
            return reader.u32(address + 4u, count);
        },
        [&](std::uint32_t& current_texnames) {
            return reader.u32(address, current_texnames);
        },
        [&](const std::uint32_t current_texnames, const std::uint32_t index,
            std::uint32_t& descriptor) {
            return reader.u32(
                current_texnames + index * 12u + 8u, descriptor);
        },
        [&](const std::uint32_t descriptor, const std::uint32_t) {
            if (descriptor == 0u) return true;
            if (!is_registry_row(descriptor)) return false;
            if (std::ranges::any_of(rows, [&](const RowSnapshot& row) {
                    return sonic_native_same_backing_address(
                        row.descriptor, descriptor);
                })) {
                const auto existing = std::ranges::find_if(
                    rows, [&](const RowSnapshot& row) {
                        return sonic_native_same_backing_address(
                            row.descriptor, descriptor);
                    });
                if (existing == rows.end() ||
                    existing->ordered_calls ==
                        std::numeric_limits<std::uint32_t>::max())
                    return false;
                ++existing->ordered_calls;
                return true;
            }
            RowSnapshot row;
            row.descriptor = descriptor;
            row.ordered_calls = 1u;
            if (!read_native_guest_texture_descriptor(
                    reader, descriptor, row.words))
                return false;
            if (!sonic_native_guest_texture_descriptor_released(row.words) &&
                (row.words[4] & 2u) != 0u && row.words[6] == 0u)
                row.layout = sonic_native_live_texture_layout(
                    reader, descriptor);
            rows.push_back(std::move(row));
            return true;
        });
    } catch (const sonic_native_sdk_texture_list_release::Error& error) {
        record_rejection(error);
        throw;
    }
    if (initial.count != texture_count ||
        !sonic_native_same_backing_address(initial.texnames, texnames))
        fail("native-sdk-release-control-drift");

    // An absent entry may follow an earlier SDK load failure. Capture the
    // current error globals and at most two live row images before releasing
    // anything; these are observations, not proof of which load failed.
    // This branch adds no guest reads to fully populated lists.
    if (null_descriptor_count != 0u && context.crash_capsule != nullptr) {
        katana::runtime::CrashCapsuleProviderTranscript record;
        record.provider = 0x53524C50u; // SRLP: pre-release incomplete-list state.
        record.sequence = context.frame_index;
        record.address = address;
        record.width = texture_count;
        record.value = null_descriptor_count;
        record.slot = first_null_index;
        record.pointer = texnames + first_null_index * 12u;
        record.source = cpu.pc;
        record.callsite = cpu.pr;
        record.instruction_runtime_pc = cpu.active_instruction_pc;
        std::uint32_t sdk_index = 0u, sdk_error = 0u;
        if (reader.u32(sonic_native_sdk_release::last_error_index_slot, sdk_index))
            record.flags |= 1u;
        if (reader.u32(sonic_native_sdk_release::release_error_slot, sdk_error))
            record.flags |= 2u;
        record.result = static_cast<std::uint64_t>(sdk_index) |
                        (static_cast<std::uint64_t>(sdk_error) << 32u);
        record.provider_identity.assign("sonic-sdk-incomplete-list-v1");
        record.target_identity.assign("current-sdk-index-error-before-release");
        context.crash_capsule->note_v5_provider_transcript(record);
        for (std::size_t i = 0u; i < std::min<std::size_t>(2u, rows.size()); ++i)
            note_native_texture_descriptor_words(
                context, rows[i].descriptor, rows[i].words, 1u);
    }

    auto& state = sonic_native_title_state;
    const auto row_can_free = [](const RowSnapshot& row) noexcept {
        return row.layout.has_value() &&
            sonic_native_sdk_texture_list_release::loaded_type0_can_reach_free(
                static_cast<std::uint16_t>(row.words[16] & 0xFFFFu),
                row.ordered_calls);
    };
    const auto overlaps_releasable_backing = [&](const auto begin,
                                                  const auto size) {
        return std::ranges::any_of(rows, [&](const RowSnapshot& row) {
            return row_can_free(row) && sonic_native_ranges_overlap(
                begin & 0x007FFFFFu, size,
                sonic_native_texture_encoded_backing_address(*row.layout),
                row.layout->encoded_bytes);
        });
    };
    std::vector<katana::runtime::NativePortTextureHandle> planned_retirements;
    const auto account_retirement = [&](const auto texture) {
        sonic_native_sdk_texture_list_release::plan_retired_handle(
            planned_retirements, texture,
            [](const auto handle) {
                return pending_native_draw_uses_texture(handle);
            },
            [&](const auto handle) {
                return std::ranges::any_of(
                    state.retired_dynamic_textures,
                    [&](const SonicNativeRetiredDynamicTexture& retired) {
                        return retired.handle == handle;
                    });
            });
    };
    bool host_retirement = false;
    for (const auto& view : state.dynamic_texture_views) {
        if (!overlaps_releasable_backing(view.vram_address, view.byte_size) ||
            !static_cast<bool>(view.texture))
            continue;
        host_retirement = true;
        account_retirement(view.texture);
    }
    for (const auto& surface : state.dynamic_surfaces) {
        if (!overlaps_releasable_backing(
                surface.destination_address, surface.byte_size) ||
            !static_cast<bool>(surface.texture))
            continue;
        host_retirement = true;
        account_retirement(surface.texture);
    }
    if (!sonic_native_sdk_texture_list_release::retirement_budget_accepts(
            state.retired_dynamic_textures.size(),
            planned_retirements.size(), max_native_retired_dynamic_textures))
        fail("native-sdk-release-retirement-budget");
    if (host_retirement && context.graphics == nullptr)
        fail("native-sdk-release-graphics");
    state.retired_dynamic_textures.reserve(
        state.retired_dynamic_textures.size() + planned_retirements.size());

    std::uint32_t freed_rows = 0u;
    std::array<std::uint32_t,
               sonic_ninja_texture_descriptor_words> leaf_before{};
    sonic_native_sdk_texture_list_release::Result outer;
    try {
        outer = sonic_native_sdk_texture_list_release::run(
        max_native_texture_names,
        [&](std::uint32_t& count) {
            return reader.u32(address + 4u, count);
        },
        [&](std::uint32_t& current_texnames) {
            return reader.u32(address, current_texnames);
        },
        [&](const std::uint32_t current_texnames, const std::uint32_t index,
            std::uint32_t& descriptor) {
            if (index >= texture_count ||
                !sonic_native_same_backing_address(current_texnames, texnames) ||
                !reader.u32(current_texnames + index * 12u + 8u, descriptor))
                return false;
            if (descriptor == 0u) return true;
            if (!is_registry_row(descriptor))
                throw sonic_native_sdk_texture_list_release::Error(
                    sonic_native_sdk_texture_list_release::Failure::Row,
                    index, descriptor);
            return std::ranges::any_of(rows, [&](const RowSnapshot& row) {
                return sonic_native_same_backing_address(
                    row.descriptor, descriptor);
            });
        },
        [&](const std::uint32_t descriptor) {
        if (descriptor == 0u) {
            // Exact PAL 64DD00 null behavior for the bound retail BIOS:
            // flags[0x10]=001A204E selects loaded Type0, data[0x18]
            // resolves E100 as ordinary, and refword[0x40]=C800 remains
            // nonzero after the boot-ROM write is ignored. The leaf returns
            // 1 and changes no SDK or host resource state.
            return 1u;
        }
        std::array<std::uint32_t,
                   sonic_ninja_texture_descriptor_words> before{};
        if (!read_native_guest_texture_descriptor(reader, descriptor, before))
            fail("native-sdk-release-row-drift");
        leaf_before = before;
        cpu.r[4] = descriptor;
        if (!invoke_frame_aot_service(context, 0x8C64DD00u))
            fail("native-sdk-release-leaf");
        return cpu.r[0];
        },
        [&](const std::uint32_t index) {
            katana::runtime::guest_write_u32(
                cpu, sonic_native_sdk_release::last_error_index_slot, index,
                katana::runtime::CodeWriteSource::Copy);
        },
        [&](const std::uint32_t descriptor, const std::uint32_t) {
        if (descriptor == 0u) return;
        std::array<std::uint32_t,
                   sonic_ninja_texture_descriptor_words> after{};
        if (!read_native_guest_texture_descriptor(reader, descriptor, after))
            fail("native-sdk-release-post-state");
        const bool exact_free =
            !sonic_native_guest_texture_descriptor_released(leaf_before) &&
            sonic_native_guest_texture_descriptor_released(after);
        if (exact_free) ++freed_rows;
        const auto snapshot = std::ranges::find_if(
            rows, [&](const RowSnapshot& row) {
                return sonic_native_same_backing_address(
                    row.descriptor, descriptor);
            });
        if (snapshot == rows.end() || !snapshot->layout.has_value())
            return;
        // Loaded Type0 flags 3 -> 1 is a successful SDK backing release but
        // retains a registered row. 64DD3A calls 653CA8 before clearing bit 1
        // (numeric 2); only the subsequent zero-flags branch enters 64E660.
        // Retire the stale GPU view at the resource transition while keeping
        // exact registry-row collection independent above. Type1 rows never
        // receive a Type0 layout and remain wholly owned by the retail leaf.
        if (!sonic_native_sdk_texture_list_release::
                loaded_type0_backing_was_released(
                    leaf_before[4], after[4]))
            return;
        const auto backing = sonic_native_texture_encoded_backing_address(
            *snapshot->layout);
        invalidate_native_dynamic_texture_views(
            context, backing, snapshot->layout->encoded_bytes);
        for (auto it = state.dynamic_surfaces.begin();
             it != state.dynamic_surfaces.end();) {
            if (!sonic_native_ranges_overlap(
                    it->destination_address & 0x007FFFFFu, it->byte_size,
                    backing, snapshot->layout->encoded_bytes)) {
                ++it;
                continue;
            }
            retire_or_destroy_native_dynamic_texture(
                context, it->texture, it->pixel_format);
            it = state.dynamic_surfaces.erase(it);
        }
        });
    } catch (const sonic_native_sdk_texture_list_release::Error& error) {
        record_rejection(error);
        throw;
    }
    if (freed_rows != 0u && !state.pvm_allocations.empty())
        collect_native_pvm_allocations(context);
    // Exact 6087FC epilogue-visible state: r2 is the count loaded by the final
    // loop test and CMP/HS leaves T set. The final leaf's other volatile
    // registers remain visible; callee-saved r9-r14 and PR were never
    // repurposed by this native bridge.
    cpu.r[0] = outer.value;
    cpu.r[2] = outer.final_count;
    cpu.t = true;
    if (context.crash_capsule != nullptr) {
        katana::runtime::CrashCapsuleProviderTranscript record;
        record.provider = 0x53524C53u; // SRLS: one bounded SDK release-list result.
        record.operation = outer.value;
        record.width = null_descriptor_count;
        record.sequence = context.frame_index;
        record.address = address;
        record.value = outer.final_count;
        record.result = static_cast<std::uint32_t>(rows.size());
        record.state = freed_rows;
        record.source = cpu.pc;
        record.callsite = cpu.pr;
        record.provider_identity.assign("sonic-sdk-release-list-v2");
        record.source_identity.assign("retail-6087fc-ordered-leaf-64dd00");
        record.target_identity.assign(
            "aggregate-null-count-unique-rows-freed-rows");
        context.crash_capsule->note_v5_provider_transcript(record);
    }
    return outer.value;
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_named_texture_archive_release(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context) || context.textures == nullptr)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_content_error_context};
    const auto release_texlist = context.cpu->r[4];
    try {
        if (const auto result = release_native_pvm_view(context, release_texlist)) {
            context.cpu->r[0] = *result;
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
        }
        // Exact SDK ABI: r4 is the NJS_TEXLIST and r0 is 1 only when every
        // entry was released. A missing native generation mirrors the SDK's
        // negative aggregate result instead of silently succeeding.
        const auto main_release = release_native_main_texture_list(context, release_texlist);
        const bool named_owner = !main_release.has_value() &&
            std::ranges::any_of(
                sonic_native_title_state.texlist_catalog_bindings,
                [&](const SonicNativeTexlistCatalogBinding& binding) {
                    return binding.named_archive_owner &&
                           sonic_native_same_backing_address(
                               binding.texlist_address, release_texlist);
                });
        const bool released = main_release.has_value() ? *main_release
            : named_owner
                ? release_native_named_texture_archive(context, release_texlist)
                : false;
        context.cpu->r[0] = released ? 1u
            : main_release.has_value()
                ? std::numeric_limits<std::uint32_t>::max()
                : release_native_sdk_texture_list(context, release_texlist);
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        note_native_texture_contract_failure(context, error.what(), release_texlist);
        std::cerr << "SONIC_NATIVE_NAMED_TEXTURE failure=release detail="
                  << error.what() << '\n';
    } catch (...) {
        note_native_texture_contract_failure(context, "non-standard-texture-exception", release_texlist);
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_content_error_texture_set};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_character_texture_set_load(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context) || context.platform == nullptr ||
        context.textures == nullptr)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_content_error_context};
    try {
        static_cast<void>(acquire_native_texture_set(
            context, SonicNativeTextureSetDomain::Character,
            context.cpu->r[4]));
        // Exact displaced ABI: the common increment tail leaves the base of
        // the eight signed-byte reference counters in r0.
        context.cpu->r[0] = sonic_character_texture_refcounts;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        note_native_texture_contract_failure(context, error.what(), 0u);
        std::cerr << "SONIC_NATIVE_TEXTURE_SET failure=character-load detail="
                  << error.what() << '\n';
    } catch (...) {
        note_native_texture_contract_failure(context, "non-standard-texture-exception", 0u);
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_content_error_texture_set};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_character_texture_set_release(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_content_error_context};
    try {
        release_native_character_texture_set(context, context.cpu->r[4]);
        context.cpu->r[0] = sonic_character_texture_refcounts;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        note_native_texture_contract_failure(context, error.what(), 0u);
        std::cerr << "SONIC_NATIVE_TEXTURE_SET failure=character-release detail="
                  << error.what() << '\n';
    } catch (...) {
        note_native_texture_contract_failure(context, "non-standard-texture-exception", 0u);
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_content_error_texture_set};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_character_texture_sets_release_all(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_content_error_context};
    try {
        release_all_native_character_texture_sets(context);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        note_native_texture_contract_failure(context, error.what(), 0u);
        std::cerr << "SONIC_NATIVE_TEXTURE_SET failure=release-all detail="
                  << error.what() << '\n';
    } catch (...) {
        note_native_texture_contract_failure(context, "non-standard-texture-exception", 0u);
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_content_error_texture_set};
}

[[nodiscard]] constexpr std::uint32_t
sonic_native_platform_callback_descriptor_address(
    const std::uint16_t slot) noexcept {
    return sonic_native_platform_callback_table +
           static_cast<std::uint32_t>(slot) *
               static_cast<std::uint32_t>(sonic_native_platform_callback_stride);
}

[[nodiscard]] bool sonic_native_platform_callback_decode_pointer(
    const std::uint32_t pointer,
    std::uint16_t& slot) noexcept {
    if (pointer == 0u) {
        slot = 0u;
        return true;
    }
    if (pointer < sonic_native_platform_callback_table +
                      sonic_native_platform_callback_stride ||
        pointer >= sonic_native_platform_callback_table +
                       static_cast<std::uint32_t>(
                           sonic_native_platform_callback_slot_count *
                           sonic_native_platform_callback_stride))
        return false;
    const auto delta = pointer - sonic_native_platform_callback_table;
    if ((delta % sonic_native_platform_callback_stride) != 0u)
        return false;
    slot = static_cast<std::uint16_t>(delta / sonic_native_platform_callback_stride);
    return slot != 0u &&
           slot < sonic_native_platform_callback_slot_count;
}

[[nodiscard]] bool sonic_native_platform_callback_table_ranges_valid(
    const SonicGuestReader& reader) noexcept {
    return reader.valid() &&
           reader.range(
               sonic_native_platform_callback_table,
               sonic_native_platform_callback_slot_count *
                   sonic_native_platform_callback_stride) &&
           reader.range(
               sonic_native_platform_callback_bucket_roots,
               sonic_native_platform_callback_bucket_count *
                   sizeof(std::uint32_t));
}

[[nodiscard]] bool sonic_native_platform_callback_validate_bucket_mirror(
    const SonicGuestReader& reader,
    const SonicNativePlatformInterruptState& state,
    const std::size_t bucket) noexcept {
    if (bucket >= sonic_native_platform_callback_bucket_count ||
        !sonic_native_platform_callback_table_ranges_valid(reader))
        return false;

    std::uint32_t root_pointer = 0u;
    if (!reader.u32(
            sonic_native_platform_callback_bucket_roots +
                static_cast<std::uint32_t>(bucket * sizeof(std::uint32_t)),
            root_pointer))
        return false;
    std::uint16_t root_slot = 0u;
    if (!sonic_native_platform_callback_decode_pointer(root_pointer, root_slot) ||
        root_slot != state.bucket_heads[bucket])
        return false;

    std::array<bool, sonic_native_platform_callback_slot_count> visited{};
    auto slot = root_slot;
    for (std::size_t count = 0u;
         slot != 0u && count < sonic_native_platform_callback_slot_count;
         ++count) {
        if (slot >= sonic_native_platform_callback_slot_count || visited[slot])
            return false;
        visited[slot] = true;
        const auto& registration = state.registrations[slot];
        if (!registration.active ||
            (static_cast<std::size_t>(registration.event) >> 4u) != bucket)
            return false;

        const auto descriptor =
            sonic_native_platform_callback_descriptor_address(slot);
        std::uint32_t callback = 0u;
        std::uint32_t next_pointer = 0u;
        std::uint32_t callback_context = 0u;
        std::uint32_t active_priority = 0u;
        if (!reader.u32(descriptor, callback) ||
            !reader.u32(descriptor + 4u, next_pointer) ||
            !reader.u32(descriptor + 8u, callback_context) ||
            !reader.u32(descriptor + 12u, active_priority))
            return false;
        const auto expected_next = registration.next_slot == 0u
                                       ? 0u
                                       : sonic_native_platform_callback_descriptor_address(
                                             registration.next_slot);
        if (callback != registration.callback_token ||
            next_pointer != expected_next ||
            callback_context != registration.context ||
            active_priority !=
                (registration.priority |
                 sonic_native_platform_callback_active_bit))
            return false;
        slot = registration.next_slot;
    }
    return slot == 0u;
}

void sonic_native_platform_callback_recompute_state(
    SonicNativePlatformInterruptState& state) noexcept {
    state.primary_mask_word = 0u;
    state.secondary_mask_word = 0u;
    state.special_0900_bound = false;
    state.special_0920_bound = false;
    for (std::size_t slot = 1u;
         slot < sonic_native_platform_callback_slot_count; ++slot) {
        const auto& registration = state.registrations[slot];
        if (!registration.active) continue;
        const auto event = static_cast<std::uint32_t>(registration.event);
        if (event == 0x0900u) state.special_0900_bound = true;
        if (event == 0x0920u) state.special_0920_bound = true;
        if (event >= sonic_native_platform_interrupt_primary_event &&
            event <= sonic_native_platform_interrupt_primary_event +
                         ((sonic_native_platform_interrupt_primary_bits - 1u)
                          << 5u) &&
            ((event - sonic_native_platform_interrupt_primary_event) &
             0x1Fu) == 0u) {
            const auto bit =
                (event - sonic_native_platform_interrupt_primary_event) >> 5u;
            state.primary_mask_word |=
                std::uint32_t{1u} <<
                (sonic_native_platform_interrupt_primary_status_shift + bit);
        }
        if (event >= sonic_native_platform_interrupt_secondary_event &&
            event <= sonic_native_platform_interrupt_secondary_event +
                         ((sonic_native_platform_interrupt_secondary_bits - 1u)
                          << 5u) &&
            ((event - sonic_native_platform_interrupt_secondary_event) &
             0x1Fu) == 0u) {
            const auto bit =
                (event - sonic_native_platform_interrupt_secondary_event) >> 5u;
            state.secondary_mask_word |= std::uint32_t{1u} << bit;
        }
    }
}

[[nodiscard]] std::uint32_t
sonic_native_platform_interrupt_adopt_checkpoint_state(
    const SonicGuestReader& reader,
    const SonicNativePlatformInterruptState& current,
    SonicNativePlatformInterruptState& adopted) noexcept {
    constexpr std::size_t table_words =
        (sonic_native_platform_interrupt_entry_count + 1u) * 2u;
    if (!reader.valid() ||
        !reader.range(sonic_native_platform_interrupt_table,
                      table_words * sizeof(std::uint32_t)) ||
        !sonic_native_platform_callback_table_ranges_valid(reader))
        return sonic_native_platform_interrupt_error_range;

    // 0x8C6024B0 executes before the exported post-bootstrap checkpoint.  Its
    // hardware writes are represented by the same immutable configuration
    // identity as the whole-owner hook, while the callback table itself is
    // ordinary RAM and may already contain live registrations.  Import both
    // into a temporary state so a malformed checkpoint can never be partly
    // published to the native provider.
    SonicNativePlatformInterruptState next{};
    sonic_native_platform_interrupt_preserve_independent_projections(
        current, next);
    constexpr std::array<std::uint32_t,
                         sonic_native_platform_interrupt_reset_count>
        intc_addresses{
            0xFFD00000u, 0xFFD00004u, 0xFFD00008u, 0xFFD0000Cu};
    for (std::size_t index = 0u; index < intc_addresses.size(); ++index)
        next.intc_resets[index] = {intc_addresses[index], 0u};

    for (std::size_t index = 0u;
         index < sonic_native_platform_interrupt_entry_count; ++index) {
        const auto address = sonic_native_platform_interrupt_table +
                             static_cast<std::uint32_t>(index * 8u);
        SonicNativePlatformInterruptConfiguration actual{};
        if (!reader.u32(address, actual.destination) ||
            !reader.u32(address + 4u, actual.value) ||
            actual.destination !=
                sonic_native_platform_interrupt_expected_configuration[index]
                    .destination ||
            actual.value !=
                sonic_native_platform_interrupt_expected_configuration[index]
                    .value)
            return sonic_native_platform_interrupt_error_identity;
        next.configuration[index] = actual;
    }

    std::uint32_t sentinel_destination = 0u;
    std::uint32_t sentinel_value = 0u;
    const auto sentinel_address =
        sonic_native_platform_interrupt_table +
        static_cast<std::uint32_t>(
            sonic_native_platform_interrupt_entry_count * 8u);
    if (!reader.u32(sentinel_address, sentinel_destination) ||
        !reader.u32(sentinel_address + 4u, sentinel_value) ||
        sentinel_destination != 0u || sentinel_value != 0u)
        return sonic_native_platform_interrupt_error_table;
    next.configuration_count = sonic_native_platform_interrupt_entry_count;

    std::array<bool, sonic_native_platform_callback_slot_count> visited{};
    std::uint64_t generation = 1u;
    for (std::size_t bucket = 0u;
         bucket < sonic_native_platform_callback_bucket_count; ++bucket) {
        std::uint32_t root_pointer = 0u;
        if (!reader.u32(
                sonic_native_platform_callback_bucket_roots +
                    static_cast<std::uint32_t>(bucket * sizeof(std::uint32_t)),
                root_pointer))
            return sonic_native_platform_interrupt_error_range;
        std::uint16_t slot = 0u;
        if (!sonic_native_platform_callback_decode_pointer(root_pointer, slot))
            return sonic_native_platform_interrupt_error_registration;
        next.bucket_heads[bucket] = slot;

        std::uint32_t previous_priority = 0u;
        bool have_previous_priority = false;
        for (std::size_t count = 0u;
             slot != 0u && count < sonic_native_platform_callback_slot_count;
             ++count) {
            if (slot >= sonic_native_platform_callback_slot_count ||
                visited[slot])
                return sonic_native_platform_interrupt_error_registration;
            visited[slot] = true;

            const auto descriptor =
                sonic_native_platform_callback_descriptor_address(slot);
            std::uint32_t callback = 0u;
            std::uint32_t next_pointer = 0u;
            std::uint32_t callback_context = 0u;
            std::uint32_t active_priority = 0u;
            if (!reader.u32(descriptor, callback) ||
                !reader.u32(descriptor + 4u, next_pointer) ||
                !reader.u32(descriptor + 8u, callback_context) ||
                !reader.u32(descriptor + 12u, active_priority))
                return sonic_native_platform_interrupt_error_range;
            if ((active_priority & sonic_native_platform_callback_active_bit) ==
                0u)
                return sonic_native_platform_interrupt_error_registration;
            const auto priority =
                active_priority & sonic_native_platform_callback_priority_mask;
            if (have_previous_priority && priority < previous_priority)
                return sonic_native_platform_interrupt_error_registration;

            std::uint16_t next_slot = 0u;
            if (!sonic_native_platform_callback_decode_pointer(
                    next_pointer, next_slot))
                return sonic_native_platform_interrupt_error_registration;
            next.registrations[slot] = {
                true,
                static_cast<std::uint16_t>(bucket << 4u),
                next_slot,
                callback,
                callback_context,
                priority,
                generation++};
            previous_priority = priority;
            have_previous_priority = true;
            slot = next_slot;
        }
        if (slot != 0u)
            return sonic_native_platform_interrupt_error_registration;
    }

    // An active record which is absent from every bucket cannot be produced
    // by 0x8C64588C/0x8C645B94.  Reject it instead of silently inventing an
    // event identity that the 16-byte retail descriptor does not store.
    for (std::uint16_t slot = 1u;
         slot < sonic_native_platform_callback_slot_count; ++slot) {
        if (visited[slot]) continue;
        std::uint32_t active_priority = 0u;
        if (!reader.u32(
                sonic_native_platform_callback_descriptor_address(slot) + 12u,
                active_priority))
            return sonic_native_platform_interrupt_error_range;
        if ((active_priority & sonic_native_platform_callback_active_bit) != 0u)
            return sonic_native_platform_interrupt_error_registration;
    }

    next.event_status_bound = false;
    if (!next.iml4_nrm_bound) {
        next.iml4_nrm_bound = true;
        next.iml4_nrm_value = 0u;
        next.iml4_nrm_sequence = 1u;
    }
    next.next_generation = generation;
    next.sequence = current.sequence + 1u;
    next.initialized = true;
    sonic_native_platform_callback_recompute_state(next);
    adopted = next;
    return 0u;
}

[[nodiscard]] std::uint32_t
sonic_native_platform_interrupt_ensure_checkpoint_state(
    const SonicGuestReader& reader,
    SonicNativePlatformInterruptState& state) noexcept {
    if (state.initialized) return 0u;
    SonicNativePlatformInterruptState adopted{};
    const auto error = sonic_native_platform_interrupt_adopt_checkpoint_state(
        reader, state, adopted);
    if (error != 0u) return error;
    state = adopted;
    return 0u;
}

[[nodiscard]] katana::runtime::NativePortHookResult
sonic_native_system_bus_revision_instruction(
    katana::runtime::NativePortContext& context,
    const std::size_t address_register,
    const std::size_t result_register,
    const std::uint32_t resume_address) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_system_bus_revision_error_context};
    if (address_register >= context.cpu->r.size() ||
        result_register >= context.cpu->r.size() ||
        context.cpu->r[address_register] !=
            sonic_native_system_bus_revision_address)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_system_bus_revision_error_identity};

    // SB_SBREV is an immutable platform capability, not mutable device state.
    // Validate the exact audited address transport, publish only the SH-4
    // destination register, and leave the surrounding owner in static AOT.
    context.cpu->r[result_register] = sonic_native_system_bus_revision_value;
    return {katana::runtime::NativePortHookAction::Jump, resume_address, 0u};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_system_bus_revision_read_8c604852(
    katana::runtime::NativePortContext& context) noexcept {
    return sonic_native_system_bus_revision_instruction(
        context, 1u, 2u, 0x8C604854u);
}

