sonic_native_system_bus_revision_read_8c65f56c(
    katana::runtime::NativePortContext& context) noexcept {
    return sonic_native_system_bus_revision_instruction(
        context, 0u, 1u, 0x8C65F56Eu);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_system_bus_revision_read_8c6656b8(
    katana::runtime::NativePortContext& context) noexcept {
    return sonic_native_system_bus_revision_instruction(
        context, 3u, 5u, 0x8C6656BAu);
}

[[nodiscard]] katana::runtime::NativePortHookResult
sonic_native_platform_interrupt_iml4_nrm_read_instruction(
    katana::runtime::NativePortContext& context,
    const std::size_t address_register,
    const std::size_t result_register,
    const std::uint32_t resume_address) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_platform_interrupt_error_context};
    constexpr std::uint32_t iml4_nrm_address = 0xA05F6920u;
    if (address_register >= context.cpu->r.size() ||
        result_register >= context.cpu->r.size() ||
        context.cpu->r[address_register] != iml4_nrm_address)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_platform_interrupt_error_identity};

    SonicGuestReader reader(*context.cpu);
    auto& state = sonic_native_title_state.platform_interrupt_state;
    const auto error =
        sonic_native_platform_interrupt_ensure_checkpoint_state(reader, state);
    if (error != 0u || !state.iml4_nrm_bound)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                error != 0u ? error
                            : sonic_native_platform_interrupt_error_state};
    context.cpu->r[result_register] = state.iml4_nrm_value;
    return {katana::runtime::NativePortHookAction::Jump, resume_address, 0u};
}

[[nodiscard]] katana::runtime::NativePortHookResult
sonic_native_platform_interrupt_iml4_nrm_write_instruction(
    katana::runtime::NativePortContext& context,
    const std::size_t address_register,
    const std::size_t value_register,
    const std::uint32_t resume_address) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_platform_interrupt_error_context};
    constexpr std::uint32_t iml4_nrm_address = 0xA05F6920u;
    if (address_register >= context.cpu->r.size() ||
        value_register >= context.cpu->r.size() ||
        context.cpu->r[address_register] != iml4_nrm_address)
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_platform_interrupt_error_identity};

    SonicGuestReader reader(*context.cpu);
    auto& current = sonic_native_title_state.platform_interrupt_state;
    const auto error = sonic_native_platform_interrupt_ensure_checkpoint_state(
        reader, current);
    if (error != 0u || !current.iml4_nrm_bound ||
        current.iml4_nrm_sequence ==
            std::numeric_limits<std::uint64_t>::max() ||
        current.sequence == std::numeric_limits<std::uint64_t>::max())
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                error != 0u ? error
                            : sonic_native_platform_interrupt_error_state};

    auto next = current;
    next.iml4_nrm_value = context.cpu->r[value_register];
    ++next.iml4_nrm_sequence;
    ++next.sequence;
    // This exact instruction pair owns the title's live IML4NRM value after
    // bootstrap. Retain only that bounded projection; no ASIC register bank
    // or raw guest-address dereference exists in the native product.
    current = next;
    return {katana::runtime::NativePortHookAction::Jump, resume_address, 0u};
}

