extern "C" katana::runtime::NativePortHookResult
sonic_native_draw_pretransformed_dispatch(
    katana::runtime::NativePortContext& context) noexcept {
    SonicNativeScopedWork work{
        sonic_native_title_state.work_timing,
        SonicNativeWorkClass::Pretransformed};
    if (!valid_sonic_native_context(context))
        return graphics_abort(sonic_native_graphics_error_context);
    const auto count_signed = static_cast<std::int32_t>(context.cpu->r[5]);
    if (count_signed < 0)
        return graphics_abort(sonic_native_graphics_error_layout);
    const auto count = static_cast<std::uint32_t>(count_signed);
    if (count == 0u) {
        return finish_pretransformed_stream_draw(
            context,
            {katana::runtime::NativePortHookAction::Return, 0u, 0u});
    }

    const auto selector = context.cpu->r[6];
    const bool textured = (selector & 0x80000000u) != 0u;
    const bool translucent = (selector & 0x40u) != 0u;
    const bool direct_strip = (selector & 0x20u) != 0u;
    const auto variant = static_cast<std::size_t>(textured) +
                         (direct_strip ? 2u : 0u);

    SonicGuestReader reader(*context.cpu);
    std::array<std::uint32_t, 3u> streams{};
    if (!reader.valid() || !reader.u32(context.cpu->r[4] + 0u, streams[0]) ||
        !reader.u32(context.cpu->r[4] + 4u, streams[1]) ||
        (textured && !reader.u32(context.cpu->r[4] + 8u, streams[2])))
        return graphics_abort(sonic_native_graphics_error_range);

    std::optional<sonic::subtitles::Layout> subtitle_layout;
    const auto& subtitle_settings=sonic::presentation::settings();
    const bool subtitle_background_call=context.cpu->pr==0x8C054AF0u;
    if((subtitle_settings.subtitle_scale!=100||subtitle_settings.subtitle_background) && count==4 &&
        (subtitle_background_call||context.cpu->pr==0x8C054B9Au) && context.cpu->fr[4]==0xBF999999u &&
        selector==(subtitle_background_call?0x60u:0x80000060u) && context.cpu->r[15]<=0xFFFFFFFFu-92 &&
        context.cpu->r[4]==context.cpu->r[15]+(subtitle_background_call?28u:12u) &&
        streams[0]==context.cpu->r[15]+(subtitle_background_call?44u:28u) && streams[1]==context.cpu->r[15]+76u &&
        (subtitle_background_call || streams[2]==context.cpu->r[15]+60u)) {
        std::uint8_t type=0;std::int16_t x=0,y=0;std::uint16_t width=0,height=0;
        const auto owner=context.cpu->r[14];
        if(reader.range(owner,60) && reader.u8(owner,type) && type==1 && reader.i16(owner+2,x)&&reader.i16(owner+4,y)&&
            reader.u16(owner+10,width)&&reader.u16(owner+12,height)&&width&&height)
            subtitle_layout=sonic::subtitles::layout(float(x),float(y),float(width),float(height),subtitle_settings);
        // The optional contrast layer is emitted exactly once at the text
        // call, including when retail background alpha suppresses this call.
        if(subtitle_layout && subtitle_background_call && subtitle_settings.subtitle_background)
            return finish_pretransformed_stream_draw(context,{katana::runtime::NativePortHookAction::Return,0,0});
    }

    // Source-bound PAL transition owners, not a four-vertex geometry guess.
    // 0436FE calls this API; 0439AE tails here using its static descriptor.
    // 09B46C/09B4F2 are the black/white level fades, with stack-owned streams.
    const auto& cpu = *context.cpu;
    const bool stack_fade = cpu.r[15] <= 0xFFFFFFFFu-56u &&
        cpu.r[4] == cpu.r[15]+8u && streams[0] == cpu.r[4]+16u &&
        streams[1] == cpu.r[4]+48u && cpu.fr[4] == 0xBC23D70Au &&
        ((cpu.pr == 0x8C09B4EAu && selector == 0x60u) ||
         (cpu.pr == 0x8C09B582u && (selector == 0x60u || selector == 0x20u)));
    // The separate 042E4E stage-entry fade orders its perimeter differently
    // and places the descriptor after the colors/positions in its stack frame.
    const bool stage_fade = cpu.pr == 0x8C042F06u && selector == 0x62u &&
        cpu.fr[4] == 0xBDCCCCCCu && cpu.r[15] <= 0xFFFFFFFFu-68u &&
        cpu.r[4] == cpu.r[15]+52u && streams[0] == cpu.r[15]+20u &&
        streams[1] == cpu.r[15]+4u;
    const bool fullscreen_overlay = count == 4u && !textured &&
        (stack_fade || stage_fade || (context.cpu->pr == 0x8C0437BAu && selector == 0x62u &&
          context.cpu->fr[4] == 0xBDCCCCCCu) ||
         (context.cpu->r[4] == 0x8C19B518u && selector == 0x60u &&
          context.cpu->fr[4] == 0xBF8147AEu &&
          streams[0] == 0x8C19B4E8u && streams[1] == 0x8C19B508u));

    // One bounded value witness per statically proven selector class.  It is
    // private product evidence, not a source of rendering semantics: no bulk
    // title data is persisted and an unimplemented class remains typed-abort.
    if (!sonic_native_title_state.pretransformed_probe_reported[variant]) {
        sonic_native_title_state.pretransformed_probe_reported[variant] = true;
        std::cerr << "SONIC_NATIVE_PRETRANSFORMED_PROBE r4=0x" << std::hex
                  << context.cpu->r[4] << " pr=0x" << context.cpu->pr
                  << " sp=0x" << context.cpu->r[15] << " fullscreen=" << fullscreen_overlay
                  << " r5=0x" << context.cpu->r[5]
                  << " r6=0x" << context.cpu->r[6] << " fr4=0x"
                  << context.cpu->fr[4] << " streams=0x" << streams[0]
                  << ",0x" << streams[1] << ",0x" << streams[2];
        const auto sampled = std::min<std::uint32_t>(count, 4u);
        for (std::uint32_t index = 0u; index < sampled; ++index) {
            std::uint32_t x = 0u;
            std::uint32_t y = 0u;
            std::uint32_t color = 0u;
            std::uint32_t uv = 0u;
            const bool complete =
                reader.u32(streams[0] + index * 8u, x) &&
                reader.u32(streams[0] + index * 8u + 4u, y) &&
                reader.u32(streams[1] + index * 4u, color) &&
                (!textured || reader.u32(streams[2] + index * 4u, uv));
            std::cerr << " v" << std::dec << index << std::hex << "=[";
            if (complete) {
                std::cerr << "0x" << x << ",0x" << y << ",0x" << color;
                if (textured) std::cerr << ",0x" << uv;
            } else {
                std::cerr << "invalid";
            }
            std::cerr << ']';
        }
        std::cerr << std::dec << '\n';
    }

    if ((direct_strip && count < 3u) || (!direct_strip && count < 2u) ||
        count > max_native_draw_vertices ||
        (!direct_strip && count > max_native_draw_vertices / 6u))
        return graphics_abort(sonic_native_graphics_error_budget);

    std::size_t point_bytes = 0u;
    std::size_t color_bytes = 0u;
    std::size_t uv_bytes = 0u;
    if (!checked_span_size(count, 8u, point_bytes) ||
        !checked_span_size(count, 4u, color_bytes) ||
        !reader.range(streams[0], point_bytes) ||
        !reader.range(streams[1], color_bytes) ||
        (textured &&
         (!checked_span_size(count, 4u, uv_bytes) ||
          !reader.range(streams[2], uv_bytes))))
        return graphics_abort(sonic_native_graphics_error_range);

    const auto source_depth = std::bit_cast<float>(context.cpu->fr[4]);
    if (!std::isfinite(source_depth))
        return graphics_abort(sonic_native_graphics_error_layout);
    const auto reciprocal_depth =
        source_depth < -1.0f ? -1.0f / source_depth : 1.0f;
    if (!std::isfinite(reciprocal_depth) || reciprocal_depth <= 0.0f)
        return graphics_abort(sonic_native_graphics_error_layout);

    const bool collect_graphics_diagnostics =
        sonic_native_graphics_diagnostics_enabled();
    katana::runtime::NativePortTextureHandle texture;
    SonicNativeTextureResolutionDiagnostics texture_diagnostics;
    SonicNativeTextureBinding texture_binding;
    std::uint32_t resolved_texture_index = 0u;
    if (textured) {
        const auto texture_resolution = resolve_current_native_texture(
            context, reader, texture,
            &texture_diagnostics, &texture_binding,
            &resolved_texture_index);
        if (texture_resolution != SonicNativeTextureResolution::Bound) {
            if (texture_resolution ==
                SonicNativeTextureResolution::UnboundSentinel)
                return finish_pretransformed_stream_draw(
                    context,
                    {katana::runtime::NativePortHookAction::Return, 0u, 0u});
            return graphics_abort(sonic_native_graphics_error_texture);
        }
    }

    struct PretransformedPoint final {
        float x = 0.0f;
        float y = 0.0f;
        std::array<float, 4u> color{1.0f, 1.0f, 1.0f, 1.0f};
        std::array<float, 2u> texture_coordinate{};
    };
    const auto read_point = [&](const std::uint32_t index,
                                PretransformedPoint& point) noexcept {
        std::uint32_t color = 0u;
        if (!reader.f32(streams[0] + index * 8u, point.x) ||
            !reader.f32(streams[0] + index * 8u + 4u, point.y) ||
            !reader.u32(streams[1] + index * 4u, color))
            return false;
        point.color = argb_color(color);
        if (textured) {
            std::int16_t u = 0;
            std::int16_t v = 0;
            if (!reader.i16(streams[2] + index * 4u, u) ||
                !reader.i16(streams[2] + index * 4u + 2u, v))
                return false;
            // NJS_TEX stores signed fixed-point U then V; the exact E83C/EA02
            // paths convert both with 1/256 before submitting the vertex.
            point.texture_coordinate = {
                static_cast<float>(u) / 256.0f,
                static_cast<float>(v) / 256.0f};
        }
        return true;
    };
    const auto make_vertex = [&](const PretransformedPoint& point,
                                 const float x,
                                 const float y) noexcept {
        katana::runtime::NativePortVertex vertex;
        vertex.position = {x, y, reciprocal_depth};
        vertex.depth_coordinate = reciprocal_depth;
        vertex.color = point.color;
        vertex.texture_coordinate = point.texture_coordinate;
        return vertex;
    };

    auto& vertices = sonic_native_title_state.transient_vertices;
    vertices.clear();
    if (direct_strip) {
        vertices.reserve(count);
        // The identity-bound E774/E83C NINJA paths do not submit their SoA
        // inputs in source order. They build the strip by alternating the
        // front and back of the input contour: 0, n-1, 1, n-2, ... . This
        // turns a perimeter-ordered quad into the GPU strip expected by the
        // host backend and applies equally to the textured variant.
        for (std::uint32_t output = 0u; output < count; ++output) {
            const auto index = (output & 1u) == 0u
                                   ? output / 2u
                                   : count - 1u - output / 2u;
            PretransformedPoint point;
            if (!read_point(index, point))
                return graphics_abort(sonic_native_graphics_error_range);
            vertices.push_back(make_vertex(point, point.x, point.y));
        }
    } else {
        // The E92A/EA02 family closes the input contour: adjacent endpoint
        // pairs are expanded by E230/E3B8, then the last endpoint is paired
        // with the first.  Each segment is a 1.05-pixel-wide quad (two
        // triangles) with the exact 0.525 half-width and endpoint attributes.
        constexpr float half_width = 0.525f;
        vertices.reserve(static_cast<std::size_t>(count) * 6u);
        for (std::uint32_t index = 0u; index < count; ++index) {
            const auto next = index + 1u == count ? 0u : index + 1u;
            PretransformedPoint a;
            PretransformedPoint b;
            if (!read_point(index, a) || !read_point(next, b))
                return graphics_abort(sonic_native_graphics_error_range);
            const auto dx = b.x - a.x;
            const auto dy = b.y - a.y;
            const auto length = std::hypot(dx, dy);
            if (!std::isfinite(length) || length <= 0.0f)
                return graphics_abort(sonic_native_graphics_error_layout);
            const auto offset_x = dy * (half_width / length);
            const auto offset_y = -dx * (half_width / length);
            const auto a_positive =
                make_vertex(a, a.x + offset_x, a.y + offset_y);
            const auto a_negative =
                make_vertex(a, a.x - offset_x, a.y - offset_y);
            const auto b_positive =
                make_vertex(b, b.x + offset_x, b.y + offset_y);
            const auto b_negative =
                make_vertex(b, b.x - offset_x, b.y - offset_y);
            vertices.push_back(a_positive);
            vertices.push_back(a_negative);
            vertices.push_back(b_positive);
            vertices.push_back(b_positive);
            vertices.push_back(a_negative);
            vertices.push_back(b_negative);
        }
    }

    if(subtitle_layout) {
        sonic::subtitles::apply(vertices,*subtitle_layout,subtitle_background_call);
        if(!subtitle_background_call && subtitle_settings.subtitle_background){
            auto text_vertices=std::move(vertices);const auto band=sonic::subtitles::backdrop(text_vertices);vertices.assign(band.begin(),band.end());
            katana::runtime::NativePortBlendState alpha;alpha.enabled=true;alpha.source_color=katana::runtime::NativePortBlendFactor::SourceAlpha;
            alpha.destination_color=katana::runtime::NativePortBlendFactor::InverseSourceAlpha;
            const auto background_result=draw_packet(context,ninja_flag_use_alpha,{},katana::runtime::NativePortPrimitiveTopology::TriangleStrip,
                katana::runtime::NativePortViewportTarget::Ui,alpha,std::nullopt,std::nullopt,std::nullopt,std::nullopt,{},std::nullopt,std::nullopt,{},std::nullopt,false,std::nullopt,
                katana::runtime::NativePortDepthCoordinateMode::ReciprocalPositive,0x02100002u,std::nullopt,{}, {},std::nullopt,sonic::presentation::Role::Fullscreen);
            vertices=std::move(text_vertices);if(background_result.action==katana::runtime::NativePortHookAction::Abort)return background_result;
        }
    }
    static const bool diagnostic_pretransformed_state =
        sonic_native_diagnostic_enabled(
            "KATANA_SONIC_DIAGNOSTIC_PRETRANSFORMED_STATE");
    std::uint64_t draw_signature = 0u;
    if (diagnostic_pretransformed_state) {
        draw_signature = 1469598103934665603ull;
        const auto mix_signature = [&draw_signature](
                                       const std::uint32_t value) {
            draw_signature ^= value;
            draw_signature *= 1099511628211ull;
        };
        mix_signature(selector);
        mix_signature(count);
        mix_signature(std::bit_cast<std::uint32_t>(source_depth));
        for (const auto& vertex : vertices) {
            mix_signature(std::bit_cast<std::uint32_t>(vertex.position[0]));
            mix_signature(std::bit_cast<std::uint32_t>(vertex.position[1]));
            mix_signature(std::bit_cast<std::uint32_t>(vertex.position[2]));
            for (const auto component : vertex.color)
                mix_signature(std::bit_cast<std::uint32_t>(component));
        }
    }
    if (diagnostic_pretransformed_state &&
        (!sonic_native_title_state.pretransformed_draw_signature_bound ||
         sonic_native_title_state.pretransformed_draw_signature !=
             draw_signature)) {
        sonic_native_title_state.pretransformed_draw_signature_bound = true;
        sonic_native_title_state.pretransformed_draw_signature = draw_signature;
        std::cerr << "SONIC_NATIVE_PRETRANSFORMED_STATE frame="
                  << context.frame_index << " selector=0x" << std::hex
                  << selector << std::dec << " count=" << count
                  << " source_depth=" << source_depth
                  << " reciprocal_depth=" << reciprocal_depth;
        const auto sampled = std::min<std::size_t>(vertices.size(), 4u);
        for (std::size_t index = 0u; index < sampled; ++index) {
            const auto& vertex = vertices[index];
            std::cerr << " v" << index << "=[" << vertex.position[0] << ','
                      << vertex.position[1] << ',' << vertex.color[0] << ','
                      << vertex.color[1] << ',' << vertex.color[2] << ','
                      << vertex.color[3] << ']';
        }
        std::cerr << '\n';
    }

    katana::runtime::NativePortDrawDiagnostics draw_diagnostics;
    draw_diagnostics.enabled = collect_graphics_diagnostics;
    draw_diagnostics.origin =
        katana::runtime::NativePortDrawOriginKind::Immediate;
    draw_diagnostics.intent =
        katana::runtime::NativePortDrawIntent::Interface;
    draw_diagnostics.origin_identity = sonic_native_opaque_identity(
        0x5052455452414E53ull,
        context.cpu->active_instruction_pc,
        context.cpu->pr,
        context.cpu->r[4],
        selector);
    draw_diagnostics.origin_identity_bound = true;
    if (sonic_native_armed_graphics_identity_frame(
            context.frame_index)) {
        draw_diagnostics.model_identity = native_ui_coverage_identity(
            std::span<const katana::runtime::NativePortVertex>(
                vertices.data(), vertices.size()),
            std::span<const std::uint32_t>{}, texture,
            direct_strip
                ? katana::runtime::NativePortPrimitiveTopology::
                      TriangleStrip
                : katana::runtime::NativePortPrimitiveTopology::
                      TriangleList);
        draw_diagnostics.model_identity_bound = true;
    }
    draw_diagnostics.primitive_index = static_cast<std::uint32_t>(variant) |
        (translucent ? 4u : 0u);
    draw_diagnostics.primitive_index_bound = true;
    if (textured)
        populate_native_texture_draw_diagnostics(
            texture_binding, resolved_texture_index,
            texture_diagnostics, draw_diagnostics);

    const auto result = draw_packet(
        context,
        (textured ? ninja_flag_use_texture : 0u) |
            (translucent ? ninja_flag_use_alpha : 0u),
        texture,
        direct_strip
            ? katana::runtime::NativePortPrimitiveTopology::TriangleStrip
            : katana::runtime::NativePortPrimitiveTopology::TriangleList,
        katana::runtime::NativePortViewportTarget::Ui,
        std::nullopt, std::nullopt, std::nullopt, std::nullopt, std::nullopt,
        {}, std::nullopt, std::nullopt, {}, std::nullopt, false, std::nullopt,
        katana::runtime::NativePortDepthCoordinateMode::ReciprocalPositive,
        (translucent ? 0x02100002u : 0x00080002u) |
            (textured ? 0x8u : 0u),
        std::nullopt, draw_diagnostics, {}, std::nullopt,
        fullscreen_overlay ? sonic::presentation::Role::Fullscreen : sonic::presentation::Role::Interface);
    return finish_pretransformed_stream_draw(context, result);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_draw_pretransformed_line_dispatch(
    katana::runtime::NativePortContext& context) noexcept {
    SonicNativeScopedWork work{
        sonic_native_title_state.work_timing,
        SonicNativeWorkClass::Pretransformed};
    if (!valid_sonic_native_context(context))
        return graphics_abort(sonic_native_graphics_error_context);

    const auto selector = context.cpu->r[6];
    constexpr std::uint32_t supported_selector_bits =
        0x80000000u | 0x40u | 0x0Fu;
    const auto mode = selector & 0x0Fu;
    if ((selector & ~supported_selector_bits) != 0u || mode > 2u)
        return graphics_abort(sonic_native_graphics_error_layout);
    const bool textured = (selector & 0x80000000u) != 0u;
    const bool translucent = (selector & 0x40u) != 0u;

    const auto count_signed = static_cast<std::int32_t>(context.cpu->r[5]);
    if (count_signed < 0)
        return graphics_abort(sonic_native_graphics_error_layout);
    if (count_signed == 0 || (mode != 0u && count_signed == 1)) {
        return finish_pretransformed_stream_draw(
            context,
            {katana::runtime::NativePortHookAction::Return, 0u, 0u});
    }
    const auto count = static_cast<std::uint32_t>(count_signed);
    const auto segment_count = mode == 0u ? count : count - 1u;
    const std::uint64_t source_count_64 =
        mode == 0u ? static_cast<std::uint64_t>(count) * 2u : count;
    if (source_count_64 > max_native_draw_vertices ||
        segment_count > max_native_draw_vertices / 6u)
        return graphics_abort(sonic_native_graphics_error_budget);
    const auto source_count = static_cast<std::uint32_t>(source_count_64);

    SonicGuestReader reader(*context.cpu);
    std::array<std::uint32_t, 3u> streams{};
    std::size_t point_bytes = 0u;
    std::size_t color_bytes = 0u;
    std::size_t uv_bytes = 0u;
    if (!reader.valid() || !reader.range(context.cpu->r[4], 8u) ||
        !reader.u32(context.cpu->r[4] + 0u, streams[0]) ||
        !reader.u32(context.cpu->r[4] + 4u, streams[1]) ||
        (textured &&
         (!reader.range(context.cpu->r[4], 12u) ||
          !reader.u32(context.cpu->r[4] + 8u, streams[2]))) ||
        streams[0] == 0u || streams[1] == 0u ||
        (textured && streams[2] == 0u) ||
        !checked_span_size(source_count, 8u, point_bytes) ||
        !checked_span_size(source_count, 4u, color_bytes) ||
        !reader.range(streams[0], point_bytes) ||
        !reader.range(streams[1], color_bytes) ||
        (textured &&
         (!checked_span_size(source_count, 4u, uv_bytes) ||
          !reader.range(streams[2], uv_bytes))))
        return graphics_abort(sonic_native_graphics_error_range);

    const auto source_depth = std::bit_cast<float>(context.cpu->fr[4]);
    if (!std::isfinite(source_depth))
        return graphics_abort(sonic_native_graphics_error_layout);
    const auto reciprocal_depth =
        source_depth < -1.0f ? -1.0f / source_depth : 1.0f;
    if (!std::isfinite(reciprocal_depth) || reciprocal_depth <= 0.0f)
        return graphics_abort(sonic_native_graphics_error_layout);

    const bool collect_graphics_diagnostics =
        sonic_native_graphics_diagnostics_enabled();
    katana::runtime::NativePortTextureHandle texture;
    SonicNativeTextureResolutionDiagnostics texture_diagnostics;
    SonicNativeTextureBinding texture_binding;
    std::uint32_t resolved_texture_index = 0u;
    if (textured) {
        const auto texture_resolution = resolve_current_native_texture(
            context, reader, texture, &texture_diagnostics, &texture_binding,
            &resolved_texture_index);
        if (texture_resolution != SonicNativeTextureResolution::Bound) {
            if (texture_resolution ==
                SonicNativeTextureResolution::UnboundSentinel)
                return finish_pretransformed_stream_draw(
                    context,
                    {katana::runtime::NativePortHookAction::Return, 0u, 0u});
            return graphics_abort(sonic_native_graphics_error_texture);
        }
    }

    struct LinePoint final {
        float x = 0.0f;
        float y = 0.0f;
        std::array<float, 4u> color{1.0f, 1.0f, 1.0f, 1.0f};
        std::array<float, 2u> texture_coordinate{};
    };
    const auto read_point = [&](const std::uint32_t index,
                                LinePoint& point) noexcept {
        std::uint32_t color = 0u;
        if (index >= source_count ||
            !reader.f32(streams[0] + index * 8u, point.x) ||
            !reader.f32(streams[0] + index * 8u + 4u, point.y) ||
            !reader.u32(streams[1] + index * 4u, color) ||
            !std::isfinite(point.x) || !std::isfinite(point.y))
            return false;
        point.color = argb_color(color);
        if (textured) {
            std::int16_t u = 0;
            std::int16_t v = 0;
            if (!reader.i16(streams[2] + index * 4u, u) ||
                !reader.i16(streams[2] + index * 4u + 2u, v))
                return false;
            point.texture_coordinate = {
                static_cast<float>(u) / 256.0f,
                static_cast<float>(v) / 256.0f};
        }
        return true;
    };
    const auto make_vertex = [&](const LinePoint& point,
                                 const float x,
                                 const float y) noexcept {
        katana::runtime::NativePortVertex vertex;
        vertex.position = {x, y, reciprocal_depth};
        vertex.depth_coordinate = reciprocal_depth;
        vertex.color = point.color;
        vertex.texture_coordinate = point.texture_coordinate;
        return vertex;
    };

    auto& vertices = sonic_native_title_state.transient_vertices;
    vertices.clear();
    vertices.reserve(static_cast<std::size_t>(segment_count) * 6u);
    constexpr auto half_width = std::bit_cast<float>(0x3F066666u);
    const auto append_segment = [&](const std::uint32_t first_index,
                                    const std::uint32_t second_index) noexcept {
        LinePoint first;
        LinePoint second;
        if (!read_point(first_index, first) ||
            !read_point(second_index, second))
            return false;
        const auto delta_x = second.x - first.x;
        const auto delta_y = second.y - first.y;
        const auto length = std::hypot(delta_x, delta_y);
        if (!std::isfinite(length) || length <= 0.0f) return false;
        const auto offset_x = delta_y * (half_width / length);
        const auto offset_y = -delta_x * (half_width / length);
        if (!std::isfinite(offset_x) || !std::isfinite(offset_y)) return false;

        // D950/DADC publish the independent four-vertex strip
        // A+o,A-o,B+o,B-o and terminate it at B-o. Convert that exact strip to
        // a host triangle list without joining adjacent source segments.
        const auto first_positive = make_vertex(
            first, first.x + offset_x, first.y + offset_y);
        const auto first_negative = make_vertex(
            first, first.x - offset_x, first.y - offset_y);
        const auto second_positive = make_vertex(
            second, second.x + offset_x, second.y + offset_y);
        const auto second_negative = make_vertex(
            second, second.x - offset_x, second.y - offset_y);
        vertices.push_back(first_positive);
        vertices.push_back(first_negative);
        vertices.push_back(second_positive);
        vertices.push_back(second_positive);
        vertices.push_back(first_negative);
        vertices.push_back(second_negative);
        return true;
    };

    if (mode == 0u) {
        // DD6E/DC88: r5 independent endpoint pairs.
        for (std::uint32_t segment = 0u; segment < segment_count; ++segment) {
            if (!append_segment(segment * 2u, segment * 2u + 1u))
                return graphics_abort(sonic_native_graphics_error_layout);
        }
    } else if (mode == 1u) {
        // E07C/DFAE: V0 is retained while each following point emits one
        // spoke V0->Vi. The guest emitter never mutates the retained scratch.
        for (std::uint32_t index = 1u; index < count; ++index) {
            if (!append_segment(0u, index))
                return graphics_abort(sonic_native_graphics_error_layout);
        }
    } else {
        // DF10/DE28: adjacent points with parity-swapped A/B endpoints. This
        // preserves the guest strip winding while each segment remains EOL.
        for (std::uint32_t index = 1u; index < count; ++index) {
            const auto first = (index & 1u) != 0u ? index - 1u : index;
            const auto second = (index & 1u) != 0u ? index : index - 1u;
            if (!append_segment(first, second))
                return graphics_abort(sonic_native_graphics_error_layout);
        }
    }

    const auto selector_class = static_cast<std::size_t>(mode) +
        (textured ? 3u : 0u) + (translucent ? 6u : 0u);
    if (!sonic_native_title_state
             .pretransformed_line_probe_reported[selector_class]) {
        sonic_native_title_state
            .pretransformed_line_probe_reported[selector_class] = true;
        std::cerr << "SONIC_NATIVE_PRETRANSFORMED_LINE selector=0x" << std::hex
                  << selector << " r4=0x" << context.cpu->r[4] << std::dec
                  << " count=" << count << " segments=" << segment_count
                  << " vertices=" << vertices.size() << '\n';
    }

    katana::runtime::NativePortDrawDiagnostics draw_diagnostics;
    draw_diagnostics.enabled = collect_graphics_diagnostics;
    draw_diagnostics.origin =
        katana::runtime::NativePortDrawOriginKind::Immediate;
    draw_diagnostics.intent =
        katana::runtime::NativePortDrawIntent::Interface;
    draw_diagnostics.origin_identity = sonic_native_opaque_identity(
        0x4C494E4544495350ull, context.cpu->active_instruction_pc,
        context.cpu->pr, context.cpu->r[4], selector);
    draw_diagnostics.origin_identity_bound = true;
    if (sonic_native_armed_graphics_identity_frame(context.frame_index)) {
        draw_diagnostics.model_identity = native_ui_coverage_identity(
            std::span<const katana::runtime::NativePortVertex>(
                vertices.data(), vertices.size()),
            std::span<const std::uint32_t>{}, texture,
            katana::runtime::NativePortPrimitiveTopology::TriangleList);
        draw_diagnostics.model_identity_bound = true;
    }
    draw_diagnostics.primitive_index =
        static_cast<std::uint32_t>(selector_class);
    draw_diagnostics.primitive_index_bound = true;
    if (textured)
        populate_native_texture_draw_diagnostics(
            texture_binding, resolved_texture_index, texture_diagnostics,
            draw_diagnostics);

    const auto result = draw_packet(
        context,
        (textured ? ninja_flag_use_texture : 0u) |
            (translucent ? ninja_flag_use_alpha : 0u),
        texture, katana::runtime::NativePortPrimitiveTopology::TriangleList,
        katana::runtime::NativePortViewportTarget::Ui, std::nullopt,
        std::nullopt, std::nullopt, std::nullopt, std::nullopt, {},
        std::nullopt, std::nullopt, {}, std::nullopt, false, std::nullopt,
        katana::runtime::NativePortDepthCoordinateMode::ReciprocalPositive,
        (translucent ? 0x02100002u : 0x00080002u) |
            (textured ? 0x8u : 0u),
        std::nullopt, draw_diagnostics);
    return finish_pretransformed_stream_draw(context, result);
}

[[nodiscard]] std::optional<katana::runtime::NativePortPrimitiveTopology>
sonic_native_filter_pretransformed_strip_vertices(
    std::vector<katana::runtime::NativePortVertex>& vertices) noexcept {
    const bool all_raster_valid = std::ranges::all_of(
        vertices, [](const auto& vertex) noexcept {
            return sonic_native_raster_position_valid(vertex.position);
        });
    if (all_raster_valid)
        return katana::runtime::NativePortPrimitiveTopology::TriangleStrip;

    // The SDK submits the source words unchanged. Flycast removes invalid
    // positions while building the strip index, so retain every unaffected
    // source triangle without joining the two sides of an invalid gap.
    try {
        const auto source_vertices = vertices;
        vertices.clear();
        for (std::size_t third = 2u; third < source_vertices.size(); ++third) {
            std::size_t first = third - 2u;
            std::size_t second = third - 1u;
            if (!sonic_native_raster_position_valid(
                    source_vertices[first].position) ||
                !sonic_native_raster_position_valid(
                    source_vertices[second].position) ||
                !sonic_native_raster_position_valid(
                    source_vertices[third].position))
                continue;
            if (3u > max_native_draw_vertices - vertices.size())
                return std::nullopt;
            // Triangle-strip winding alternates. Keep the vertex which
            // completed the source triangle last so flat/provoking-vertex
            // semantics survive conversion to an independent list triangle.
            if (((third - 2u) & 1u) != 0u) std::swap(first, second);
            vertices.push_back(source_vertices[first]);
            vertices.push_back(source_vertices[second]);
            vertices.push_back(source_vertices[third]);
        }
    } catch (...) {
        return std::nullopt;
    }
    return katana::runtime::NativePortPrimitiveTopology::TriangleList;
}

struct SonicNativeImmediateStateTransaction final {
    std::uint32_t renderer = 0u;
    std::uint32_t material_pointer = 0u;
    std::uint32_t cursor_owner = 0u;
    std::uint32_t arc1 = 0u;
    std::uint32_t advanced_cursor = 0u;
    std::uint32_t selected_cursor = 0u;
    std::array<std::uint32_t, 4u> packet{};
    std::array<std::uint32_t, 5u> cursors{};
    std::array<std::uint32_t, 5u> cursor_offsets{};
    std::optional<SonicNativeRegisteredTextureSelection> selection;
};

[[nodiscard]] std::optional<SonicNativeImmediateStateTransaction>
prepare_native_immediate_state(
    const SonicGuestReader& reader, const std::uint32_t arc1,
    const std::uint32_t source_count,
    const std::optional<SonicNativeRegisteredTextureSelection>& selection) noexcept {
    SonicNativeImmediateStateTransaction state;
    state.arc1 = arc1;
    state.selection = selection;
    std::uint32_t flags = 0u;
    if (source_count == 0u || source_count > max_native_draw_vertices ||
        !reader.u32(sonic_ninja_renderer_context_pointer, state.renderer) ||
        !reader.range(state.renderer, 0xA0u) ||
        !reader.range(sonic_ninja_packet_words, 36u) ||
        !reader.range(sonic_ninja_packet_region, 8u) ||
        !reader.u32(0x8C88FC10u, state.material_pointer) ||
        !reader.range(state.material_pointer, 4u) ||
        !reader.u32(0x8C88F56Cu, flags) ||
        !reader.u32(0x8C88FC14u, state.cursor_owner) ||
        !reader.range(state.cursor_owner, 20u)) return std::nullopt;
    state.cursor_offsets = (flags & 0x4000u) != 0u
        ? std::array<std::uint32_t, 5u>{0u, 16u, 8u, 4u, 12u}
        : std::array<std::uint32_t, 5u>{0u, 8u, 16u, 4u, 12u};
    for (std::uint32_t i = 0u; i < state.packet.size(); ++i)
        if (!reader.u32(state.renderer + 0x90u + i * 4u, state.packet[i]))
            return std::nullopt;
    for (std::uint32_t i = 0u; i < state.cursors.size(); ++i)
        if (!reader.u32(state.cursor_owner + state.cursor_offsets[i], state.cursors[i]))
            return std::nullopt;
    // 606948 edits the scratch packet; 605D4A later commits these same words.
    state.packet[0] = (state.packet[0] & 0xFDFFFF00u) | (arc1 & 0x020000FFu);
    state.packet[2] = (state.packet[2] & 0xFFE7FFFFu) | (arc1 & 0x00180000u);
    const bool shadow = (flags & 0x400u) != 0u ||
        ((flags & 0x1000u) != 0u && (arc1 & 0x02100000u) == 0u);
    state.packet[0] = shadow ? state.packet[0] | 0x80u : state.packet[0] & ~0x80u;
    if (selection) {
        std::uint32_t previous_key = 0u, previous_tag = 0u;
        if (!reader.u32(sonic_ninja_texture_descriptor_word0, previous_key) ||
            !reader.u32(sonic_ninja_texture_descriptor_word1, previous_tag))
            return std::nullopt;
        if (selection->words[0] != previous_key || selection->words[1] != previous_tag) {
            state.packet[2] = (state.packet[2] & ~0x3Fu) | (selection->words[2] & 0x3Fu);
            // Original selector returns -1 above this address, retaining TCW;
            // the enclosing draw ignores the return value and still submits.
            if ((selection->words[3] & 0x001FFFFFu) <= 0x00100000u)
                state.packet[3] = selection->words[3];
        }
    }
    state.selected_cursor = (arc1 & 0x02000000u) != 0u ? 1u : 0u;
    const auto cursor = state.cursors[state.selected_cursor];
    const auto bytes = (static_cast<std::uint64_t>(source_count) + 1u) * 32u;
    const auto end = static_cast<std::uint64_t>(cursor) + bytes;
    const bool ta_span = cursor >= sonic_ninja_ta_aperture_begin &&
        end <= sonic_ninja_ta_aperture_end;
    if ((!ta_span && !reader.range(cursor, static_cast<std::size_t>(bytes))) ||
        (cursor & 31u) != 0u || end > 0xFFFFFFFFull ||
        static_cast<std::uint64_t>(cursor & sonic_ninja_store_queue_mask) + bytes >
            static_cast<std::uint64_t>(sonic_ninja_store_queue_mask))
        return std::nullopt;
    state.advanced_cursor = static_cast<std::uint32_t>(end);
    return state;
}

[[nodiscard]] katana::runtime::NativePortHookResult
finish_native_immediate_state(
    katana::runtime::NativePortContext& context,
    const SonicNativeImmediateStateTransaction& state,
    const katana::runtime::NativePortHookResult result) noexcept {
    if (result.action != katana::runtime::NativePortHookAction::Return) return result;
    try {
        const auto write = [&](const std::uint32_t address, const std::uint32_t value) {
            katana::runtime::guest_write_u32(*context.cpu, address, value,
                                           katana::runtime::CodeWriteSource::Copy);
        };
        if (state.selection) {
            write(sonic_ninja_texture_descriptor_word0, state.selection->words[0]);
            write(sonic_ninja_texture_descriptor_word1, state.selection->words[1]);
        }
        write(state.material_pointer, state.arc1);
        for (std::uint32_t i = 0u; i < state.packet.size(); ++i) {
            write(sonic_ninja_packet_words + i * 4u, state.packet[i]);
            write(state.renderer + 0x90u + i * 4u, state.packet[i]);
        }
        for (std::uint32_t i = 0u; i < state.cursors.size(); ++i) {
            const auto cursor = i == state.selected_cursor ? state.advanced_cursor : state.cursors[i];
            write(sonic_ninja_packet_words + 16u + i * 4u, cursor);
            write(state.cursor_owner + state.cursor_offsets[i], cursor);
        }
        write(sonic_ninja_packet_region, state.cursors[state.selected_cursor] & 0xFC000000u);
        write(sonic_ninja_packet_destination_pointer, state.selected_cursor == 0u
            ? sonic_ninja_packet_destination_16 : sonic_ninja_packet_destination_32);
        if (state.selection) sonic_native_title_state.current_texture_index_bound = false;
        return finish_pretransformed_stream_draw(context, result);
    } catch (...) {
        return graphics_abort(sonic_native_graphics_error_range);
    }
}

#include "sonic_tutorial_prompt_adapter.inc"
#include "sonic_tutorial_page_adapter.inc"

[[nodiscard]] katana::runtime::NativePortHookResult
draw_pretransformed_stream(
    katana::runtime::NativePortContext& context,
    const bool textured) noexcept {
    SonicNativeScopedWork work{
        sonic_native_title_state.work_timing,
        SonicNativeWorkClass::Pretransformed};
    if (!valid_sonic_native_context(context))
        return graphics_abort(sonic_native_graphics_error_context);

    const auto count_signed = static_cast<std::int32_t>(context.cpu->r[5]);
    if (count_signed <= 0)
        return graphics_abort(sonic_native_graphics_error_layout);
    const auto count = static_cast<std::uint32_t>(count_signed);
    if (count > max_native_draw_vertices)
        return graphics_abort(sonic_native_graphics_error_budget);

    const auto source = context.cpu->r[4];
    const auto stride = textured ? 24u : 16u;
    std::size_t source_bytes = 0u;
    SonicGuestReader reader(*context.cpu);
    if (!reader.valid() || !checked_span_size(count, stride, source_bytes) ||
        !reader.range(source, source_bytes))
        return graphics_abort(sonic_native_graphics_error_range);

    const bool translucent =
        (textured ? context.cpu->r[7] : context.cpu->r[6]) != 0u;
    const bool collect_graphics_diagnostics =
        sonic_native_graphics_diagnostics_enabled();
    katana::runtime::NativePortTextureHandle texture;
    SonicNativeTextureResolutionDiagnostics texture_diagnostics;
    std::uint32_t texture_key = 0u;
    bool texture_bound = false;
    SonicNativeRegisteredTextureSelection selection;
    if (textured) {
        texture_key = context.cpu->r[6];
        if (!resolve_native_registered_texture(
                context, reader, texture_key, texture, texture_bound, selection,
                &texture_diagnostics)) {
            record_graphics_decision(
                context,
                SonicNativeGraphicsDecisionReason::UnresolvedTexture,
                source, 0u, 0u, texture_key);
            return graphics_abort(sonic_native_graphics_error_texture);
        }
    }

    const auto arc1 = (translucent ? 0x02100002u : 0x00080002u) |
                      (textured ? 0x8u : 0u);
    const auto transaction = prepare_native_immediate_state(reader, arc1, count,
        textured ? std::optional{selection} : std::nullopt);
    if (!transaction) return graphics_abort(sonic_native_graphics_error_range);
    auto& vertices = sonic_native_title_state.transient_vertices;
    vertices.clear();
    vertices.reserve(count);
    for (std::uint32_t index = 0u; index < count; ++index) {
        const auto address = source + index * stride;
        katana::runtime::NativePortVertex vertex;
        std::array<std::uint32_t, 3u> position_words{};
        std::uint32_t color = 0u;
        if (!reader.u32(address + 0u, position_words[0]) ||
            !reader.u32(address + 4u, position_words[1]) ||
            !reader.u32(address + 8u, position_words[2]))
            return graphics_abort(sonic_native_graphics_error_range);
        for (std::size_t axis = 0u; axis < position_words.size(); ++axis)
            vertex.position[axis] = std::bit_cast<float>(position_words[axis]);
        vertex.depth_coordinate = vertex.position[2];
        if (textured) {
            if (!reader.f32(address + 12u, vertex.texture_coordinate[0]) ||
                !reader.f32(address + 16u, vertex.texture_coordinate[1]) ||
                !reader.u32(address + 20u, color))
                return graphics_abort(sonic_native_graphics_error_range);
        } else if (!reader.u32(address + 12u, color)) {
            return graphics_abort(sonic_native_graphics_error_range);
        }
        vertex.color = argb_color(color);
        vertices.push_back(vertex);
    }

    const auto topology =
        sonic_native_filter_pretransformed_strip_vertices(vertices);
    if (!topology.has_value())
        return graphics_abort(sonic_native_graphics_error_budget);
    if (vertices.empty()) {
        return finish_native_immediate_state(
            context, *transaction,
            {katana::runtime::NativePortHookAction::Return, 0u, 0u});
    }

    const auto witness = textured ? 1u : 0u;
    if (!sonic_native_title_state.pretransformed_stream_reported[witness]) {
        sonic_native_title_state.pretransformed_stream_reported[witness] = true;
        std::cerr << "SONIC_NATIVE_PRETRANSFORMED_STREAM kind="
                  << (textured ? "textured" : "colored")
                  << " source=0x" << std::hex << source << std::dec
                  << " count=" << count
                  << " texture_key=0x" << std::hex << texture_key << std::dec
                  << " translucent=" << translucent << '\n';
    }

    const auto draw_state = sonic_render_state_from_words(
        transaction->packet[0], transaction->packet[1], transaction->packet[2]);
    if (!draw_state) return graphics_abort(sonic_native_graphics_error_model_draw);
    std::optional<katana::runtime::NativePortSamplerState> sampler_override;
    if (textured) {
        sampler_override = draw_state->sampler;
    }
    katana::runtime::NativePortDrawDiagnostics draw_diagnostics;
    draw_diagnostics.enabled = collect_graphics_diagnostics;
    draw_diagnostics.origin =
        katana::runtime::NativePortDrawOriginKind::Immediate;
    draw_diagnostics.intent =
        katana::runtime::NativePortDrawIntent::Interface;
    draw_diagnostics.origin_identity = sonic_native_opaque_identity(
        0x505245535452454Dull,
        context.cpu->active_instruction_pc,
        context.cpu->pr,
        source,
        texture_key);
    draw_diagnostics.origin_identity_bound = true;
    if (sonic_native_armed_graphics_identity_frame(
            context.frame_index)) {
        draw_diagnostics.model_identity = native_ui_coverage_identity(
            std::span<const katana::runtime::NativePortVertex>(
                vertices.data(), vertices.size()),
            std::span<const std::uint32_t>{}, texture, *topology);
        draw_diagnostics.model_identity_bound = true;
    }
    draw_diagnostics.primitive_index =
        (textured ? 2u : 0u) | (translucent ? 1u : 0u);
    draw_diagnostics.primitive_index_bound = true;
    if (textured && texture_bound) {
        auto& binding = draw_diagnostics.texture_binding;
        binding.resolver = texture_diagnostics.resolver;
        binding.expected_asset_identity =
            texture_diagnostics.expected_asset_identity;
        binding.expected_asset_bound =
            binding.expected_asset_identity != 0u;
        binding.resolved_asset_identity =
            texture_diagnostics.resolved_asset_identity;
        binding.resolved_asset_bound =
            binding.resolved_asset_identity != 0u;
    }
    if (textured && texture_bound) {
        sonic_native_apply_tutorial_prompt(context, reader, selection, source, count, texture, vertices);
        sonic_native_apply_tutorial_page(context, reader, selection, source, count, texture, vertices);
    }
    auto result = draw_packet(
        context,
        (texture_bound ? ninja_flag_use_texture : 0u) |
            (translucent ? ninja_flag_use_alpha : 0u),
        texture, *topology,
        katana::runtime::NativePortViewportTarget::Ui,
        std::nullopt,
        std::nullopt, std::nullopt, sampler_override, std::nullopt, {}, std::nullopt,
        std::nullopt, {}, std::nullopt, false, std::nullopt,
        katana::runtime::NativePortDepthCoordinateMode::ReciprocalPositive,
        arc1, draw_state, draw_diagnostics);
    return finish_native_immediate_state(context, *transaction, result);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_draw_pretransformed_colored(
    katana::runtime::NativePortContext& context) noexcept {
    return draw_pretransformed_stream(context, false);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_draw_pretransformed_textured(
    katana::runtime::NativePortContext& context) noexcept {
    return draw_pretransformed_stream(context, true);
}

[[nodiscard]] bool sound_test_trace_enabled_for_frame(
    const std::uint64_t frame_index) noexcept {
    static const bool enabled =
        sonic_native_diagnostic_enabled(
            "KATANA_SONIC_DIAGNOSTIC_SOUND_TEST_TRACE") ||
        sonic_native_diagnostic_enabled(
            "KATANA_SONIC_DIAGNOSTIC_TEXT_ROWS");
    static const auto start_frame = sonic_native_diagnostic_u32(
        "KATANA_SONIC_DIAGNOSTIC_SOUND_TEST_START_FRAME").value_or(0u);
    static const auto end_frame = sonic_native_diagnostic_u32(
        "KATANA_SONIC_DIAGNOSTIC_SOUND_TEST_END_FRAME").value_or(
            std::numeric_limits<std::uint32_t>::max());
    return enabled && frame_index >= start_frame && frame_index <= end_frame;
}

[[nodiscard]] std::optional<std::uint64_t>
reserve_sound_test_trace(const std::uint64_t signature) noexcept {
    static std::array<std::uint64_t, 512u> signatures{};
    static std::size_t signature_count = 0u;
    static std::uint64_t sequence = 0u;
    if (std::find(signatures.begin(),
                  signatures.begin() +
                      static_cast<std::ptrdiff_t>(signature_count),
                  signature) !=
        signatures.begin() +
            static_cast<std::ptrdiff_t>(signature_count))
        return std::nullopt;
    if (signature_count == signatures.size() ||
        sequence == std::numeric_limits<std::uint64_t>::max())
        return std::nullopt;
    signatures[signature_count++] = signature;
    return ++sequence;
}

enum class SonicNativeSpriteProfile : std::uint8_t {
    Standard,
    RouteCamera
};

// The boot-image identity in the retained manifest binds these callsites and
// their carrier contracts. In particular, CON_REGULAR alone is not HUD: the
// menu and the generic 08EDD8 formatter use it too. No coordinate heuristic.
[[nodiscard]] sonic::presentation::Role sonic_sprite_presentation_role(
    const katana::runtime::CpuState& cpu, const std::uint32_t carrier,
    const std::uint32_t texlist, const std::uint32_t frames,
    const SonicGuestReader& reader) noexcept {
    using sonic::presentation::Role;
    if (!sonic::presentation::settings().widescreen) return Role::Interface;
    std::optional<std::uint32_t> formatter_parent;
    if (sonic::big_hud::formatted_digits(cpu.pr,carrier,texlist,frames) &&
        reader.direct_ram() && cpu.r[15]<=0xFFFFFFFFu-8u) {
        std::uint32_t saved_pr=0u;
        // 08EDD8 saves PR, reserves eight bytes, and keeps SP unchanged at
        // its sprite call. This presentation-only ownership read must never
        // add a scalar/observer-visible guest access.
        if(reader.u32(cpu.r[15]+8u,saved_pr))formatter_parent=saved_pr;
    }
    if(sonic::big_hud::left_anchored(cpu.pr,cpu.r[15],carrier,texlist,frames,formatter_parent))
        return Role::HudLeft;
    constexpr std::array counters{0x8C08A332u,0x8C08A3B6u,
        0x8C089ECCu,0x8C089F00u,0x8C089F2Eu,0x8C089F58u,0x8C089F7Au};
    constexpr std::array clock{0x8C08A818u,0x8C08A838u,0x8C08A84Eu,
        0x8C08A86Eu,0x8C08A88Eu,0x8C08A8A4u,0x8C08A8ECu,0x8C08A98Cu,
        0x8C08A9A2u,0x8C08A9B8u,0x8C08A9CEu,0x8C08A9E4u,0x8C08A9FAu,
        0x8C08AA10u,0x8C08AA26u};
    constexpr std::array boss{0x8C0F205Au,0x8C0F2076u,0x8C0F209Au,
        0x8C0F20CEu,0x8C0F20E2u,0x8C0F211Au,0x8C0F214Eu};
    const auto has = [&](const auto& calls) {
        return std::ranges::find(calls,cpu.pr) != calls.end();
    };
    if (texlist == 0x8C1BF0E4u && frames == 0x8C1BF1C8u &&
        ((carrier == 0x8C1BF420u && has(counters)) ||
         (cpu.r[15] <= 0xFFFFFFFFu-20u && carrier == cpu.r[15]+20u && has(clock))))
        return Role::HudLeft;
    if (carrier == 0x8C5901D8u && texlist == 0x8C590158u && frames == 0x8C590160u && has(boss))
        return Role::HudRight;
    // Adventure Fields (stage IDs 26..34) select the animated ring carrier
    // at 08A30E, then share 08A32E/PR08A332 with the action-stage ring icon.
    // Keep that icon in the same left-anchored group as its counter digits.
    if (cpu.pr == 0x8C08A332u && carrier == 0x8C1BF4F4u &&
        texlist == 0x8C1C3250u && frames == 0x8C1BF4E0u)
        return Role::HudLeft;
    // EXTRA: both animated owners draw the animal row from x603 toward the
    // left. Bind the shared carrier and exact returns, not general sprite X.
    if (carrier == 0x8C195F44u && texlist == 0x8C195E10u && frames == 0x8C195E18u &&
        (cpu.pr == 0x8C026F4Cu || cpu.pr == 0x8C027070u || cpu.pr == 0x8C027298u))
        return Role::HudRight;
    // Alternative icons/counter reached directly by the original main HUD.
    // The second icon is a tail call and retains the outer owner's return.
    if ((cpu.pr == 0x8C0A1198u && carrier == 0x8C1C4490u && texlist == 0x8C1C3250u && frames == 0x8C1C447Cu) ||
        (cpu.pr == 0x8C0A110Eu && carrier == 0x8C15B110u && texlist == 0x8C1C44BCu && frames == 0x8C15B0FCu) ||
        (cpu.pr == 0x8C08A266u && carrier == 0x8C15B144u && texlist == 0x8C1C3250u && frames == 0x8C15B130u))
        return Role::HudLeft;
    return Role::Interface;
}

namespace {
// Process-local observation only: deliberately outside SonicNativeTitleState,
// so a development restore neither serializes nor resets this 64-record budget.
const bool sonic_native_sprite_binding_enabled = sonic_native_diagnostic_enabled(
    "KATANA_SONIC_DIAGNOSTIC_SPRITE_BINDING");
const std::uint64_t sonic_native_sprite_binding_start =
    sonic_native_diagnostic_u32(
        "KATANA_SONIC_DIAGNOSTIC_MODEL_STATE_START_FRAME").value_or(0u);
const std::uint64_t sonic_native_sprite_binding_end =
    sonic_native_diagnostic_u32(
        "KATANA_SONIC_DIAGNOSTIC_MODEL_STATE_END_FRAME")
        .value_or(std::numeric_limits<std::uint32_t>::max());

struct SonicNativeSpriteBindingRecord final {
    std::uint64_t frame = 0u;
    std::array<std::uint64_t, 39u> fields{};
};
std::array<SonicNativeSpriteBindingRecord, 64u> sonic_native_sprite_bindings{};
std::size_t sonic_native_sprite_binding_count = 0u;
std::size_t sonic_native_sprite_binding_emitted = 0u;

void record_sonic_native_sprite_binding(
    const katana::runtime::NativePortContext& context,
    const SonicNativeTextureBinding& binding,
    const std::uint32_t sprite, const bool sprite_2d,
    const SonicNativeSpriteProfile profile,
    const std::uint32_t texanim, const std::uint32_t animation_address,
    const std::uint32_t animation_index, const std::uint32_t ordinal,
    const std::uint32_t reason, const std::uint64_t texture = 0u) noexcept {
    if (sonic_native_sprite_binding_count == sonic_native_sprite_bindings.size() ||
        context.frame_index < sonic_native_sprite_binding_start ||
        context.frame_index > sonic_native_sprite_binding_end)
        return;
    SonicNativeSpriteBindingRecord record;
    record.frame = context.frame_index;
    auto& f = record.fields;
    f[0] = context.cpu->pc;
    f[1] = context.cpu->pr;
    f[2] = context.cpu->active_instruction_pc;
    f[3] = sprite;
    f[4] = sprite_2d;
    f[5] = static_cast<std::uint32_t>(profile);
    f[6] = binding.texlist_address;
    f[7] = binding.texname_address;
    f[8] = binding.texture_count;
    f[9] = texanim;
    f[10] = animation_address;
    f[11] = animation_index;
    f[12] = ordinal;
    f[13] = reason; // 1=ordinal>=count, 2=typed UnboundSentinel, 3=Bound.
    f[27] = std::numeric_limits<std::uint64_t>::max();
    f[31] = std::numeric_limits<std::uint64_t>::max();
    f[38] = texture;

    // Direct RAM only. No scalar/MMIO/watchpoint fallback, memory accounting,
    // resolver, catalog materialization, hashes, strings or allocation.
    const auto guard = context.cpu->memory.direct_linear_memory_guard(false);
    const auto read_word = [&](const std::uint64_t address,
                               std::uint32_t& value) noexcept {
        if (address > std::numeric_limits<std::uint32_t>::max()) return false;
        const auto guest_address = static_cast<std::uint32_t>(address);
        const auto segment = guest_address & 0xC0000000u;
        if (segment != 0u && segment != 0x80000000u) return false;
        const auto direct_address =
            katana::runtime::canonical_physical_address(guest_address) |
            0x80000000u;
        std::uint32_t offset = 0u;
        if (!katana::runtime::direct_linear_guard_offset(
                guard, direct_address, 4u, offset))
            return false;
        value = 0u;
        for (std::uint32_t byte = 0u; byte < 4u; ++byte)
            value |= static_cast<std::uint32_t>(guard.read_bytes[offset + byte])
                     << (byte * 8u);
        return true;
    };
    f[14] = static_cast<std::uint64_t>(binding.texname_address) +
            static_cast<std::uint64_t>(ordinal) * 12u + 8u;
    std::uint32_t texaddr = 0u;
    if (read_word(f[14], texaddr)) {
        f[15] = texaddr;
        f[16] = 1u;
        for (std::uint32_t index = 0u; index < 8u; ++index) {
            std::uint32_t word = 0u;
            if (read_word(static_cast<std::uint64_t>(texaddr) + index * 4u,
                          word)) {
                f[18u + index] = word;
                f[17] |= std::uint64_t{1u} << index;
            }
        }
    }

    // Stored owner geometry, not a new active-generation validation. In
    // particular do not call find_native_texlist_catalog_owner: its loaded-AOT
    // currency check can hash module bytes. Report this distinction explicitly.
    const SonicNativeTexlistCatalogBinding* exact = nullptr;
    const SonicNativeTexlistCatalogBinding* subview = nullptr;
    std::uint32_t base_ordinal = 0u;
    bool conflict = false;
    bool subview_conflict = false;
    const auto view_begin = static_cast<std::uint64_t>(
        sonic_native_backing_address(binding.texname_address));
    const auto view_end = view_begin +
                          static_cast<std::uint64_t>(binding.texture_count) * 12u;
    if (binding.valid && binding.texture_count != 0u) {
        for (const auto& candidate : sonic_native_title_state.texlist_catalog_bindings) {
            if (sonic_native_same_backing_address(
                    candidate.texlist_address, binding.texlist_address)) {
                if (exact != nullptr ||
                    candidate.texture_count != binding.texture_count ||
                    !sonic_native_same_backing_address(
                        candidate.texname_address, binding.texname_address)) {
                    conflict = true;
                    break;
                }
                exact = &candidate;
                continue;
            }
            const auto begin = static_cast<std::uint64_t>(
                sonic_native_backing_address(candidate.texname_address));
            const auto end = begin +
                static_cast<std::uint64_t>(candidate.texture_count) * 12u;
            if (view_begin < begin || view_end > end ||
                (view_begin - begin) % 12u != 0u)
                continue;
            if (subview != nullptr) {
                subview_conflict = true;
                continue;
            }
            subview = &candidate;
            base_ordinal = static_cast<std::uint32_t>((view_begin - begin) / 12u);
        }
    }
    const auto kind = conflict
        ? SonicNativeTexlistOwnerMatchKind::Conflict
        : exact != nullptr ? SonicNativeTexlistOwnerMatchKind::Exact
        : subview_conflict ? SonicNativeTexlistOwnerMatchKind::Conflict
        : subview != nullptr ? SonicNativeTexlistOwnerMatchKind::Subview
                             : SonicNativeTexlistOwnerMatchKind::None;
    f[26] = static_cast<std::uint32_t>(kind);
    const auto* owner = kind == SonicNativeTexlistOwnerMatchKind::Exact ? exact
        : kind == SonicNativeTexlistOwnerMatchKind::Subview ? subview : nullptr;
    if (owner != nullptr) {
        if (exact != nullptr) base_ordinal = 0u;
        f[27] = owner->catalog_index;
        f[28] = owner->texture_set_references;
        f[29] = owner->named_archive_binding;
        f[30] = owner->loaded_aot_module_binding;
        f[32] = owner->texture_set_owner;
        f[33] = owner->named_archive_owner;
        f[35] = base_ordinal;
        f[37] = owner->descriptor_transition_authority.transition_epoch;
        const auto owner_ordinal = static_cast<std::uint64_t>(base_ordinal) + ordinal;
        if (owner_ordinal < owner->guest_descriptors.size()) {
            f[31] = owner->guest_descriptors[owner_ordinal].transition_epoch;
            f[36] = 1u;
        }
        for (const auto& resident : sonic_native_title_state.materialized_texture_archives) {
            if (resident.catalog_index == owner->catalog_index) {
                f[34] = resident.texture_set_references;
                break;
            }
        }
    }
    for (std::size_t index = 0u; index < sonic_native_sprite_binding_count; ++index) {
        if (sonic_native_sprite_bindings[index].fields == f) return;
    }
    sonic_native_sprite_bindings[sonic_native_sprite_binding_count++] = record;
}

void flush_sonic_native_sprite_bindings() noexcept {
    static constexpr std::array<const char*, 39u> names{
        "pc", "pr", "active_pc", "sprite", "sprite_2d", "profile",
        "texlist", "texname", "count", "texanim", "animation_address",
        "animation_index", "ordinal", "reason", "texaddr_address", "texaddr",
        "texaddr_valid", "descriptor_validmask", "descriptor0", "descriptor1",
        "descriptor2", "descriptor3", "descriptor4", "descriptor5",
        "descriptor6", "descriptor7", "stored_owner_match", "catalog_index",
        "owner_refs", "named", "loaded", "descriptor_epoch", "set_owner",
        "named_owner", "resident_refs", "owner_base_ordinal",
        "descriptor_epoch_valid", "authority_epoch", "texture"};
    try {
        while (sonic_native_sprite_binding_emitted < sonic_native_sprite_binding_count) {
            const auto index = sonic_native_sprite_binding_emitted++;
            const auto& record = sonic_native_sprite_bindings[index];
            std::cerr << "SONIC_NATIVE_SPRITE_BINDING version=1 owner_current_validated=0"
                      << " seq=" << std::dec << index << " frame=" << record.frame;
            for (std::size_t field = 0u; field < names.size(); ++field)
                std::cerr << ' ' << names[field] << '=' << record.fields[field];
            std::cerr << '\n';
        }
    } catch (...) {
        // An observation failure cannot change guest execution or shutdown.
    }
}
} // namespace

// These wrappers use the SDK's RAM transaction (605CEC -> 6069C8 ->
// 606948 -> 605D4A). The final leaf commits the edited packet template; it
// does not restore a separate pre-call snapshot. Keep the persistent template
// distinct from the opaque header's draw-only One/Zero blend override.
struct SonicNativeSpriteStateTransaction final {
    std::uint32_t renderer = 0u;
    std::uint32_t material_word = 0u;
    std::uint32_t texlist = 0u;
    std::uint32_t ordinal = 0u;
    std::uint32_t descriptor_key = 0u;
    std::uint32_t descriptor_tag = 0u;
    std::uint32_t arc1 = 0u;
    std::array<std::uint32_t, 4u> packet{};
    std::uint32_t cursor_owner = 0u;
    std::array<std::uint32_t, 5u> cursor{};
    std::array<std::uint32_t, 5u> cursor_owner_offsets{};
};

// 605CEC snapshots these five physical list cursors after the four packet
// words. Bit 0x4000 swaps only the two middle translucent-list fields; 605D4A
// applies the exact inverse mapping.
[[nodiscard]] constexpr std::array<std::uint32_t, 5u>
sonic_sprite_cursor_owner_offsets(const bool permuted) noexcept {
    return permuted
        ? std::array<std::uint32_t, 5u>{0u, 16u, 8u, 4u, 12u}
        : std::array<std::uint32_t, 5u>{0u, 8u, 16u, 4u, 12u};
}

// The two-triangle PAL clip helper duplicates the shared edge. These are TA
// packet counts, not host triangle-strip vertex counts.
constexpr std::array<std::uint8_t, 16u> sonic_sprite_near_clip_vertices{
    4u, 7u, 8u, 7u, 8u, 7u, 6u, 3u,
    7u, 8u, 7u, 6u, 7u, 6u, 3u, 0u};

[[nodiscard]] constexpr std::size_t sonic_sprite_cursor_index(
    const std::uint32_t arc1) noexcept {
    return (arc1 & 0x02000000u) != 0u ? 1u : 0u;
}

[[nodiscard]] constexpr std::optional<std::uint32_t>
sonic_sprite_advanced_cursor(const std::uint32_t cursor,
                             const std::uint32_t vertices,
                             const bool mapped_ram_span = false) noexcept {
    constexpr auto header_bytes = sonic_ninja_packet_bytes;
    constexpr auto vertex_bytes = sonic_ninja_packet_bytes;
    if (vertices == 0u || vertices > 8u) return std::nullopt;
    const auto bytes = static_cast<std::uint64_t>(header_bytes) +
                       static_cast<std::uint64_t>(vertices) * vertex_bytes;
    // The same SDK header supports both direct TA output and buffered lists
    // in main RAM (including P2). 6063F0 derives QACR from the actual cursor;
    // it does not force area 0x10. The RAM branch requires a complete current
    // SonicGuestReader range proof, never just a plausible pointer prefix.
    const bool ta_span = cursor >= sonic_ninja_ta_aperture_begin &&
        static_cast<std::uint64_t>(cursor) + bytes <= sonic_ninja_ta_aperture_end;
    if ((!mapped_ram_span && !ta_span) ||
        (cursor & (sonic_ninja_packet_bytes - 1u)) != 0u ||
        static_cast<std::uint64_t>(cursor) + bytes > 0xFFFFFFFFull ||
        static_cast<std::uint64_t>(cursor & sonic_ninja_store_queue_mask) + bytes >
            static_cast<std::uint64_t>(sonic_ninja_store_queue_mask))
        return std::nullopt;
    return cursor + static_cast<std::uint32_t>(bytes);
}

[[nodiscard]] constexpr std::optional<std::uint32_t>
sonic_sprite_committed_cursor(const std::uint32_t cursor,
                              const std::uint32_t vertices) noexcept {
    if (vertices == 0u) return cursor;
    return sonic_sprite_advanced_cursor(cursor, vertices);
}

static_assert(sonic_sprite_cursor_owner_offsets(false) ==
              std::array<std::uint32_t, 5u>{0u, 8u, 16u, 4u, 12u});
static_assert(sonic_sprite_cursor_owner_offsets(true) ==
              std::array<std::uint32_t, 5u>{0u, 16u, 8u, 4u, 12u});
static_assert(sonic_sprite_near_clip_vertices ==
              std::array<std::uint8_t, 16u>{
                  4u, 7u, 8u, 7u, 8u, 7u, 6u, 3u,
                  7u, 8u, 7u, 6u, 7u, 6u, 3u, 0u});
static_assert(sonic_sprite_cursor_index(0x00080028u) == 0u);
static_assert(sonic_sprite_cursor_index(0x02100028u) == 1u);
static_assert(sonic_sprite_advanced_cursor(0x10000000u, 4u) ==
              0x100000A0u);
static_assert(!sonic_sprite_advanced_cursor(0x10000000u, 0u).has_value());
static_assert(sonic_sprite_committed_cursor(0x10000000u, 0u) ==
              0x10000000u);
static_assert(sonic_sprite_committed_cursor(0xDEADBEEFu, 0u) ==
              0xDEADBEEFu);
static_assert(sonic_sprite_committed_cursor(0x10000000u, 4u) ==
              0x100000A0u);
static_assert(sonic_sprite_advanced_cursor(0x107FFF60u, 4u) ==
              0x10800000u);
static_assert(!sonic_sprite_advanced_cursor(0x107FFF80u, 4u).has_value());
static_assert(!sonic_sprite_advanced_cursor(0x10000001u, 0u).has_value());
static_assert(!sonic_sprite_advanced_cursor(0xACF5FD00u, 4u).has_value());
static_assert(sonic_sprite_advanced_cursor(0xACF5FD00u, 4u, true) ==
              0xACF5FDA0u);
static_assert(!sonic_sprite_advanced_cursor(0xACF5FD01u, 4u, true).has_value());
static_assert(!sonic_sprite_advanced_cursor(0xFFFFFFE0u, 4u, true).has_value());
static_assert([] {
    constexpr std::array<std::uint32_t, 16u> expected_bytes{
        160u, 256u, 288u, 256u, 288u, 256u, 224u, 128u,
        256u, 288u, 256u, 224u, 256u, 224u, 128u, 0u};
    for (std::size_t mask = 0u; mask < expected_bytes.size(); ++mask) {
        if (sonic_sprite_near_clip_vertices[mask] == 0u) {
            if (expected_bytes[mask] != 0u) return false;
            continue;
        }
        const auto end = sonic_sprite_advanced_cursor(
            0x10000000u, sonic_sprite_near_clip_vertices[mask]);
        if (!end.has_value() || *end - 0x10000000u != expected_bytes[mask])
            return false;
    }
    return true;
}());

[[nodiscard]] std::optional<SonicNativeSpriteStateTransaction>
prepare_native_sprite_state(const SonicGuestReader& reader,
                            const SonicNativeTextureBinding& binding,
                            const std::uint32_t ordinal,
                            const std::uint32_t arc1,
                            const bool capture_cursor_state = true) noexcept {
    SonicNativeSpriteStateTransaction state;
    state.texlist = binding.texlist_address;
    state.ordinal = ordinal;
    state.arc1 = arc1;
    std::uint32_t material_pointer = 0u;
    std::uint32_t descriptor = 0u;
    std::uint32_t previous_key = 0u, previous_tag = 0u;
    std::uint32_t flags = 0u;
    if (!binding.valid || ordinal >= binding.texture_count ||
        !reader.u32(sonic_ninja_renderer_context_pointer, state.renderer) ||
        !reader.range(state.renderer, 0xA0u) ||
        !reader.range(sonic_ninja_packet_words, 36u) ||
        !reader.range(sonic_ninja_packet_region, 8u) ||
        !reader.u32(0x8C88FC10u, material_pointer) ||
        !reader.range(material_pointer, 4u) ||
        !reader.u32(0x8C88F56Cu, flags) ||
        !reader.u32(binding.texname_address + ordinal * 12u + 8u, descriptor) ||
        !reader.range(descriptor, 16u) ||
        !reader.u32(sonic_ninja_texture_descriptor_word0, previous_key) ||
        !reader.u32(sonic_ninja_texture_descriptor_word1, previous_tag) ||
        !reader.u32(descriptor, state.descriptor_key) ||
        !reader.u32(descriptor + 4u, state.descriptor_tag))
        return std::nullopt;
    if (capture_cursor_state &&
        (!reader.u32(0x8C88FC14u, state.cursor_owner) ||
         !reader.range(state.cursor_owner, 20u)))
        return std::nullopt;
    state.material_word = material_pointer;
    if (capture_cursor_state)
        state.cursor_owner_offsets =
            sonic_sprite_cursor_owner_offsets((flags & 0x4000u) != 0u);
    for (std::uint32_t word = 0u; word < state.packet.size(); ++word) {
        if (!reader.u32(state.renderer + 0x90u + word * 4u,
                        state.packet[word])) return std::nullopt;
    }
    if (capture_cursor_state) {
        for (std::uint32_t word = 0u; word < state.cursor.size(); ++word) {
            if (!reader.u32(
                    state.cursor_owner + state.cursor_owner_offsets[word],
                    state.cursor[word]))
                return std::nullopt;
        }
    }
    // 6069C8 selects this TEXNAME's descriptor directly, including a released
    // descriptor. Only the separate 606AA6 key selector searches the registry.
    // The key/tag cache suppresses TSP/TCW updates when both words match.
    if (state.descriptor_key != previous_key ||
        state.descriptor_tag != previous_tag) {
        std::uint32_t tsp = 0u, tcw = 0u;
        if (!reader.u32(descriptor + 8u, tsp) ||
            !reader.u32(descriptor + 12u, tcw)) return std::nullopt;
        state.packet[2] = (state.packet[2] & ~0x3Fu) | (tsp & 0x3Fu);
        // cmp/hi -> failure return for an address ABOVE 0x100000; the
        // wrappers ignore that return but the old TCW remains untouched.
        if ((tcw & 0x001FFFFFu) <= 0x00100000u) state.packet[3] = tcw;
    }
    state.packet[0] = (state.packet[0] & 0xFDFFFF00u) |
                      (arc1 & 0x020000FFu);
    state.packet[2] = (state.packet[2] & 0xFFE7FFFFu) |
                      (arc1 & 0x00180000u);
    const bool shadow = (flags & 0x400u) != 0u ||
        ((flags & 0x1000u) != 0u && (arc1 & 0x02100000u) == 0u);
    state.packet[0] = shadow ? state.packet[0] | 0x80u
                             : state.packet[0] & ~0x80u;
    return state;
}

[[nodiscard]] katana::runtime::NativePortHookResult
finish_native_culled_route_sprite_state(
    katana::runtime::NativePortContext& context,
    const SonicGuestReader& reader) noexcept {
    SonicNativeSpriteStateTransaction state;
    std::uint32_t flags = 0u;
    if (!reader.u32(sonic_ninja_renderer_context_pointer, state.renderer) ||
        !reader.range(state.renderer, 0xA0u) ||
        !reader.range(sonic_ninja_packet_words, 36u) ||
        !reader.u32(0x8C88FC14u, state.cursor_owner) ||
        !reader.range(state.cursor_owner, 20u) ||
        !reader.u32(0x8C88F56Cu, flags))
        return graphics_abort(sonic_native_graphics_error_range);
    state.cursor_owner_offsets =
        sonic_sprite_cursor_owner_offsets((flags & 0x4000u) != 0u);
    for (std::uint32_t word = 0u; word < state.packet.size(); ++word) {
        if (!reader.u32(state.renderer + 0x90u + word * 4u,
                        state.packet[word]))
            return graphics_abort(sonic_native_graphics_error_range);
    }
    for (std::uint32_t word = 0u; word < state.cursor.size(); ++word) {
        if (!reader.u32(state.cursor_owner + state.cursor_owner_offsets[word],
                        state.cursor[word]))
            return graphics_abort(sonic_native_graphics_error_range);
    }
    try {
        auto& cpu = *context.cpu;
        const auto write = [&](const std::uint32_t address,
                               const std::uint32_t value) {
            katana::runtime::guest_write_u32(
                cpu, address, value, katana::runtime::CodeWriteSource::Copy);
        };
        for (std::uint32_t word = 0u; word < state.packet.size(); ++word) {
            write(sonic_ninja_packet_words + word * 4u, state.packet[word]);
            write(state.renderer + 0x90u + word * 4u, state.packet[word]);
        }
        for (std::uint32_t word = 0u; word < state.cursor.size(); ++word) {
            write(sonic_ninja_packet_words + 16u + word * 4u,
                  state.cursor[word]);
            write(state.cursor_owner + state.cursor_owner_offsets[word],
                  state.cursor[word]);
        }
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (...) {
        return graphics_abort(sonic_native_graphics_error_range);
    }
}

[[nodiscard]] katana::runtime::NativePortHookResult finish_native_sprite_state(
    katana::runtime::NativePortContext& context,
    const SonicGuestReader& reader,
    const SonicNativeSpriteStateTransaction& state,
    const katana::runtime::NativePortHookResult result,
    const bool header_selected,
    const std::uint32_t ta_vertex_count) noexcept {
    if (result.action != katana::runtime::NativePortHookAction::Return)
        return result;
    if ((!header_selected && ta_vertex_count != 0u) || ta_vertex_count > 8u)
        return graphics_abort(sonic_native_graphics_error_layout);
    const auto selected_cursor = sonic_sprite_cursor_index(state.arc1);
    auto committed_cursor = state.cursor;
    if (header_selected) {
        const auto advanced_cursor = sonic_sprite_advanced_cursor(
            state.cursor[selected_cursor], ta_vertex_count,
            reader.range(state.cursor[selected_cursor],
                         (1u + ta_vertex_count) * sonic_ninja_packet_bytes));
        if (!advanced_cursor.has_value())
            return graphics_abort(sonic_native_graphics_error_range);
        committed_cursor[selected_cursor] = *advanced_cursor;
    }
    try {
        auto& cpu = *context.cpu;
        const auto write = [&](const std::uint32_t address,
                               const std::uint32_t value) {
            katana::runtime::guest_write_u32(
                cpu, address, value, katana::runtime::CodeWriteSource::Copy);
        };
        write(sonic_ninja_texture_list_state, state.texlist);
        write(sonic_ninja_texture_descriptor_word0, state.descriptor_key);
        write(sonic_ninja_texture_descriptor_word1, state.descriptor_tag);
        write(state.material_word, state.arc1);
        for (std::uint32_t word = 0u; word < state.packet.size(); ++word) {
            write(sonic_ninja_packet_words + word * 4u, state.packet[word]);
            write(state.renderer + 0x90u + word * 4u, state.packet[word]);
        }
        for (std::uint32_t word = 0u; word < committed_cursor.size(); ++word) {
            write(sonic_ninja_packet_words + 16u + word * 4u,
                  committed_cursor[word]);
            write(state.cursor_owner + state.cursor_owner_offsets[word],
                  committed_cursor[word]);
        }
        if (header_selected) {
            const auto destination_word = selected_cursor == 0u
                                              ? sonic_ninja_packet_destination_16
                                              : sonic_ninja_packet_destination_32;
            write(sonic_ninja_packet_region,
                  state.cursor[selected_cursor] & 0xFC000000u);
            write(sonic_ninja_packet_destination_pointer, destination_word);
        }
        sonic_native_title_state.texture_binding = {};
        sonic_native_title_state.texture_binding.texlist_address = state.texlist;
        sonic_native_title_state.current_texture_index = state.ordinal;
        sonic_native_title_state.current_texture_index_bound = true;
        note_texlist_bind_diagnostic(context, state.texlist);
        note_texture_binding_writer(context,
            katana::runtime::NativePortTextureBindingWriterKind::TextureNumberSelect,
            state.texlist);
        return finish_pretransformed_stream_draw(context, result);
    } catch (...) {
        return graphics_abort(sonic_native_graphics_error_range);
    }
}

[[nodiscard]] constexpr std::uint32_t sonic_ta_float_color_byte(
    const std::uint32_t bits) noexcept {
    return sonic::color::ta_float_color_byte(bits);
}

[[nodiscard]] katana::runtime::NativePortHookResult draw_sprite_family(
    katana::runtime::NativePortContext& context,
    const bool sprite_2d,
    const SonicNativeSpriteProfile profile =
        SonicNativeSpriteProfile::Standard) noexcept {
    SonicNativeScopedWork work{
        sonic_native_title_state.work_timing,
        SonicNativeWorkClass::Sprite};
    if (!valid_sonic_native_context(context))
        return graphics_abort(sonic_native_graphics_error_context);
    SonicGuestReader reader(*context.cpu);
    if (!reader.valid())
        return graphics_abort(sonic_native_graphics_error_range);

    const bool route_camera_profile =
        profile == SonicNativeSpriteProfile::RouteCamera;
    if (route_camera_profile) {
        // The identity-bound route owner 0x8C09E6B8 performs this gate before
        // saving registers or consuming any arguments. Preserve that exact
        // no-draw return rather than validating otherwise dormant inputs.
        std::uint32_t disabled = 0u;
        if (!reader.u32(sonic_route_sprite_disable, disabled))
            return graphics_abort(sonic_native_graphics_error_range);
        if (disabled != 0u)
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    }
    const auto animation_index_signed =
        static_cast<std::int32_t>(context.cpu->r[5]);
    if (animation_index_signed < 0 ||
        static_cast<std::uint32_t>(animation_index_signed) >=
            max_native_texture_names)
        return graphics_abort(sonic_native_graphics_error_budget);
    const auto animation_index =
        static_cast<std::uint32_t>(animation_index_signed);
    float source_priority = 0.0f;
    if (sprite_2d) {
        source_priority = std::bit_cast<float>(context.cpu->fr[4]);
        if (!std::isfinite(source_priority))
            return graphics_abort(sonic_native_graphics_error_layout);
    }
    if (!reader.valid() || !reader.range(context.cpu->r[4], 32u))
        return graphics_abort(sonic_native_graphics_error_range);
    const auto address = context.cpu->r[4];
    float x = 0.0f;
    float y = 0.0f;
    float z = 0.0f;
    float scale_x = 0.0f;
    float scale_y = 0.0f;
    std::uint32_t angle = 0u;
    std::uint32_t texlist = 0u;
    std::uint32_t texanim = 0u;
    std::uint32_t sprite_2d_unused_z = 0u;
    // The PAL NINJA 2D owner at 0x8C63EDF4 obtains depth from FR4 and never
    // consumes NJS_SPRITE::z. Real title records can therefore retain a NaN
    // bit pattern in that dormant word. Preserve the full mapped-range read,
    // but do not impose a floating-point contract on an unused field. The 3D
    // family does consume z and remains finite/fail-closed through f32().
    const bool valid_z = sprite_2d
                             ? reader.u32(address + 8u,
                                          sprite_2d_unused_z)
                             : reader.f32(address + 8u, z);
    if (!reader.f32(address + 0u, x) || !reader.f32(address + 4u, y) ||
        !valid_z ||
        !reader.f32(address + 12u, scale_x) ||
        !reader.f32(address + 16u, scale_y) ||
        !reader.u32(address + 20u, angle) ||
        !reader.u32(address + 24u, texlist) ||
        !reader.u32(address + 28u, texanim))
        return graphics_abort(sonic_native_graphics_error_range);

    std::uint32_t animation_address = 0u;
    if (!checked_guest_address(texanim, animation_index, 20u,
                               animation_address) ||
        !reader.range(animation_address, 20u))
        return graphics_abort(sonic_native_graphics_error_range);
    std::int16_t width = 0;
    std::int16_t height = 0;
    std::int16_t center_x = 0;
    std::int16_t center_y = 0;
    std::int16_t u0 = 0;
    std::int16_t v0 = 0;
    std::int16_t u1 = 0;
    std::int16_t v1 = 0;
    std::uint16_t texture_index = 0u;
    if (!reader.i16(animation_address + 0u, width) ||
        !reader.i16(animation_address + 2u, height) ||
        !reader.i16(animation_address + 4u, center_x) ||
        !reader.i16(animation_address + 6u, center_y) ||
        !reader.i16(animation_address + 8u, u0) ||
        !reader.i16(animation_address + 10u, v0) ||
        !reader.i16(animation_address + 12u, u1) ||
        !reader.i16(animation_address + 14u, v1) ||
        !reader.u16(animation_address + 16u, texture_index))
        return graphics_abort(sonic_native_graphics_error_layout);

    const auto attribute = context.cpu->r[6];
    if ((attribute & (1u << 2u)) != 0u) std::swap(u0, u1);
    if ((attribute & (1u << 3u)) != 0u) std::swap(v0, v1);
    // The route-owned screen-scaled variant at 0x8C09E7C0 loads sprite +12
    // for both axes. The standard NINJA 0x8C63EF78 variant loads +12/+16.
    // Keep this as an explicit family profile; the object-space variants are
    // instruction-equivalent and retain the ordinary independent scales.
    const auto vertical_sprite_scale =
        route_camera_profile && !sprite_2d &&
                (attribute & (1u << 4u)) != 0u
            ? scale_x
            : scale_y;
    const float left = -static_cast<float>(center_x) * scale_x;
    const float right = static_cast<float>(width - center_x) * scale_x;
    const float top =
        -static_cast<float>(center_y) * vertical_sprite_scale;
    const float bottom =
        static_cast<float>(height - center_y) * vertical_sprite_scale;
    const std::array<std::array<float, 2u>, 4u> positions{{
        {left, top}, {left, bottom}, {right, top}, {right, bottom}}};
    const std::array<std::array<float, 2u>, 4u> coordinates{{
        {static_cast<float>(u0) / 256.0f, static_cast<float>(v0) / 256.0f},
        {static_cast<float>(u0) / 256.0f, static_cast<float>(v1) / 256.0f},
        {static_cast<float>(u1) / 256.0f, static_cast<float>(v0) / 256.0f},
        {static_cast<float>(u1) / 256.0f, static_cast<float>(v1) / 256.0f}}};
    float cosine = 1.0f;
    float sine = 0.0f;
    if ((attribute & 1u) != 0u) {
        // The identity-bound NINJA sprite owner reaches its FSCA/rotation
        // block only when attribute bit 0 is set. The title is free to keep
        // changing the stored angle while requesting an axis-aligned sprite;
        // applying that dormant value unconditionally turns tiled screens
        // into giant off-screen wedges.
        const auto angle_radians =
            static_cast<float>(angle & 0xFFFFu) *
            (2.0f * std::numbers::pi_v<float> / 65'536.0f);
        cosine = std::cos(angle_radians);
        sine = std::sin(angle_radians);
    }
    std::array<std::array<float, 3u>, 4u> output_positions{};
    std::array<float, 4u> output_depths{};
    std::optional<katana::runtime::NativePortMatrix4x4> sprite_transform;
    auto sprite_depth_mapping =
        katana::runtime::NativePortDepthCoordinateMode::ReciprocalPositive;
    bool sprite_visible = true;
    std::uint32_t sdk_ta_vertex_count = 4u;

    if (sprite_2d) {
        const auto negated_priority = -source_priority;
        const auto depth = negated_priority > 1.0f
                               ? 1.0f / negated_priority
                               : 1.0f;
        for (std::size_t index = 0u; index < positions.size(); ++index) {
            output_positions[index] = {
                x + positions[index][0] * cosine -
                    positions[index][1] * sine,
                y + positions[index][0] * sine +
                    positions[index][1] * cosine,
                depth};
            output_depths[index] = depth;
        }
    } else {
        // The exact 0x8C63EEB4 wrapper selects two NINJA Sprite3D geometry
        // owners with attribute bit 4. Both consume the same NJS_SPRITE and
        // NJS_TEXANIM records; they differ only in where the quad size is
        // applied. Keep that distinction as a data-driven provider variant,
        // rather than treating Sprite3D as the 2D screen-space owner.
        // Both disassembly-proven Sprite3D families consume the NINJA
        // projection globals directly. They are not the separate GBR-based
        // transform-owner parameter record used by 0x8C037294.
        float common_scale = 0.0f;
        float projection_center_x = 0.0f;
        float projection_center_y = 0.0f;
        float near_plane = 0.0f;
        float far_plane = 0.0f;
        float horizontal_factor = 0.0f;
        float vertical_factor = 0.0f;
        if (!reader.f32(sonic_ninja_projection_common_scale,
                        common_scale) ||
            !reader.f32(sonic_ninja_projection_center_x,
                        projection_center_x) ||
            !reader.f32(sonic_ninja_projection_center_y,
                        projection_center_y) ||
            !reader.f32(sonic_ninja_projection_near, near_plane) ||
            !reader.f32(sonic_ninja_projection_far, far_plane) ||
            !reader.f32(sonic_ninja_projection_horizontal_factor,
                        horizontal_factor) ||
            !reader.f32(sonic_ninja_projection_vertical_factor,
                        vertical_factor) ||
            !std::isfinite(common_scale) ||
            !std::isfinite(projection_center_x) ||
            !std::isfinite(projection_center_y) ||
            !std::isfinite(near_plane) || !std::isfinite(far_plane) ||
            !std::isfinite(horizontal_factor) ||
            !std::isfinite(vertical_factor) ||
            near_plane <= 0.0f || far_plane < near_plane)
            return graphics_abort(sonic_native_graphics_error_layout);

        const auto view = sonic_normal_transform(*context.cpu);
        const std::array<float, 5u> clip_projection{
            projection_center_x,
            projection_center_y,
            common_scale * horizontal_factor,
            common_scale * vertical_factor,
            near_plane};
        const auto clip_transform =
            sonic_model_clip_transform(view, clip_projection);
        if (!clip_transform.has_value())
            return graphics_abort(sonic_native_graphics_error_model_transform);

        const auto transform_camera =
            [&view](const std::array<float, 3u>& point)
                -> std::optional<std::array<float, 3u>> {
            std::array<float, 3u> result{};
            for (std::size_t column = 0u; column < result.size(); ++column) {
                result[column] =
                    point[0u] * view.values[column] +
                    point[1u] * view.values[4u + column] +
                    point[2u] * view.values[8u + column] +
                    view.values[12u + column];
            }
            if (!std::ranges::all_of(result, [](const float value) {
                    return std::isfinite(value);
                }))
                return std::nullopt;
            return result;
        };

        if ((attribute & (1u << 4u)) != 0u) {
            // Screen-scaled Sprite3D (0x8C63EF78): transform only the sprite
            // origin through XMTRX, then scale its already rotated 2D extents
            // by the exact NINJA perspective factor. This keeps billboards a
            // constant camera-facing quad while preserving the guest depth.
            auto center =
                transform_camera(std::array<float, 3u>{x, y, z});
            if (!center.has_value())
                return graphics_abort(sonic_native_graphics_error_layout);
            // Both PAL screen-scaled owners project the sprite origin and
            // extents with the reciprocal produced immediately after XMTRX.
            // The route owner then adds its private Z offset only for the
            // near/far decision and the emitted depth coordinate; it does
            // not feed that offset back into X/Y projection.
            const auto projection_reciprocal_depth =
                1.0f / (*center)[2u];
            auto output_reciprocal_depth =
                projection_reciprocal_depth;
            if (route_camera_profile) {
                // 0x8C09E7C0 alone adds this mutable route depth offset after
                // XMTRX and its projection reciprocal, but before the
                // near/far tests. Its object-space sibling and the standard
                // NINJA family do not consume the value.
                float depth_offset = 0.0f;
                if (!reader.f32(sonic_route_sprite_depth_offset,
                                depth_offset) ||
                    !std::isfinite(depth_offset))
                    return graphics_abort(sonic_native_graphics_error_range);
                (*center)[2u] += depth_offset;
            }
            if ((*center)[2u] > far_plane || near_plane > (*center)[2u]) {
                sprite_visible = false;
                sdk_ta_vertex_count = 0u;
            } else {
                if (route_camera_profile)
                    output_reciprocal_depth = 1.0f / (*center)[2u];
                // The standard 0x8C63EF78 owner scales extents by the X/Y
                // projection factors. The route-owned 0x8C09E7C0 variant
                // intentionally applies those factors only to the origin.
                const auto extent_scale_x =
                    common_scale * projection_reciprocal_depth *
                    (route_camera_profile ? 1.0f : horizontal_factor);
                const auto extent_scale_y =
                    common_scale * projection_reciprocal_depth *
                    (route_camera_profile ? 1.0f : vertical_factor);
                const auto screen_x =
                    projection_center_x + (*center)[0u] * horizontal_factor *
                                              common_scale *
                                              projection_reciprocal_depth;
                const auto screen_y =
                    projection_center_y + (*center)[1u] * vertical_factor *
                                              common_scale *
                                              projection_reciprocal_depth;
                if (!std::isfinite(projection_reciprocal_depth) ||
                    !std::isfinite(output_reciprocal_depth) ||
                    !std::isfinite(extent_scale_x) ||
                    !std::isfinite(extent_scale_y) ||
                    !std::isfinite(screen_x) ||
                    !std::isfinite(screen_y) ||
                    output_reciprocal_depth <= 0.0f)
                    return graphics_abort(sonic_native_graphics_error_layout);
                for (std::size_t index = 0u; index < positions.size(); ++index) {
                    const auto rotated_x =
                        positions[index][0] * cosine -
                        positions[index][1] * sine;
                    const auto rotated_y =
                        positions[index][0] * sine +
                        positions[index][1] * cosine;
                    output_positions[index] = {
                        screen_x + rotated_x * extent_scale_x,
                        screen_y + rotated_y * extent_scale_y,
                        output_reciprocal_depth};
                    output_depths[index] = output_reciprocal_depth;
                }
            }
        } else {
            // Object-space Sprite3D (0x8C63F214): rotate and scale the four
            // corners before XMTRX. The host's homogeneous clip path replaces
            // the owner's bounded near-plane polygon clip, including mixed
            // near visibility; the same exact transform is already proven by
            // the BasicAttach and raw NINJA families.
            bool all_beyond_far = true;
            bool all_before_near = true;
            std::uint32_t near_mask = 0u;
            std::uint32_t common_screen_outcode = 0xFu;
            std::array<float, 4u> screen_bounds{};
            for (std::size_t bound = 0u; bound < screen_bounds.size(); ++bound) {
                if (!reader.f32(0x8C88F540u +
                                    static_cast<std::uint32_t>(bound * 4u),
                                screen_bounds[bound]) ||
                    !std::isfinite(screen_bounds[bound]))
                    return graphics_abort(sonic_native_graphics_error_layout);
            }
            if (sonic::presentation::settings().widescreen) {
                screen_bounds[0] -= sonic::presentation::extra_horizontal_pixels();
                screen_bounds[2] += sonic::presentation::extra_horizontal_pixels();
            }
            for (std::size_t index = 0u; index < positions.size(); ++index) {
                const auto rotated_x =
                    positions[index][0] * cosine -
                    positions[index][1] * sine;
                const auto rotated_y =
                    positions[index][0] * sine +
                    positions[index][1] * cosine;
                output_positions[index] = {x + rotated_x, y + rotated_y, z};
                output_depths[index] = z;
                const auto camera = transform_camera(output_positions[index]);
                if (!camera.has_value())
                    return graphics_abort(sonic_native_graphics_error_layout);
                all_beyond_far = all_beyond_far && (*camera)[2u] > far_plane;
                all_before_near =
                    all_before_near && near_plane > (*camera)[2u];
                near_mask = (near_mask << 1u) |
                            (near_plane > (*camera)[2u] ? 1u : 0u);
                const auto reciprocal_depth = 1.0f / (*camera)[2u];
                const auto screen_x = projection_center_x +
                    (*camera)[0u] * common_scale * horizontal_factor *
                        reciprocal_depth;
                const auto screen_y = projection_center_y +
                    (*camera)[1u] * common_scale * vertical_factor *
                        reciprocal_depth;
                std::uint32_t outcode = 0u;
                if (screen_y > screen_bounds[3u]) outcode |= 8u;
                if (screen_bounds[1u] > screen_y) outcode |= 4u;
                if (screen_x > screen_bounds[2u]) outcode |= 2u;
                if (screen_bounds[0u] > screen_x) outcode |= 1u;
                common_screen_outcode &= outcode;
            }
            sprite_visible = !all_beyond_far && !all_before_near;
            sdk_ta_vertex_count =
                all_beyond_far || near_mask == 0xFu ||
                        common_screen_outcode != 0u
                    ? 0u
                    : sonic_sprite_near_clip_vertices[near_mask];
            sprite_transform = *clip_transform;
            sprite_depth_mapping =
                katana::runtime::NativePortDepthCoordinateMode::
                    ReciprocalPositiveHomogeneousClip;
        }
    }

    // The route owner rejects every zero-emission result before consuming
    // TEXLIST. Preserve its raw 605CEC/605D4A snapshot even when the host's
    // existing four-vertex path remains useful for homogeneous GPU clipping.
    const bool route_sdk_culled =
        route_camera_profile && sdk_ta_vertex_count == 0u;
    if (route_sdk_culled) {
        const auto snapshot =
            finish_native_culled_route_sprite_state(context, reader);
        if (snapshot.action != katana::runtime::NativePortHookAction::Return ||
            !sprite_visible)
            return snapshot;
    }

    // njSetTexture(nullptr) returns failure without replacing the previous
    // list; the sprite wrapper still runs its selector against that list.
    if (texlist == 0u &&
        !reader.u32(sonic_ninja_texture_list_state, texlist))
        return graphics_abort(sonic_native_graphics_error_range);
    SonicNativeTextureBinding binding;
    if (!read_texlist(reader, texlist, binding))
        return graphics_abort(sonic_native_graphics_error_layout);
    // A valid sprite animation can briefly retain the old ordinal while its
    // TEXLIST is being republished for the next owner.  This is the same
    // bounded ownership gap handled by resolve_native_texture_state; do not
    // turn an optional sprite into a layout abort before the resolver can
    // classify it as no-draw.
    if (texture_index >= binding.texture_count) {
        if (sonic_native_sprite_binding_enabled)
            record_sonic_native_sprite_binding(
                context, binding, address, sprite_2d, profile, texanim,
                animation_address, animation_index, texture_index, 1u);
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    }

    const bool collect_graphics_diagnostics =
        sonic_native_graphics_diagnostics_enabled();
    SonicNativeTextureResolutionDiagnostics texture_diagnostics;
    katana::runtime::NativePortTextureHandle texture;
    const auto texture_resolution = resolve_native_texture_state(
        context, reader, texlist, texture_index, texture,
        collect_graphics_diagnostics ? &texture_diagnostics : nullptr);
    if (texture_resolution ==
        SonicNativeTextureResolution::UnboundSentinel) {
        if (sonic_native_sprite_binding_enabled)
            record_sonic_native_sprite_binding(
                context, binding, address, sprite_2d, profile, texanim,
                animation_address, animation_index, texture_index, 2u);
    }
    if (texture_resolution != SonicNativeTextureResolution::Bound &&
        texture_resolution != SonicNativeTextureResolution::UnboundSentinel) {
        // Cold failure only: retain the sprite's pointer chain in ordinary
        // user capsules. GPR windows alone do not reach TEXLIST/TEXADDR, and
        // a texture error without this data cannot identify a stale owner.
        if (context.crash_capsule != nullptr) {
            katana::runtime::CrashCapsuleProviderTranscript record;
            record.sequence = context.frame_index;
            record.provider = 0x53505446u; // SPTF: sprite texture failure.
            record.operation = 1u;
            record.source = context.cpu->pc;
            record.callsite = context.cpu->pr;
            record.address = texlist;
            record.pointer = binding.texname_address;
            record.value = binding.texture_count;
            record.slot = texture_index;
            record.alias = animation_address;
            record.state = static_cast<std::uint32_t>(texture_resolution);
            std::uint32_t descriptor = 0u;
            const auto descriptor_slot = static_cast<std::uint64_t>(
                binding.texname_address) + texture_index * 12ull + 8u;
            if (descriptor_slot <= std::numeric_limits<std::uint32_t>::max() &&
                reader.u32(static_cast<std::uint32_t>(descriptor_slot), descriptor)) {
                record.target = descriptor;
                record.flags = 1u;
            }
            record.provider_identity.assign("sonic-sprite-texture-failure-v1");
            record.source_identity.assign("texlist-count-ordinal-texname-texaddr");
            context.crash_capsule->note_v5_provider_transcript(record);
            if ((record.flags & 1u) != 0u && reader.range(descriptor, 4u)) {
                record.operation = 2u;
                record.source_identity.assign("descriptor-word-pairs");
                for (std::uint32_t word = 0u; word < 17u; word += 2u) {
                    const auto chunk = static_cast<std::uint64_t>(descriptor) + word * 4u;
                    record.width = word == 16u ? 4u : 8u;
                    if (chunk + record.width > 0x100000000ull) break;
                    record.address = chunk;
                    std::uint32_t first = 0u;
                    std::uint32_t second = 0u;
                    if (!reader.u32(static_cast<std::uint32_t>(chunk), first) ||
                        (record.width == 8u &&
                         !reader.u32(static_cast<std::uint32_t>(chunk + 4u), second))) break;
                    record.value = first;
                    record.result = second;
                    context.crash_capsule->note_v5_provider_transcript(record);
                }
            }
            const auto owner = find_native_texlist_catalog_owner(context, texlist, binding);
            record.operation = 3u;
            record.address = texlist;
            record.width = 0u;
            record.value = static_cast<std::uint32_t>(owner.kind);
            record.result = owner.base_ordinal;
            record.source_identity.assign("current-owner-kind-base-ordinal");
            if (owner.binding != nullptr) {
                record.slot = static_cast<std::uint32_t>(owner.binding->catalog_index);
                record.generation = owner.binding->descriptor_transition_authority.transition_epoch;
                record.flags |= 2u;
            } else {
                record.slot = 0u;
            }
            context.crash_capsule->note_v5_provider_transcript(record);
            record.operation = 4u;
            record.source_identity.assign("last-texlist-bind");
            record.address = sonic_native_title_state.diagnostic_texlist_bind_address;
            record.value = sonic_native_title_state.diagnostic_texlist_bind_sequence;
            record.result = sonic_native_title_state.diagnostic_texlist_bind_pc;
            record.state = sonic_native_title_state.diagnostic_texlist_bind_pr;
            context.crash_capsule->note_v5_provider_transcript(record);
            std::uint32_t registry_base = 0u, registry_count = 0u;
            record.operation = 5u;
            record.source_identity.assign("texture-registry-base-count");
            record.address = sonic_ninja_texture_registry_state;
            record.flags =
                reader.u32(sonic_ninja_texture_registry_state, registry_base) &&
                reader.u32(sonic_ninja_texture_registry_count, registry_count) ? 1u : 0u;
            record.value = registry_base;
            record.result = registry_count;
            context.crash_capsule->note_v5_provider_transcript(record);
        }
        return graphics_abort(sonic_native_graphics_error_texture);
    }

    if (sonic_native_sprite_binding_enabled &&
        texture_resolution == SonicNativeTextureResolution::Bound)
        record_sonic_native_sprite_binding(
            context, binding, address, sprite_2d, profile, texanim,
            animation_address, animation_index, texture_index, 3u, texture.value);

    auto& vertices = sonic_native_title_state.transient_vertices;
    vertices.clear();
    if (sprite_visible) {
        vertices.reserve(4u);
        for (std::size_t index = 0u; index < positions.size(); ++index) {
            katana::runtime::NativePortVertex vertex;
            vertex.position = output_positions[index];
            vertex.depth_coordinate = output_depths[index];
            vertex.texture_coordinate = coordinates[index];
            vertex.color = {1.0f, 1.0f, 1.0f, 1.0f};
            vertices.push_back(vertex);
        }
    }
    const bool translucent = (attribute & (1u << 5u)) != 0u;
    const auto sprite_arc1 =
        translucent ? std::uint32_t{0x02100028u}
                    : std::uint32_t{0x00080028u};
    // The route wrapper culls before binding/selecting its texture and before
    // writing ARC1. Standard Sprite2D/3D wrappers perform that setup even if
    // the quad is later rejected or degenerate.
    const auto sprite_transaction = prepare_native_sprite_state(
        reader, binding, texture_index, sprite_arc1, !route_sdk_culled);
    if (!sprite_transaction.has_value()) {
        // Preserve the existing optional publication-gap policy only where
        // there is no mapped SDK descriptor from which to project state.
        if (texture_resolution == SonicNativeTextureResolution::UnboundSentinel)
            return finish_pretransformed_stream_draw(
                context, {katana::runtime::NativePortHookAction::Return, 0u, 0u});
        return graphics_abort(sonic_native_graphics_error_layout);
    }
    // A selected list cursor is consumed by the original TA emission. Prove
    // the complete header+vertex range before draw_packet can enqueue any
    // graphics work. A zero-emission route has no selected cursor at all.
    if (!route_sdk_culled && sdk_ta_vertex_count != 0u) {
        const auto selected = sonic_sprite_cursor_index(sprite_arc1);
        if (!sonic_sprite_advanced_cursor(
                 sprite_transaction->cursor[selected], sdk_ta_vertex_count,
                 reader.range(sprite_transaction->cursor[selected],
                              (1u + sdk_ta_vertex_count) * sonic_ninja_packet_bytes))
                 .has_value()) {
            // Failure-only evidence: retain the real owner and all five
            // cursors so user runs are sufficient to diagnose buffer lifecycle
            // errors without suspending the process for a live RAM capture.
            std::cerr << "SONIC_NATIVE_SPRITE_CURSOR_FAILURE frame="
                      << context.frame_index << " pc=0x" << std::hex
                      << context.cpu->pc << " pr=0x" << context.cpu->pr
                      << " owner=0x" << sprite_transaction->cursor_owner
                      << " cursor=0x" << sprite_transaction->cursor[selected]
                      << std::dec << " selected=" << selected
                      << " vertices=" << sdk_ta_vertex_count << '\n';
            if (context.crash_capsule != nullptr) {
                katana::runtime::CrashCapsuleProviderTranscript record;
                record.sequence = context.frame_index;
                record.provider = 0x53415343u;
                record.operation = 1u;
                record.source = context.cpu->pc;
                record.callsite = context.cpu->pr;
                record.pointer = sprite_transaction->cursor_owner;
                record.target = sprite_transaction->cursor[selected];
                record.width = (1u + sdk_ta_vertex_count) * sonic_ninja_packet_bytes;
                record.result = sdk_ta_vertex_count;
                record.state = static_cast<std::uint32_t>(selected);
                record.provider_identity.assign("sonic-sprite-cursor-failure-v1");
                record.source_identity.assign("physical-owner-cursor-words");
                for (std::size_t index = 0u; index < sprite_transaction->cursor.size(); ++index) {
                    record.slot = static_cast<std::uint32_t>(index);
                    record.address = sprite_transaction->cursor_owner +
                                     sprite_transaction->cursor_owner_offsets[index];
                    record.value = sprite_transaction->cursor[index];
                    record.flags = reader.range(sprite_transaction->cursor[index],
                                                record.width) ? 1u : 0u;
                    context.crash_capsule->note_v5_provider_transcript(record);
                }
            }
            return graphics_abort(sonic_native_graphics_error_range);
        }
    }
    const auto finish_sprite = [&](const auto result) {
        if (route_sdk_culled) {
            if (result.action != katana::runtime::NativePortHookAction::Return)
                return result;
            return finish_pretransformed_stream_draw(context, result);
        }
        // A fully clipped owner does not submit a header and therefore does
        // not advance either TA list cursor.
        const bool header_selected = sdk_ta_vertex_count != 0u;
        return finish_native_sprite_state(
            context, reader, *sprite_transaction, result, header_selected,
            sdk_ta_vertex_count);
    };
    if (texture_resolution == SonicNativeTextureResolution::UnboundSentinel)
        return finish_sprite(katana::runtime::NativePortHookResult{
            katana::runtime::NativePortHookAction::Return, 0u, 0u});
    const auto sprite_packet_tsp = translucent
        ? sprite_transaction->packet[2]
        : (sprite_transaction->packet[2] & 0x03EFFFFFu) | 0x20080000u;
    auto sprite_render_state = sonic_render_state_from_words(
        sprite_transaction->packet[0], sprite_transaction->packet[1],
        sprite_packet_tsp);
    if (!sprite_render_state.has_value())
        return graphics_abort(sonic_native_graphics_error_model_draw);
    auto sprite_sampler = sprite_render_state->sampler;
    // Both exact sprite wrappers select the mutable NINJA material only when
    // attribute bit 1 is set; otherwise they submit the same static white
    // material. Both sources are four raw floats in A,R,G,B order. The TA
    // quantizes face color before applying the sprite's constant intensity
    // 1.0; alpha is not multiplied by intensity (Flycast ta_vtx.cpp).
    const auto material_address =
        (attribute & (1u << 1u)) != 0u
            ? sonic_ninja_global_alpha
            : (route_camera_profile ? sonic_route_sprite_white_material
                                    : sonic_ninja_white_material);
    std::array<std::uint32_t, 4u> ninja_material{};
    for (std::size_t index = 0u; index < ninja_material.size(); ++index) {
        std::uint32_t bits = 0u;
        if (!reader.u32(
                material_address +
                    static_cast<std::uint32_t>(index * sizeof(float)),
                bits))
            return graphics_abort(sonic_native_graphics_error_range);
        ninja_material[index] = sonic_ta_float_color_byte(bits);
    }
    auto sprite_material = sprite_render_state->material;
    sprite_material.diffuse = {
        static_cast<float>((ninja_material[1u] * 255u) / 256u) / 255.0f,
        static_cast<float>((ninja_material[2u] * 255u) / 256u) / 255.0f,
        static_cast<float>((ninja_material[3u] * 255u) / 256u) / 255.0f,
        static_cast<float>(ninja_material[0u]) / 255.0f};
    // Blend and address modes come from the SDK packet for every asset.
    // Sheet names and UV coverage do not authorize replacing DestinationAlpha
    // with SourceAlpha or Wrap/Mirror with Clamp.
    std::optional<std::uint64_t> trace_sequence;
    if (sound_test_trace_enabled_for_frame(context.frame_index)) {
        std::uint64_t trace_signature = 1469598103934665603ull;
        const auto trace_mix = [&trace_signature](const std::uint32_t value) {
            trace_signature ^= value;
            trace_signature *= 1099511628211ull;
        };
        trace_mix(0x53505249u);
        trace_mix(address);
        trace_mix(animation_address);
        trace_mix(animation_index);
        trace_mix(texture_index);
        trace_mix(attribute);
        trace_mix(static_cast<std::uint32_t>(texture.value));
        trace_mix(static_cast<std::uint32_t>(texture.value >> 32u));
        trace_mix(std::bit_cast<std::uint32_t>(sprite_material.diffuse[3u]));
        trace_sequence = reserve_sound_test_trace(trace_signature);
    }
    const auto report_trace = [&](const unsigned action) {
        if (!trace_sequence.has_value()) return;
        std::cerr << "SONIC_NATIVE_SOUND_TEST_DRAW seq=" << *trace_sequence
                  << " frame=" << context.frame_index
                  << " kind=sprite pc=0x" << std::hex
                  << context.cpu->active_instruction_pc << " pr=0x"
                  << context.cpu->pr << " source=0x" << address
                  << " texlist=0x" << texlist << " texanim=0x" << texanim
                  << " animation=0x" << animation_address << " texture=0x"
                  << texture.value << std::dec
                  << " animation_index=" << animation_index
                  << " texture_index=" << texture_index
                  << " extent=" << width << 'x' << height
                  << " center=" << center_x << ',' << center_y
                  << " uv=" << u0 << ',' << v0 << ',' << u1 << ',' << v1
                  << " xy=" << x << ',' << y << ',' << z
                  << " scale=" << scale_x << ',' << scale_y
                  << " material_alpha=" << sprite_material.diffuse[3u]
                  << " texture_alpha="
                  << sprite_material.use_texture_alpha
                  << " blend=" << sprite_render_state->blend.enabled << ':'
                  << static_cast<unsigned>(
                         sprite_render_state->blend.source_color)
                  << ':' << static_cast<unsigned>(
                         sprite_render_state->blend.destination_color)
                  << " visible=" << (sprite_visible ? 1 : 0)
                  << " action=" << action << '\n';
    };
    if (!sprite_visible) {
        report_trace(static_cast<unsigned>(
            katana::runtime::NativePortHookAction::Return));
        return finish_sprite(katana::runtime::NativePortHookResult{
            katana::runtime::NativePortHookAction::Return, 0u, 0u});
    }
    katana::runtime::NativePortDrawDiagnostics draw_diagnostics;
    if (collect_graphics_diagnostics) {
        draw_diagnostics.enabled = true;
        draw_diagnostics.origin =
            katana::runtime::NativePortDrawOriginKind::Sprite;
        draw_diagnostics.intent =
            sprite_2d
                ? katana::runtime::NativePortDrawIntent::Interface
                : katana::runtime::NativePortDrawIntent::SceneObject;
        draw_diagnostics.origin_identity = sonic_native_opaque_identity(
            0x5350524954454452ull,
            context.cpu->active_instruction_pc,
            context.cpu->pr,
            address,
            animation_address);
        draw_diagnostics.origin_identity_bound = true;
        if (sonic_native_armed_graphics_identity_frame(
                context.frame_index)) {
            draw_diagnostics.model_identity = native_ui_coverage_identity(
                std::span<const katana::runtime::NativePortVertex>(
                    vertices.data(), vertices.size()),
                std::span<const std::uint32_t>{}, texture,
                katana::runtime::NativePortPrimitiveTopology::TriangleStrip);
            draw_diagnostics.model_identity_bound = true;
        }
        draw_diagnostics.primitive_index =
            (static_cast<std::uint32_t>(profile) << 1u) |
            (sprite_2d ? 1u : 0u);
        draw_diagnostics.primitive_index_bound = true;
        populate_native_texture_draw_diagnostics(
            binding, texture_index, texture_diagnostics, draw_diagnostics);
    }
    const auto result = draw_packet(
        context,
        attribute | ninja_flag_use_texture,
        texture,
        katana::runtime::NativePortPrimitiveTopology::TriangleStrip,
        // Both Sprite2D and Sprite3D owners ultimately emit the PAL title's
        // logical 640x480 raster coordinates. Sprite3D performs its camera
        // projection above, but that does not change the destination raster.
        // Route every sprite through the same aspect-preserving framebuffer
        // viewport as the projected scene. Sending Sprite3D to FullRender
        // scales it against 16:9 while the scene is centred at 4:3, which
        // visibly places police lights and other billboards in the sidebars.
        katana::runtime::NativePortViewportTarget::Ui,
        std::nullopt, std::nullopt, std::nullopt, sprite_sampler,
        sprite_material, {}, std::nullopt, std::nullopt, {}, std::nullopt,
        false, sprite_transform, sprite_depth_mapping, sprite_arc1,
        sprite_render_state, draw_diagnostics, {}, std::nullopt,
        sprite_2d ? sonic_sprite_presentation_role(*context.cpu, address, texlist, texanim, reader)
                  : sonic::presentation::Role::World);
    report_trace(static_cast<unsigned>(result.action));
    return finish_sprite(result);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_draw_sprite_2d(
    katana::runtime::NativePortContext& context) noexcept {
    return draw_sprite_family(context, true);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_draw_sprite_3d(
    katana::runtime::NativePortContext& context) noexcept {
    return draw_sprite_family(context, false);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_draw_route_sprite_3d(
    katana::runtime::NativePortContext& context) noexcept {
    return draw_sprite_family(
        context, false, SonicNativeSpriteProfile::RouteCamera);
}

enum class SonicNativeGlyphProfile : std::uint8_t {
    TextBytes,
    FixedDecimal,
    PackedNibbles,
    FixedBinary,
    FixedFloat,
};

enum class SonicNativeGlyphLayout : std::uint8_t {
    Sdk,
    Resident,
    ResidentForeground,
};

// Exact negative SHLD count used by the resident binary/nibble formatters.
// A nonzero magnitude divisible by 32 shifts out the entire word.
constexpr std::uint32_t sonic_resident_glyph_shift_right(
    const std::uint32_t value, const std::uint32_t magnitude) noexcept {
    if (magnitude == 0u) return value;
    const auto count = magnitude & 31u;
    return count == 0u ? 0u : value >> count;
}

katana::runtime::NativePortHookResult draw_glyph_family(
    katana::runtime::NativePortContext& context,
    const SonicNativeGlyphProfile profile,
    const SonicNativeGlyphLayout layout = SonicNativeGlyphLayout::Sdk) noexcept {
    SonicNativeScopedWork work{
        sonic_native_title_state.work_timing,
        SonicNativeWorkClass::Glyph};
    if (!valid_sonic_native_context(context))
        return graphics_abort(sonic_native_graphics_error_context);
    const bool resident = layout != SonicNativeGlyphLayout::Sdk;
    SonicGuestReader reader(*context.cpu);
    if (resident) {
        std::uint32_t suppressed = 0u;
        if (!reader.u32(0x8C754E08u, suppressed))
            return graphics_abort(sonic_native_graphics_error_range);
        // This is the original owner gate, before even reading the string.
        if (suppressed != 0u)
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    }
    if (!static_cast<bool>(sonic_native_title_state.font_texture) ||
        sonic_native_title_state.font_dimension !=
            sonic_ninja_builtin_font_dimension)
        return graphics_abort(sonic_native_graphics_error_text);

    try {
        // All three exact NINJA owners share packed signed cell coordinates,
        // font state and the 0x8C6406F0 glyph leaf. Only the source encoding
        // differs: a terminated byte string, a fixed-width signed decimal,
        // or a fixed-width packed nibble value. Decode that source into one
        // bounded stack buffer and submit one order-preserving native packet;
        // no store queue, QACR or PVR address reaches the host runtime.
        const auto packed_position = context.cpu->r[4];
        if (!reader.valid())
            return graphics_abort(sonic_native_graphics_error_range);

        std::array<std::uint8_t, max_native_text_bytes> glyph_storage{};
        std::size_t glyph_count = 0u;
        switch (profile) {
        case SonicNativeGlyphProfile::TextBytes: {
            // Exact 0x8C640862 ABI: r5 is a terminated guest byte string.
            const auto buffer = context.cpu->r[5];
            if (buffer == 0u)
                return graphics_abort(sonic_native_graphics_error_range);
            bool terminated = false;
            for (std::size_t offset = 0u; offset < max_native_text_bytes;
                 ++offset) {
                std::uint32_t address = 0u;
                std::uint8_t byte = 0u;
                if (!checked_guest_address(buffer, offset, 1u, address) ||
                    !reader.u8(address, byte))
                    return graphics_abort(sonic_native_graphics_error_range);
                if (byte == 0u) {
                    terminated = true;
                    break;
                }
                glyph_storage[glyph_count++] = byte;
            }
            if (!terminated)
                return graphics_abort(sonic_native_graphics_error_budget);
            break;
        }
        case SonicNativeGlyphProfile::FixedDecimal: {
            // Exact 0x8C6409C0 ABI: r5 is a signed integer and r6 is the
            // decimal field width. The proven product family uses 1..9; a
            // larger shape fails closed. The original emits a leading minus
            // before testing whether the digit width is positive.
            const auto width = std::bit_cast<std::int32_t>(context.cpu->r[6]);
            if (width > 9)
                return graphics_abort(sonic_native_graphics_error_budget);
            auto magnitude = context.cpu->r[5];
            if (std::bit_cast<std::int32_t>(magnitude) < 0) {
                glyph_storage[glyph_count++] = '-';
                magnitude = 0u - magnitude;
            }
            if (width <= 0) break;
            std::uint32_t divisor = 1u;
            for (std::int32_t index = 1; index < width; ++index)
                divisor *= 10u;
            for (std::int32_t index = 0; index < width; ++index) {
                const auto quotient = magnitude / divisor;
                magnitude -= quotient * divisor;
                glyph_storage[glyph_count++] = static_cast<std::uint8_t>(
                    '0' + (quotient > 9u ? 0u : quotient));
                if (divisor > 1u) divisor /= 10u;
            }
            break;
        }
        case SonicNativeGlyphProfile::PackedNibbles: {
            // Exact 0x8C640D22 ABI: r5 contains up to eight nibbles and r6
            // selects the fixed output width. The immutable resident lookup
            // table 0x8C673620 is the conventional 0..9/A..F glyph mapping.
            const auto width = std::bit_cast<std::int32_t>(context.cpu->r[6]);
            if (width <= 0) break;
            if (width > static_cast<std::int32_t>(max_native_text_bytes) ||
                (!resident && width > 8))
                return graphics_abort(sonic_native_graphics_error_budget);
            const auto packed = context.cpu->r[5];
            for (std::int32_t index = 0; index < width; ++index) {
                const auto shift = static_cast<std::uint32_t>(
                    4 * (width - 1 - index));
                const auto nibble = sonic_resident_glyph_shift_right(packed, shift) & 0x0Fu;
                glyph_storage[glyph_count++] =
                    sonic_ninja_hex_glyphs[nibble];
            }
            break;
        }
        case SonicNativeGlyphProfile::FixedBinary: {
            const auto width = std::bit_cast<std::int32_t>(context.cpu->r[6]);
            if (width <= 0) break;
            if (width > static_cast<std::int32_t>(max_native_text_bytes))
                return graphics_abort(sonic_native_graphics_error_budget);
            for (std::int32_t index = 0; index < width; ++index) {
                const auto shift = static_cast<std::uint32_t>(width - 1 - index);
                glyph_storage[glyph_count++] = static_cast<std::uint8_t>(
                    '0' + (sonic_resident_glyph_shift_right(context.cpu->r[5], shift) & 1u));
            }
            break;
        }
        case SonicNativeGlyphProfile::FixedFloat: {
            const auto value = std::bit_cast<float>(context.cpu->fr[4]);
            const auto width = std::bit_cast<std::int32_t>(context.cpu->r[5]);
            if (!std::isfinite(value) || width < 0 ||
                width > static_cast<std::int32_t>(max_native_text_bytes - 8u))
                return graphics_abort(sonic_native_graphics_error_budget);
            // The exact resident owner uses %0.*f with precision 5. Host
            // to_chars is locale independent, including the decimal point.
            const bool negative = value < 0.0f;
            if (negative) glyph_storage[glyph_count++] = '-';
            std::array<char, max_native_text_bytes> formatted{};
            const auto result = std::to_chars(
                formatted.data(), formatted.data() + formatted.size(),
                static_cast<double>(negative ? -value : value),
                std::chars_format::fixed, 5);
            if (result.ec != std::errc{})
                return graphics_abort(sonic_native_graphics_error_budget);
            const auto point = std::find(formatted.data(), result.ptr, '.');
            const auto integer_digits = point - formatted.data();
            // A narrower field makes the original backwards shift write
            // before its local buffer. Never turn that invalid span into a
            // successful native draw.
            if (point == result.ptr || width < integer_digits)
                return graphics_abort(sonic_native_graphics_error_range);
            const auto padding = static_cast<std::size_t>(width - integer_digits);
            const auto length = static_cast<std::size_t>(result.ptr - formatted.data());
            if (padding + length > glyph_storage.size() - glyph_count)
                return graphics_abort(sonic_native_graphics_error_budget);
            std::fill_n(glyph_storage.data() + glyph_count, padding, '0');
            glyph_count += padding;
            std::copy_n(formatted.data(), length, glyph_storage.data() + glyph_count);
            glyph_count += length;
            break;
        }
        }

        std::uint32_t resident_destination_word = 0u;
        std::uint32_t resident_destination = 0u;
        std::uint32_t resident_next_destination = 0u;
        std::uint32_t resident_cursor = 0u;
        if (resident) {
            std::uint32_t descriptor = 0u;
            if (!reader.u32(0x8C88FC14u, descriptor) ||
                !checked_guest_address(descriptor, 2u, 4u, resident_destination_word) ||
                !reader.u32(resident_destination_word, resident_destination) ||
                (resident_destination & 31u) != 0u ||
                !(reader.range(resident_destination, 32u + glyph_count * 128u) ||
                  (resident_destination >= sonic_ninja_ta_aperture_begin &&
                   static_cast<std::uint64_t>(resident_destination) +
                       32u + glyph_count * 128u <= sonic_ninja_ta_aperture_end)) ||
                !reader.range(0x8C6733CCu, 4u) ||
                !reader.range(0x8C749060u, 16u))
                return graphics_abort(sonic_native_graphics_error_range);
            std::uint32_t resident_tcw = 0u;
            std::uint32_t sdk_tcw = 0u;
            if (!reader.u32(0x8C749050u, resident_tcw) ||
                !reader.u32(0x8C8904CCu, sdk_tcw) ||
                resident_tcw != 0x000A5800u || resident_tcw != sdk_tcw)
                return graphics_abort(sonic_native_graphics_error_texture);
            const auto advance = static_cast<std::uint32_t>(32u + glyph_count * 128u);
            resident_cursor = 0xE0000000u | (resident_destination & 0x03FFFFFFu);
            resident_cursor += advance;
            resident_next_destination = (resident_cursor & 0x03FFFFFFu) |
                                        (resident_destination & 0xFC000000u);
        }
        const auto publish_resident_result = [&]() {
            // These are title-owned cursor/result words, never mapped queue
            // registers or parsed TA packets. The native GPU owns the draw.
            const std::array<std::uint32_t, 6u> addresses{
                0x8C6733CCu, 0x8C749060u, 0x8C749064u, 0x8C749068u,
                0x8C74906Cu, resident_destination_word};
            const std::array<std::uint32_t, 6u> values{
                0xFFFFFFFEu, resident_cursor, resident_destination,
                (resident_destination >> 24u) & 28u,
                resident_destination & 0xFC000000u, resident_next_destination};
            for (std::size_t index = 0; index < addresses.size(); ++index)
                katana::runtime::guest_write_u32(
                    *context.cpu, addresses[index], values[index],
                    katana::runtime::CodeWriteSource::Copy);
            context.cpu->r[0] = resident_next_destination;
        };
        const auto glyphs = std::span<const std::uint8_t>(
            glyph_storage.data(), glyph_count);
        if (glyphs.empty()) {
            if (resident) publish_resident_result();
            else if (profile == SonicNativeGlyphProfile::TextBytes)
                context.cpu->r[0] = 0u;
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
        }
        if (glyphs.size() > max_native_draw_vertices / 6u)
            return graphics_abort(sonic_native_graphics_error_budget);

        float glyph_size = 0.0f;
        std::uint32_t packed_color = 0u;
        if (!reader.f32(resident ? 0x8C74904Cu : sonic_ninja_font_glyph_size, glyph_size) ||
            !std::isfinite(glyph_size) || glyph_size <= 0.0f ||
            glyph_size > 256.0f ||
            !reader.u32(resident ? 0x8C749048u : sonic_ninja_font_color, packed_color))
            return graphics_abort(sonic_native_graphics_error_layout);
        std::uint32_t parameter_control = 0u;
        std::uint32_t depth_raster = 0u;
        std::uint32_t texture_shading = 0u;
        if (!reader.u32(resident ? 0x8C749058u : sonic_ninja_font_parameter_control,
                        parameter_control) ||
            !reader.u32(resident ? 0x8C74905Cu : sonic_ninja_font_depth_raster, depth_raster) ||
            !reader.u32(resident ? 0x8C749054u : sonic_ninja_font_texture_shading, texture_shading))
            return graphics_abort(sonic_native_graphics_error_range);
        // All three owners write the same font polygon header in reverse
        // store-queue order: 4D4 is PCW, 4D8 is ISP/TSP and 4D0 is TSP.
        // Decode those title-owned words directly; the surrounding renderer
        // context is neither read nor modified by this native family.
        const auto glyph_render_state = sonic_render_state_from_words(
            parameter_control, depth_raster, texture_shading);
        if (!glyph_render_state.has_value())
            return graphics_abort(sonic_native_graphics_error_model_draw);
        const auto color = argb_color(packed_color);
        std::optional<std::uint64_t> trace_sequence;
        if (sound_test_trace_enabled_for_frame(context.frame_index)) {
            std::uint64_t trace_signature = 1469598103934665603ull;
            const auto trace_mix = [&trace_signature](const std::uint32_t value) {
                trace_signature ^= value;
                trace_signature *= 1099511628211ull;
            };
            trace_mix(0x474C5950u);
            trace_mix(static_cast<std::uint32_t>(profile));
            trace_mix(packed_position);
            trace_mix(context.cpu->active_instruction_pc);
            trace_mix(context.cpu->r[5]);
            trace_mix(std::bit_cast<std::uint32_t>(glyph_size));
            trace_mix(packed_color);
            trace_mix(static_cast<std::uint32_t>(
                sonic_native_title_state.font_texture.value));
            trace_mix(static_cast<std::uint32_t>(
                sonic_native_title_state.font_texture.value >> 32u));
            for (const auto glyph : glyphs) trace_mix(glyph);
            trace_sequence = reserve_sound_test_trace(trace_signature);
        }
        const auto cell_x = std::bit_cast<std::int16_t>(
            static_cast<std::uint16_t>(packed_position >> 16u));
        const auto cell_y = std::bit_cast<std::int16_t>(
            static_cast<std::uint16_t>(packed_position & 0xFFFFu));
        const auto quantize = [](const float value)
            -> std::optional<std::int32_t> {
            if (!std::isfinite(value) ||
                value < static_cast<float>(
                            std::numeric_limits<std::int32_t>::min()) ||
                value > static_cast<float>(
                            std::numeric_limits<std::int32_t>::max()))
                return std::nullopt;
            return static_cast<std::int32_t>(std::trunc(value));
        };
        auto current_x = quantize(static_cast<float>(cell_x) * glyph_size);
        const auto initial_y =
            quantize(static_cast<float>(cell_y) * glyph_size);
        if (!current_x.has_value() || !initial_y.has_value())
            return graphics_abort(sonic_native_graphics_error_layout);
        const auto draw_y = static_cast<std::int16_t>(*initial_y);
        // The resident font is a 128x128 ARGB1555 sheet addressed by the
        // packed byte glyph code: the low nibble selects one of 16 columns
        // and the high nibble selects one of 16 rows.  Each cell is therefore
        // 8x8 texels.  Using 1/8 for V spans two rows and composites adjacent
        // glyphs, which corrupts every text family (including the diagnostic
        // overlay) while leaving the layout itself apparently plausible.
        constexpr float atlas_cell_u = 1.0f / 16.0f;
        constexpr float atlas_cell_v = 1.0f / 16.0f;

        auto& vertices = sonic_native_title_state.transient_vertices;
        vertices.clear();
        vertices.reserve(glyphs.size() * 6u);
        for (auto glyph : glyphs) {
            if (resident && glyph == '0') glyph = 'O';
            const auto column = static_cast<std::uint32_t>(glyph & 0x0Fu);
            const auto row = static_cast<std::uint32_t>(glyph >> 4u);
            // 0x8C6406F0 sign-extends the low half of each coordinate. After
            // every call the owners sign-extend X again and execute
            // ftrc(float(s16(X)) + glyph_size). This is observably different
            // from (cell + index) * glyph_size for fractional font sizes.
            const auto draw_x = static_cast<std::int16_t>(*current_x);
            const float left = static_cast<float>(draw_x);
            const float top = static_cast<float>(draw_y);
            const float right = left + glyph_size;
            const float bottom = top + glyph_size;
            const float u0 = static_cast<float>(column) * atlas_cell_u + 1.0f / 1024.0f;
            const float v0 = static_cast<float>(row) * atlas_cell_v + 1.0f / 1024.0f;
            const float u1 = u0 + 63.0f / 1024.0f;
            const float v1 = v0 + 63.0f / 1024.0f;

            const auto append = [&](const float x, const float y,
                                    const float u, const float v) {
                katana::runtime::NativePortVertex vertex;
                const auto depth = layout == SonicNativeGlyphLayout::ResidentForeground
                    ? 2.0f : resident ? std::bit_cast<float>(0x3F68BA2Fu) : 1.0f;
                vertex.position = {x, y, depth};
                vertex.depth_coordinate = depth;
                vertex.texture_coordinate = {u, v};
                vertex.color = color;
                vertices.push_back(vertex);
            };
            append(left + (resident ? 1.0f : 0.0f), top, u0, v0);
            append(left - (resident ? 4.0f : 0.0f), bottom, u0, v1);
            append(right + (resident ? 4.0f : 0.0f), top, u1, v0);
            append(right + (resident ? 4.0f : 0.0f), top, u1, v0);
            append(left - (resident ? 4.0f : 0.0f), bottom, u0, v1);
            append(right - (resident ? 1.0f : 0.0f), bottom, u1, v1);

            current_x = quantize(static_cast<float>(draw_x) + glyph_size);
            if (!current_x.has_value())
                return graphics_abort(sonic_native_graphics_error_layout);
        }

        katana::runtime::NativePortDrawDiagnostics draw_diagnostics;
        if (sonic_native_graphics_diagnostics_enabled()) {
            draw_diagnostics.enabled = true;
            draw_diagnostics.origin =
                katana::runtime::NativePortDrawOriginKind::Font;
            draw_diagnostics.intent =
                katana::runtime::NativePortDrawIntent::Font;
            draw_diagnostics.origin_identity = sonic_native_opaque_identity(
                0x474C595048445241ull,
                context.cpu->active_instruction_pc,
                context.cpu->pr,
                context.cpu->r[5],
                packed_position);
            draw_diagnostics.origin_identity_bound = true;
            if (sonic_native_armed_graphics_identity_frame(
                    context.frame_index)) {
                draw_diagnostics.model_identity = native_ui_coverage_identity(
                    std::span<const katana::runtime::NativePortVertex>(
                        vertices.data(), vertices.size()),
                    std::span<const std::uint32_t>{},
                    sonic_native_title_state.font_texture,
                    katana::runtime::NativePortPrimitiveTopology::
                        TriangleList);
                draw_diagnostics.model_identity_bound = true;
            }
            draw_diagnostics.primitive_index =
                static_cast<std::uint32_t>(profile);
            draw_diagnostics.primitive_index_bound = true;
        }

        const auto result = draw_packet(
            context,
            ninja_flag_use_texture | ninja_flag_use_alpha |
                ninja_flag_double_side,
            sonic_native_title_state.font_texture,
            katana::runtime::NativePortPrimitiveTopology::TriangleList,
            katana::runtime::NativePortViewportTarget::Ui,
            std::nullopt, sonic_depth_state(false, false), std::nullopt,
            std::nullopt,
            std::nullopt, {}, std::nullopt, std::nullopt, {}, std::nullopt,
            false, std::nullopt,
            katana::runtime::NativePortDepthCoordinateMode::ReciprocalPositive,
            std::nullopt, glyph_render_state, draw_diagnostics);
        if (trace_sequence.has_value()) {
            std::cerr << "SONIC_NATIVE_SOUND_TEST_DRAW seq="
                      << *trace_sequence << " frame=" << context.frame_index
                      << " kind=glyph pc=0x" << std::hex
                      << context.cpu->active_instruction_pc << " pr=0x"
                      << context.cpu->pr << " source=0x" << context.cpu->r[5]
                      << " position=0x" << packed_position << " texture=0x"
                      << sonic_native_title_state.font_texture.value
                      << " font_source=0x"
                      << sonic_native_title_state.font_source_address
                      << std::dec << " profile="
                      << static_cast<unsigned>(profile)
                      << " glyph_size=" << glyph_size
                      << " packed_color=" << packed_color
                      << " texture_alpha="
                      << glyph_render_state->material.use_texture_alpha
                      << " blend=" << glyph_render_state->blend.enabled << ':'
                      << static_cast<unsigned>(
                             glyph_render_state->blend.source_color)
                      << ':' << static_cast<unsigned>(
                             glyph_render_state->blend.destination_color)
                      << " action=" << static_cast<unsigned>(result.action)
                      << " bytes=";
            for (const auto glyph : glyphs) {
                if (glyph >= 0x20u && glyph <= 0x7Eu)
                    std::cerr << static_cast<char>(glyph);
                else
                    std::cerr << "\\x" << std::hex
                              << static_cast<unsigned>(glyph) << std::dec;
            }
            std::cerr << '\n';
        }
        if (result.action == katana::runtime::NativePortHookAction::Return) {
            if (resident) publish_resident_result();
            else if (profile == SonicNativeGlyphProfile::TextBytes)
                context.cpu->r[0] = 0u;
        }
        return result;
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_GLYPH profile="
                  << static_cast<unsigned>(profile)
                  << " failure=" << error.what() << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_GLYPH profile="
                  << static_cast<unsigned>(profile)
                  << " failure=non-standard-exception\n";
    }
    return graphics_abort(sonic_native_graphics_error_text);
}

