// The private menu reuses the already-bound NINJA font texture and the same
// glyph render-state decoder as the title.  It writes into the pre-reserved
// transient vertex vector; no per-frame host allocation or platform I/O is
// introduced by Ctrl+F10.
void sonic_native_private_draw_scenario_overlay(
    katana::runtime::NativePortContext& context,
    const sonic_native_private::ScenarioOverlayView& view) noexcept {
    if (!view.open || !valid_sonic_native_context(context)) return;
    try {
        SonicGuestReader reader(*context.cpu);
        if (!static_cast<bool>(sonic_native_title_state.font_texture) ||
            sonic_native_title_state.font_dimension !=
                sonic_ninja_builtin_font_dimension)
            return;
        float glyph_size = 0.0f;
        std::uint32_t parameter_control = 0u;
        std::uint32_t depth_raster = 0u;
        std::uint32_t texture_shading = 0u;
        if (!reader.f32(sonic_ninja_font_glyph_size, glyph_size) ||
            glyph_size <= 0.0f || glyph_size > 256.0f ||
            !reader.u32(sonic_ninja_font_parameter_control,
                        parameter_control) ||
            !reader.u32(sonic_ninja_font_depth_raster, depth_raster) ||
            !reader.u32(sonic_ninja_font_texture_shading, texture_shading))
            return;
        const auto render_state = sonic_render_state_from_words(
            parameter_control, depth_raster, texture_shading);
        if (!render_state.has_value()) return;

        // Six vertices per glyph, bounded by the fixed 16-line/96-byte menu
        // contract plus header/character/status/failure rows. Bootstrap reserves
        // max_native_draw_vertices up front; refusing a non-reserved vector
        // keeps this path allocation-free.
        constexpr std::size_t maximum_line_bytes = 96u;
        constexpr std::size_t maximum_lines = 16u;
        constexpr std::size_t maximum_overlay_lines = maximum_lines + 4u;
        constexpr std::size_t maximum_vertices =
            maximum_line_bytes * maximum_overlay_lines * 6u;
        auto& vertices = sonic_native_title_state.transient_vertices;
        if (vertices.capacity() < maximum_vertices) return;
        vertices.clear();

        const auto append_line = [&](const std::string_view text,
                                     const bool selected,
                                     const float line_index,
                                     const std::uint32_t packed_color) {
            std::array<std::uint8_t, maximum_line_bytes> glyphs{};
            std::size_t glyph_count = 0u;
            const auto append = [&](const std::uint8_t byte) {
                if (glyph_count >= glyphs.size() || byte == 0u) return false;
                glyphs[glyph_count++] = byte;
                return true;
            };
            if (!append(selected ? static_cast<std::uint8_t>('>')
                                 : static_cast<std::uint8_t>(' ')) ||
                !append(static_cast<std::uint8_t>(' ')))
                return;
            for (const auto byte : text) {
                if (!append(static_cast<std::uint8_t>(byte))) break;
            }
            const auto color = argb_color(packed_color);
            // Keep the private overlay on the same 16x16, 8x8-cell atlas
            // contract as the three native glyph owners above.
            constexpr float atlas_cell_u = 1.0f / 16.0f;
            constexpr float atlas_cell_v = 1.0f / 16.0f;
            for (std::size_t index = 0u; index < glyph_count; ++index) {
                const auto glyph = glyphs[index];
                const auto column = static_cast<std::uint32_t>(glyph & 0x0Fu);
                const auto row = static_cast<std::uint32_t>(glyph >> 4u);
                const float left =
                    (2.0f + static_cast<float>(index)) * glyph_size;
                const float top = (1.0f + line_index) * glyph_size;
                const float right = left + glyph_size;
                const float bottom = top + glyph_size;
                const float u0 = static_cast<float>(column) * atlas_cell_u;
                const float v0 = static_cast<float>(row) * atlas_cell_v;
                const float u1 = u0 + atlas_cell_u;
                const float v1 = v0 + atlas_cell_v;
                const auto append_vertex = [&](const float x, const float y,
                                               const float u, const float v) {
                    katana::runtime::NativePortVertex vertex;
                    vertex.position = {x, y, 1.0f};
                    vertex.depth_coordinate = 1.0f;
                    vertex.texture_coordinate = {u, v};
                    vertex.color = color;
                    vertices.push_back(vertex);
                };
                append_vertex(left, top, u0, v0);
                append_vertex(left, bottom, u0, v1);
                append_vertex(right, top, u1, v0);
                append_vertex(right, top, u1, v0);
                append_vertex(left, bottom, u0, v1);
                append_vertex(right, bottom, u1, v1);
            }
        };

        append_line(view.character == "Events" ? "EVENT SCENARIOS  CTRL+F10"
                                               : "ACTION STAGES  CTRL+F10",
                    false, 0.0f, 0xFFFFFFFFu);
        append_line(view.character, false, 1.0f, 0xFF80D0FFu);
        const auto count = std::min(view.line_count, view.lines.size());
        for (std::size_t index = 0u; index < count; ++index) {
            const auto& line = view.lines[index];
            append_line(line.text, line.selected,
                        static_cast<float>(index + 2u),
                        line.ready ? 0xFFFFFFFFu : 0xFF909090u);
        }
        if (!view.status.empty())
            append_line(view.status, false,
                        static_cast<float>(count + 3u), 0xFFFFD080u);
        if (view.failed_launches != 0u)
            append_line("Unavailable in this game state", false,
                        static_cast<float>(count + 4u), 0xFFFF8080u);
        if (vertices.empty()) return;

        katana::runtime::NativePortDrawDiagnostics draw_diagnostics;
        if (sonic_native_graphics_diagnostics_enabled()) {
            draw_diagnostics.enabled = true;
            draw_diagnostics.origin =
                katana::runtime::NativePortDrawOriginKind::Font;
            draw_diagnostics.intent =
                katana::runtime::NativePortDrawIntent::Font;
            draw_diagnostics.origin_identity = sonic_native_opaque_identity(
                0x505249564D454E55ull,
                context.cpu->active_instruction_pc,
                context.cpu->pr,
                static_cast<std::uint32_t>(view.selected),
                static_cast<std::uint32_t>(view.line_count));
            draw_diagnostics.origin_identity_bound = true;
            if (sonic_native_armed_graphics_identity_frame(
                    context.frame_index)) {
                draw_diagnostics.model_identity = native_ui_coverage_identity(
                    std::span<const katana::runtime::NativePortVertex>(
                        vertices.data(), vertices.size()),
                    std::span<const std::uint32_t>{},
                    sonic_native_title_state.font_texture,
                    katana::runtime::NativePortPrimitiveTopology::
                        TriangleList);
                draw_diagnostics.model_identity_bound = true;
            }
            draw_diagnostics.primitive_index = 3u;
            draw_diagnostics.primitive_index_bound = true;
        }

        static_cast<void>(draw_packet(
            context,
            ninja_flag_use_texture | ninja_flag_use_alpha |
                ninja_flag_double_side,
            sonic_native_title_state.font_texture,
            katana::runtime::NativePortPrimitiveTopology::TriangleList,
            katana::runtime::NativePortViewportTarget::Ui,
            std::nullopt, std::nullopt, std::nullopt, std::nullopt,
            std::nullopt, {}, std::nullopt, std::nullopt, {}, std::nullopt,
            false, std::nullopt,
            katana::runtime::NativePortDepthCoordinateMode::ReciprocalPositive,
            std::nullopt, render_state, draw_diagnostics));
    } catch (...) {
        // A diagnostic menu is never allowed to turn a normal title frame
        // into a host exception or a guest progress mutation.
    }
}

void run_sonic_quit_modal(katana::runtime::NativePortContext& context) {
    using namespace katana::runtime;
    sonic::rumble::engine().policy(true,0);
    // The already-completed title frame contains the popup. Repeat it without
    // advancing any guest task, demo timer, save operation or original audio.
    const auto guest_instructions=context.cpu->retired_guest_instructions;
    const auto guest_frame=context.frame_index;
    auto* audio=sonic_native_title_state.native_audio_processor_running?
        sonic_native_title_state.audio_engine.get():nullptr;
    if(audio)audio->set_output_paused(true);
    struct Resume {NativePortContext& context;decltype(audio) engine;
        ~Resume(){try{if(engine)engine->set_output_paused(false);}catch(...){}sonic::quit_prompt::release(context);}
    } resume{context,audio};
    while(context.stop_reason==NativePortStopReason::None && sonic::quit_prompt::visible()) {
        if(try_accept_native_port_host_stop(context))break;
        if(context.host_deadline_nanoseconds && context.host->monotonic_time_nanoseconds()>=context.host_deadline_nanoseconds) {
            (void)request_native_port_host_stop(context,NativePortStopReason::HostDeadline);break;
        }
        const auto life=context.host->poll_lifecycle();
        if(life==NativePortLifecycleState::Shutdown) {
            (void)request_native_port_host_stop(context,NativePortStopReason::HostRequested);break;
        }
        const auto decision=sonic::quit_prompt::poll_modal(context,life!=NativePortLifecycleState::Paused);
        if(decision==sonic::quit_prompt::Decision::Confirmed) {
            (void)request_native_port_host_stop(context,NativePortStopReason::HostRequested);break;
        }
        if(decision==sonic::quit_prompt::Decision::Cancelled)break;
        if(life==NativePortLifecycleState::Paused)std::this_thread::sleep_for(std::chrono::milliseconds(16));
        else context.host->present_frame(context.frame_index);
    }
    // Fresh normal sampling consumes the closing button until its release.
    sonic_native_title_state.native_input_frame_index=std::numeric_limits<std::uint64_t>::max();
    sonic_native_title_state.frame_producer_next_deadline_nanoseconds=0u;
    sonic_native_title_state.frame_producer_deferred_deadline_nanoseconds=0u;
    std::cerr<<"SONIC_QUIT modal_end guest_instructions_delta="
             <<(context.cpu->retired_guest_instructions-guest_instructions)
             <<" guest_frame_delta="<<(context.frame_index-guest_frame)<<'\n';
}

void run_sonic_options_modal(katana::runtime::NativePortContext& context) {
    if(!sonic::menu::pending(context))return;
    sonic::rumble::engine().policy(true,0);
    using namespace katana::runtime;
    auto* const audio=sonic_native_title_state.audio_engine.get();bool audio_suspended=false,prior_pause=false;
    sonic::menu::Services services;
    services.suspend_audio=[&]{if(audio){prior_pause=audio->snapshot().output_paused;audio->set_output_paused(true);audio_suspended=true;}};
    services.resume=[&](std::uint64_t elapsed){
        auto& s=sonic_native_title_state;
        s.timer_epoch_nanoseconds+=elapsed;s.periodic_epoch_nanoseconds+=elapsed;
        reset_sonic_host_sleep_clock(context);
        s.native_input_frame_index=std::numeric_limits<std::uint64_t>::max();
        s.frame_producer_next_deadline_nanoseconds=0;s.frame_producer_deferred_deadline_nanoseconds=0;
        if(audio_suspended)audio->set_output_paused(prior_pause);
    };
    services.apply_audio=[](bool focus){sonic::audio::focused=focus;refresh_sonic_audio_settings();};
    services.original_transition=[&](unsigned destination){
        if(!sonic::menu::original_options_ready(context)||(destination!=5&&destination!=7))return false;
        auto& cpu=*context.cpu;const auto task=cpu.memory.read_u32(canonical_physical_address(0x8C9645D0));
        const auto work=cpu.memory.read_u32(canonical_physical_address(task+0x2C));
        const auto r=cpu.r,fr=cpu.fr,xf=cpu.xf;const auto sr=cpu.read_sr();
        const std::array control{cpu.mach,cpu.macl,cpu.fpul,cpu.fpscr,cpu.gbr};
        cpu.r[4]=destination;const bool result=invoke_frame_aot_service(context,0x8C90177E);
        cpu.write_sr(sr);cpu.r=r;cpu.fr=fr;cpu.xf=xf;cpu.mach=control[0];cpu.macl=control[1];cpu.fpul=control[2];cpu.fpscr=control[3];cpu.gbr=control[4];
        if(result)guest_write_u32(cpu,work+24,9,CodeWriteSource::Copy);
        return result;
    };
    (void)sonic::menu::run(context,services);
}

[[nodiscard]] bool run_private_scenario_modal(
    katana::runtime::NativePortContext& context) {
    using namespace sonic_native_private;
    const ScenarioProvider provider{
        sonic_native_private_scenario_ready,
        sonic_native_private_automatic_scenario_ready,
        sonic_native_private_scenario_launch,
        sonic_native_private_draw_scenario_overlay};

    // The private menu is a host-side modal boundary.  No guest block is
    // dispatched while this loop owns the frame, and no sound-bank pump is
    // allowed to advance voices behind the menu.  Preserve the pre-menu
    // processor state so closing the menu resumes the ordinary title path.
    const bool resume_audio =
        sonic_native_title_state.native_audio_processor_running;
    const bool audio_paused = resume_audio &&
                              sonic_native_title_state.audio_engine != nullptr;
    if (audio_paused)
        sonic_native_title_state.audio_engine->set_output_paused(true);

    bool success = true;
    while (context.stop_reason == katana::runtime::NativePortStopReason::None &&
           scenario_menu_open(context)) {
        if (katana::runtime::try_accept_native_port_host_stop(context)) break;
        if (context.host_deadline_nanoseconds != 0u &&
            context.host->monotonic_time_nanoseconds() >=
                context.host_deadline_nanoseconds &&
            katana::runtime::request_native_port_host_stop(
                context, katana::runtime::NativePortStopReason::HostDeadline)) {
            break;
        }
        const auto lifecycle = context.host->poll_lifecycle();
        if (lifecycle == katana::runtime::NativePortLifecycleState::Shutdown &&
            katana::runtime::request_native_port_host_stop(
                context, katana::runtime::NativePortStopReason::HostRequested)) {
            break;
        }
        if (lifecycle == katana::runtime::NativePortLifecycleState::Paused &&
            context.pending_host_stop_reason ==
                katana::runtime::NativePortStopReason::None) {
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
            continue;
        }

        // Force one fresh host sample per modal frame.  suppress_edges keeps
        // the guest-visible pressed/released words inert, while the current
        // button word remains available to scenario_tick for exclusive menu
        // navigation and confirmation.
        sonic_native_title_state.native_input_frame_index =
            std::numeric_limits<std::uint64_t>::max();
        if (!service_sonic_native_input(
                context, true, false, "scenario-modal")) {
            success = false;
            break;
        }
        scenario_tick(
            context,
            std::span<const std::uint32_t>(
                sonic_native_title_state.native_input_buttons),
            provider);
        if (!scenario_menu_open(context)) break;

        // scenario_tick queues the overlay after the guest frame has already
        // completed.  Present it through the same native frame owner now so
        // it is the last UI layer and cannot remain behind a title/logo draw.
        static_cast<void>(complete_native_frame(
            context, "scenario-modal", false));
        if (context.stop_reason != katana::runtime::NativePortStopReason::None)
            break; // Restore paused audio below, but never queue another overlay.
        if (sonic_native_title_state.development_state_restart_requested)
            return true;
    }

    if (audio_paused && sonic_native_title_state.audio_engine)
        sonic_native_title_state.audio_engine->set_output_paused(!resume_audio);
    return success;
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_frame_begin(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_frame_error_context};

    try {
        sonic::startup::frame(context.frame_index);
        if (sonic_native_title_state.postpal_main_textures_pending) {
            static_cast<void>(acquire_native_texture_set(
                context, SonicNativeTextureSetDomain::Main, 0u, false));
            sonic_native_title_state.postpal_main_textures_pending = false;
        }
        reconcile_native_texture_registry_write_trace(context);
        // Install the opt-in palette trace only after the bootstrap memory
        // transaction has captured and validated its direct-RAM snapshot.
        // Watchpoints intentionally disable direct RAM while armed, so
        // installing them inside the bootstrap hook would invalidate that
        // transaction before the first guest frame can run.
        if (sonic_native_title_state.lighting_palette_trace_requested &&
            !sonic_native_title_state.lighting_palette_pointer_watchpoint
                 .has_value()) {
            auto& cpu = *context.cpu;
            if (cpu.gbr > std::numeric_limits<std::uint32_t>::max() - 88u)
                throw std::runtime_error(
                    "native-lighting-palette-watchpoint-address");
            constexpr std::uint32_t palette_data_begin = 0x8C038F60u;
            constexpr std::size_t palette_data_size = 0x2000u;
            constexpr std::uint32_t palette_trace_record_limit = 12288u;
            const auto palette_pointer_address = cpu.gbr + 88u;
            sonic_native_title_state.lighting_palette_pointer_watchpoint =
                cpu.memory.add_watchpoint(
                    palette_pointer_address, sizeof(std::uint32_t),
                    katana::runtime::MemoryWatchpointAccess::Write,
                    [&context, palette_pointer_address](
                        const katana::runtime::MemoryAccessEvent& event) {
                        if (context.cpu == nullptr ||
                            event.address != palette_pointer_address ||
                            sonic_native_title_state
                                    .lighting_palette_watchpoint_records >=
                                palette_trace_record_limit)
                            return;
                        ++sonic_native_title_state
                              .lighting_palette_watchpoint_records;
                        const auto& active_cpu = *context.cpu;
                        std::cerr
                            << "SONIC_NATIVE_LIGHTING_PALETTE_WRITE kind=selector"
                            << " frame=" << context.frame_index << " sequence="
                            << sonic_native_title_state
                                   .lighting_palette_watchpoint_records
                            << " instruction=0x" << std::hex
                            << active_cpu.active_instruction_pc << " pc=0x"
                            << active_cpu.pc << " pr=0x" << active_cpu.pr
                            << " shifted_selector=0x" << active_cpu.r[4]
                            << " selector=" << std::dec
                            << (active_cpu.r[4] >> 11u) << " address=0x"
                            << std::hex << event.address << " value=0x"
                            << event.value << std::dec << '\n';
                    });
            sonic_native_title_state.lighting_palette_data_watchpoint =
                cpu.memory.add_watchpoint(
                    palette_data_begin, palette_data_size,
                    katana::runtime::MemoryWatchpointAccess::Write,
                    [&context](
                        const katana::runtime::MemoryAccessEvent& event) {
                        if (context.cpu == nullptr ||
                            sonic_native_title_state
                                    .lighting_palette_watchpoint_records >=
                                palette_trace_record_limit)
                            return;
                        ++sonic_native_title_state
                              .lighting_palette_watchpoint_records;
                        const auto& active_cpu = *context.cpu;
                        std::cerr
                            << "SONIC_NATIVE_LIGHTING_PALETTE_WRITE kind=data"
                            << " frame=" << context.frame_index << " sequence="
                            << sonic_native_title_state
                                   .lighting_palette_watchpoint_records
                            << " instruction=0x" << std::hex
                            << active_cpu.active_instruction_pc << " pc=0x"
                            << active_cpu.pc << " pr=0x" << active_cpu.pr
                            << " address=0x" << event.address << " value=0x"
                            << event.value << std::dec << '\n';
                    });
        }

        // Once Ctrl+F10 has opened the private menu, stay at this native
        // frame/task safepoint until the user closes it or launches a proven
        // scenario.  Returning directly to the guest here would let title
        // tasks, timers and callbacks continue behind the supposedly modal
        // UI.
        if (sonic_native_private::scenario_menu_open(context)) {
            if (!run_private_scenario_modal(context))
                return graphics_abort(context, sonic_native_frame_error_exception);
            return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
        }

        // 0x8C051790 is an exact 102-byte title wrapper. Its first effect is a
        // signed producer-slot wait. Service the complete registered callback
        // contract at a native simulation boundary instead of spinning AOT
        // while the removed guest scheduler can no longer decrement the slot.
        SonicGuestReader reader(*context.cpu);
        std::uint32_t producer_release = 0u;
        std::uint32_t frame_mode = 0u;
        std::uint32_t frame_counter = 0u;
        if (!reader.valid() ||
            !frame_word(reader, sonic_frame_producer_release, producer_release) ||
            !frame_word(reader, sonic_frame_mode, frame_mode) ||
            !frame_word(reader, sonic_frame_counter, frame_counter) ||
            !reader.range(sonic_frame_pre_submit_ticks, sizeof(std::uint32_t)) ||
            !reader.range(sonic_frame_clear_a, sizeof(std::uint32_t)) ||
            !reader.range(sonic_frame_clear_b, sizeof(std::uint32_t)) ||
            !reader.range(sonic_frame_clear_c, sizeof(std::uint32_t)) ||
            !reader.range(sonic_frame_post_service_ticks, sizeof(std::uint32_t)))
            return graphics_abort(sonic_native_frame_error_side_effect);
        bool title_cadence_owned = false;
        if (!service_frame_producer_until(context, 0,
                frame_mode == 1u ? SonicFrameCadencePolicy::Untracked
                                 : SonicFrameCadencePolicy::WaitForFrame,
                &title_cadence_owned))
            return graphics_abort(sonic_native_frame_error_completion);
        if (!service_periodic_host_time(context))
            return graphics_abort(sonic_native_frame_error_periodic_time);

        // The original wrapper copies this title-owned producer release value
        // after its wait.  Keep the observed handoff exactly, under the normal
        // guarded guest-memory/immutable-write contract.
        katana::runtime::guest_write_u32(
            *context.cpu, sonic_frame_producer_ready, producer_release,
            katana::runtime::CodeWriteSource::Copy);

        // Finish only this hook's validated RAM/ABI epilogue when a completed
        // frame requests a stop; no next-frame input or scenario work is needed.
        const auto finish_frame_hook = [&]() {
            const auto final_ticks = sonic_native_timer_ticks(context);
            katana::runtime::guest_write_u32(
                *context.cpu, sonic_frame_post_service_ticks, final_ticks,
                katana::runtime::CodeWriteSource::Copy);
            context.cpu->r[0] = final_ticks;
            return katana::runtime::NativePortHookResult{
                katana::runtime::NativePortHookAction::Return, 0u, 0u};
        };

        if (frame_mode == 1u) {
            // The exact alternate frame owner configures seven PVR words and
            // then updates one ordinary title render-context record. Native
            // graphics owns the former register configuration; retain the
            // complete title-visible generation/context transition and run
            // only its independently proven, hardware-free AOT state helper.
            std::uint32_t special_state = 0u;
            std::uint32_t special_index = 0u;
            std::uint32_t next_generation = 0u;
            std::uint32_t context_selector = 0u;
            if (!frame_word(reader, sonic_special_frame_state, special_state) ||
                !frame_word(reader, sonic_special_frame_index, special_index) ||
                !frame_word(reader, sonic_special_frame_next_generation,
                            next_generation) ||
                !frame_word(reader, sonic_special_frame_context_selector,
                            context_selector) ||
                !reader.range(sonic_special_frame_pending,
                              sizeof(std::uint32_t)) ||
                !reader.range(sonic_special_frame_active_generation,
                              sizeof(std::uint32_t)) ||
                special_index > 3u)
                return graphics_abort(sonic_native_frame_error_special_mode);
            if (special_state == 1u) {
                katana::runtime::guest_write_u32(
                    *context.cpu, sonic_special_frame_pending, 0u,
                    katana::runtime::CodeWriteSource::Copy);
                katana::runtime::guest_write_u32(
                    *context.cpu, sonic_special_frame_active_generation,
                    next_generation, katana::runtime::CodeWriteSource::Copy);
            }
            context.cpu->r[4] = context_selector;
            if (!invoke_frame_aot_service(
                    context, sonic_special_frame_state_service))
                return graphics_abort(sonic_native_frame_error_service);
        } else {
            // Draw providers open a host frame lazily at the first native draw
            // after the previous present. A transition boundary without a new
            // draw repeats the last completed image instead of publishing a
            // synthetic black clear frame.
            trace_sonic_native_text_progress(context, false);
            if (!invoke_frame_aot_service(context, sonic_frame_prepare_service))
                return graphics_abort(sonic_native_frame_error_service);
            trace_sonic_native_text_progress(context, true);

            katana::runtime::guest_write_u32(
                *context.cpu, sonic_frame_pre_submit_ticks,
                sonic_native_timer_ticks(context),
                katana::runtime::CodeWriteSource::Copy);

            if(sonic::quit_prompt::pending() && sonic_native_title_state.frame_open) {
                flush_native_draw_queues(context);
                if(sonic::quit_prompt::draw(context))sonic_native_title_state.draw_calls_this_frame+=2;
            }
            static_cast<void>(complete_native_frame(context, "frame-begin", true, title_cadence_owned));
            if(!sonic::quit_prompt::visible())sonic::quit_prompt::release(context);
            if (context.stop_reason ==
                    katana::runtime::NativePortStopReason::None &&
                sonic_native_title_state.development_state_restart_requested)
                return consume_sonic_native_development_state_restart();

            if (context.stop_reason == katana::runtime::NativePortStopReason::None &&
                !complete_sonic_native_drain_ram_tail(context))
                return graphics_abort(sonic_native_frame_error_service);

            // This native frame owner deliberately replaces PAL SceneBegin
            // (0x8C641E40) instead of calling it below.  Bind the next
            // frame's ordering authority at the equivalent post-turnover
            // safepoint: the previous frame has been fully flushed, the
            // frame index now names the upcoming scene, and no new packet has
            // been accepted.  Keeping the binding only in the displaced
            // SceneBegin hook left ordinary title frames permanently
            // AuthoredUnsorted even when the authenticated RegionHeader says
            // Type-2 PreSort=0.  The helper remains fail-closed on every
            // source/header/generation check, so Type-1, presorted, mixed or
            // stale scenes retain their existing path.
            if (context.stop_reason ==
                katana::runtime::NativePortStopReason::None)
                (void)bind_sonic_native_type2_scene_authority(context);

            katana::runtime::guest_write_u32(
                *context.cpu, sonic_frame_clear_a, 0u,
                katana::runtime::CodeWriteSource::Copy);
            katana::runtime::guest_write_u32(
                *context.cpu, sonic_frame_clear_b, 0u,
                katana::runtime::CodeWriteSource::Copy);
            katana::runtime::guest_write_u32(
                *context.cpu, sonic_frame_clear_c, 0u,
                katana::runtime::CodeWriteSource::Copy);
            katana::runtime::guest_write_u32(
                *context.cpu, sonic_frame_counter, frame_counter + 1u,
                katana::runtime::CodeWriteSource::Copy);
        }

        if (context.stop_reason != katana::runtime::NativePortStopReason::None)
            return finish_frame_hook();

        if(sonic::quit_prompt::visible()) {
            run_sonic_quit_modal(context);
            if(context.stop_reason!=katana::runtime::NativePortStopReason::None)return finish_frame_hook();
        }
        if(!sonic_native_private::scenario_menu_open(context)) {
            run_sonic_options_modal(context);
            if(context.stop_reason!=katana::runtime::NativePortStopReason::None)return finish_frame_hook();
        }
        if (!configure_sonic_sixty_frame_fixture(context))
            throw std::runtime_error("sixty-frame-fixture-contract");
        if (!configure_sonic_standard_gameplay_cadence(context))
            throw std::runtime_error("standard-gameplay-cadence-contract");
        service_sonic_hidden_transition_probe(context);
        sonic::profiles::poll(context.host->monotonic_time_nanoseconds());

        // 0x8C641E40 (and its 0x8C641E7E MMU/TA write) is intentionally not
        // called. The displaced second service was the complete 24-slot SDK
        // peripheral updater. Publish the equivalent native controller state
        // directly instead of re-entering its Maple/device descendants.
        if (!service_sonic_native_input(
                context, false, false, "frame-begin"))
            return graphics_abort(sonic_native_input_error_contract);

        // The private SA launcher observes the already-projected title input
        // words. It never polls the platform a second time and is inert on
        // the normal path unless Ctrl+F10 opens its explicit menu.
        const sonic_native_private::ScenarioProvider scenario_provider{
            sonic_native_private_scenario_ready,
            sonic_native_private_automatic_scenario_ready,
            sonic_native_private_scenario_launch,
            sonic_native_private_draw_scenario_overlay};
        sonic_native_private::scenario_tick(
            context,
            std::span<const std::uint32_t>(
                sonic_native_title_state.native_input_buttons),
            scenario_provider);

        // The opening edge is observed after the ordinary title frame has
        // completed. Flush that first modal image immediately; subsequent
        // frames are owned by run_private_scenario_modal above.
        if (sonic_native_private::scenario_menu_open(context)) {
            // The opening frame must not leak its controller edge into the
            // title update that follows the frame-begin hook.  The next
            // modal iteration samples a fresh host state for the launcher.
            sonic_native_title_state.native_input_frame_index =
                std::numeric_limits<std::uint64_t>::max();
            if (!service_sonic_native_input(
                    context, true, true, "scenario-open"))
                return graphics_abort(sonic_native_input_error_contract);
            static_cast<void>(complete_native_frame(
                context, "scenario-open", false));
            if (context.stop_reason !=
                katana::runtime::NativePortStopReason::None)
                return finish_frame_hook();
            if (sonic_native_title_state.development_state_restart_requested)
                return consume_sonic_native_development_state_restart();
            // Stay inside this exact frame/task safepoint immediately.  A
            // one-frame return to the guest here would still let tasks,
            // timers and logo/title draws advance once behind the menu before
            // the next frame-begin hook can reclaim the modal boundary.
            if (!run_private_scenario_modal(context))
                return graphics_abort(context, sonic_native_frame_error_exception);
            if (context.stop_reason !=
                katana::runtime::NativePortStopReason::None)
                return finish_frame_hook();
            if (sonic_native_title_state.development_state_restart_requested)
                return consume_sonic_native_development_state_restart();
        }

        return finish_frame_hook();
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_FRAME_BEGIN failure=" << error.what()
                  << '\n';
        if (context.crash_capsule != nullptr) {
            katana::runtime::CrashCapsuleProviderTranscript record;
            record.sequence = context.frame_index;
            record.provider = 0x53414645u; // SAFE: Sonic Adventure frame exception.
            record.operation = 1u;
            record.source = context.cpu != nullptr ? context.cpu->pc : 0u;
            record.callsite = context.cpu != nullptr ? context.cpu->pr : 0u;
            record.value = sonic_native_frame_error_exception;
            record.provider_identity.assign("sonic-frame-exception-v1");
            record.target_identity.assign(error.what());
            context.crash_capsule->note_v5_provider_transcript(record);
        }
    } catch (...) {
        std::cerr << "SONIC_NATIVE_FRAME_BEGIN failure=non-standard-exception\n";
        return graphics_abort(context, sonic_native_frame_error_exception);
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_frame_error_exception};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_frame_producer_complete(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_frame_error_context};

    try {
        SonicFrameProducerObservation observation;
        SonicFrameProducerFailure failure =
            SonicFrameProducerFailure::CompletionResult;
        if (!service_frame_producer_completion(context, &observation, &failure)) {
            note_frame_producer_failure(context, observation, failure);
            return graphics_abort(sonic_native_frame_error_completion);
        }
        // A direct completion enters outside the accounted producer-wait
        // cycle. Its invocation clock is not bound to our native phase.
        sonic_native_title_state.frame_producer_next_deadline_nanoseconds = 0u;
        sonic_native_title_state.frame_producer_deferred_deadline_nanoseconds = 0u;
        sonic_native_title_state.frame_producer_deadline_remainder = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_FRAME_PRODUCER_COMPLETE failure="
                  << error.what() << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_FRAME_PRODUCER_COMPLETE "
                     "failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_frame_error_exception};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_frame_producer_wait(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_frame_error_context};

    try {
        // This exact SDK owner is a pure external-progress wait followed by
        // two title services. Katana's generic native-progress analysis now
        // requires a provider for this shape; the private binding supplies the
        // identity/ABI and retains both original post-wait calls through AOT.
        const auto threshold = static_cast<std::int32_t>(context.cpu->r[4]);
        observe_sonic_native_update_timing(
            context, sonic::diagnostics::UpdateTimingEvent::Wait, context.cpu->r[4]);
        if (!service_frame_producer_until(context, threshold,
                SonicFrameCadencePolicy::AccountWithoutWait))
            return graphics_abort(sonic_native_frame_error_completion);
        if (!service_sonic_native_input(
                context, false, false, "producer-wait"))
            return graphics_abort(sonic_native_input_error_contract);
        if (!invoke_frame_aot_service(context,
                                      sonic_frame_wait_tail_service))
            return graphics_abort(sonic_native_frame_error_service);
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_FRAME_PRODUCER_WAIT failure="
                  << error.what() << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_FRAME_PRODUCER_WAIT "
                     "failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_frame_error_exception};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_scene_begin(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return graphics_abort(sonic_native_graphics_error_context);

    const auto prefetch_count_on_entry = context.cpu->prefetch_count;
    try {
        static const bool diagnostic_scene_boundaries =
            sonic_native_diagnostic_enabled(
                "KATANA_SONIC_DIAGNOSTIC_FRAME_BOUNDARIES");
        static const auto diagnostic_scene_boundary_start_frame =
            sonic_native_diagnostic_u32(
                "KATANA_SONIC_DIAGNOSTIC_FRAME_BOUNDARY_START_FRAME")
                .value_or(0u);
        static const auto diagnostic_scene_boundary_end_frame =
            sonic_native_diagnostic_u32(
                "KATANA_SONIC_DIAGNOSTIC_FRAME_BOUNDARY_END_FRAME")
                .value_or(std::numeric_limits<std::uint32_t>::max());
        if (diagnostic_scene_boundaries &&
            context.frame_index >= diagnostic_scene_boundary_start_frame &&
            context.frame_index <= diagnostic_scene_boundary_end_frame) {
            std::cerr << "SONIC_NATIVE_SCENE_BOUNDARY phase=begin frame="
                      << context.frame_index << " open_before="
                      << (sonic_native_title_state.frame_open ? 1 : 0)
                      << " draws_before="
                      << sonic_native_title_state.draw_calls_this_frame
                      << '\n';
        }
        // Exact 0x8C641E40â€“0x8C642116 is a stateful TA scene initializer in
        // the old product.  Rebind its ordinary-RAM arena/source selection to
        // the exact 24-byte RegionHeader outputs captured by the existing
        // native copy provider.  Failure is deliberately non-fatal: it only
        // keeps the scene on AuthoredUnsorted.  No QACR/store-queue/TA command
        // is parsed or replayed, and no host begin/present is fabricated.
        (void)bind_sonic_native_type2_scene_authority(context);
        if (!ensure_native_frame_open(context)) {
            note_native_graphics_frame_failure(context, 2u);
            return graphics_abort(sonic_native_graphics_error_frame);
        }
        if (context.cpu->prefetch_count != prefetch_count_on_entry)
            return graphics_abort(sonic_native_graphics_error_ta_poison);
        context.cpu->r[0] = 0u;
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const katana::runtime::NativePortGraphicsError& error) {
        note_native_graphics_frame_failure(context, 3u, error.what(), &error,
            sonic_native_scene_error_exception);
        std::cerr << "SONIC_NATIVE_SCENE_BEGIN failure=" << error.what() << '\n';
    } catch (const std::exception& error) {
        note_native_graphics_frame_failure(context, 4u, error.what(), nullptr,
            sonic_native_scene_error_exception);
        std::cerr << "SONIC_NATIVE_SCENE_BEGIN failure=" << error.what()
                  << '\n';
    } catch (...) {
        note_native_graphics_frame_failure(context, 5u, {}, nullptr,
            sonic_native_scene_error_exception);
        std::cerr << "SONIC_NATIVE_SCENE_BEGIN failure=non-standard-exception\n";
    }
    return graphics_abort(sonic_native_scene_error_exception);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_frame_turnover(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                sonic_native_frame_error_context};

    try {
        SonicGuestReader reader(*context.cpu);
        std::uint32_t pacing_enabled = 0u;
        std::uint32_t pacing_delay_ticks = 0u;
        std::uint32_t frame_counter = 0u;
        if (!reader.valid() ||
            !frame_word(reader, sonic_turnover_pacing_enabled, pacing_enabled) ||
            !frame_word(reader, sonic_turnover_pacing_delay_ticks,
                        pacing_delay_ticks) ||
            !frame_word(reader, sonic_frame_counter, frame_counter) ||
            !reader.range(sonic_frame_pre_submit_ticks, sizeof(std::uint32_t)) ||
            !reader.range(sonic_frame_clear_a, sizeof(std::uint32_t)) ||
            !reader.range(sonic_frame_clear_b, sizeof(std::uint32_t)) ||
            !reader.range(sonic_frame_clear_c, sizeof(std::uint32_t)) ||
            !reader.range(sonic_frame_post_service_ticks, sizeof(std::uint32_t)) ||
            !reader.range(sonic_turnover_status_source, sizeof(std::uint32_t)))
            return graphics_abort(sonic_native_frame_error_side_effect);
        for (const auto destination : sonic_turnover_status_destinations) {
            if (!reader.range(destination, sizeof(std::uint32_t)))
                return graphics_abort(sonic_native_frame_error_status_copy);
        }

        // Preserve the pre-turnover TMU-visible timestamp.  A nonzero mode
        // and delay selected the old polling loop.  The native host owns
        // bounded pacing at present_frame(), so reading both words remains
        // part of the validated title contract but cannot reintroduce a
        // device-timer spin or delay a title frame twice.
        const auto pre_submit_ticks = sonic_native_timer_ticks(context);
        katana::runtime::guest_write_u32(
            *context.cpu, sonic_frame_pre_submit_ticks, pre_submit_ticks,
            katana::runtime::CodeWriteSource::Copy);
        static_cast<void>(pacing_enabled);
        static_cast<void>(pacing_delay_ticks);

        if (!service_periodic_host_time(context))
            return graphics_abort(sonic_native_frame_error_periodic_time);
        // Replace the exact Kamui drain directly.  Do not invoke 0x8C642380
        // or 0x8C641E40: both are full historical hardware owners.  The
        // scene-begin provider remains separately available to direct title
        // callers and is idempotent, but this whole-owner replacement does
        // not need to enter it to present already submitted native packets.
        const bool presented_title_draw =
            complete_native_frame(context, "frame-turnover");
        if (context.stop_reason == katana::runtime::NativePortStopReason::None &&
            sonic_native_title_state.development_state_restart_requested)
            return consume_sonic_native_development_state_restart();

        if (context.stop_reason == katana::runtime::NativePortStopReason::None &&
            !complete_sonic_native_drain_ram_tail(context))
            return graphics_abort(sonic_native_frame_error_service);

        katana::runtime::guest_write_u32(
            *context.cpu, sonic_frame_clear_a, 0u,
            katana::runtime::CodeWriteSource::Copy);
        katana::runtime::guest_write_u32(
            *context.cpu, sonic_frame_clear_b, 0u,
            katana::runtime::CodeWriteSource::Copy);
        katana::runtime::guest_write_u32(
            *context.cpu, sonic_frame_clear_c, 0u,
            katana::runtime::CodeWriteSource::Copy);
        katana::runtime::guest_write_u32(
            *context.cpu, sonic_frame_counter, frame_counter + 1u,
            katana::runtime::CodeWriteSource::Copy);

        // The displaced post-submit service was the SDK peripheral updater.
        // Keep its exact ordering while replacing the entire hardware-facing
        // family with the native controller provider. At the terminal frame
        // retain the RAM/status/ABI epilogue below, but consume no next input.
        if (context.stop_reason == katana::runtime::NativePortStopReason::None &&
            !service_sonic_native_input(
                context, false, false, "frame-turnover"))
            return graphics_abort(sonic_native_input_error_contract);

        const auto post_service_ticks = sonic_native_timer_ticks(context);
        katana::runtime::guest_write_u32(
            *context.cpu, sonic_frame_post_service_ticks, post_service_ticks,
            katana::runtime::CodeWriteSource::Copy);
        // The original loads this indirection only after the post-service.
        // Preserve that order: the service is allowed to publish a fresh
        // five-word title status block for the just-completed native frame.
        std::uint32_t status_source = 0u;
        if (!reader.u32(sonic_turnover_status_source, status_source) ||
            status_source == 0u ||
            !reader.range(
                status_source,
                sonic_turnover_status_destinations.size() *
                    sizeof(std::uint32_t)))
            return graphics_abort(sonic_native_frame_error_status_copy);
        for (std::size_t index = 0u;
             index < sonic_turnover_status_destinations.size(); ++index) {
            std::uint32_t word = 0u;
            const auto source =
                status_source + static_cast<std::uint32_t>(index * sizeof(word));
            if (!reader.u32(source, word))
                return graphics_abort(sonic_native_frame_error_status_copy);
            katana::runtime::guest_write_u32(
                *context.cpu, sonic_turnover_status_destinations[index], word,
                katana::runtime::CodeWriteSource::Copy);
        }
        context.cpu->r[0] = post_service_ticks;
        // The manifest binds the acceptance witness to this exact complete
        // turnover owner, not to its former Kamui callee.  Do not claim the
        // milestone until a real host present and every title-RAM effect of
        // this replacement have both completed.
        if (presented_title_draw)
            static_cast<void>(context.report_acceptance("FirstVisibleGameFrame"));
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const std::exception& error) {
        std::cerr << "SONIC_NATIVE_FRAME_TURNOVER failure=" << error.what()
                  << '\n';
    } catch (...) {
        std::cerr << "SONIC_NATIVE_FRAME_TURNOVER failure=non-standard-exception\n";
    }
    return {katana::runtime::NativePortHookAction::Abort, 0u,
            sonic_native_frame_error_exception};
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_kamui_present_drain(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return graphics_abort(sonic_native_graphics_error_context);
    const auto prefetch_count_on_entry = context.cpu->prefetch_count;
    try {
        if (sonic_render_completion_experiment_enabled() &&
            !service_sonic_render_completions(context))
            return graphics_abort(sonic_native_frame_error_periodic_time);
        // This exact whole-function replacement is the only present/drain
        // sink in the private bring-up path.  It deliberately has no TA/PVR
        // work to drain: earlier verified NINJA hooks submit NativePortDrawPacket
        // calls directly to the host GPU.  A host presentation is still real
        // even when the draw count is zero, but acceptance is never claimed
        // until a GPU draw and its following present have both succeeded.
        // A direct drain before any draw has no new native pixels. Complete
        // the paced title boundary by repeating the last GPU frame; do not
        // manufacture a black clear-and-swap.
        const bool presented_title_draw =
            complete_native_frame(context, "kamui-drain");
        // A restored quicksave already owns its cursor generation. Otherwise
        // retain the successful original drain's RAM-only state transition.
        if (context.stop_reason == katana::runtime::NativePortStopReason::None &&
            sonic_native_title_state.development_state_restart_requested)
            return consume_sonic_native_development_state_restart();
        if (context.cpu->prefetch_count != prefetch_count_on_entry)
            return graphics_abort(sonic_native_graphics_error_ta_poison);
        if (context.stop_reason == katana::runtime::NativePortStopReason::None &&
            !complete_sonic_native_drain_ram_tail(context))
            return graphics_abort(sonic_native_frame_error_service);
        context.cpu->r[0] = 0u;
        if (presented_title_draw)
            static_cast<void>(context.report_acceptance("FirstVisibleGameFrame"));
        return {katana::runtime::NativePortHookAction::Return, 0u, 0u};
    } catch (const katana::runtime::NativePortGraphicsError& error) {
        note_native_graphics_frame_failure(context, 3u, error.what(), &error);
        std::cerr << "SONIC_NATIVE_PRESENT failure=" << error.what() << '\n';
    } catch (const std::exception& error) {
        note_native_graphics_frame_failure(context, 4u, error.what());
        std::cerr << "SONIC_NATIVE_PRESENT failure=" << error.what() << '\n';
    } catch (...) {
        note_native_graphics_frame_failure(context, 5u);
        std::cerr << "SONIC_NATIVE_PRESENT failure=non-standard-exception\n";
    }
    return graphics_abort(sonic_native_graphics_error_frame);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_waypoint_probe(
    katana::runtime::NativePortContext& context) noexcept {
    if (!valid_sonic_native_context(context))
        return {katana::runtime::NativePortHookAction::Abort, 0u,
                0x53415700u};

    constexpr std::array waypoints{
        0x8C053CA2u, 0x8C054482u, 0x8C051794u};
    const auto pc = context.cpu->pc;
    for (std::size_t index = 0u; index < waypoints.size(); ++index) {
        if (pc != waypoints[index] ||
            sonic_native_title_state.waypoint_reported[index])
            continue;
        sonic_native_title_state.waypoint_reported[index] = true;
        std::cerr << "SONIC_NATIVE_WAYPOINT pc=0x" << std::hex
                  << std::setfill('0') << std::setw(8) << pc
                  << " pr=0x" << std::setw(8) << context.cpu->pr
                  << " r0=0x" << std::setw(8) << context.cpu->r[0]
                  << " r14=0x" << std::setw(8) << context.cpu->r[14]
                  << " r15=0x" << std::setw(8) << context.cpu->r[15]
                  << std::dec << '\n';
        break;
    }
    return {katana::runtime::NativePortHookAction::ContinueOriginal, 0u, 0u};
}

