sonic_native_ninja_basic_model_draw_8c6214fa(
    katana::runtime::NativePortContext& context) noexcept {
    return sonic_native_ninja_basic_model_draw_composite_impl(
        context, SonicNativeBasicCompositeOwner::Basic8C6214FA);
}

extern "C" katana::runtime::NativePortHookResult
sonic_native_ninja_basic_model_draw_8c638d72(
    katana::runtime::NativePortContext& context) noexcept {
    return sonic_native_ninja_basic_model_draw_composite_impl(
        context, SonicNativeBasicCompositeOwner::Basic8C638D72);
}
